	private static void ConfigureOnnxRuntimeSearchPath()
	{
		string runtimeDirectory = (Environment.GetEnvironmentVariable(OnnxRuntimeDirectoryEnvironmentVariable) ?? string.Empty).Trim();
		if (runtimeDirectory.Length <= 0)
		{
			return;
		}
		runtimeDirectory = Path.GetFullPath(runtimeDirectory);
		string nativeRuntimePath = Path.Combine(runtimeDirectory, "onnxruntime.dll");
		if (!Directory.Exists(runtimeDirectory) || !File.Exists(nativeRuntimePath))
		{
			throw new InvalidOperationException(OnnxRuntimeDirectoryEnvironmentVariable
				+ " must point to a directory containing onnxruntime.dll: " + runtimeDirectory);
		}
		if (!SetDllDirectory(runtimeDirectory))
		{
			throw new InvalidOperationException("SetDllDirectory failed for the ONNX contract runtime; Win32Error="
				+ Marshal.GetLastWin32Error().ToString(CultureInfo.InvariantCulture));
		}
	}

	private static void ConfigureOnnxModuleRootOverride(string[] args)
	{
		string moduleRoot = null;
		for (int i = 0; i + 1 < (args?.Length ?? 0); i++)
		{
			if (string.Equals(args[i], OnnxModuleRootOption, StringComparison.OrdinalIgnoreCase))
			{
				moduleRoot = Path.GetFullPath(args[i + 1]);
				break;
			}
		}
		if (string.IsNullOrWhiteSpace(moduleRoot))
		{
			return;
		}

		string onnxDirectory = Path.Combine(moduleRoot, "ONNX");
		bool hasModel = File.Exists(Path.Combine(onnxDirectory, "model_quantized.onnx"))
			|| File.Exists(Path.Combine(onnxDirectory, "model.onnx"));
		if (!string.Equals(Path.GetFileName(moduleRoot.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar)),
				"AnimusForge", StringComparison.OrdinalIgnoreCase)
			|| !File.Exists(Path.Combine(moduleRoot, "SubModule.xml"))
			|| !Directory.Exists(Path.Combine(moduleRoot, "ModuleData"))
			|| !Directory.Exists(onnxDirectory)
			|| !hasModel
			|| !File.Exists(Path.Combine(onnxDirectory, "tokenizer.json")))
		{
			throw new InvalidOperationException(OnnxModuleRootOption
				+ " must point to an AnimusForge module containing SubModule.xml, ModuleData, and existing ONNX assets: "
				+ moduleRoot);
		}

		MethodInfo prefix = typeof(Program).GetMethod(nameof(OverrideOnnxContractModuleRoot), All)
			?? throw new MissingMethodException(typeof(Program).FullName, nameof(OverrideOnnxContractModuleRoot));
		Type harmonyType = Type.GetType("HarmonyLib.Harmony, 0Harmony", throwOnError: true);
		Type harmonyMethodType = Type.GetType("HarmonyLib.HarmonyMethod, 0Harmony", throwOnError: true);
		object harmony = Activator.CreateInstance(harmonyType, "AnimusForge.PolicyEffectModule.ContractTests.OnnxModuleRoot");
		object harmonyPrefix = Activator.CreateInstance(harmonyMethodType, prefix);
		MethodInfo patch = harmonyType.GetMethods(All).Single(method =>
			method.Name == "Patch" && method.GetParameters().Length == 5);
		HashSet<Assembly> patchedAssemblies = new HashSet<Assembly>();
		PatchOnnxContractModuleRoot(
			typeof(PolicyEffectModuleRouter).Assembly.GetType("AnimusForge.AnimusForgeModulePaths", throwOnError: true),
			harmony,
			harmonyPrefix,
			patch,
			patchedAssemblies);
		PatchOnnxContractModuleRoot(
			SutType("AnimusForge.AnimusForgeModulePaths"),
			harmony,
			harmonyPrefix,
			patch,
			patchedAssemblies);
		foreach (Assembly assembly in patchedAssemblies)
		{
			InitializeOnnxContractEmbedding(
				assembly.GetType("AnimusForge.OnnxEmbeddingEngine", throwOnError: true),
				moduleRoot);
		}
	}

	private static void PatchOnnxContractModuleRoot(
		Type modulePathsType,
		object harmony,
		object harmonyPrefix,
		MethodInfo patch,
		ISet<Assembly> patchedAssemblies)
	{
		if (modulePathsType == null || modulePathsType.Assembly == null || patchedAssemblies == null
			|| !patchedAssemblies.Add(modulePathsType.Assembly))
		{
			return;
		}

		MethodInfo target = modulePathsType.GetMethod("GetCurrentModuleRoot", All, null, Type.EmptyTypes, null)
			?? throw new MissingMethodException(modulePathsType.FullName, "GetCurrentModuleRoot");
		patch.Invoke(harmony, new[] { (object)target, harmonyPrefix, null, null, null });
	}

	private static void InitializeOnnxContractEmbedding(Type embeddingType, string moduleRoot)
	{
		object embedding = embeddingType.GetProperty("Instance", All)?.GetValue(null, null)
			?? throw new MissingMemberException(embeddingType.FullName, "Instance");
		bool available;
		string lastError;
		_onnxContractModuleRoot = moduleRoot;
		try
		{
			available = (bool)(embeddingType.GetProperty("IsAvailable", All)?.GetValue(embedding, null)
				?? throw new MissingMemberException(embeddingType.FullName, "IsAvailable"));
			lastError = (string)(embeddingType.GetProperty("LastError", All)?.GetValue(embedding, null) ?? string.Empty);
		}
		finally
		{
			_onnxContractModuleRoot = null;
		}
		Check(available, "Existing ONNX embedding assets failed to initialize from the requested module root: " + lastError);
	}

	private static bool OverrideOnnxContractModuleRoot(ref string __result)
	{
		string moduleRoot = _onnxContractModuleRoot;
		if (string.IsNullOrWhiteSpace(moduleRoot))
		{
			return true;
		}
		_onnxContractModuleRoot = null;
		__result = moduleRoot;
		return false;
	}

	private static void LoadAssemblies(string[] args)
	{
		string requestedPath = null;
		for (int i = 0; i + 1 < args.Length; i++)
		{
			if (string.Equals(args[i], "--assembly", StringComparison.OrdinalIgnoreCase))
			{
				requestedPath = Path.GetFullPath(args[i + 1]);
				break;
			}
		}

		string baseDirectory = AppDomain.CurrentDomain.BaseDirectory;
		string repositoryRoot = FindRepositoryRoot(baseDirectory);
		string bannerlordRoot = @"D:\steam\steamapps\common\Mount & Blade II Bannerlord";
		string requestedDirectory = string.IsNullOrWhiteSpace(requestedPath)
			? null
			: Path.GetDirectoryName(requestedPath);
		string[] searchDirectories = new[]
		{
			requestedDirectory,
			baseDirectory,
			repositoryRoot == null ? null : Path.Combine(repositoryRoot, "_deps_auto"),
			repositoryRoot == null ? null : Path.Combine(repositoryRoot, "..", "_deps_261550_managed"),
			Path.Combine(bannerlordRoot, "bin", "Win64_Shipping_Client"),
			Path.Combine(bannerlordRoot, "Modules", "Bannerlord.Harmony", "bin", "Win64_Shipping_Client"),
			Path.Combine(bannerlordRoot, "Modules", "Bannerlord.UIExtenderEx", "bin", "Win64_Shipping_Client"),
			Path.Combine(bannerlordRoot, "Modules", "Bannerlord.MBOptionScreen", "bin", "Win64_Shipping_Client"),
			Path.Combine(bannerlordRoot, "Modules", "DistinguishedServiceRedux", "bin", "Win64_Shipping_Client")
		}
			.Where(path => !string.IsNullOrWhiteSpace(path))
			.Select(Path.GetFullPath)
			.Where(Directory.Exists)
			.Distinct(StringComparer.OrdinalIgnoreCase)
			.ToArray();
		AppDomain.CurrentDomain.AssemblyResolve += (_, eventArgs) =>
		{
			AssemblyName requestedAssemblyName;
			try
			{
				requestedAssemblyName = new AssemblyName(eventArgs.Name);
			}
			catch
			{
				return null;
			}

			string simpleName = requestedAssemblyName.Name;
			if (string.IsNullOrWhiteSpace(simpleName))
			{
				return null;
			}

			foreach (Assembly loadedAssembly in AppDomain.CurrentDomain.GetAssemblies())
			{
				try
				{
					if (AssemblyName.ReferenceMatchesDefinition(requestedAssemblyName, loadedAssembly.GetName()))
					{
						return loadedAssembly;
					}
				}
				catch
				{
					// Ignore broken dynamic assemblies and continue probing the filesystem.
				}
			}

			foreach (string directory in searchDirectories)
			{
				string candidate = Path.Combine(directory, simpleName + ".dll");
				if (File.Exists(candidate))
				{
					return Assembly.LoadFrom(candidate);
				}
			}

			return null;
		};

		string assemblyPath = requestedPath ?? Path.Combine(baseDirectory, "AnimusForge.dll");
		Check(File.Exists(assemblyPath), "AnimusForge.dll not found: " + assemblyPath);
		_sut = Assembly.LoadFrom(assemblyPath);
		TryPreloadAssembly("Newtonsoft.Json", searchDirectories);
		_jTokenType = RequireType("Newtonsoft.Json.Linq.JToken, Newtonsoft.Json");
	}

	private static string FindRepositoryRoot(string startDirectory)
	{
		string current = startDirectory;
		while (!string.IsNullOrWhiteSpace(current))
		{
			if (File.Exists(Path.Combine(current, "AnimusForge.csproj")))
			{
				return current;
			}
			DirectoryInfo parent = Directory.GetParent(current);
			current = parent?.FullName;
		}
		return null;
	}

	private static void TryPreloadAssembly(string simpleName, IEnumerable<string> searchDirectories)
	{
		if (AppDomain.CurrentDomain.GetAssemblies().Any(assembly => string.Equals(assembly.GetName().Name, simpleName, StringComparison.OrdinalIgnoreCase)))
		{
			return;
		}

		foreach (string directory in searchDirectories)
		{
			string candidate = Path.Combine(directory, simpleName + ".dll");
			if (File.Exists(candidate))
			{
				Assembly.LoadFrom(candidate);
				return;
			}
		}
	}

