	private static void TestCatalogAndLegacyIds()
	{
		Type catalog = SutType("AnimusForge.PolicyEffects.PolicyEffectModuleCatalog");
		object firstSnapshot = Property(catalog, null, "Modules");
		object secondSnapshot = Property(catalog, null, "Modules");
		Check(ReferenceEquals(firstSnapshot, secondSnapshot), "Catalog must reuse its single reflected snapshot.");
		object[] modules = Items(firstSnapshot).ToArray();
		Check(modules.Length >= ExpectedPromptVisibleModuleIds.Length,
			"Catalog must retain every prompt-visible production module, actual=" + modules.Length);
		Type moduleContract = SutType("AnimusForge.PolicyEffects.IPolicyEffectModule");
		Check(modules.All(moduleContract.IsInstanceOfType),
			"Every production Catalog entry must still implement IPolicyEffectModule after lifecycle contract changes.");
		Array productionModules = Array.CreateInstance(moduleContract, modules.Length);
		Array.Copy(modules, productionModules, modules.Length);
		MethodInfo productionValidation = catalog.GetMethod("ValidateModuleSetForContractTests", All);
		Check(productionValidation != null, "Catalog production-set validation entry point is missing.");
		productionValidation.Invoke(null, new object[] { productionModules });

		string[] ids = modules.Select(module => (string)Property(module.GetType(), module, "Id")).ToArray();
		Check(ids.Distinct(StringComparer.Ordinal).Count() == ids.Length, "Catalog module IDs must be unique.");
		Check(ExpectedPromptVisibleModuleIds.All(expected => ids.Contains(expected, StringComparer.Ordinal)),
			"Catalog is missing a prompt-visible module. actual=" + string.Join(",", ids));
		Check(HiddenRuntimeModuleIds.All(hidden => !ids.Contains(hidden, StringComparer.Ordinal)),
			"Prompt-facing Catalog.Modules must not expose internal or legacy module IDs. actual=" + string.Join(",", ids));
		Check(modules.All(module => (bool)Property(
			Property(module.GetType(), module, "Descriptor").GetType(),
			Property(module.GetType(), module, "Descriptor"),
			"PromptVisible")),
			"Every prompt-facing Catalog.Modules entry must explicitly be prompt-visible.");
		Check(modules.All(module =>
		{
			object moduleDescriptor = Property(module.GetType(), module, "Descriptor");
			string displayName = (string)Property(moduleDescriptor.GetType(), moduleDescriptor, "PlayerDisplayName");
			return !string.IsNullOrWhiteSpace(displayName) && !ContainsAsciiLetter(displayName);
		}), "Every prompt-facing module must expose a non-English player display name.");

		int[] orders = modules.Select(module => Convert.ToInt32(Property(module.GetType(), module, "Order"), CultureInfo.InvariantCulture)).ToArray();
		Check(orders.Distinct().Count() == orders.Length, "Catalog module orders must be unique.");
		Check(orders.SequenceEqual(orders.OrderBy(value => value)), "Catalog modules must be ordered by Order.");

		string[] localIds = ScopeIds(catalog, "local");
		string[] kingdomIds = ScopeIds(catalog, "kingdom");
		string[] vassalIds = ScopeIds(catalog, "vassal");
		string[] expectedLocal = ExpectedPromptVisibleModuleIds
			.Where(id => !string.Equals(id, "kingdomStability", StringComparison.Ordinal)
				&& !string.Equals(id, "armyFormationTendencyPct", StringComparison.Ordinal)
				&& !string.Equals(id, "kingdomVillageRaidBan", StringComparison.Ordinal))
			.ToArray();
		Check(expectedLocal.All(expected => localIds.Contains(expected, StringComparer.Ordinal)),
			"Local scope must retain every visible module that explicitly supports local policies.");
		Check(ExpectedPromptVisibleModuleIds.All(expected => kingdomIds.Contains(expected, StringComparer.Ordinal)),
			"Kingdom scope must expose every prompt-visible module.");
		string[] expectedVassal = ExpectedPromptVisibleModuleIds
			.Where(id => !string.Equals(id, "kingdomVillageRaidBan", StringComparison.Ordinal))
			.ToArray();
		Check(expectedVassal.All(expected => vassalIds.Contains(expected, StringComparer.Ordinal))
			&& !vassalIds.Contains("kingdomVillageRaidBan", StringComparer.Ordinal),
			"Vassal scope must expose every supported prompt-visible module and exclude issuer-kingdom-only raid bans.");
		Check(localIds.Length >= expectedLocal.Length, "Local scope baseline count regressed: " + localIds.Length);
		Check(kingdomIds.Length >= ExpectedPromptVisibleModuleIds.Length, "Kingdom scope baseline count regressed: " + kingdomIds.Length);
		Check(vassalIds.Length >= expectedVassal.Length, "Vassal scope baseline count regressed: " + vassalIds.Length);

		foreach (KeyValuePair<string, string> pair in LegacyIds)
		{
			object[] call = { pair.Key, null };
			bool resolved = (bool)InvokeStatic(catalog, "TryResolveCanonicalId", call, 2);
			Check(resolved, "Legacy module ID must resolve: " + pair.Key);
			Check(string.Equals((string)call[1], pair.Value, StringComparison.Ordinal),
				"Legacy module ID resolved incorrectly: " + pair.Key + " -> " + call[1]);
		}

		foreach (string hiddenId in HiddenRuntimeModuleIds)
		{
			Check(PolicyEffectModuleCatalog.TryGet(hiddenId, out IPolicyEffectModule hidden),
				"Hidden runtime/compatibility module must remain resolvable by ID: " + hiddenId);
			Check(!hidden.Descriptor.PromptVisible,
				"Hidden runtime/compatibility module must not be prompt-visible: " + hiddenId);
			Check(PolicyEffectModuleCatalog.ResolveModules(new[] { hiddenId }).Count == 0,
				"Prompt module resolution must not re-expose hidden module: " + hiddenId);
		}

		Check(PolicyEffectModuleCatalog.TryGet("kingdomStabilityOnce", out IPolicyEffectModule stability),
			"Legacy kingdomStabilityOnce compatibility module must remain resolvable.");
		object descriptor = stability.Descriptor;
		Check(string.Equals(Property(descriptor.GetType(), descriptor, "ExecutionKind").ToString(), "OneShot", StringComparison.Ordinal),
			"kingdomStabilityOnce must be OneShot.");
		Check((bool)Property(descriptor.GetType(), descriptor, "SupportsRollback"), "kingdomStabilityOnce must support rollback.");
		Check((bool)Property(descriptor.GetType(), descriptor, "SupportsIdempotency"), "kingdomStabilityOnce must support idempotency.");
		Check(stability is IOneShotPolicyEffectModule, "kingdomStabilityOnce must implement the one-shot executor contract.");

		Check(PolicyEffectModuleCatalog.TryGet("clanInfluence", out IPolicyEffectModule influence),
			"Visible clanInfluence module must remain resolvable by ID.");
		Check(influence.Descriptor.ExecutionKind == PolicyEffectExecutionKind.Composite
			&& influence is IPolicyEffectCompositeModule
			&& string.Equals(influence.Descriptor.DisplayGroup, "clanInfluence", StringComparison.Ordinal),
			"clanInfluence must be a visible Composite grouped under clanInfluence.");
		JObject influenceSchema = influence.Descriptor.PayloadPromptSchema;
		Check((influenceSchema["required"] as JArray)?.Values<string>()
			.SequenceEqual(new[] { "onceDelta", "dailyDelta" }, StringComparer.Ordinal) == true
			&& influenceSchema.Value<bool?>("additionalProperties") == false,
			"clanInfluence prompt payload must require exactly onceDelta and dailyDelta.");

		Check(PolicyEffectModuleCatalog.TryGet("clanLeaderRelationOnce", out IPolicyEffectModule relation),
			"Visible clanLeaderRelationOnce module must remain resolvable by ID.");
		Check(relation.Descriptor.ExecutionKind == PolicyEffectExecutionKind.ScheduledOnce
			&& relation is IScheduledOncePolicyEffectModule
			&& relation.Descriptor.SupportsRollback
			&& relation.Descriptor.SupportsIdempotency,
			"clanLeaderRelationOnce must expose the scheduled-once execution contract.");

		Check(PolicyEffectModuleCatalog.TryGet("kingdomStability", out IPolicyEffectModule stabilityComposite),
			"Visible kingdomStability module must remain resolvable by ID.");
		Check(stabilityComposite.Descriptor.ExecutionKind == PolicyEffectExecutionKind.Composite
			&& stabilityComposite is IPolicyEffectCompositeModule
			&& string.Equals(stabilityComposite.Descriptor.DisplayGroup, "kingdomStability", StringComparison.Ordinal),
			"New kingdomStability must be the visible next-day Composite module.");

		Check(PolicyEffectModuleCatalog.TryGet("clanInfluenceNextDayOnce", out IPolicyEffectModule influenceOnce)
			&& influenceOnce.Descriptor.ExecutionKind == PolicyEffectExecutionKind.ScheduledOnce
			&& influenceOnce is IScheduledOncePolicyEffectModule
			&& string.Equals(influenceOnce.Descriptor.DisplayGroup, influence.Descriptor.DisplayGroup, StringComparison.Ordinal),
			"The hidden influence once child must be ScheduledOnce and share the visible display group.");
		Check(PolicyEffectModuleCatalog.TryGet("clanInfluencePerDay", out IPolicyEffectModule influenceDaily)
			&& influenceDaily.Descriptor.ExecutionKind == PolicyEffectExecutionKind.DailyMutation
			&& influenceDaily is IDailyPolicyEffectModule
			&& string.Equals(influenceDaily.Descriptor.DisplayGroup, influence.Descriptor.DisplayGroup, StringComparison.Ordinal),
			"The hidden influence daily child must remain daily and share the visible display group.");
		Check(PolicyEffectModuleCatalog.TryGet("kingdomStabilityNextDayOnce", out IPolicyEffectModule stabilityOnce)
			&& stabilityOnce.Descriptor.ExecutionKind == PolicyEffectExecutionKind.ScheduledOnce
			&& stabilityOnce is IScheduledOncePolicyEffectModule
			&& string.Equals(stabilityOnce.Descriptor.DisplayGroup, stabilityComposite.Descriptor.DisplayGroup, StringComparison.Ordinal),
			"The hidden stability child must be ScheduledOnce and share the visible display group.");
		Check(((IPolicyEffectCompositeModule)influence).RuntimeModuleIds
			.SequenceEqual(new[] { "clanInfluenceNextDayOnce", "clanInfluencePerDay" }, StringComparer.Ordinal)
			&& ((IPolicyEffectCompositeModule)stabilityComposite).RuntimeModuleIds
				.SequenceEqual(new[] { "kingdomStabilityNextDayOnce" }, StringComparer.Ordinal),
			"Composite modules must explicitly declare their runtime descendants.");
		Check(PolicyEffectModuleCatalog.IsAuthorizedRuntimeModule("clanInfluence", "clanInfluenceNextDayOnce")
			&& PolicyEffectModuleCatalog.IsAuthorizedRuntimeModule("clanInfluence", "clanInfluencePerDay")
			&& PolicyEffectModuleCatalog.IsAuthorizedRuntimeModule("kingdomStability", "kingdomStabilityNextDayOnce")
			&& !PolicyEffectModuleCatalog.IsAuthorizedRuntimeModule("kingdomStability", "clanInfluencePerDay"),
			"Catalog-cached source/runtime lineage must authorize only declared descendants.");

		Check(PolicyEffectModuleCatalog.TryGet("armyFormationTendencyPct", out IPolicyEffectModule armyFormation)
			&& armyFormation.Descriptor.Order == 150
			&& armyFormation.Descriptor.ExecutionKind == PolicyEffectExecutionKind.ModelModifier
			&& armyFormation.Descriptor.Hook == PolicyEffectHook.ArmyFormationScore
			&& armyFormation.Descriptor.Aggregation == PolicyEffectAggregationKind.Additive
			&& armyFormation.Descriptor.ValueUnit == PolicyEffectValueUnit.RelativePercent
			&& armyFormation.Descriptor.FundingMode == PolicyEffectFundingMode.InheritPolicy
			&& armyFormation.Descriptor.FundingStrategy == PolicyEffectFundingStrategy.Linear
			&& armyFormation.Descriptor.TargetKinds.SequenceEqual(new[] { PolicyEffectTargetKind.Clan })
			&& armyFormation is IModelModifierPolicyEffectModule,
			"armyFormationTendencyPct must remain one Clan-targeted relative-percent model modifier.");
	}

	private static void TestClanLeaderRelationActorClanTargetContracts()
	{
		Check(PolicyEffectModuleCatalog.TryGet("clanLeaderRelationOnce", out IPolicyEffectModule relation),
			"clanLeaderRelationOnce must remain registered for actor-clan exclusion contracts.");
		Check(relation.Descriptor.ExcludeActorClanTargets
			&& relation.Descriptor.TargetKinds.Contains(PolicyEffectTargetKind.Clan),
			"clanLeaderRelationOnce alone must opt into actor-clan target exclusion through Clan targets.");

		PolicyEffectCanonicalTargetSet unfiltered = new PolicyEffectCanonicalTargetSet
		{
			KingdomIds = new List<string> { "issuer-kingdom" },
			ClanIds = new List<string> { "actor-clan", "other-clan-b", "other-clan-a" }
		};
		PolicyEffectCanonicalTargetSet filtered = PolicyEffectCompiler.ApplyActorClanTargetExclusion(
			relation,
			"actor-clan",
			unfiltered);
		Check(filtered.ClanIds.SequenceEqual(new[] { "other-clan-a", "other-clan-b" }, StringComparer.Ordinal)
			&& unfiltered.ClanIds.Contains("actor-clan", StringComparer.OrdinalIgnoreCase),
			"Actor-clan filtering must be a read-only linear projection that retains only other clans.");
		Check(PolicyEffectModuleCatalog.TryGet("clanInfluence", out IPolicyEffectModule influence)
			&& PolicyEffectCompiler.ApplyActorClanTargetExclusion(
				influence,
				"actor-clan",
				new PolicyEffectCanonicalTargetSet { ClanIds = new List<string> { "actor-clan" } })
				.ClanIds.SequenceEqual(new[] { "actor-clan" }, StringComparer.Ordinal),
			"Actor-clan exclusion must not globally remove valid self-clan targets from clanInfluence.");

		PolicyEffectTargetResolver resolver = delegate(
			string handle,
			IPolicyEffectModule module,
			out PolicyEffectResolvedTarget resolved,
			out string error)
		{
			_ = module;
			string normalized = (handle ?? string.Empty).Trim();
			List<string> clanIds;
			PolicyEffectTargetKind selectorKind;
			switch (normalized)
			{
				case "K_ALL":
					selectorKind = PolicyEffectTargetKind.Kingdom;
					clanIds = new List<string> { "actor-clan", "other-clan-a", "other-clan-b" };
					break;
				case "C_ALL":
					selectorKind = PolicyEffectTargetKind.Clan;
					clanIds = new List<string> { "actor-clan", "other-clan-a", "other-clan-b" };
					break;
				case "C_OTHER":
					selectorKind = PolicyEffectTargetKind.Clan;
					clanIds = new List<string> { "other-clan-a", "other-clan-b" };
					break;
				case "C_PUBLISHER":
					selectorKind = PolicyEffectTargetKind.Clan;
					clanIds = new List<string> { "actor-clan" };
					break;
				default:
					resolved = null;
					error = "unknown handle";
					return false;
			}
			resolved = new PolicyEffectResolvedTarget
			{
				Handle = normalized,
				SelectorKind = selectorKind,
				CanonicalTargetSet = new PolicyEffectCanonicalTargetSet
				{
					SelectorHandles = new List<string> { normalized },
					KingdomIds = new List<string> { "issuer-kingdom" },
					ClanIds = clanIds
				}
			};
			error = string.Empty;
			return true;
		};
		string[] handles = { "K_ALL", "C_ALL", "C_OTHER", "C_PUBLISHER" };
		PolicyTargetHandleDirectory directory = PolicyTargetHandleDirectoryBuilder.Build(
			handles.Select(handle => new PolicyTargetHandleDirectoryCandidate
			{
				Handle = handle,
				Entry = new PolicyTargetHandleDirectoryEntry { Kind = "contract", SelectorId = handle }
			}).ToArray(),
			new[] { relation },
			resolver,
			"issuer-kingdom",
			"actor-clan",
			(handle, entry, module, resolved) => string.Equals(handle, "K_ALL", StringComparison.Ordinal));
		Check(directory.Capabilities.TryGetValue(relation.Id, out PolicyEffectCapabilityDirectoryEntry capability)
			&& capability.AllowedTargetHandles.Count == 3
			&& string.Equals(capability.DefaultTargetHandle, "K_ALL", StringComparison.Ordinal)
			&& capability.AllowedSubsetTargetHandles.SequenceEqual(new[] { "C_ALL", "C_OTHER" }, StringComparer.Ordinal)
			&& capability.AllowedTargetHandles.Contains("K_ALL", StringComparer.Ordinal)
			&& capability.AllowedTargetHandles.Contains("C_ALL", StringComparer.Ordinal)
			&& capability.AllowedTargetHandles.Contains("C_OTHER", StringComparer.Ordinal)
			&& !capability.AllowedTargetHandles.Contains("C_PUBLISHER", StringComparer.Ordinal)
			&& !directory.Targets.ContainsKey("C_PUBLISHER"),
			"Relation target directories must normalize all/other-clan selectors and reject publisher-only handles.");

		PolicyEffectCompilerRequest request = new PolicyEffectCompilerRequest
		{
			Scope = PolicyEffectScopes.Kingdom,
			PolicyId = "relation-actor-clan-filter",
			ActorHeroId = "actor-hero",
			ActorClanId = "actor-clan",
			IssuerKingdomId = "issuer-kingdom",
			StartDay = 10f,
			EndDay = 20f,
			Funding = new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			CandidateModuleIds = new[] { relation.Id },
			DetailedModuleIds = new[] { relation.Id }
		};
		PolicyEffectWireEffect BuildWire(string handle) => new PolicyEffectWireEffect
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "M0",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			ModuleId = relation.Id,
			TargetHandles = new List<string> { handle },
			Payload = new JObject { ["value"] = 5f },
			Reason = "actor clan exclusion contract"
		};
		PolicyEffectInstanceIdFactory idFactory = (ordinal, moduleId, targetSet) =>
			"relation-actor-clan-filter:" + ordinal.ToString(CultureInfo.InvariantCulture);
		Check(PolicyEffectCompiler.TryCompile(
				new[] { BuildWire("K_ALL") },
				request,
				resolver,
				idFactory,
				out PolicyEffectCompilerResult compiled,
				out string compileError)
			&& compiled.Effects.Single().SaveData.TargetSet.ClanIds
				.SequenceEqual(new[] { "other-clan-a", "other-clan-b" }, StringComparer.Ordinal)
			&& compiled.Effects.Single().PreparedInstance.Instance.TargetSet.ClanIds
				.SequenceEqual(new[] { "other-clan-a", "other-clan-b" }, StringComparer.Ordinal),
			"Compiler must freeze only the two external clans from a Kingdom target: " + compileError);
		Check(!PolicyEffectCompiler.TryCompile(
				new[] { BuildWire("C_PUBLISHER") },
				request,
				resolver,
				idFactory,
				out _,
				out string publisherOnlyError)
			&& !string.IsNullOrWhiteSpace(publisherOnlyError),
			"Forged publisher-only relation wires must fail closed after target filtering.");

		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		JObject packagedPrompt = JObject.Parse(File.ReadAllText(Path.Combine(
			repositoryRoot,
			"AnimusForge",
			"CustomPrompts",
			"Policy",
			"Effects",
			"clanLeaderRelationOnce.json"), Encoding.UTF8));
		Check(relation.Descriptor.EditableUnderstandingPrompt.Contains("发布者所属家族整体")
			&& relation.Descriptor.PostprocessRule.Contains("发布者所属家族整体")
			&& string.Equals(
				(string)packagedPrompt["UnderstandingPrompt"],
				relation.Descriptor.EditableUnderstandingPrompt,
				StringComparison.Ordinal)
			&& string.Equals(
				(string)packagedPrompt["EvaluationPrompt"],
				relation.Descriptor.EditableEvaluationPrompt,
				StringComparison.Ordinal),
			"Relation descriptor, built-in fallback, and packaged prompt must share whole-publisher-clan semantics.");

		string bridgeSource = File.ReadAllText(Path.Combine(
			repositoryRoot,
			"PolicySystem",
			"Core",
			"PolicyEffectExecutionCoordinator.cs"), Encoding.UTF8);
		string managementSource = File.ReadAllText(Path.Combine(
			repositoryRoot,
			"PolicySystem",
			"Core",
			"CustomPolicyBehavior.Management.cs"), Encoding.UTF8);
		Check(bridgeSource.Contains("Clan actorClan = actor.Clan")
			&& bridgeSource.Contains("ReferenceEquals(actorClan, targetClan)")
			&& bridgeSource.IndexOf("ReferenceEquals(actorClan, targetClan)", StringComparison.Ordinal)
				< bridgeSource.IndexOf("ChangeRelationAction.ApplyRelationChangeBetweenHeroes", StringComparison.Ordinal),
			"The production bridge must skip actor-clan targets before invoking ChangeRelationAction.");
		Check(managementSource.Contains("BuildPlayerVisibleTargetSet")
			&& managementSource.Contains("PolicyEffectCompiler.ApplyActorClanTargetExclusion(module, actorClanId, instance.TargetSet)"),
			"Old saved relation summaries must use the shared actor-clan target filter without rewriting persistence.");
	}

	private static void TestVolunteerProductionGrowthModuleContracts()
	{
		IPolicyEffectModule module = RequirePolicyEffectModule("volunteerProductionGrowthPct");
		PolicyEffectModuleDescriptor descriptor = module.Descriptor;
		Check(descriptor.Order == 145
			&& descriptor.ExecutionKind == PolicyEffectExecutionKind.ModelModifier
			&& descriptor.Hook == PolicyEffectHook.VolunteerProductionProbability
			&& descriptor.Aggregation == PolicyEffectAggregationKind.Additive
			&& descriptor.ValueUnit == PolicyEffectValueUnit.RelativePercent
			&& descriptor.FundingMode == PolicyEffectFundingMode.InheritPolicy
			&& descriptor.FundingStrategy == PolicyEffectFundingStrategy.Linear
			&& descriptor.TargetProjection == PolicyEffectTargetProjectionKind.PrimaryFiefAndBoundSettlements
			&& descriptor.TargetRefresh == PolicyEffectTargetRefreshKind.Dynamic
			&& descriptor.TargetKinds.SequenceEqual(new[] { PolicyEffectTargetKind.Settlement })
			&& module is IModelModifierPolicyEffectModule,
			"Volunteer production/growth must be one dynamic Settlement-targeted relative-percent model modifier.");
		Check(descriptor.AllowedScopes.OrderBy(value => value, StringComparer.Ordinal).SequenceEqual(
			new[] { PolicyEffectScopes.Kingdom, PolicyEffectScopes.Local, PolicyEffectScopes.Vassal }
				.OrderBy(value => value, StringComparer.Ordinal))
			&& descriptor.AllowedSelectorKinds.OrderBy(value => value).SequenceEqual(
				new[] { PolicyEffectTargetKind.Settlement, PolicyEffectTargetKind.Clan, PolicyEffectTargetKind.Kingdom }
					.OrderBy(value => value))
			&& PolicyEffectModuleRetrievalSettings.IsContextSupported(module, PolicyEffectRetrievalContext.PlayerKingdom)
			&& PolicyEffectModuleRetrievalSettings.IsContextSupported(module, PolicyEffectRetrievalContext.PlayerLocal)
			&& PolicyEffectModuleRetrievalSettings.IsContextSupported(module, PolicyEffectRetrievalContext.NpcRulerKingdom)
			&& PolicyEffectModuleRetrievalSettings.IsContextSupported(module, PolicyEffectRetrievalContext.PlayerVassal),
			"Volunteer production/growth must be selectable from all three policy scopes and all four retrieval contexts.");

		Check(PolicyEffectModuleCatalog.TryNormalizePayload(
			module.Id,
			new JObject { ["value"] = 20f },
			PolicyEffectScopes.Local,
			out PolicyEffectPayload normalizedPayload,
			out string normalizeError)
			&& normalizedPayload is NumericPolicyEffectPayload numeric
			&& Math.Abs(numeric.Value - 20f) < 0.0001f,
			"Volunteer production/growth +20 payload must normalize: " + normalizeError);
		Check(PolicyEffectModuleCatalog.TryNormalizePayload(
			module.Id,
			new JObject { ["value"] = 500f },
			PolicyEffectScopes.Kingdom,
			out _,
			out _)
			&& !PolicyEffectModuleCatalog.TryNormalizePayload(
				module.Id,
				new JObject { ["value"] = float.NaN },
				PolicyEffectScopes.Kingdom,
				out _,
				out _)
			&& !PolicyEffectModuleCatalog.TryNormalizePayload(
				module.Id,
				new JObject { ["value"] = 20f, ["unexpected"] = true },
				PolicyEffectScopes.Kingdom,
				out _,
				out _),
			"Volunteer production/growth must preserve the old finite-number behavior without adding a positive hard cap, while rejecting non-finite and unknown fields.");
		Check(module.TryApplyFunding(
			normalizedPayload,
			new PolicyEffectFundingContext { GoldScale = 0.5f, InfluenceScale = 0.75f },
			out PolicyEffectPayload fundedPayload,
			out string fundingError)
			&& fundedPayload is NumericPolicyEffectPayload fundedNumeric
			&& Math.Abs(fundedNumeric.Value - 10f) < 0.0001f,
			"Volunteer production/growth must linearly inherit the lower policy funding fraction: " + fundingError);

		PolicyEffectCanonicalTargetSet targetSet = new PolicyEffectCanonicalTargetSet
		{
			SettlementIds = new List<string> { "volunteer-primary", "volunteer-bound-village" },
			ParentSettlementIds = new List<string> { "volunteer-primary" }
		};
		PolicyEffectPreparedInstance prepared = new PolicyEffectPreparedInstance
		{
			Descriptor = descriptor,
			IdempotencyKey = "volunteer-growth-prepared",
			Instance = new PolicyEffectInstance
			{
				InstanceId = "volunteer-growth-prepared",
				PolicyId = "volunteer-growth-policy",
				ModuleId = module.Id,
				SourceModuleId = module.Id,
				SourceScope = PolicyEffectScopes.Local,
				Payload = normalizedPayload,
				TargetSet = targetSet
			}
		};
		IReadOnlyList<PolicyEffectModelContribution> modelContributions =
			((IModelModifierPolicyEffectModule)module).BuildModelContributions(prepared);
		Check(modelContributions.Count == 2
			&& modelContributions.All(item => item.Hook == PolicyEffectHook.VolunteerProductionProbability
				&& item.TargetKind == PolicyEffectTargetKind.Settlement
				&& Math.Abs(item.Value - 20f) < 0.0001f)
			&& modelContributions.Select(item => item.TargetId).OrderBy(value => value, StringComparer.Ordinal)
				.SequenceEqual(new[] { "volunteer-bound-village", "volunteer-primary" }, StringComparer.Ordinal),
			"Volunteer production/growth must index the primary fief and bound villages as exact Settlement IDs.");

		PolicyEffectRuntimeContribution Contribution(
			string instanceId,
			float value,
			PolicyEffectAggregationKind aggregation = PolicyEffectAggregationKind.Additive)
			=> new PolicyEffectRuntimeContribution(
				instanceId,
				"volunteer-growth-policy-" + instanceId,
				module.Id,
				"志愿兵政策",
				PolicyEffectHook.VolunteerProductionProbability,
				PolicyEffectTargetKind.Settlement,
				"volunteer-primary",
				aggregation,
				value);
		Check(Math.Abs(CustomPolicyBehavior.CalculatePolicyVolunteerProductionAdjustedProbability(
			0.1f,
			new[] { Contribution("plus-20", 20f) }) - 0.12f) < 0.0001f,
			"+20 must multiply the vanilla volunteer probability by 120%, not add 20 probability points.");
		Check(Math.Abs(CustomPolicyBehavior.CalculatePolicyVolunteerProductionAdjustedProbability(
			0.1f,
			new[] { Contribution("plus-20", 20f), Contribution("plus-30", 30f) }) - 0.15f) < 0.0001f,
			"Multiple volunteer policy percentages must add before applying the old relative multiplier formula.");
		Check(Math.Abs(CustomPolicyBehavior.CalculatePolicyVolunteerProductionAdjustedProbability(
			0.1f,
			new[] { Contribution("minus-100", -100f) })) < 0.0001f
			&& Math.Abs(CustomPolicyBehavior.CalculatePolicyVolunteerProductionAdjustedProbability(
				0.25f,
				new[] { Contribution("plus-500", 500f) }) - 1f) < 0.0001f,
			"Volunteer policy probability must retain the old zero-multiplier floor and final [0,1] clamp.");
		Check(Math.Abs(CustomPolicyBehavior.CalculatePolicyVolunteerProductionAdjustedProbability(
			0.1f,
			new[] { Contribution("wrong-aggregation", 50f, PolicyEffectAggregationKind.PercentPoints) }) - 0.1f) < 0.0001f,
			"Volunteer runtime scaling must ignore contributions with an incompatible aggregation contract.");

		PolicyEffectInstanceSaveData displayInstance = BuildPlayerVisibleEffectInstance(
			"display-volunteer-growth",
			"M-volunteer",
			module.Id,
			20f,
			targetSet);
		List<string> display = PolicyEffectSaveCodec.DescribePlayerVisibleInstances(new[] { displayInstance });
		Check(display.Count == 1
			&& display[0].Contains("志愿兵补充与成长：相对原版每日判定频率 +20%")
			&& display[0].IndexOf("招募池刷新", StringComparison.Ordinal) < 0,
			"Volunteer player text must expose the abstract supplement/growth result and relative-frequency semantics.");

		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string promptPath = Path.Combine(repositoryRoot, "AnimusForge", "CustomPrompts", "Policy", "Effects", module.Id + ".json");
		Check(File.Exists(promptPath), "Volunteer production/growth prompt JSON is missing: " + promptPath);
		JObject prompt = JObject.Parse(File.ReadAllText(promptPath, Encoding.UTF8));
		Check(prompt.Value<int>("Version") == descriptor.PayloadSchemaVersion
			&& string.Equals(prompt.Value<string>("ModuleId"), module.Id, StringComparison.Ordinal)
			&& string.Equals(prompt.Value<string>("UnderstandingPrompt"), descriptor.EditableUnderstandingPrompt, StringComparison.Ordinal)
			&& string.Equals(prompt.Value<string>("EvaluationPrompt"), descriptor.EditableEvaluationPrompt, StringComparison.Ordinal)
			&& descriptor.MainInstruction.Contains("同一个数值")
			&& descriptor.MainInstruction.Contains("不给领主队伍或驻军士兵经验")
			&& !descriptor.PlayerDisplayName.Contains("招募池刷新"),
			"Volunteer prompt, fallback, one-value rule, and soldier-XP boundary must remain aligned.");
		IPolicyEffectModule soldierXp = RequirePolicyEffectModule("soldierTroopXp");
		Check(soldierXp.Descriptor.EditableUnderstandingPrompt.Contains("尚未招募的要人志愿兵槽位")
			&& soldierXp.Descriptor.MainInstruction.Contains("志愿兵补充与成长"),
			"soldierTroopXp must explicitly exclude pre-recruitment volunteer slots unless the policy separately grants fielded-troop XP.");

		string behaviorSource = File.ReadAllText(
			Path.Combine(repositoryRoot, "PolicySystem", "Core", "CustomPolicyBehavior.Effects.cs"),
			Encoding.UTF8);
		int postfixStart = behaviorSource.IndexOf("Patch_PolicyVolunteerProductionProbability_Postfix", StringComparison.Ordinal);
		int calculatorStart = behaviorSource.IndexOf("CalculatePolicyVolunteerProductionAdjustedProbability", postfixStart + 1, StringComparison.Ordinal);
		string postfixSource = postfixStart >= 0 && calculatorStart > postfixStart
			? behaviorSource.Substring(postfixStart, calculatorStart - postfixStart)
			: string.Empty;
		Check(postfixSource.Contains("PolicyEffectRuntimeIndex") == false
			&& postfixSource.Contains("GetContributions")
			&& postfixSource.IndexOf("VolunteerTypes[index]", StringComparison.Ordinal) < 0,
			"Volunteer postfix must use the cached exact-target lookup and must not branch on empty versus occupied slots.");
		Check(behaviorSource.Contains("PrimaryFiefAndBoundSettlements")
			&& behaviorSource.Contains("GetBoundVillageSettlements(primary)"),
			"The dedicated target projection must materialize the primary fief and its bound villages without changing global Settlement projection.");
	}

	private static void TestVolunteerProductionBannerlordApi()
	{
		Type volunteerModelType = typeof(TaleWorlds.CampaignSystem.ComponentInterfaces.VolunteerModel);
		Type settlementType = typeof(TaleWorlds.CampaignSystem.Settlements.Settlement);
		MethodInfo target = volunteerModelType.GetMethod(
			"GetDailyVolunteerProductionProbability",
			All,
			null,
			new[] { typeof(TaleWorlds.CampaignSystem.Hero), typeof(int), settlementType },
			null);
		Check(target != null
			&& target.ReturnType == typeof(float)
			&& target.GetParameters().Select(parameter => parameter.ParameterType).SequenceEqual(
				new[] { typeof(TaleWorlds.CampaignSystem.Hero), typeof(int), settlementType }),
			"Bannerlord VolunteerModel.GetDailyVolunteerProductionProbability must retain Hero,int,Settlement -> float in both supported API builds.");

		MethodInfo postfix = typeof(CustomPolicyBehavior).GetMethod("Patch_PolicyVolunteerProductionProbability_Postfix", All);
		ParameterInfo[] postfixParameters = postfix?.GetParameters();
		Check(postfix != null
			&& postfix.ReturnType == typeof(void)
			&& postfixParameters?.Length == 4
			&& postfixParameters[0].ParameterType == typeof(TaleWorlds.CampaignSystem.Hero)
			&& postfixParameters[1].ParameterType == typeof(int)
			&& postfixParameters[2].ParameterType == settlementType
			&& postfixParameters[3].ParameterType.IsByRef
			&& postfixParameters[3].ParameterType.GetElementType() == typeof(float),
			"Volunteer Harmony postfix must bind Hero,int,Settlement and ref float result exactly.");

		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string behaviorSource = File.ReadAllText(
			Path.Combine(repositoryRoot, "PolicySystem", "Core", "CustomPolicyBehavior.Effects.cs"),
			Encoding.UTF8);
		string gcczSource = File.ReadAllText(Path.Combine(repositoryRoot, "GcczVolunteerRecruitmentRatePatch.cs"), Encoding.UTF8);
		Check(behaviorSource.Contains("new Harmony(\"com.AnimusForge.custompolicy.settlementmodels\")")
			&& behaviorSource.Contains("Campaign.Current.Models.VolunteerModel, \"GetDailyVolunteerProductionProbability\""),
			"Volunteer policy must reuse the established policy settlement-model Harmony owner.");
		Check(gcczSource.Contains("priority = Priority.Last")
			&& gcczSource.Contains("after = new[] { \"com.AnimusForge.custompolicy.settlementmodels\" }")
			&& gcczSource.Contains("hero.VolunteerTypes[index] != null"),
			"GCCZ must remain after the policy postfix and continue applying only to empty volunteer slots.");
	}

	private static void TestArmyFormationTendencyModuleContracts()
	{
		IPolicyEffectModule module = RequirePolicyEffectModule("armyFormationTendencyPct");
		PolicyEffectModuleDescriptor descriptor = module.Descriptor;
		Check(descriptor.AllowedScopes.OrderBy(value => value, StringComparer.Ordinal)
			.SequenceEqual(new[] { PolicyEffectScopes.Kingdom, PolicyEffectScopes.Vassal }.OrderBy(value => value, StringComparer.Ordinal))
			&& descriptor.AllowedSelectorKinds.Count == 4
			&& descriptor.AllowedSelectorKinds.Contains(PolicyEffectTargetKind.Settlement)
			&& descriptor.AllowedSelectorKinds.Contains(PolicyEffectTargetKind.Clan)
			&& descriptor.AllowedSelectorKinds.Contains(PolicyEffectTargetKind.Kingdom)
			&& descriptor.AllowedSelectorKinds.Contains(PolicyEffectTargetKind.Hero)
			&& !descriptor.AllowedScopes.Contains(PolicyEffectScopes.Local, StringComparer.Ordinal),
			"Army formation tendency must support Kingdom/Vassal selectors while remaining unavailable to Local policies.");

		Check(module.TryNormalizePayload(
			new JObject
			{
				["moduleId"] = module.Id,
				["schemaVersion"] = descriptor.PayloadSchemaVersion,
				["value"] = 50f
			},
			PolicyEffectScopes.Kingdom,
			out PolicyEffectPayload normalizedPayload,
			out string normalizeError),
			"Army formation +50 payload must normalize: " + normalizeError);
		Check(!PolicyEffectModuleCatalog.TryNormalizePayload(module.Id, new JObject { ["value"] = -100.001f }, PolicyEffectScopes.Kingdom, out _, out _)
			&& !PolicyEffectModuleCatalog.TryNormalizePayload(module.Id, new JObject { ["value"] = 200.001f }, PolicyEffectScopes.Kingdom, out _, out _)
			&& !PolicyEffectModuleCatalog.TryNormalizePayload(module.Id, new JObject { ["value"] = float.NaN }, PolicyEffectScopes.Kingdom, out _, out _)
			&& !PolicyEffectModuleCatalog.TryNormalizePayload(module.Id, new JObject { ["value"] = 50f }, PolicyEffectScopes.Local, out _, out _),
			"Army formation payload must reject out-of-range, non-finite, and Local-scope input.");

		Check(module.TryApplyFunding(
			normalizedPayload,
			new PolicyEffectFundingContext { GoldScale = 0.5f, InfluenceScale = 0.75f },
			out PolicyEffectPayload fundedPayload,
			out string fundingError)
			&& fundedPayload is NumericPolicyEffectPayload fundedNumeric
			&& Math.Abs(fundedNumeric.Value - 25f) < 0.0001f,
			"Army formation tendency must linearly inherit the lower policy funding fraction: " + fundingError);

		PolicyEffectPreparedInstance prepared = new PolicyEffectPreparedInstance
		{
			Descriptor = descriptor,
			IdempotencyKey = "army-formation-prepared",
			Instance = new PolicyEffectInstance
			{
				InstanceId = "army-formation-prepared",
				PolicyId = "army-formation-policy",
				ModuleId = module.Id,
				SourceModuleId = module.Id,
				SourceScope = PolicyEffectScopes.Kingdom,
				Payload = normalizedPayload,
				TargetSet = new PolicyEffectCanonicalTargetSet
				{
					ClanIds = new List<string> { "army-formation-clan" }
				}
			}
		};
		IReadOnlyList<PolicyEffectModelContribution> modelContributions =
			((IModelModifierPolicyEffectModule)module).BuildModelContributions(prepared);
		Check(modelContributions.Count == 1
			&& modelContributions[0].Hook == PolicyEffectHook.ArmyFormationScore
			&& modelContributions[0].TargetKind == PolicyEffectTargetKind.Clan
			&& string.Equals(modelContributions[0].TargetId, "army-formation-clan", StringComparison.Ordinal)
			&& Math.Abs(modelContributions[0].Value - 50f) < 0.0001f,
			"Prepared army formation effects must project only the frozen Clan ID into the runtime index.");

		PolicyEffectRuntimeContribution Contribution(float value, PolicyEffectAggregationKind aggregation = PolicyEffectAggregationKind.Additive)
			=> new PolicyEffectRuntimeContribution(
				"army-formation-runtime-" + value.ToString("R", CultureInfo.InvariantCulture),
				"army-formation-policy",
				module.Id,
				"军团政策",
				PolicyEffectHook.ArmyFormationScore,
				PolicyEffectTargetKind.Clan,
				"army-formation-clan",
				aggregation,
				value);

		Check(Math.Abs(CustomPolicyBehavior.CalculatePolicyArmyFormationAdjustedScore(
			10f, new[] { Contribution(50f) }) - 15f) < 0.0001f,
			"+50 percent must multiply the vanilla-qualified candidate score by 1.5.");
		Check(Math.Abs(CustomPolicyBehavior.CalculatePolicyArmyFormationAdjustedScore(
			10f, new[] { Contribution(100f), Contribution(200f) }) - 30f) < 0.0001f,
			"Stacked positive policy contributions must clamp at the x3 runtime multiplier.");
		Check(Math.Abs(CustomPolicyBehavior.CalculatePolicyArmyFormationAdjustedScore(
			10f, new[] { Contribution(-100f) })) < 0.0001f
			&& Math.Abs(CustomPolicyBehavior.CalculatePolicyArmyFormationAdjustedScore(
				10f, new[] { Contribution(-100f), Contribution(-100f) })) < 0.0001f,
			"-100 percent and lower stacked totals must clamp the new-army candidate score to zero.");
		Check(Math.Abs(CustomPolicyBehavior.CalculatePolicyArmyFormationAdjustedScore(
			10f, new[] { Contribution(50f, PolicyEffectAggregationKind.PercentPoints) }) - 10f) < 0.0001f,
			"Army formation runtime scaling must ignore contributions with an incompatible aggregation contract.");

		PolicyEffectInstanceSaveData displayInstance = BuildPlayerVisibleEffectInstance(
			"display-army-formation",
			"M-army",
			module.Id,
			50f,
			prepared.Instance.TargetSet);
		List<string> display = PolicyEffectSaveCodec.DescribePlayerVisibleInstances(new[] { displayInstance });
		Check(display.Count == 1
			&& display[0].Contains("军团组建倾向：相对原版候选分数 +50%")
			&& display[0].IndexOf("税收", StringComparison.Ordinal) < 0,
			"RelativePercent player text must describe candidate-score scaling without reusing tax wording.");

		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string promptPath = Path.Combine(repositoryRoot, "AnimusForge", "CustomPrompts", "Policy", "Effects", module.Id + ".json");
		Check(File.Exists(promptPath), "Army formation prompt JSON is missing: " + promptPath);
		JObject prompt = JObject.Parse(File.ReadAllText(promptPath, Encoding.UTF8));
		Check(prompt.Value<int>("Version") == descriptor.PayloadSchemaVersion
			&& string.Equals(prompt.Value<string>("ModuleId"), module.Id, StringComparison.Ordinal)
			&& prompt.Value<string>("UnderstandingPrompt")?.Contains("不绕过") == true
			&& prompt.Value<string>("EvaluationPrompt")?.Contains("绝对概率") == true,
			"Army formation prompt must match the module ID/version and preserve qualification/probability exclusions.");
	}

	private static void TestArmyFormationBannerlordApi()
	{
		Type tupleType = typeof(ValueTuple<TaleWorlds.CampaignSystem.AIBehaviorData, float>);
		Type partyThinkParamsType = typeof(TaleWorlds.CampaignSystem.PartyThinkParams);
		MethodInfo target = partyThinkParamsType.GetMethod("AddBehaviorScore", All);
		ParameterInfo[] targetParameters = target?.GetParameters();
		Check(target != null
			&& target.ReturnType == typeof(void)
			&& targetParameters?.Length == 1
			&& targetParameters[0].ParameterType.IsByRef
			&& targetParameters[0].ParameterType.GetElementType() == tupleType
			&& targetParameters[0].IsIn
			&& !targetParameters[0].IsOut
			&& string.Equals(targetParameters[0].Name, "value", StringComparison.Ordinal),
			"Bannerlord PartyThinkParams.AddBehaviorScore must retain its verified in ValueTuple<AIBehaviorData,float> metadata.");

		MethodInfo prefix = typeof(CustomPolicyBehavior).GetMethod("Patch_PolicyArmyFormationScore_Prefix", All);
		ParameterInfo[] prefixParameters = prefix?.GetParameters();
		Check(prefix != null
			&& prefix.ReturnType == typeof(void)
			&& prefixParameters?.Length == 2
			&& prefixParameters[0].ParameterType == partyThinkParamsType
			&& string.Equals(prefixParameters[0].Name, "__instance", StringComparison.Ordinal)
			&& prefixParameters[1].ParameterType.IsByRef
			&& prefixParameters[1].ParameterType.GetElementType() == tupleType
			&& string.Equals(prefixParameters[1].Name, "__0", StringComparison.Ordinal),
			"Harmony prefix must bind the readonly tuple by argument index and expose it as ref for score replacement.");

		MethodInfo installer = typeof(CustomPolicyBehavior).GetMethod("ApplyPolicyArmyFormationPatchesOnce", All);
		FieldInfo installedField = typeof(CustomPolicyBehavior).GetField("_policyArmyFormationPatchesApplied", All);
		Check(installer != null && installedField != null,
			"Army formation Harmony installer contract is missing.");
		installer.Invoke(null, null);
		Check((bool)installedField.GetValue(null),
			"Army formation Harmony installer must accept the verified readonly target and ref prefix signatures.");

		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string lifecycleSource = File.ReadAllText(
			Path.Combine(repositoryRoot, "PolicySystem", "Core", "CustomPolicyBehavior.Lifecycle.cs"),
			Encoding.UTF8);
		Check(lifecycleSource.Split(
			new[] { "ApplyPolicyArmyFormationPatchesOnce();" },
			StringSplitOptions.None).Length - 1 == 2,
			"Army formation patch installation must remain wired exactly once in each load/session lifecycle path.");
	}

	private static void TestKingdomVillageRaidBanModuleContracts()
	{
		IPolicyEffectModule module = RequirePolicyEffectModule("kingdomVillageRaidBan");
		PolicyEffectModuleDescriptor descriptor = module.Descriptor;
		Check(descriptor.Order == 160
			&& descriptor.ExecutionKind == PolicyEffectExecutionKind.ModelModifier
			&& descriptor.Hook == PolicyEffectHook.KingdomVillageRaidBlock
			&& descriptor.Aggregation == PolicyEffectAggregationKind.AnyBlock
			&& descriptor.ValueUnit == PolicyEffectValueUnit.BooleanFlag
			&& descriptor.FundingMode == PolicyEffectFundingMode.Unscaled
			&& descriptor.FundingStrategy == PolicyEffectFundingStrategy.None
			&& descriptor.TargetRefresh == PolicyEffectTargetRefreshKind.FrozenCanonicalIds
			&& descriptor.TargetBinding == PolicyEffectTargetBindingKind.IssuerKingdom
			&& descriptor.AllowedScopes.SequenceEqual(new[] { PolicyEffectScopes.Kingdom })
			&& descriptor.AllowedSelectorKinds.SequenceEqual(new[] { PolicyEffectTargetKind.Kingdom })
			&& descriptor.TargetKinds.SequenceEqual(new[] { PolicyEffectTargetKind.Kingdom })
			&& module is IModelModifierPolicyEffectModule,
			"kingdomVillageRaidBan must remain one issuer-Kingdom-bound BooleanFlag model modifier.");
		Check(PolicyEffectModuleRetrievalSettings.IsContextSupported(module, PolicyEffectRetrievalContext.PlayerKingdom)
			&& PolicyEffectModuleRetrievalSettings.IsContextSupported(module, PolicyEffectRetrievalContext.NpcRulerKingdom)
			&& !PolicyEffectModuleRetrievalSettings.IsContextSupported(module, PolicyEffectRetrievalContext.PlayerLocal)
			&& !PolicyEffectModuleRetrievalSettings.IsContextSupported(module, PolicyEffectRetrievalContext.PlayerVassal),
			"Village raid ban retrieval must be available only to player and NPC ruler Kingdom contexts.");

		Check(module.TryNormalizePayload(
			new JObject(),
			PolicyEffectScopes.Kingdom,
			out PolicyEffectPayload normalizedPayload,
			out string normalizeError),
			"Empty marker payload must normalize for kingdomVillageRaidBan: " + normalizeError);
		Check(string.Equals(normalizedPayload.ModuleId, module.Id, StringComparison.Ordinal)
			&& normalizedPayload.SchemaVersion == descriptor.PayloadSchemaVersion,
			"Marker normalization must freeze module identity and schema version.");
		Check(!module.TryNormalizePayload(new JObject { ["value"] = true }, PolicyEffectScopes.Kingdom, out _, out _)
			&& !module.TryNormalizePayload(new JValue(true), PolicyEffectScopes.Kingdom, out _, out _)
			&& !module.TryNormalizePayload(new JObject(), PolicyEffectScopes.Local, out _, out _),
			"Village raid ban marker payload must reject fields, non-objects, and non-Kingdom scopes.");
		Check(module.TryApplyFunding(
			normalizedPayload,
			new PolicyEffectFundingContext { GoldScale = 0f, InfluenceScale = 0f },
			out PolicyEffectPayload fundedPayload,
			out string fundingError)
			&& ReferenceEquals(fundedPayload, normalizedPayload),
			"Village raid ban must remain an unscaled binary rule: " + fundingError);

		PolicyEffectCompileContext prepareContext = new PolicyEffectCompileContext
		{
			InstanceId = "village-raid-ban-instance",
			PolicyId = "village-raid-ban-policy",
			ActorHeroId = "issuer-ruler",
			Module = module,
			SourceModuleId = module.Id,
			SourceScope = PolicyEffectScopes.Kingdom,
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				KingdomIds = new List<string> { "issuer-kingdom" }
			},
			Payload = fundedPayload,
			Funding = new PolicyEffectFundingContext(),
			IdempotencyKey = "village-raid-ban-instance:v1"
		};
		PolicyEffectPrepareResult prepare = module.Prepare(prepareContext, fundedPayload);
		Check(prepare.Success && prepare.PreparedInstance?.Instance != null,
			"Village raid ban must prepare one frozen issuer Kingdom target: " + prepare.Error);
		IReadOnlyList<PolicyEffectModelContribution> contributions =
			((IModelModifierPolicyEffectModule)module).BuildModelContributions(prepare.PreparedInstance);
		Check(contributions.Count == 1
			&& contributions[0].Hook == PolicyEffectHook.KingdomVillageRaidBlock
			&& contributions[0].TargetKind == PolicyEffectTargetKind.Kingdom
			&& string.Equals(contributions[0].TargetId, "issuer-kingdom", StringComparison.Ordinal)
			&& Math.Abs(contributions[0].Value - 1f) < 0.0001f,
			"Village raid ban must publish exactly one issuer Kingdom AnyBlock contribution.");
		prepareContext.TargetSet = new PolicyEffectCanonicalTargetSet
		{
			KingdomIds = new List<string> { "issuer-kingdom", "foreign-kingdom" }
		};
		Check(!module.Prepare(prepareContext, fundedPayload).Success,
			"Village raid ban module preparation must reject multiple Kingdom targets.");

		PolicyEffectTargetResolver resolver = delegate(
			string handle,
			IPolicyEffectModule ignoredModule,
			out PolicyEffectResolvedTarget resolved,
			out string error)
		{
			_ = ignoredModule;
			string kingdomId = string.Equals(handle, "K0", StringComparison.Ordinal)
				? "issuer-kingdom"
				: string.Equals(handle, "K1", StringComparison.Ordinal)
					? "foreign-kingdom"
					: string.Empty;
			resolved = kingdomId.Length == 0
				? null
				: new PolicyEffectResolvedTarget
				{
					Handle = handle,
					SelectorKind = PolicyEffectTargetKind.Kingdom,
					CanonicalTargetSet = new PolicyEffectCanonicalTargetSet
					{
						KingdomIds = new List<string> { kingdomId }
					}
				};
			error = resolved == null ? "unknown handle" : string.Empty;
			return resolved != null;
		};
		PolicyTargetHandleDirectory directory = PolicyTargetHandleDirectoryBuilder.Build(
			new[]
			{
				new PolicyTargetHandleDirectoryCandidate
				{
					Handle = "K0",
					Entry = new PolicyTargetHandleDirectoryEntry { Kind = "kingdom", EntityId = "issuer-kingdom" }
				},
				new PolicyTargetHandleDirectoryCandidate
				{
					Handle = "K1",
					Entry = new PolicyTargetHandleDirectoryEntry { Kind = "kingdom", EntityId = "foreign-kingdom" }
				}
			},
			new[] { module },
			resolver,
			"issuer-kingdom",
			string.Empty,
			(handle, entry, currentModule, resolved) => string.Equals(entry?.EntityId, "issuer-kingdom", StringComparison.Ordinal));
		Check(directory.Capabilities.TryGetValue(module.Id, out PolicyEffectCapabilityDirectoryEntry capability)
			&& capability.AllowedTargetHandles.SequenceEqual(new[] { "K0" }, StringComparer.Ordinal)
			&& string.Equals(capability.DefaultTargetHandle, "K0", StringComparison.Ordinal)
			&& capability.AllowedSubsetTargetHandles.Count == 0
			&& directory.Targets.Count == 1
			&& directory.Targets.ContainsKey("K0"),
			"Issuer-bound target directory must expose only the publisher Kingdom handle.");
		Check(PolicyEffectCompiler.IsTargetBindingAuthorizedForModule(
				module,
				new PolicyEffectCanonicalTargetSet { KingdomIds = new List<string> { "issuer-kingdom" } },
				"issuer-kingdom")
			&& !PolicyEffectCompiler.IsTargetBindingAuthorizedForModule(
				module,
				new PolicyEffectCanonicalTargetSet { KingdomIds = new List<string> { "foreign-kingdom" } },
				"issuer-kingdom")
			&& !PolicyEffectCompiler.IsTargetBindingAuthorizedForModule(
				module,
				new PolicyEffectCanonicalTargetSet { KingdomIds = new List<string> { "issuer-kingdom" } },
				string.Empty),
			"Issuer binding must fail closed for foreign, missing, or tampered persisted targets.");

		PolicyEffectCompilerRequest compilerRequest = new PolicyEffectCompilerRequest
		{
			Scope = PolicyEffectScopes.Kingdom,
			PolicyId = "village-raid-ban-compile",
			ActorHeroId = "issuer-ruler",
			IssuerKingdomId = "issuer-kingdom",
			StartDay = 10f,
			EndDay = 20f,
			Funding = new PolicyEffectFundingContext { GoldScale = 0f, InfluenceScale = 0f },
			CandidateModuleIds = new[] { module.Id },
			DetailedModuleIds = new[] { module.Id }
		};
		PolicyEffectWireEffect BuildWire(string targetHandle) => new PolicyEffectWireEffect
		{
			EffectPlanVersion = 1,
			MechanismId = "M0",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			ModuleId = module.Id,
			TargetHandles = new List<string> { targetHandle },
			Payload = new JObject(),
			Reason = "禁止本国领主烧村"
		};
		PolicyEffectInstanceIdFactory idFactory = (ordinal, moduleId, targetSet) =>
			"village-raid-ban-compile:" + ordinal.ToString(CultureInfo.InvariantCulture);
		Check(PolicyEffectCompiler.TryCompile(
			new[] { BuildWire("K0") },
			compilerRequest,
			resolver,
			idFactory,
			out PolicyEffectCompilerResult compiled,
			out string compileError)
			&& compiled.Effects.Count == 1,
			"Compiler must accept the issuer Kingdom handle for the raid-ban module: " + compileError);
		Check(!PolicyEffectCompiler.TryCompile(
			new[] { BuildWire("K1") },
			compilerRequest,
			resolver,
			idFactory,
			out PolicyEffectCompilerResult foreignCompiled,
			out string foreignError)
			&& (foreignCompiled?.Effects?.Count ?? 0) == 0
			&& !string.IsNullOrWhiteSpace(foreignError),
			"Compiler must reject a foreign Kingdom handle for the issuer-bound raid-ban module.");

		PolicyEffectRuntimeContribution RuntimeContribution(
			string instanceId,
			float value,
			PolicyEffectAggregationKind aggregation) => new PolicyEffectRuntimeContribution(
				instanceId,
				"village-raid-ban-policy",
				module.Id,
				"禁掠政策",
				PolicyEffectHook.KingdomVillageRaidBlock,
				PolicyEffectTargetKind.Kingdom,
				"issuer-kingdom",
				aggregation,
				value);
		Check(CustomPolicyBehavior.HasPolicyVillageRaidBlock(new[]
			{
				RuntimeContribution("raid-ban-one", 1f, PolicyEffectAggregationKind.AnyBlock)
			})
			&& CustomPolicyBehavior.HasPolicyVillageRaidBlock(new[]
			{
				RuntimeContribution("raid-ban-one", 1f, PolicyEffectAggregationKind.AnyBlock),
				RuntimeContribution("raid-ban-two", 1f, PolicyEffectAggregationKind.AnyBlock)
			})
			&& !CustomPolicyBehavior.HasPolicyVillageRaidBlock(new[]
			{
				RuntimeContribution("raid-ban-zero", 0f, PolicyEffectAggregationKind.AnyBlock),
				RuntimeContribution("raid-ban-wrong-kind", 1f, PolicyEffectAggregationKind.Additive)
			}),
			"AnyBlock runtime semantics must be non-stacking and require at least one positive compatible contribution.");

		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string promptPath = Path.Combine(repositoryRoot, "AnimusForge", "CustomPrompts", "Policy", "Effects", module.Id + ".json");
		Check(File.Exists(promptPath), "Village raid ban prompt JSON is missing: " + promptPath);
		JObject prompt = JObject.Parse(File.ReadAllText(promptPath, Encoding.UTF8));
		Check(prompt.Value<int>("Version") == descriptor.PayloadSchemaVersion
			&& string.Equals(prompt.Value<string>("ModuleId"), module.Id, StringComparison.Ordinal)
			&& prompt.Value<string>("UnderstandingPrompt")?.Contains("发布者所属王国") == true
			&& prompt.Value<string>("UnderstandingPrompt")?.Contains("全局护盾") == true
			&& prompt.Value<string>("EvaluationPrompt")?.Contains("不判断强度或概率") == true
			&& prompt.Value<string>("EvaluationPrompt")?.Contains("{}") == false
			&& descriptor.PostprocessRule.Contains("payload 必须严格为 {}"),
			"Village raid ban prompt must preserve issuer-only, non-shield, and non-stacking semantics.");
	}

	private static void TestKingdomVillageRaidBanBannerlordApi()
	{
		Type mobilePartyType = typeof(TaleWorlds.CampaignSystem.Party.MobileParty);
		Type settlementType = typeof(TaleWorlds.CampaignSystem.Settlements.Settlement);
		Type navigationType = typeof(TaleWorlds.CampaignSystem.Party.MobileParty.NavigationType);
		MethodInfo setMoveRaidSettlement = mobilePartyType.GetMethods(All)
			.SingleOrDefault(method => string.Equals(method.Name, "SetMoveRaidSettlement", StringComparison.Ordinal)
				&& method.GetParameters().Length >= 2
				&& method.GetParameters()[0].ParameterType == settlementType
				&& method.GetParameters()[1].ParameterType == navigationType);
		ParameterInfo[] setMoveParameters = setMoveRaidSettlement?.GetParameters();
		Check(setMoveRaidSettlement != null
			&& (setMoveParameters.Length == 2
				|| (setMoveParameters.Length == 3 && setMoveParameters[2].ParameterType == typeof(bool))),
			"Bannerlord SetMoveRaidSettlement must match the verified 1.3 two-parameter or 1.4 three-parameter signature.");

		Type startBattleActionType = typeof(TaleWorlds.CampaignSystem.Actions.StartBattleAction);
		MethodInfo applyStartRaid = startBattleActionType.GetMethod(
			"ApplyStartRaid",
			All,
			null,
			new[] { mobilePartyType, settlementType },
			null);
		Check(applyStartRaid != null && applyStartRaid.ReturnType == typeof(void),
			"Bannerlord StartBattleAction.ApplyStartRaid(MobileParty, Settlement) signature is missing.");

		Type raidEventType = typeof(TaleWorlds.CampaignSystem.MapEvents.RaidEventComponent);
		MethodInfo updateRaid = raidEventType.GetMethod("Update", All);
		ParameterInfo[] updateParameters = updateRaid?.GetParameters();
		Check(updateRaid != null
			&& updateParameters?.Length == 1
			&& updateParameters[0].ParameterType == typeof(bool).MakeByRefType(),
			"Bannerlord RaidEventComponent.Update(ref bool) signature is missing.");

		MethodInfo setMovePrefix = typeof(CustomPolicyBehavior).GetMethod("Patch_PolicyVillageRaidSetMove_Prefix", All);
		MethodInfo startPrefix = typeof(CustomPolicyBehavior).GetMethod("Patch_PolicyVillageRaidStart_Prefix", All);
		MethodInfo updatePrefix = typeof(CustomPolicyBehavior).GetMethod("Patch_PolicyVillageRaidUpdate_Prefix", All);
		Check(setMovePrefix?.ReturnType == typeof(bool)
			&& setMovePrefix.GetParameters().Length == 2
			&& setMovePrefix.GetParameters()[0].ParameterType == mobilePartyType
			&& setMovePrefix.GetParameters()[1].ParameterType == settlementType,
			"SetMoveRaidSettlement prefix must use the shared cross-version instance/settlement signature.");
		Check(startPrefix?.ReturnType == typeof(bool)
			&& startPrefix.GetParameters().Length == 2
			&& startPrefix.GetParameters()[0].ParameterType == mobilePartyType
			&& startPrefix.GetParameters()[1].ParameterType == settlementType,
			"ApplyStartRaid prefix signature is invalid.");
		Check(updatePrefix?.ReturnType == typeof(bool)
			&& updatePrefix.GetParameters().Length == 2
			&& updatePrefix.GetParameters()[0].ParameterType == raidEventType
			&& updatePrefix.GetParameters()[1].ParameterType == typeof(bool).MakeByRefType(),
			"RaidEventComponent.Update prefix must bind ref bool finish.");

		MethodInfo installer = typeof(CustomPolicyBehavior).GetMethod("ApplyPolicyVillageRaidBanPatchesOnce", All);
		FieldInfo installedField = typeof(CustomPolicyBehavior).GetField("_policyVillageRaidBanPatchesApplied", All);
		Check(installer != null && installedField != null,
			"Village raid ban shared Harmony installer contract is missing.");
		installer.Invoke(null, null);
		Check((bool)installedField.GetValue(null),
			"Village raid ban Harmony installer must accept all verified Bannerlord signatures.");

		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string lifecycleSource = File.ReadAllText(
			Path.Combine(repositoryRoot, "PolicySystem", "Core", "CustomPolicyBehavior.Lifecycle.cs"),
			Encoding.UTF8);
		Check(lifecycleSource.Split(
			new[] { "ApplyPolicyVillageRaidBanPatchesOnce();" },
			StringSplitOptions.None).Length - 1 == 2,
			"Village raid ban patch installation must remain wired exactly once in each load/session lifecycle path.");
		string moduleSource = File.ReadAllText(
			Path.Combine(repositoryRoot, "PolicySystem", "Effects", "Modules", "kingdomVillageRaidBan", "KingdomVillageRaidBanEffectModule.cs"),
			Encoding.UTF8);
		Check(moduleSource.IndexOf("Harmony", StringComparison.Ordinal) < 0,
			"Village raid ban source module must not install or reference Harmony.");
	}

	private static void TestPolicyEffectRetrievalSettingsContracts()
	{
		string tempRoot = Path.Combine(Path.GetTempPath(), "af-policy-effect-retrieval-settings-" + Guid.NewGuid().ToString("N"));
		Directory.CreateDirectory(tempRoot);
		PolicyEffectModuleRetrievalSettings.SetStorageDirectoryOverrideForContractTests(tempRoot);
		try
		{
			PolicyEffectModuleRetrievalSettings.ReloadForContractTests();
			IPolicyEffectModule stability = RequirePolicyEffectModule("kingdomStability");
			IPolicyEffectModule armyFormation = RequirePolicyEffectModule("armyFormationTendencyPct");
			Check(PolicyEffectModuleRetrievalSettings.IsContextSupported(stability, PolicyEffectRetrievalContext.PlayerKingdom)
				&& !PolicyEffectModuleRetrievalSettings.IsContextSupported(stability, PolicyEffectRetrievalContext.PlayerLocal)
				&& PolicyEffectModuleRetrievalSettings.IsContextSupported(stability, PolicyEffectRetrievalContext.NpcRulerKingdom)
				&& PolicyEffectModuleRetrievalSettings.IsContextSupported(stability, PolicyEffectRetrievalContext.PlayerVassal),
				"Retrieval contexts must enforce module AllowedScopes, including a permanently unavailable local kingdom-stability cell.");
			Check(PolicyEffectModuleRetrievalSettings.IsContextSupported(armyFormation, PolicyEffectRetrievalContext.PlayerKingdom)
				&& !PolicyEffectModuleRetrievalSettings.IsContextSupported(armyFormation, PolicyEffectRetrievalContext.PlayerLocal)
				&& PolicyEffectModuleRetrievalSettings.IsContextSupported(armyFormation, PolicyEffectRetrievalContext.NpcRulerKingdom)
				&& PolicyEffectModuleRetrievalSettings.IsContextSupported(armyFormation, PolicyEffectRetrievalContext.PlayerVassal),
				"Army formation tendency retrieval must be available only in Kingdom, NPC-ruler, and Vassal contexts.");
			Check(!PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.PlayerLocal)
				.Any(module => string.Equals(module.Id, stability.Id, StringComparison.Ordinal))
				&& PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.PlayerKingdom)
				.Any(module => string.Equals(module.Id, stability.Id, StringComparison.Ordinal)),
				"Default retrieval settings must enable supported contexts while excluding unsupported contexts.");
			Check(HiddenRuntimeModuleIds.All(hiddenId => Enum.GetValues(typeof(PolicyEffectRetrievalContext))
				.Cast<PolicyEffectRetrievalContext>()
				.All(context => PolicyEffectModuleRetrievalSettings.GetEnabledModules(context)
					.All(module => !string.Equals(module.Id, hiddenId, StringComparison.Ordinal)))),
				"Hidden runtime descendants must never enter any configurable retrieval context.");

			Check(armyFormation.TryNormalizePayload(
				new JObject
				{
					["moduleId"] = armyFormation.Id,
					["schemaVersion"] = armyFormation.Descriptor.PayloadSchemaVersion,
					["value"] = 50f
				},
				PolicyEffectScopes.Kingdom,
				out PolicyEffectPayload frozenArmyPayload,
				out string frozenArmyError),
				"Army formation active-snapshot fixture must normalize before its future retrieval toggle is disabled: " + frozenArmyError);
			PolicyEffectPreparedInstance frozenArmyPrepared = new PolicyEffectPreparedInstance
			{
				Descriptor = armyFormation.Descriptor,
				IdempotencyKey = "frozen-army-retrieval",
				Instance = new PolicyEffectInstance
				{
					InstanceId = "frozen-army-retrieval",
					PolicyId = "frozen-army-policy",
					ModuleId = armyFormation.Id,
					SourceModuleId = armyFormation.Id,
					SourceScope = PolicyEffectScopes.Kingdom,
					Payload = frozenArmyPayload,
					TargetSet = new PolicyEffectCanonicalTargetSet
					{
						ClanIds = new List<string> { "frozen-army-clan" }
					}
				}
			};

			Dictionary<string, PolicyEffectModuleRetrievalState> staged = PolicyEffectModuleRetrievalSettings.CreateEditableStateSnapshot();
			staged[stability.Id].PlayerPolicyEnabled = false;
			staged[armyFormation.Id].PlayerPolicyEnabled = false;
			staged["foodPerDay"].RulerPolicyEnabled = false;
			Check(PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.PlayerKingdom)
				.Any(module => string.Equals(module.Id, stability.Id, StringComparison.Ordinal)),
				"Editing a detached UI state must not affect retrieval until the user saves.");
			Check(PolicyEffectModuleRetrievalSettings.TrySave(staged, out string saveError),
				"Retrieval settings must save atomically: " + saveError);
			Check(!PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.PlayerKingdom)
				.Any(module => string.Equals(module.Id, stability.Id, StringComparison.Ordinal))
				&& PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.NpcRulerKingdom)
				.Any(module => string.Equals(module.Id, stability.Id, StringComparison.Ordinal))
				&& PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.PlayerVassal)
				.Any(module => string.Equals(module.Id, stability.Id, StringComparison.Ordinal))
				&& !PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.NpcRulerKingdom)
					.Any(module => string.Equals(module.Id, "foodPerDay", StringComparison.Ordinal))
				&& PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.PlayerKingdom)
					.Any(module => string.Equals(module.Id, "foodPerDay", StringComparison.Ordinal))
				&& !PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.PlayerKingdom)
					.Any(module => string.Equals(module.Id, armyFormation.Id, StringComparison.Ordinal))
				&& PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.NpcRulerKingdom)
					.Any(module => string.Equals(module.Id, armyFormation.Id, StringComparison.Ordinal)),
				"Player, local, ruler, and vassal retrieval switches must remain independent.");
			Check(((IModelModifierPolicyEffectModule)armyFormation).BuildModelContributions(frozenArmyPrepared).Count == 1,
				"Disabling future army-formation retrieval must not act as a runtime kill switch for an already frozen active instance.");

			const string multiCue = "稳定度改革；增加粮食储备；加强治安巡逻；调整税率；推进工程施工";
			IReadOnlyList<string> playerIntents = PolicyEffectModuleRouter.BuildQueryIntents(
				multiCue,
				PolicyEffectRetrievalContext.PlayerKingdom);
			IReadOnlyList<string> rulerIntents = PolicyEffectModuleRouter.BuildQueryIntents(
				multiCue,
				PolicyEffectRetrievalContext.NpcRulerKingdom);
			Check(playerIntents.Any(intent => string.Equals(intent, "稳定度改革", StringComparison.Ordinal))
				&& rulerIntents.Any(intent => string.Equals(intent, "稳定度改革", StringComparison.Ordinal)),
				"Bounded clause queries may preserve policy prose, while module enablement is enforced before semantic recall and injection.");

			IPolicyEffectModule food = RequirePolicyEffectModule("foodPerDay");
			IReadOnlyList<PolicyEffectModuleIntentRecall> syntheticRecall = new[]
			{
				BuildIntentRecall(0, true, "稳定度与粮食", (stability, 0.99f), (food, 0.98f))
			};
			IReadOnlyList<PolicyEffectModuleSelection> playerCandidates = PolicyEffectModuleRouter.MergeCandidates(
				syntheticRecall,
				PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.PlayerKingdom),
				"稳定度与粮食",
				out _,
				out _);
			IReadOnlyList<PolicyEffectModuleSelection> rulerCandidates = PolicyEffectModuleRouter.MergeCandidates(
				syntheticRecall,
				PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.NpcRulerKingdom),
				"稳定度与粮食",
				out _,
				out _);
			Check(playerCandidates.All(selection => !string.Equals(selection.Module.Id, stability.Id, StringComparison.Ordinal))
				&& playerCandidates.Any(selection => string.Equals(selection.Module.Id, food.Id, StringComparison.Ordinal))
				&& rulerCandidates.Any(selection => string.Equals(selection.Module.Id, stability.Id, StringComparison.Ordinal))
				&& rulerCandidates.All(selection => !string.Equals(selection.Module.Id, food.Id, StringComparison.Ordinal)),
				"Candidate merging must ignore high-scoring disabled modules instead of allowing vector or cue hits to bypass the channel snapshot.");

			string settingsPath = Path.Combine(tempRoot, PolicyEffectModuleRetrievalSettings.FileName);
			JObject document = JObject.Parse(File.ReadAllText(settingsPath, Encoding.UTF8));
			((JObject)document["Modules"])["future.module.kept"] = new JObject
			{
				["PlayerPolicyEnabled"] = false,
				["LocalPolicyEnabled"] = true,
				["RulerPolicyEnabled"] = false,
				["VassalPolicyEnabled"] = true
			};
			File.WriteAllText(settingsPath, document.ToString(Formatting.Indented), new UTF8Encoding(false));
			PolicyEffectModuleRetrievalSettings.ReloadForContractTests();
			Dictionary<string, PolicyEffectModuleRetrievalState> secondSave = PolicyEffectModuleRetrievalSettings.CreateEditableStateSnapshot();
			secondSave["prosperityPerDay"].LocalPolicyEnabled = false;
			Check(PolicyEffectModuleRetrievalSettings.TrySave(secondSave, out saveError)
				&& ((JObject)JObject.Parse(File.ReadAllText(settingsPath, Encoding.UTF8))["Modules"])["future.module.kept"] != null,
				"Saving known dynamic module states must preserve unknown future module entries.");
			PolicyEffectModuleRetrievalSettings.ReloadForContractTests();
			Check(!PolicyEffectModuleRetrievalSettings.GetEnabledModules(PolicyEffectRetrievalContext.PlayerLocal)
				.Any(module => string.Equals(module.Id, "prosperityPerDay", StringComparison.Ordinal)),
				"Saved channel settings must survive an explicit reload.");
		}
		finally
		{
			PolicyEffectModuleRetrievalSettings.SetStorageDirectoryOverrideForContractTests(null);
			try { Directory.Delete(tempRoot, recursive: true); } catch { }
		}
	}

	private static void TestSoldierTroopXpModuleContracts()
	{
		Check(!PolicyEffectModuleCatalog.TryGet("lordPartyTroopXp", out _)
			&& !PolicyEffectModuleCatalog.TryGet("lordPartyTroopXpOnce", out _)
			&& !PolicyEffectModuleCatalog.TryGet("lordPartyTroopXpPerDay", out _),
			"The three unpublished lordPartyTroopXp IDs must not remain registered or aliased.");
		Check(PolicyEffectModuleCatalog.TryGet("soldierTroopXp", out IPolicyEffectModule composite),
			"Visible soldierTroopXp Composite must be registered.");
		Check(composite.Descriptor.PromptVisible
			&& composite.Descriptor.ExecutionKind == PolicyEffectExecutionKind.Composite
			&& composite.Descriptor.Hook == PolicyEffectHook.DailyScheduler
			&& composite.Descriptor.Family == PolicyEffectFamily.Military
			&& composite is IPolicyEffectCompositeModule
			&& string.Equals(composite.Descriptor.DisplayGroup, "soldierTroopXp", StringComparison.Ordinal),
			"soldierTroopXp must be a visible military Composite.");
		Check(composite.Descriptor.TargetKinds.SequenceEqual(new[] { PolicyEffectTargetKind.Clan })
			&& new HashSet<PolicyEffectTargetKind>(composite.Descriptor.AllowedSelectorKinds)
				.SetEquals(new[]
				{
					PolicyEffectTargetKind.Settlement,
					PolicyEffectTargetKind.Clan,
					PolicyEffectTargetKind.Kingdom,
					PolicyEffectTargetKind.Hero
				})
			&& composite.Descriptor.TargetProjection == PolicyEffectTargetProjectionKind.None
			&& composite.Descriptor.TargetRefresh == PolicyEffectTargetRefreshKind.FrozenCanonicalIds
			&& composite.Descriptor.AllowIndependentClanTargets,
			"soldierTroopXp must canonicalize every supported selector to frozen Clan IDs, including independent Clans.");
		Check(((IPolicyEffectCompositeModule)composite).RuntimeModuleIds
			.SequenceEqual(new[] { "soldierTroopXpOnce", "soldierTroopXpPerDay" }, StringComparer.Ordinal),
			"soldierTroopXp must declare exactly its once and daily runtime descendants.");
		Check(composite.Descriptor.CueTerms.Contains("精锐化")
			&& composite.Descriptor.EditableEvaluationPrompt.IndexOf("每日60已属极强", StringComparison.Ordinal) >= 0
			&& composite.Descriptor.EditableEvaluationPrompt.IndexOf("1700", StringComparison.Ordinal) >= 0
			&& composite.Descriptor.EditableUnderstandingPrompt.IndexOf("onceDelta", StringComparison.OrdinalIgnoreCase) < 0
			&& composite.Descriptor.EditableUnderstandingPrompt.IndexOf("dailyDelta", StringComparison.OrdinalIgnoreCase) < 0
			&& composite.Descriptor.EditableUnderstandingPrompt.IndexOf("语义腿", StringComparison.Ordinal) < 0
			&& composite.Descriptor.EditableUnderstandingPrompt.IndexOf("assignment", StringComparison.OrdinalIgnoreCase) < 0
			&& composite.Descriptor.EditableUnderstandingPrompt.IndexOf("effectIntents", StringComparison.OrdinalIgnoreCase) < 0
			&& composite.Descriptor.MainInstruction.IndexOf("先集中整编", StringComparison.Ordinal) >= 0
			&& composite.PostprocessRule.IndexOf("不得把 dailyDelta 乘", StringComparison.Ordinal) >= 0,
			"The visible module prompt must keep only domain lifecycle semantics and vanilla-calibrated limits, without shared semantic-ledger wire terminology.");
		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string customPromptText = File.ReadAllText(
			Path.Combine(repositoryRoot, "AnimusForge", "CustomPrompts", "Policy", "Effects", "soldierTroopXp.json"),
			Encoding.UTF8);
		Check(customPromptText.IndexOf("语义腿", StringComparison.Ordinal) < 0
			&& customPromptText.IndexOf("assignment", StringComparison.OrdinalIgnoreCase) < 0
			&& customPromptText.IndexOf("effectIntents", StringComparison.OrdinalIgnoreCase) < 0
			&& customPromptText.IndexOf("每日60已属极强", StringComparison.Ordinal) >= 0,
			"The editable soldierTroopXp JSON must retain domain calibration without duplicating semantic-ledger wire contracts.");
		string liveProbeText = File.ReadAllText(
			Path.Combine(repositoryRoot, "tools", "PolicyEffectModule.ContractTests", "run_player_policy_effect_live_probe.ps1"),
			Encoding.UTF8);
		Check(liveProbeText.Contains("[ValidateSet('assignment', 'none', 'once', 'daily', 'both')]")
			&& liveProbeText.Contains("[Alias('ExpectedXpMinimum')]")
			&& liveProbeText.Contains("expected_runtime_module_ids")
			&& liveProbeText.Contains("main_policy_costs")
			&& liveProbeText.Contains("once_xp_per_troop")
			&& liveProbeText.Contains("daily_xp_per_troop"),
			"The sanitized live probe must expose backward-compatible once/daily/both/none expectations, exact runtime expansion evidence, and policy-cost values.");
		string liveMatrixText = File.ReadAllText(
			Path.Combine(repositoryRoot, "tools", "PolicyEffectModule.ContractTests", "run_player_policy_effect_live_matrix.ps1"),
			Encoding.UTF8);
		Check(liveMatrixText.Contains("[switch]$SoldierTroopXpStress")
			&& liveMatrixText.Contains("soldier_xp_explicit_once")
			&& liveMatrixText.Contains("soldier_xp_explicit_daily")
			&& liveMatrixText.Contains("soldier_xp_explicit_two_phase")
			&& liveMatrixText.Contains("soldier_xp_vague_with_budget")
			&& liveMatrixText.Contains("soldier_xp_clan_parties_and_garrisons")
			&& liveMatrixText.Contains("soldier_xp_militia_recruit_prisoner_excluded")
			&& liveMatrixText.Contains("soldier_xp_explicit_none"),
			"The dedicated live matrix must cover lifecycle, funding, combined Clan assets, exclusions, and explicit-zero XP scenarios.");

		JObject schema = composite.Descriptor.PayloadPromptSchema;
		Check((schema["required"] as JArray)?.Values<string>()
			.SequenceEqual(new[] { "onceDelta", "dailyDelta" }, StringComparer.Ordinal) == true
			&& schema.Value<bool?>("additionalProperties") == false
			&& schema["properties"]?["onceDelta"]?.Value<int>("minimum") == 0
			&& schema["properties"]?["onceDelta"]?.Value<int>("maximum") == 5000
			&& schema["properties"]?["dailyDelta"]?.Value<int>("minimum") == 0
			&& schema["properties"]?["dailyDelta"]?.Value<int>("maximum") == 100,
			"soldierTroopXp schema must require bounded non-negative integer deltas.");
		Check(PolicyEffectModuleCatalog.TryNormalizePayload(
			"soldierTroopXp",
			new JObject { ["onceDelta"] = 300, ["dailyDelta"] = 60 },
			PolicyEffectScopes.Kingdom,
			out PolicyEffectPayload normalized,
			out string normalizeError)
			&& JObject.FromObject(normalized).Value<int>("onceDelta") == 300
			&& JObject.FromObject(normalized).Value<int>("dailyDelta") == 60,
			"A bounded once/daily troop XP payload must normalize: " + normalizeError);
		foreach (JObject invalidPayload in new[]
		{
			new JObject { ["onceDelta"] = -1, ["dailyDelta"] = 0 },
			new JObject { ["onceDelta"] = 1.5, ["dailyDelta"] = 0 },
			new JObject { ["onceDelta"] = 5001, ["dailyDelta"] = 0 },
			new JObject { ["onceDelta"] = 0, ["dailyDelta"] = -1 },
			new JObject { ["onceDelta"] = 0, ["dailyDelta"] = 101 },
			new JObject { ["onceDelta"] = 1, ["dailyDelta"] = 1, ["unknown"] = 1 }
		})
		{
			Check(!PolicyEffectModuleCatalog.TryNormalizePayload(
				"soldierTroopXp",
				invalidPayload,
				PolicyEffectScopes.Kingdom,
				out _,
				out _),
				"Raw soldierTroopXp payload must reject invalid fields or bounds: " + invalidPayload);
		}
		Check(composite.TryApplyFunding(
			normalized,
			new PolicyEffectFundingContext { GoldScale = 0.5f, InfluenceScale = 0.5f },
			out PolicyEffectPayload funded,
			out string fundingError)
			&& JObject.FromObject(funded).Value<int>("onceDelta") == 150
			&& JObject.FromObject(funded).Value<int>("dailyDelta") == 30,
			"Composite funding must scale each delta exactly once: " + fundingError);
		Check(((IPolicyEffectCompositeModule)composite).TryExpand(
			new PolicyEffectCompileContext { SourceScope = PolicyEffectScopes.Kingdom },
			funded,
			out IReadOnlyList<PolicyEffectCompositeChild> fundedChildren,
			out string expandError)
			&& fundedChildren.Count == 2
			&& fundedChildren[0].ModuleId == "soldierTroopXpOnce"
			&& fundedChildren[1].ModuleId == "soldierTroopXpPerDay"
			&& JObject.FromObject(fundedChildren[0].Payload).Value<int>("value") == 150
			&& JObject.FromObject(fundedChildren[1].Payload).Value<int>("value") == 30,
			"Funded Composite must expand deterministic once/daily children without a second scale: " + expandError);
		Check(PolicyEffectModuleCatalog.TryNormalizePayload(
			"soldierTroopXp",
			new JObject { ["onceDelta"] = 0, ["dailyDelta"] = 0 },
			PolicyEffectScopes.Kingdom,
			out PolicyEffectPayload zeroPayload,
			out _)
			&& ((IPolicyEffectCompositeModule)composite).TryExpand(
				new PolicyEffectCompileContext { SourceScope = PolicyEffectScopes.Kingdom },
				zeroPayload,
				out IReadOnlyList<PolicyEffectCompositeChild> zeroChildren,
				out _)
			&& zeroChildren.Count == 0,
			"A zero/zero Composite must omit the entire effect.");

		Check(PolicyEffectModuleCatalog.TryGet("soldierTroopXpOnce", out IPolicyEffectModule module)
			&& !module.Descriptor.PromptVisible
			&& module.Descriptor.ExecutionKind == PolicyEffectExecutionKind.ScheduledOnce
			&& module.Descriptor.FundingMode == PolicyEffectFundingMode.Unscaled
			&& module.Descriptor.FundingStrategy == PolicyEffectFundingStrategy.None
			&& module.Descriptor.TargetRefresh == composite.Descriptor.TargetRefresh
			&& module.Descriptor.AllowIndependentClanTargets == composite.Descriptor.AllowIndependentClanTargets
			&& module.Descriptor.TargetKinds.SequenceEqual(composite.Descriptor.TargetKinds)
			&& module.Descriptor.AllowedSelectorKinds.SequenceEqual(composite.Descriptor.AllowedSelectorKinds)
			&& module is IScheduledOncePolicyEffectModule,
			"soldierTroopXpOnce must remain a hidden, unscaled ScheduledOnce runtime module.");
		Check(PolicyEffectModuleCatalog.TryGet("soldierTroopXpPerDay", out IPolicyEffectModule dailyModule)
			&& !dailyModule.Descriptor.PromptVisible
			&& dailyModule.Descriptor.ExecutionKind == PolicyEffectExecutionKind.DailyMutation
			&& dailyModule.Descriptor.FundingMode == PolicyEffectFundingMode.Unscaled
			&& dailyModule.Descriptor.FundingStrategy == PolicyEffectFundingStrategy.None
			&& dailyModule.Descriptor.TargetRefresh == composite.Descriptor.TargetRefresh
			&& dailyModule.Descriptor.AllowIndependentClanTargets == composite.Descriptor.AllowIndependentClanTargets
			&& dailyModule.Descriptor.TargetKinds.SequenceEqual(composite.Descriptor.TargetKinds)
			&& dailyModule.Descriptor.AllowedSelectorKinds.SequenceEqual(composite.Descriptor.AllowedSelectorKinds)
			&& dailyModule is IDailyPolicyEffectModule
			&& dailyModule is ICompensatingDailyPolicyEffectModule,
			"soldierTroopXpPerDay must be a hidden, compensating DailyMutation runtime module.");
		Check(PolicyEffectModuleCatalog.IsAuthorizedRuntimeModule("soldierTroopXp", "soldierTroopXpOnce")
			&& PolicyEffectModuleCatalog.IsAuthorizedRuntimeModule("soldierTroopXp", "soldierTroopXpPerDay"),
			"The new Composite must authorize exactly its once and daily descendants.");

		PolicyEffectInstanceSaveData effect = BuildSoldierTroopXpScheduled("soldier-troop-xp", 300,
			new[] { "clan-b", "clan-a", "clan-a" });
		JObject plan = new JObject
		{
			["v"] = 1,
			["x"] = 300,
			["p"] = new JArray
			{
				new JObject
				{
					["c"] = "clan-a",
					["i"] = "party-a",
					["k"] = "l",
					["r"] = "hero-a",
					["s"] = new JArray
					{
						new JObject { ["i"] = "troop-a", ["n"] = 10, ["b"] = 0, ["a"] = 3000 },
						new JObject { ["i"] = "troop-b", ["n"] = 5, ["b"] = 100, ["a"] = 1600 }
					}
				},
				new JObject
				{
					["c"] = "clan-a",
					["i"] = "garrison-a",
					["k"] = "g",
					["r"] = "settlement-a",
					["s"] = new JArray
					{
						new JObject { ["i"] = "troop-c", ["n"] = 8, ["b"] = 40, ["a"] = 2440 }
					}
				}
			}
		};
		GameBridgeProxy bridgeProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge));
		bridgeProxy.SetClanTroopXpPlan(plan);
		IPolicyEffectGameBridge bridge = (IPolicyEffectGameBridge)bridgeProxy.GetTransparentProxy();
		List<PolicyEffectExecutionReceipt> receipts = new List<PolicyEffectExecutionReceipt>();
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { effect }, receipts, bridge, 11,
			out List<string> completed, out bool changed, out string executionError),
			"soldierTroopXpOnce must execute through the production ScheduledOnce path: " + executionError);
		Check(changed
			&& completed.SequenceEqual(new[] { effect.InstanceId }, StringComparer.Ordinal)
			&& bridgeProxy.TroopXpPrepareCallCount == 1
			&& bridgeProxy.TroopXpApplyCallCount == 1
			&& bridgeProxy.LastTroopXpClanIds.SequenceEqual(new[] { "clan-a", "clan-b" }, StringComparer.Ordinal)
			&& bridgeProxy.ReadTroopXp("party-a", "troop-a") == 3000
			&& bridgeProxy.ReadTroopXp("party-a", "troop-b") == 1600
			&& bridgeProxy.ReadTroopXp("garrison-a", "troop-c") == 2440,
			"The module must de-duplicate and sort Clan IDs, then mutate LordParty and garrison rosters in one transaction.");
		Check(effect.ExecutionReceipt?.Status == PolicyEffectExecutionStatus.Applied
			&& effect.ExecutionReceipt.AppliedPayload?["journal"] == null
			&& effect.ExecutionReceipt.AppliedPayload?.Value<int>("parties") == 2
			&& effect.ExecutionReceipt.AppliedPayload?.Value<int>("stacks") == 3
			&& effect.ExecutionReceipt.AppliedPayload?.Value<long>("totalXp") == 6900L,
			"The durable receipt must stay compact and expose only aggregate application results.");
		Check(effect.RuntimeState is JObject runtimeRoot
			&& runtimeRoot[PolicyEffectRuntimeStateEnvelope.ModuleProperty]?["j"]?["p"] is JArray,
			"The exact before/after rollback journal must be stored in bounded module RuntimeState.");

		PolicyEffectSaveEnvelope envelope = new PolicyEffectSaveEnvelope
		{
			Instances = new List<PolicyEffectInstanceSaveData> { effect },
			Receipts = receipts.ToList()
		};
		Check(PolicyEffectSaveCodec.TrySerialize(envelope, out _, out string saveError),
			"The troop XP rollback journal and compact receipt must satisfy save limits: " + saveError);
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryCompensateScheduledOnceAfterPersistenceFailure(
			new[] { effect }, receipts, completed, bridge, 11,
			out bool compensationChanged, out string compensationError)
			&& compensationChanged
			&& bridgeProxy.TroopXpRestoreCallCount == 1
			&& bridgeProxy.ReadTroopXp("party-a", "troop-a") == 0
			&& bridgeProxy.ReadTroopXp("party-a", "troop-b") == 100
			&& bridgeProxy.ReadTroopXp("garrison-a", "troop-c") == 40,
			"Persistence failure must CAS-restore every changed troop stack: " + compensationError);

		PolicyEffectInstanceSaveData oversized = BuildSoldierTroopXpScheduled(
			"troop-xp-big", 300, new[] { "clan-a" });
		GameBridgeProxy oversizedProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge));
		JObject oversizedPlan = (JObject)plan.DeepClone();
		((JObject)((JArray)((JObject)((JArray)oversizedPlan["p"])[0])["s"])[0])["i"] =
			new string('x', PolicyEffectSaveCodec.MaxRuntimeStateBytes);
		oversizedProxy.SetClanTroopXpPlan(oversizedPlan);
		List<PolicyEffectExecutionReceipt> oversizedReceipts = new List<PolicyEffectExecutionReceipt>();
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { oversized }, oversizedReceipts,
			(IPolicyEffectGameBridge)oversizedProxy.GetTransparentProxy(), 11,
			out List<string> oversizedCompleted, out _, out string oversizedExecutionError)
			&& oversizedCompleted.SequenceEqual(new[] { oversized.InstanceId }, StringComparer.Ordinal)
			&& oversized.ExecutionReceipt?.Status == PolicyEffectExecutionStatus.Skipped
			&& oversizedProxy.TroopXpApplyCallCount == 0,
			"An oversized rollback journal must complete as an explicit zero-mutation skip. status="
			+ (oversized.ExecutionReceipt?.Status.ToString() ?? "null")
			+ " completed=" + string.Join(",", oversizedCompleted)
			+ " applyCalls=" + oversizedProxy.TroopXpApplyCallCount.ToString(CultureInfo.InvariantCulture)
			+ " error=" + oversizedExecutionError);

		PolicyEffectInstanceSaveData daily = BuildSoldierTroopXpDaily("soldier-troop-xp-daily", 20, "clan-a");
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryPrepareSavedInstance(
			daily, out IPolicyEffectModule preparedDailyModule, out PolicyEffectPreparedInstance dailyPrepared, out string dailyPrepareError),
			"soldierTroopXpPerDay fixture must prepare: " + dailyPrepareError);
		GameBridgeProxy dailyProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge));
		JObject dailyPlan = (JObject)plan.DeepClone();
		dailyPlan["x"] = 20;
		JArray dailyStacks = (JArray)((JObject)((JArray)dailyPlan["p"])[0])["s"];
		((JObject)dailyStacks[0])["a"] = 200;
		((JObject)dailyStacks[1])["a"] = 200;
		JArray dailyGarrisonStacks = (JArray)((JObject)((JArray)dailyPlan["p"])[1])["s"];
		((JObject)dailyGarrisonStacks[0])["a"] = 200;
		dailyProxy.SetClanTroopXpPlan(dailyPlan);
		IPolicyEffectGameBridge dailyBridge = (IPolicyEffectGameBridge)dailyProxy.GetTransparentProxy();
		AnimusForge.PolicyEffectDailyExecutionOutcome dailyOutcome = AnimusForge.PolicyEffectActivationCoordinator.ExecuteDailyTarget(
			daily, preparedDailyModule, dailyPrepared, PolicyEffectTargetKind.Clan, "clan-a", dailyBridge, 11, 11);
		Check(dailyOutcome.Succeeded
			&& dailyOutcome.AppliedReceipt?.Status == PolicyEffectExecutionStatus.Applied
			&& dailyOutcome.AppliedReceipt.AppliedPayload?["journal"] is JObject
			&& dailyProxy.LastTroopXpClanIds.SequenceEqual(new[] { "clan-a" }, StringComparer.Ordinal)
			&& daily.RuntimeState?[PolicyEffectRuntimeStateEnvelope.ModuleProperty]?["journal"] == null,
			"Daily troop XP must execute one Clan and persist its exact multi-party journal in the per-target receipt.");
		int applyCallsAfterFirstDaily = dailyProxy.TroopXpApplyCallCount;
		AnimusForge.PolicyEffectDailyExecutionOutcome duplicateDaily = AnimusForge.PolicyEffectActivationCoordinator.ExecuteDailyTarget(
			daily, preparedDailyModule, dailyPrepared, PolicyEffectTargetKind.Clan, "clan-a", dailyBridge, 11, 11);
		Check(duplicateDaily.Succeeded && dailyProxy.TroopXpApplyCallCount == applyCallsAfterFirstDaily,
			"The same instance/target/day must be idempotent.");
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryCompensateDailyTargetAfterPersistenceFailure(
			dailyOutcome, dailyBridge, out string dailyCompensationError)
			&& dailyProxy.TroopXpRestoreCallCount == 1
			&& dailyProxy.ReadTroopXp("party-a", "troop-a") == 0
			&& dailyProxy.ReadTroopXp("party-a", "troop-b") == 100
			&& dailyProxy.ReadTroopXp("garrison-a", "troop-c") == 40,
			"Daily persistence failure must restore only that target's journal: " + dailyCompensationError);

		PolicyEffectInstanceSaveData partialDaily = BuildSoldierTroopXpDaily("soldier-troop-xp-partial", 20, "clan-a");
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryPrepareSavedInstance(
			partialDaily, out IPolicyEffectModule partialModule, out PolicyEffectPreparedInstance partialPrepared, out string partialPrepareError),
			"Partial daily fixture must prepare: " + partialPrepareError);
		GameBridgeProxy partialProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge))
		{
			FailTroopXpApplyAfterStacks = 1
		};
		partialProxy.SetClanTroopXpPlan(dailyPlan);
		IPolicyEffectGameBridge partialBridge = (IPolicyEffectGameBridge)partialProxy.GetTransparentProxy();
		AnimusForge.PolicyEffectDailyExecutionOutcome partialOutcome = AnimusForge.PolicyEffectActivationCoordinator.ExecuteDailyTarget(
			partialDaily, partialModule, partialPrepared, PolicyEffectTargetKind.Clan, "clan-a", partialBridge, 11, 11);
		Check(partialOutcome.Failed
			&& partialOutcome.Retryable
			&& partialOutcome.AppliedReceipt?.AppliedPayload?["journal"] is JObject
			&& partialProxy.TroopXpApplyCallCount == 1
			&& partialProxy.ReadTroopXp("party-a", "troop-a") == 200
			&& partialProxy.ReadTroopXp("party-a", "troop-b") == 100,
			"A partial daily mutation must preserve its receipt and stop before an automatic same-day retry.");
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryCompensateDailyTargetAfterPersistenceFailure(
			partialOutcome, partialBridge, out string partialCompensationError)
			&& partialProxy.TroopXpRestoreCallCount == 1
			&& partialProxy.ReadTroopXp("party-a", "troop-a") == 0
			&& partialProxy.ReadTroopXp("party-a", "troop-b") == 100,
			"A partial daily mutation must enter the existing compensation transaction: " + partialCompensationError);

		PolicyEffectInstanceSaveData displayOnce = BuildSoldierTroopXpScheduled("soldier-troop-xp-display-once", 300, new[] { "clan-a" });
		PolicyEffectInstanceSaveData displayDaily = BuildSoldierTroopXpDaily("soldier-troop-xp-display-daily", 20, "clan-a");
		displayDaily.MechanismId = displayOnce.MechanismId;
		List<string> display = PolicyEffectSaveCodec.DescribePlayerVisibleInstances(new[] { displayOnce, displayDaily });
		Check(display.Count == 1
			&& display[0].Contains("士兵精锐化：下一游戏日一次 +300 XP/兵；随后每日 +20 XP/兵"),
			"The two hidden runtime legs must render as one player-visible soldierTroopXp Composite.");
	}

	private static PolicyEffectInstanceSaveData BuildSoldierTroopXpScheduled(
		string instanceId,
		int xpPerTroop,
		IEnumerable<string> clanIds)
	{
		return new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = instanceId,
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = instanceId,
			PolicyId = "soldier-troop-xp-contract",
			ActorHeroId = "policy-actor",
			ModuleId = "soldierTroopXpOnce",
			SourceModuleId = "soldierTroopXp",
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = "soldierTroopXpOnce",
				["schemaVersion"] = 1,
				["value"] = xpPerTroop
			},
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				ClanIds = (clanIds ?? Array.Empty<string>()).ToList()
			},
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			StartDay = 10f,
			EndDay = 20f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "Clan soldier elite training contract"
		};
	}

	private static PolicyEffectInstanceSaveData BuildSoldierTroopXpDaily(
		string instanceId,
		int xpPerTroop,
		string clanId)
	{
		PolicyEffectInstanceSaveData instance = BuildSoldierTroopXpScheduled(instanceId, xpPerTroop, new[] { clanId });
		instance.ModuleId = "soldierTroopXpPerDay";
		instance.SourceModuleId = "soldierTroopXp";
		instance.Payload = new JObject
		{
			["moduleId"] = "soldierTroopXpPerDay",
			["schemaVersion"] = 1,
			["value"] = xpPerTroop
		};
		return instance;
	}

	private static void TestHeroGoldModuleContracts()
	{
		Check(PolicyEffectModuleCatalog.TryGet("heroGold", out IPolicyEffectModule composite),
			"Visible heroGold module must be registered.");
		Check(composite.Descriptor.ExecutionKind == PolicyEffectExecutionKind.Composite
			&& composite is IPolicyEffectCompositeModule
			&& composite.Descriptor.PromptVisible
			&& string.Equals(composite.Descriptor.DisplayGroup, "heroGold", StringComparison.Ordinal),
			"heroGold must be a visible Composite grouped under heroGold.");
		Check(composite.Descriptor.TargetKinds.Count == 1
			&& string.Equals(composite.Descriptor.TargetKinds.Single().ToString(), "Hero", StringComparison.Ordinal),
			"heroGold must target Hero only.");
		Check(((IPolicyEffectCompositeModule)composite).RuntimeModuleIds
			.SequenceEqual(new[] { "heroGoldNextDayOnce", "heroGoldPerDay" }, StringComparer.Ordinal),
			"heroGold must declare exactly its next-day and daily runtime descendants.");
		Check(composite.Descriptor.CueTerms.Contains("领主收入", StringComparer.Ordinal)
			&& composite.Descriptor.CueTerms.Contains("个人收入", StringComparer.Ordinal)
			&& composite.Descriptor.MainInstruction.IndexOf("不要求正文逐字写出职业或具体第纳尔金额", StringComparison.Ordinal) >= 0
			&& composite.Descriptor.EditableUnderstandingPrompt.IndexOf("模型应自行判断受影响的人物或原版职业群体", StringComparison.Ordinal) >= 0
			&& composite.Descriptor.EditableEvaluationPrompt.IndexOf("泛称“提高领主收入”应给出正的每日变化", StringComparison.Ordinal) >= 0
			&& composite.Descriptor.EditableEvaluationPrompt.IndexOf("dailyDelta", StringComparison.Ordinal) < 0
			&& composite.Descriptor.EditableEvaluationPrompt.IndexOf("onceDelta", StringComparison.Ordinal) < 0,
			"heroGold must let the model infer affected original occupations and a per-Hero amount without literal profession or number requirements.");
		Check(PolicyEffectModuleCatalog.TryGet("taxIncomePct", out IPolicyEffectModule taxIncome)
			&& taxIncome.Descriptor.RetrievalText.IndexOf("财政收入、领主收入", StringComparison.Ordinal) < 0
			&& taxIncome.Descriptor.MainInstruction.IndexOf("未提领地、城镇、城堡或税制时，不属于此效果", StringComparison.Ordinal) >= 0,
			"Generic lord income must not be confused with settlement tax income.");
		List<PolicyEffectModuleSelection> naturalIncomeRecall = PolicyEffectModuleCatalog.GetModulesForScope(PolicyEffectScopes.Kingdom)
			.Select(module => new PolicyEffectModuleSelection { Module = module, RecallScore = 0f })
			.ToList();
		IReadOnlyList<PolicyEffectModuleSelection> naturalIncomeCandidates = PolicyEffectModuleRouter.SelectCandidates(
			naturalIncomeRecall,
			"制定一项提高领主收入的政策");
		Check(naturalIncomeCandidates.Count > 0
			&& string.Equals(naturalIncomeCandidates[0].Module.Id, "heroGold", StringComparison.Ordinal)
			&& naturalIncomeCandidates[0].CueMatched
			&& !naturalIncomeRecall.Single(item => string.Equals(item.Module.Id, "taxIncomePct", StringComparison.Ordinal)).CueMatched,
			"The natural policy text '提高领主收入' must cue heroGold first without cueing settlement tax income or loading ONNX.");
		string candidatePayloadRules = PolicyEffectModuleCatalog.BuildPayloadPromptRules(
			PolicyEffectScopes.Kingdom,
			new[] { "heroGold", "prosperityPerDay" },
			new[] { "prosperityPerDay" });
		Check(candidatePayloadRules.IndexOf("heroGold payload=", StringComparison.Ordinal) >= 0
			&& candidatePayloadRules.IndexOf(composite.PostprocessRule.Trim(), StringComparison.Ordinal) >= 0
			&& candidatePayloadRules.IndexOf(composite.Descriptor.EditableEvaluationPrompt, StringComparison.Ordinal) < 0
			&& PolicyEffectModuleCatalog.TryGet("prosperityPerDay", out IPolicyEffectModule prosperity)
			&& candidatePayloadRules.IndexOf(prosperity.Descriptor.EditableEvaluationPrompt, StringComparison.Ordinal) >= 0,
			"Every Candidate must receive its payload schema and short rule, while only Detail modules receive editable calibration.");
		Check(typeof(PolicyHeroTargetSelectorResolver).GetMethod("BuildAvailableGroupCandidates", All) != null,
			"The shared Hero target resolver must expose a deterministic available-group candidate builder for player and NPC policies.");

		JObject schema = composite.Descriptor.PayloadPromptSchema;
		Check((schema["required"] as JArray)?.Values<string>()
			.SequenceEqual(new[] { "onceDelta", "dailyDelta" }, StringComparer.Ordinal) == true
			&& schema.Value<bool?>("additionalProperties") == false
			&& string.Equals((string)schema["properties"]?["onceDelta"]?["type"], "integer", StringComparison.Ordinal)
			&& string.Equals((string)schema["properties"]?["dailyDelta"]?["type"], "integer", StringComparison.Ordinal),
			"heroGold payload schema must require exactly two integer fields.");
		Check(PolicyEffectModuleCatalog.TryNormalizePayload(
			"heroGold",
			new JObject { ["onceDelta"] = 1001, ["dailyDelta"] = -51 },
			PolicyEffectScopes.Kingdom,
			out PolicyEffectPayload normalized,
			out string normalizeError),
			"Integer heroGold payload must normalize: " + normalizeError);
		Check(!PolicyEffectModuleCatalog.TryNormalizePayload(
			"heroGold",
			new JObject { ["onceDelta"] = 1.5, ["dailyDelta"] = 0 },
			PolicyEffectScopes.Kingdom,
			out _,
			out _),
			"heroGold must reject fractional denars.");
		Check(!PolicyEffectModuleCatalog.TryNormalizePayload(
			"heroGold",
			new JObject { ["onceDelta"] = 1, ["dailyDelta"] = 0, ["startupGoldCost"] = 1 },
			PolicyEffectScopes.Kingdom,
			out _,
			out _),
			"heroGold must reject unknown fields, including policy-cost fields.");

		Check(PolicyEffectModuleCatalog.TryGet("heroGoldNextDayOnce", out IPolicyEffectModule once)
			&& once.Descriptor.ExecutionKind == PolicyEffectExecutionKind.ScheduledOnce
			&& once is IScheduledOncePolicyEffectModule
			&& !once.Descriptor.PromptVisible,
			"heroGoldNextDayOnce must be a hidden ScheduledOnce module.");
		Check(PolicyEffectModuleCatalog.TryGet("heroGoldPerDay", out IPolicyEffectModule daily)
			&& daily.Descriptor.ExecutionKind == PolicyEffectExecutionKind.DailyMutation
			&& daily is IDailyPolicyEffectModule
			&& daily is ICompensatingDailyPolicyEffectModule
			&& !daily.Descriptor.PromptVisible,
			"heroGoldPerDay must be a hidden compensating DailyMutation module.");
		Check(PolicyEffectModuleCatalog.IsAuthorizedRuntimeModule("heroGold", "heroGoldNextDayOnce")
			&& PolicyEffectModuleCatalog.IsAuthorizedRuntimeModule("heroGold", "heroGoldPerDay"),
			"heroGold lineage must authorize both hidden descendants.");

		PropertyInfo heroIds = typeof(PolicyEffectCanonicalTargetSet).GetProperty("HeroIds", All);
		Check(heroIds != null && typeof(IEnumerable<string>).IsAssignableFrom(heroIds.PropertyType),
			"Canonical target sets must persist HeroIds.");
		Check(Enum.GetValues(typeof(PolicyEffectRetrievalContext)).Cast<PolicyEffectRetrievalContext>()
			.All(context => PolicyEffectModuleRetrievalSettings.IsContextSupported(composite, context)),
			"heroGold must be supported in player kingdom/local/vassal and NPC ruler retrieval contexts.");
		Check(PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:specific:hero-a")
			&& PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:role:ruler:kingdom-a")
			&& PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:role:lords:kingdom-a")
			&& PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:role:clan-leaders:kingdom-a")
			&& PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:role:notables:kingdom-a")
			&& PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:occupation:Lord:kingdom-a")
			&& PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:occupation:Headman:kingdom-a")
			&& PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:occupation:Wanderer:kingdom-a"),
			"Versioned Hero selectors must recognize specific, role, Lord, Headman, and Wanderer forms.");
		Check(!PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:clan-leader:clan-a")
			&& !PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:role:invented:kingdom-a")
			&& !PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:occupation:NotAssigned:kingdom-a")
			&& !PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:occupation:NumberOfOccupations:kingdom-a")
			&& !PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v1:occupation:999:kingdom-a")
			&& !PolicyHeroTargetSelectorResolver.IsKnownSelector("hero:v2:role:ruler:kingdom-a"),
			"Unknown, sentinel, or unsupported-version Hero selectors must fail closed.");
		Check(normalized != null, "Normalized heroGold payload must be materialized.");
	}

	private static void TestHeroGoldCompilerContracts()
	{
		PolicyEffectCompilerRequest request = BuildCompilerRequest(
			"hero-gold-independent",
			PolicyEffectScopes.Kingdom,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: false,
			detailedIncludesDummy: false);
		request.CandidateModuleIds = new[] { "heroGold" };
		request.DetailedModuleIds = new[] { "heroGold" };
		request.CoalesceEquivalentDisjointTargets = false;

		PolicyEffectWireEffect Wire(
			string handle,
			int onceDelta,
			int dailyDelta,
			PolicyEffectMechanismKind kind,
			PolicyEffectMechanismRole role)
		{
			return new PolicyEffectWireEffect
			{
				EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
				MechanismId = kind == PolicyEffectMechanismKind.Independent ? "gold-grant" : "gold-linked",
				MechanismKind = kind,
				MechanismRole = role,
				ModuleId = "heroGold",
				TargetHandles = new List<string> { handle },
				Payload = new JObject { ["onceDelta"] = onceDelta, ["dailyDelta"] = dailyDelta },
				Reason = "hero gold compiler contract"
			};
		}

		bool ResolveHeroTarget(
			string handle,
			IPolicyEffectModule module,
			out PolicyEffectResolvedTarget resolved,
			out string error)
		{
			resolved = null;
			error = string.Empty;
			string normalizedHandle = (handle ?? string.Empty).Trim();
			List<string> heroIds = normalizedHandle switch
			{
				"HS" => new List<string> { "source-hero" },
				"HD" => new List<string> { "destination-hero" },
				"HSAME" => new List<string> { "source-hero" },
				"HM" => new List<string> { "source-hero", "second-source-hero" },
				_ => new List<string>()
			};
			if (heroIds.Count == 0)
			{
				error = "unknown frozen hero handle";
				return false;
			}
			resolved = new PolicyEffectResolvedTarget
			{
				Handle = normalizedHandle,
				SelectorKind = PolicyEffectTargetKind.Hero,
				CanonicalTargetSet = new PolicyEffectCanonicalTargetSet
				{
					SelectorHandles = new List<string> { normalizedHandle },
					SelectorIds = new List<string> { "hero:v1:specific:" + heroIds[0] },
					HeroIds = heroIds
				}
			};
			return true;
		}

		bool Compile(
			IReadOnlyList<PolicyEffectWireEffect> wires,
			out PolicyEffectCompilerResult result,
			out string error)
		{
			return PolicyEffectCompiler.TryCompile(
				wires,
				request,
				ResolveHeroTarget,
				(ordinal, moduleId, targetSet) => "hero-gold:" + ordinal.ToString(CultureInfo.InvariantCulture) + ":" + moduleId,
				out result,
				out error);
		}

		Check(Compile(
			new[] { Wire("HD", 100, 5, PolicyEffectMechanismKind.Independent, PolicyEffectMechanismRole.Subject) },
			out PolicyEffectCompilerResult valid,
			out string validError)
			&& valid.Effects.Count == 2
			&& valid.Effects.Count(effect => effect.SaveData.ModuleId == "heroGoldNextDayOnce") == 1
			&& valid.Effects.Count(effect => effect.SaveData.ModuleId == "heroGoldPerDay") == 1,
			"Independent heroGold grant must compile for a specific Hero: " + validError);
		Check(Compile(
			new[] { Wire("HM", 0, 100, PolicyEffectMechanismKind.Independent, PolicyEffectMechanismRole.Subject) },
			out PolicyEffectCompilerResult lordIncome,
			out string lordIncomeError)
			&& lordIncome.Effects.Count == 1
			&& lordIncome.Effects.Single().SaveData.ModuleId == "heroGoldPerDay"
			&& lordIncome.Effects.Single().SaveData.TargetSet.HeroIds
				.OrderBy(id => id, StringComparer.Ordinal)
				.SequenceEqual(new[] { "second-source-hero", "source-hero" }, StringComparer.OrdinalIgnoreCase),
			"A lord-salary policy must compile one +100 daily delta for every frozen Hero target: " + lordIncomeError);
		Check(!Compile(
			new[]
			{
				Wire("HS", -100, 0, PolicyEffectMechanismKind.Linked, PolicyEffectMechanismRole.Source),
				Wire("HD", 100, 0, PolicyEffectMechanismKind.Linked, PolicyEffectMechanismRole.Destination)
			}, out _, out string linkedError)
			&& linkedError.IndexOf("only support independent", StringComparison.Ordinal) >= 0,
			"heroGold must reject linked transfer mechanisms instead of treating them as balance movement.");

		bool ResolveProjectedTarget(
			string handle,
			IPolicyEffectModule module,
			out PolicyEffectResolvedTarget resolved,
			out string error)
		{
			error = string.Empty;
			PolicyEffectCanonicalTargetSet targetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { handle },
				ParentSettlementIds = new List<string> { "owner-town" }
			};
			PolicyEffectTargetKind selectorKind;
			switch (handle)
			{
				case "S_OK":
					selectorKind = PolicyEffectTargetKind.Settlement;
					targetSet.HeroIds.Add("owner-leader");
					break;
				case "S_EMPTY":
					selectorKind = PolicyEffectTargetKind.Settlement;
					break;
				case "C0":
					selectorKind = PolicyEffectTargetKind.Clan;
					targetSet.HeroIds.Add("owner-leader");
					break;
				case "P0":
					selectorKind = PolicyEffectTargetKind.Kingdom;
					targetSet.HeroIds.Add("owner-leader");
					if (!PolicyTargetPlanResolver.TryNormalizeAndValidate(
						BuildPolicyTwoStageSyntheticPlan(PolicyEffectTargetKind.Kingdom),
						out PolicyTargetPlanSaveData normalizedPlan,
						out error))
					{
						resolved = null;
						return false;
					}
					targetSet.TargetPlans.Add(normalizedPlan);
					break;
				default:
					resolved = null;
					error = "unknown projection handle";
					return false;
			}
			resolved = new PolicyEffectResolvedTarget
			{
				Handle = handle,
				SelectorKind = selectorKind,
				CanonicalTargetSet = targetSet
			};
			return true;
		}

		bool CompileProjected(string handle, out PolicyEffectCompilerResult result, out string error)
		{
			return PolicyEffectCompiler.TryCompile(
				new[] { Wire(handle, 0, 10, PolicyEffectMechanismKind.Independent, PolicyEffectMechanismRole.Subject) },
				request,
				ResolveProjectedTarget,
				(ordinal, moduleId, targetSet) => "hero-projection:" + ordinal.ToString(CultureInfo.InvariantCulture),
				out result,
				out error);
		}

		Check(CompileProjected("S_OK", out _, out string settlementProjectionError),
			"An explicitly projected Settlement selector must compile for a Hero-target module: "
			+ settlementProjectionError);
		Check(CompileProjected("P0", out _, out string targetPlanProjectionError),
			"A TargetPlan that materializes primary settlements must remain authorized regardless of its first universe: "
			+ targetPlanProjectionError);
		Check(!CompileProjected("C0", out _, out string aggregateSelectorError)
			&& aggregateSelectorError.Contains("does not allow target handle C0"),
			"A direct Clan/Kingdom aggregate selector must not inherit settlement-owner Hero projection authority.");
		Check(!CompileProjected("S_EMPTY", out _, out string emptyProjectionError)
			&& emptyProjectionError.Contains("has no executable target"),
			"The compiler must reject each settlement-owner projection handle that has no executable Hero target.");
	}

	private static void TestHeroGoldExecutionContracts()
	{
		PolicyEffectInstanceSaveData BuildScheduled(
			string instanceId,
			string mechanismId,
			PolicyEffectMechanismKind mechanismKind,
			PolicyEffectMechanismRole role,
			string heroId,
			int delta)
		{
			return new PolicyEffectInstanceSaveData
			{
				EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
				MechanismId = mechanismId,
				MechanismKind = mechanismKind,
				MechanismRole = role,
				InstanceId = instanceId,
				PolicyId = "hero-gold-execution",
				ModuleId = "heroGoldNextDayOnce",
				SourceModuleId = "heroGold",
				PayloadSchemaVersion = 1,
				Payload = new JObject
				{
					["moduleId"] = "heroGoldNextDayOnce",
					["schemaVersion"] = 1,
					["value"] = delta
				},
				TargetSet = new PolicyEffectCanonicalTargetSet
				{
					SelectorHandles = new List<string> { "H:" + heroId },
					SelectorIds = new List<string> { "hero:v1:specific:" + heroId },
					HeroIds = string.IsNullOrWhiteSpace(heroId) ? new List<string>() : new List<string> { heroId }
				},
				LifecycleState = PolicyEffectLifecycleState.Active,
				StateSchemaVersion = 1,
				StartDay = 10,
				EndDay = 20,
				SourceScope = PolicyEffectScopes.Kingdom,
				Reason = "hero gold execution contract"
			};
		}

		PolicyEffectInstanceSaveData playerGrant = BuildScheduled(
			"player-gold-grant", "player-gold-grant", PolicyEffectMechanismKind.Independent,
			PolicyEffectMechanismRole.Subject, "main-hero", 100);
		List<PolicyEffectExecutionReceipt> receipts = new List<PolicyEffectExecutionReceipt>();
		GameBridgeProxy bridgeProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge));
		bridgeProxy.SetHeroGold("main-hero", 50);
		IPolicyEffectGameBridge bridge = (IPolicyEffectGameBridge)bridgeProxy.GetTransparentProxy();
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { playerGrant }, receipts, bridge, 11,
			out List<string> completed, out bool changed, out string executionError),
			"Independent player heroGold ScheduledOnce must execute: " + executionError);
		Check(changed
			&& completed.SequenceEqual(new[] { playerGrant.InstanceId }, StringComparer.Ordinal)
			&& bridgeProxy.ReadHeroGold("main-hero") == 150
			&& receipts.Count == 1
			&& receipts.All(receipt => receipt.Status == PolicyEffectExecutionStatus.Applied),
			"A positive heroGold delta must directly credit the selected player Hero without a payer leg.");
		int callsAfterCommit = bridgeProxy.HeroGoldChangeCallCount;
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { playerGrant }, receipts, bridge, 11,
			out List<string> duplicateCompleted, out bool duplicateChanged, out string duplicateError)
			&& duplicateCompleted.Count == 0
			&& !duplicateChanged
			&& bridgeProxy.HeroGoldChangeCallCount == callsAfterCommit,
			"Completed hero gold ScheduledOnce must be idempotent: " + duplicateError);

		PolicyEffectSaveEnvelope envelope = new PolicyEffectSaveEnvelope
		{
			Instances = new List<PolicyEffectInstanceSaveData> { playerGrant },
			Receipts = receipts.ToList()
		};
		bool encoded = PolicyEffectSaveCodec.TrySerialize(envelope, out string json, out string encodeError);
		PolicyEffectSaveDecodeResult decoded = null;
		string decodeError = string.Empty;
		bool decodedOk = encoded
			&& PolicyEffectSaveCodec.TryDeserialize(json, out decoded, out decodeError);
		Check(decodedOk
			&& decoded.Envelope.Instances.SelectMany(instance => instance.TargetSet.HeroIds).Single() == "main-hero",
			"HeroIds and hero gold receipts must round-trip through the save codec: " + encodeError + " " + decodeError);
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryCompensateScheduledOnceAfterPersistenceFailure(
			new[] { playerGrant }, receipts, completed, bridge, 11,
			out bool compensationChanged, out string compensationError)
			&& compensationChanged
			&& bridgeProxy.ReadHeroGold("main-hero") == 50,
			"Persistence failure must compensate the direct player grant exactly: " + compensationError);

		PolicyEffectInstanceSaveData corruptOnce = BuildScheduled(
			"corrupt-once", "corrupt-once", PolicyEffectMechanismKind.Independent,
			PolicyEffectMechanismRole.Subject, "corrupt-once-hero", 40);
		GameBridgeProxy corruptOnceProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge));
		corruptOnceProxy.SetHeroGold("corrupt-once-hero", 100);
		IPolicyEffectGameBridge corruptOnceBridge = (IPolicyEffectGameBridge)corruptOnceProxy.GetTransparentProxy();
		List<PolicyEffectExecutionReceipt> corruptOnceReceipts = new List<PolicyEffectExecutionReceipt>();
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { corruptOnce }, corruptOnceReceipts, corruptOnceBridge, 11,
			out List<string> corruptOnceCompleted, out _, out string corruptOnceError)
			&& corruptOnceProxy.ReadHeroGold("corrupt-once-hero") == 140,
			"Scheduled receipt-corruption fixture must apply first: " + corruptOnceError);
		((JObject)corruptOnce.ExecutionReceipt.AppliedPayload["targets"][0])["actualDelta"] = 39;
		Check(!AnimusForge.PolicyEffectActivationCoordinator.TryCompensateScheduledOnceAfterPersistenceFailure(
			new[] { corruptOnce }, corruptOnceReceipts, corruptOnceCompleted, corruptOnceBridge, 11,
			out _, out _)
			&& corruptOnceProxy.ReadHeroGold("corrupt-once-hero") == 140,
			"Scheduled gold compensation must reject a non-conserving receipt without changing the Hero balance.");

		PolicyEffectInstanceSaveData poorTax = BuildScheduled(
			"poor-tax", "poor-tax", PolicyEffectMechanismKind.Independent,
			PolicyEffectMechanismRole.Subject, "poor-hero", -100);
		GameBridgeProxy poorProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge));
		poorProxy.SetHeroGold("poor-hero", 99);
		List<PolicyEffectExecutionReceipt> poorReceipts = new List<PolicyEffectExecutionReceipt>();
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { poorTax }, poorReceipts,
			(IPolicyEffectGameBridge)poorProxy.GetTransparentProxy(), 11,
			out List<string> poorCompleted, out bool poorChanged, out string poorError)
			&& poorChanged
			&& poorCompleted.SequenceEqual(new[] { poorTax.InstanceId }, StringComparer.Ordinal)
			&& poorProxy.HeroGoldChangeCallCount == 0
			&& poorProxy.ReadHeroGold("poor-hero") == 99
			&& poorReceipts.Single().Status == PolicyEffectExecutionStatus.Skipped,
			"An unaffordable independent Hero debit must skip with zero mutation: " + poorError);

		PolicyEffectInstanceSaveData empty = BuildScheduled(
			"empty-dynamic", "empty-dynamic", PolicyEffectMechanismKind.Independent,
			PolicyEffectMechanismRole.Subject, string.Empty, 50);
		empty.TargetSet.SelectorIds = new List<string> { "hero:v1:role:lords:missing-kingdom" };
		List<PolicyEffectExecutionReceipt> emptyReceipts = new List<PolicyEffectExecutionReceipt>();
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { empty }, emptyReceipts, bridge, 11,
			out List<string> emptyCompleted, out bool emptyChanged, out string emptyError)
			&& emptyChanged
			&& emptyCompleted.Count == 0
			&& emptyReceipts.Count == 0
			&& empty.LifecycleState == PolicyEffectLifecycleState.Suspended,
			"A dynamic selector with no due-day Hero must suspend before scheduled execution and remain recoverable: " + emptyError);

		PolicyEffectInstanceSaveData daily = new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "gold-daily",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "gold-daily",
			PolicyId = "hero-gold-execution",
			ModuleId = "heroGoldPerDay",
			SourceModuleId = "heroGold",
			PayloadSchemaVersion = 1,
			Payload = new JObject { ["moduleId"] = "heroGoldPerDay", ["schemaVersion"] = 1, ["value"] = -20 },
			TargetSet = new PolicyEffectCanonicalTargetSet { HeroIds = new List<string> { "daily-hero" } },
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			StartDay = 10,
			EndDay = 20,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "daily hero gold contract"
		};
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryPrepareSavedInstance(
			daily, out IPolicyEffectModule dailyModule, out PolicyEffectPreparedInstance dailyPrepared, out string dailyPrepareError),
			"heroGoldPerDay fixture must prepare: " + dailyPrepareError);
		GameBridgeProxy dailyProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge));
		dailyProxy.SetHeroGold("daily-hero", 100);
		IPolicyEffectGameBridge dailyBridge = (IPolicyEffectGameBridge)dailyProxy.GetTransparentProxy();
		AnimusForge.PolicyEffectDailyExecutionOutcome dailyOutcome = AnimusForge.PolicyEffectActivationCoordinator.ExecuteDailyTarget(
			daily, dailyModule, dailyPrepared, PolicyEffectTargetKind.Hero, "daily-hero", dailyBridge, 11, 11);
		Check(dailyOutcome.Succeeded
			&& dailyOutcome.AppliedReceipt?.Status == PolicyEffectExecutionStatus.Applied
			&& dailyProxy.ReadHeroGold("daily-hero") == 80,
			"heroGoldPerDay must apply an exact per-Hero daily delta.");
		((JObject)dailyOutcome.AppliedReceipt.AppliedPayload["target"])["actualDelta"] = -19;
		Check(!AnimusForge.PolicyEffectActivationCoordinator.TryCompensateDailyTargetAfterPersistenceFailure(
			dailyOutcome, dailyBridge, out _)
			&& dailyProxy.ReadHeroGold("daily-hero") == 80,
			"Daily gold compensation must reject a non-conserving receipt without changing the Hero balance.");
		((JObject)dailyOutcome.AppliedReceipt.AppliedPayload["target"])["actualDelta"] = -20;
		dailyProxy.SetHeroGold("daily-hero", 70);
		Check(!AnimusForge.PolicyEffectActivationCoordinator.TryCompensateDailyTargetAfterPersistenceFailure(
			dailyOutcome, dailyBridge, out _)
			&& dailyProxy.ReadHeroGold("daily-hero") == 70,
			"Daily gold compensation must fail closed on CAS mismatch without overwriting unrelated gold changes.");
	}

	private static void TestSoldierTroopXpBannerlordApi()
	{
		Type heroType = typeof(TaleWorlds.CampaignSystem.Hero);
		Type clanType = typeof(TaleWorlds.CampaignSystem.Clan);
		Type mobilePartyType = typeof(TaleWorlds.CampaignSystem.Party.MobileParty);
		Type partyBaseType = typeof(TaleWorlds.CampaignSystem.Party.PartyBase);
		Type lordPartyComponentType = typeof(TaleWorlds.CampaignSystem.Party.PartyComponents.LordPartyComponent);
		Type garrisonPartyComponentType = typeof(TaleWorlds.CampaignSystem.Party.PartyComponents.GarrisonPartyComponent);
		Type townType = typeof(TaleWorlds.CampaignSystem.Settlements.Town);
		Type settlementType = typeof(TaleWorlds.CampaignSystem.Settlements.Settlement);
		Type rosterType = typeof(TaleWorlds.CampaignSystem.Roster.TroopRoster);
		Type rosterElementType = typeof(TaleWorlds.CampaignSystem.Roster.TroopRosterElement);
		Type characterType = typeof(TaleWorlds.CampaignSystem.CharacterObject);

		PropertyInfo partyBelongedTo = heroType.GetProperty("PartyBelongedTo", All);
		PropertyInfo mobileMemberRoster = mobilePartyType.GetProperty("MemberRoster", All);
		PropertyInfo mobilePartyBase = mobilePartyType.GetProperty("Party", All);
		PropertyInfo partyMemberRoster = partyBaseType.GetProperty("MemberRoster", All);
		Check(partyBelongedTo?.PropertyType == mobilePartyType,
			"Real Hero.PartyBelongedTo must return MobileParty.");
		Check(mobileMemberRoster?.PropertyType == rosterType
			&& partyMemberRoster?.PropertyType == rosterType
			&& mobilePartyBase?.PropertyType == partyBaseType,
			"Real MobileParty/PartyBase member-roster API shape must remain available.");

		foreach (string propertyName in new[]
		{
			"IsActive", "IsDisbanding", "IsMainParty", "IsLordParty", "IsMilitia", "IsGarrison", "LeaderHero",
			"ActualClan", "LordPartyComponent", "GarrisonPartyComponent"
		})
		{
			Check(mobilePartyType.GetProperty(propertyName, All) != null,
				"Real MobileParty eligibility property is missing: " + propertyName + ".");
		}
		Check(clanType.GetProperty("All", All)?.GetMethod?.IsStatic == true
			&& clanType.GetProperty("Fiefs", All) != null
			&& clanType.GetProperty("WarPartyComponents", All) != null
			&& clanType.GetProperty("IsEliminated", All)?.PropertyType == typeof(bool),
			"Real Clan APIs must expose cached global lookup input plus live fief and WarPartyComponent collections.");
		Check(lordPartyComponentType.GetProperty("MobileParty", All)?.PropertyType == mobilePartyType
			&& townType.GetProperty("GarrisonParty", All)?.PropertyType == mobilePartyType
			&& townType.GetProperty("Settlement", All)?.PropertyType == settlementType
			&& garrisonPartyComponentType != null,
			"Real LordParty and current Town.GarrisonParty anchors must remain available in both Bannerlord API builds.");

		PropertyInfo number = rosterElementType.GetProperty("Number", All);
		PropertyInfo woundedNumber = rosterElementType.GetProperty("WoundedNumber", All);
		PropertyInfo xp = rosterElementType.GetProperty("Xp", All);
		Check(number?.PropertyType == typeof(int)
			&& woundedNumber?.PropertyType == typeof(int)
			&& xp?.PropertyType == typeof(int)
			&& xp.CanRead
			&& xp.CanWrite,
			"Real TroopRosterElement must expose independently stored int Number/WoundedNumber/Xp values.");

		MethodInfo addXpToTroop = rosterType.GetMethod(
			"AddXpToTroop",
			All,
			null,
			new[] { characterType, typeof(int) },
			null);
		MethodInfo addXpToTroopAtIndex = rosterType.GetMethod(
			"AddXpToTroopAtIndex",
			All,
			null,
			new[] { typeof(int), typeof(int) },
			null);
		MethodInfo setElementXp = rosterType.GetMethod(
			"SetElementXp",
			All,
			null,
			new[] { typeof(int), typeof(int) },
			null);
		MethodInfo getElementCopyAtIndex = rosterType.GetMethod(
			"GetElementCopyAtIndex",
			All,
			null,
			new[] { typeof(int) },
			null);
		MethodInfo updateVersion = rosterType.GetMethod(
			"UpdateVersion",
			All,
			null,
			Type.EmptyTypes,
			null);
		MethodInfo getUpgradeXpCost = characterType.GetMethod(
			"GetUpgradeXpCost",
			All,
			null,
			new[] { partyBaseType, typeof(int) },
			null);
		Check(addXpToTroop?.ReturnType == typeof(void)
			&& addXpToTroopAtIndex?.ReturnType == typeof(void)
			&& setElementXp?.ReturnType == typeof(void)
			&& getElementCopyAtIndex?.ReturnType == rosterElementType
			&& updateVersion?.ReturnType == typeof(void)
			&& getUpgradeXpCost?.ReturnType == typeof(int),
			"Real troop-XP mutation, snapshot, refresh and upgrade-cost methods must match the bridge contract.");

		MethodInfo findMobileParty = typeof(TaleWorlds.CampaignSystem.CampaignObjectManager)
			.GetMethods(All)
			.Where(method => string.Equals(method.Name, "Find", StringComparison.Ordinal)
				&& method.IsGenericMethodDefinition)
			.SingleOrDefault(method =>
			{
				ParameterInfo[] parameters = method.GetParameters();
				return parameters.Length == 1 && parameters[0].ParameterType == typeof(string);
			});
		Check(findMobileParty != null,
			"Real CampaignObjectManager.Find<T>(string) must be available for stable party-id re-resolution.");

		Type partyUpgraderType = typeof(TaleWorlds.CampaignSystem.CampaignBehaviors.PartyUpgraderCampaignBehavior);
		MethodInfo dailyTickParty = partyUpgraderType.GetMethod(
			"DailyTickParty",
			All,
			null,
			new[] { mobilePartyType },
			null);
		MethodInfo upgradeReadyTroops = partyUpgraderType.GetMethod(
			"UpgradeReadyTroops",
			All,
			null,
			new[] { partyBaseType },
			null);
		Check(dailyTickParty?.ReturnType == typeof(void),
			"Real PartyUpgraderCampaignBehavior.DailyTickParty(MobileParty) must remain available.");
		Check(upgradeReadyTroops?.ReturnType == typeof(void),
			"Real PartyUpgraderCampaignBehavior.UpgradeReadyTroops(PartyBase) must remain available.");

		var roster = TaleWorlds.CampaignSystem.Roster.TroopRoster.CreateDummyTroopRoster();
		var troop = new TaleWorlds.CampaignSystem.CharacterObject();
		int index = roster.AddToCounts(troop, 10);
		Check(index >= 0 && roster.Count == 1,
			"Real dummy TroopRoster must accept one ten-soldier regular troop stack.");

		int versionBeforeXp = roster.VersionNo;
		roster.AddXpToTroopAtIndex(index, 3000);
		TaleWorlds.CampaignSystem.Roster.TroopRosterElement element = roster.GetElementCopyAtIndex(index);
		Console.WriteLine("VALUE scenario=stack-xp-at-index"
			+ " troopCount=" + element.Number.ToString(CultureInfo.InvariantCulture)
			+ " requestedStackXp=3000"
			+ " storedStackXp=" + element.Xp.ToString(CultureInfo.InvariantCulture));
		Check(element.Number == 10 && element.WoundedNumber == 0 && element.Xp == 3000,
			"Real AddXpToTroopAtIndex must treat its amount as total stack XP, not XP per soldier.");
		Check(roster.VersionNo == versionBeforeXp,
			"Real AddXpToTroopAtIndex must not implicitly refresh TroopRoster.VersionNo.");

		roster.AddXpToTroop(troop, 200);
		element = roster.GetElementCopyAtIndex(index);
		Check(element.Number == 10 && element.WoundedNumber == 0 && element.Xp == 3200,
			"Real AddXpToTroop must add exactly the supplied stack XP without changing count or wounded count.");
		int versionBeforeRefresh = roster.VersionNo;
		roster.UpdateVersion();
		Check(roster.VersionNo == versionBeforeRefresh + 1,
			"Real TroopRoster.UpdateVersion must perform the explicit roster refresh expected by the bridge.");

		roster.SetElementXp(index, 1250);
		element = roster.GetElementCopyAtIndex(index);
		Check(element.Number == 10 && element.WoundedNumber == 0 && element.Xp == 1250,
			"Real SetElementXp must restore exact stack XP without changing troop or wounded counts.");
	}

	private static void TestHeroGoldBannerlordApi()
	{
		void TraceGold(string scenario, int before, int requested, int after)
		{
			Console.WriteLine("VALUE scenario=" + scenario
				+ " before=" + before.ToString(CultureInfo.InvariantCulture)
				+ " requested=" + requested.ToString(CultureInfo.InvariantCulture)
				+ " after=" + after.ToString(CultureInfo.InvariantCulture)
				+ " actual=" + (after - before).ToString(CultureInfo.InvariantCulture));
		}

		Type campaignType = typeof(TaleWorlds.CampaignSystem.Campaign);
		PropertyInfo currentProperty = campaignType.GetProperty("Current", All);
		PropertyInfo dispatcherProperty = campaignType.GetProperty("CampaignEventDispatcher", All);
		ConstructorInfo dispatcherConstructor = typeof(TaleWorlds.CampaignSystem.CampaignEventDispatcher)
			.GetConstructors(All)
			.SingleOrDefault(constructor =>
			{
				ParameterInfo[] parameters = constructor.GetParameters();
				return parameters.Length == 1
					&& typeof(IEnumerable<TaleWorlds.CampaignSystem.CampaignEventReceiver>)
						.IsAssignableFrom(parameters[0].ParameterType);
			});
		Check(currentProperty != null && dispatcherProperty != null && dispatcherConstructor != null,
			"Bannerlord campaign dispatcher API shape must be available for the real gold smoke test.");

		TaleWorlds.CampaignSystem.Campaign previous = TaleWorlds.CampaignSystem.Campaign.Current;
		try
		{
			TaleWorlds.CampaignSystem.Campaign campaign
				= (TaleWorlds.CampaignSystem.Campaign)System.Runtime.Serialization.FormatterServices
					.GetUninitializedObject(campaignType);
			currentProperty.SetValue(null, campaign);
			object dispatcher = dispatcherConstructor.Invoke(new object[]
			{
				Array.Empty<TaleWorlds.CampaignSystem.CampaignEventReceiver>()
			});
			dispatcherProperty.SetValue(campaign, dispatcher);

			TaleWorlds.CampaignSystem.Hero hero = new TaleWorlds.CampaignSystem.Hero { Gold = 100 };
			int before = hero.Gold;
			TaleWorlds.CampaignSystem.Actions.GiveGoldAction.ApplyBetweenCharacters(
				null,
				hero,
				250,
				disableNotification: true);
			TraceGold("grant", before, 250, hero.Gold);
			Check(hero.Gold == 350,
				"Real GiveGoldAction must directly credit a Hero when the giver is null.");

			before = hero.Gold;
			TaleWorlds.CampaignSystem.Actions.GiveGoldAction.ApplyBetweenCharacters(
				hero,
				null,
				50,
				disableNotification: true);
			TraceGold("debit", before, -50, hero.Gold);
			Check(hero.Gold == 300,
				"Real GiveGoldAction must debit the selected Hero when the recipient is null.");

			before = hero.Gold;
			TaleWorlds.CampaignSystem.Actions.GiveGoldAction.ApplyBetweenCharacters(
				hero,
				null,
				500,
				disableNotification: true);
			TraceGold("oversized-debit", before, -500, hero.Gold);
			Check(hero.Gold == 0,
				"Real GiveGoldAction must clamp an oversized Hero debit to the available balance.");

			hero.Gold = 100;
			before = hero.Gold;
			hero.ChangeHeroGold(25);
			TraceGold("change-hero-gold-positive", before, 25, hero.Gold);
			Check(hero.Gold == 125,
				"Real Hero.ChangeHeroGold must mutate the Hero-owned denar balance.");
			before = hero.Gold;
			hero.ChangeHeroGold(-40);
			TraceGold("change-hero-gold-negative", before, -40, hero.Gold);
			Check(hero.Gold == 85,
				"Real Hero.ChangeHeroGold must apply an in-balance negative delta exactly.");
			before = hero.Gold;
			TaleWorlds.CampaignSystem.Actions.GiveGoldAction.ApplyBetweenCharacters(
				null,
				hero,
				0,
				disableNotification: true);
			TraceGold("zero-grant", before, 0, hero.Gold);
			Check(hero.Gold == before,
				"Real GiveGoldAction must leave the Hero balance unchanged for a zero grant.");

			var identityCases = new[]
			{
				new { Selector = "role-ruler", Occupation = TaleWorlds.CampaignSystem.Occupation.Lord, Before = 1000, Delta = 900 },
				new { Selector = "role-lord", Occupation = TaleWorlds.CampaignSystem.Occupation.Lord, Before = 700, Delta = 600 },
				new { Selector = "role-clan-leader", Occupation = TaleWorlds.CampaignSystem.Occupation.Lord, Before = 800, Delta = 450 },
				new { Selector = "occupation-headman", Occupation = TaleWorlds.CampaignSystem.Occupation.Headman, Before = 180, Delta = 180 },
				new { Selector = "occupation-merchant", Occupation = TaleWorlds.CampaignSystem.Occupation.Merchant, Before = 350, Delta = 350 },
				new { Selector = "occupation-artisan", Occupation = TaleWorlds.CampaignSystem.Occupation.Artisan, Before = 220, Delta = 220 },
				new { Selector = "occupation-wanderer", Occupation = TaleWorlds.CampaignSystem.Occupation.Wanderer, Before = 120, Delta = 120 },
				new { Selector = "occupation-rural-notable", Occupation = TaleWorlds.CampaignSystem.Occupation.RuralNotable, Before = 260, Delta = 200 },
				new { Selector = "occupation-gang-leader", Occupation = TaleWorlds.CampaignSystem.Occupation.GangLeader, Before = 400, Delta = 275 },
				new { Selector = "occupation-preacher", Occupation = TaleWorlds.CampaignSystem.Occupation.Preacher, Before = 90, Delta = 110 },
				new { Selector = "occupation-goods-trader", Occupation = TaleWorlds.CampaignSystem.Occupation.GoodsTrader, Before = 500, Delta = 325 }
			};
			foreach (var identityCase in identityCases)
			{
				TaleWorlds.CampaignSystem.Hero identityHero = new TaleWorlds.CampaignSystem.Hero
				{
					Gold = identityCase.Before
				};
				identityHero.SetNewOccupation(identityCase.Occupation);
				before = identityHero.Gold;
				TaleWorlds.CampaignSystem.Actions.GiveGoldAction.ApplyBetweenCharacters(
					null,
					identityHero,
					identityCase.Delta,
					disableNotification: true);
				TraceGold(
					"identity-" + identityCase.Selector + "-" + identityCase.Occupation,
					before,
					identityCase.Delta,
					identityHero.Gold);
				Check(identityHero.Occupation == identityCase.Occupation
					&& identityHero.Gold == identityCase.Before + identityCase.Delta,
					"Real GiveGoldAction must credit the full AI-selected delta to identity group "
						+ identityCase.Selector + ".");
			}

			TaleWorlds.CampaignSystem.Hero dailyHero = new TaleWorlds.CampaignSystem.Hero { Gold = 100 };
			for (int day = 1; day <= 3; day++)
			{
				before = dailyHero.Gold;
				TaleWorlds.CampaignSystem.Actions.GiveGoldAction.ApplyBetweenCharacters(
					null,
					dailyHero,
					75,
					disableNotification: true);
				TraceGold("daily-grant-day-" + day.ToString(CultureInfo.InvariantCulture), before, 75, dailyHero.Gold);
			}
			Check(dailyHero.Gold == 325,
				"Three real daily Hero grants of +75 must accumulate from 100 to 325.");
		}
		finally
		{
			currentProperty?.SetValue(null, previous);
		}
	}

	private static void TestPolicyEffectMultiIntentRoutingContracts()
	{
		const string splitQuery = "综合改革\n增加粮食储备；加强治安巡逻，调整税率。提高稳定度！推进工程施工？扩充民兵；持续至资金用尽或另行调整";
		IReadOnlyList<string> intents = PolicyEffectModuleRouter.BuildQueryIntents(splitQuery, PolicyEffectScopes.Kingdom);
		Check(intents.Count >= 2 && intents.Count <= PolicyEffectModuleRouter.QueryIntentLimit
			&& string.Equals(intents[0], splitQuery, StringComparison.Ordinal),
			"Effect routing must retain the whole policy first and cap total query intents at twelve.");
		Check(intents.Skip(1).All(intent => intent.Length >= 2 && intent.Length <= PolicyEffectModuleRouter.QueryIntentCharacterLimit)
			&& intents.Distinct(StringComparer.Ordinal).Count() == intents.Count,
			"Effect routing clauses must be bounded, non-empty and deduplicated.");
		Check(intents.Any(intent => intent.Contains("提高稳定度")),
			"Scope-legal cue clauses must be retained in the bounded query set.");

		const string ordinaryOr = "补贴政策\n全国城镇获得粮食补助，持续至补贴资金用尽或另行调整";
		IReadOnlyList<string> ordinaryOrIntents = PolicyEffectModuleRouter.BuildQueryIntents(ordinaryOr, PolicyEffectScopes.Kingdom);
		Check(ordinaryOrIntents.All(intent => !string.Equals(intent, "另行调整", StringComparison.Ordinal))
			&& ordinaryOrIntents.Any(intent => intent.Contains("资金用尽或另行调整")),
			"Effect intent splitting must not split ordinary Chinese conjunctions such as 或.");

		IPolicyEffectModule prosperity = RequirePolicyEffectModule("prosperityPerDay");
		IPolicyEffectModule food = RequirePolicyEffectModule("foodPerDay");
		IPolicyEffectModule security = RequirePolicyEffectModule("securityPerDay");
		IPolicyEffectModule tax = RequirePolicyEffectModule("taxIncomePct");
		IPolicyEffectModule stability = RequirePolicyEffectModule("kingdomStability");
		IPolicyEffectModule hearth = RequirePolicyEffectModule("hearthPerDay");
		IReadOnlyList<PolicyEffectModuleIntentRecall> intentRecalls = new[]
		{
			BuildIntentRecall(0, true, "综合改革", (prosperity, 0.91f), (tax, 0.84f), (food, 0.80f), (stability, 0.20f)),
			BuildIntentRecall(1, false, "增加粮食储备", (food, 0.95f), (prosperity, 0.62f), (tax, 0.40f), (stability, 0.20f)),
			BuildIntentRecall(2, false, "加强治安巡逻", (security, 0.94f), (prosperity, 0.61f), (tax, 0.39f), (stability, 0.20f))
		};
		IReadOnlyList<IPolicyEffectModule> scopedModules = PolicyEffectModuleCatalog.GetModulesForScope(PolicyEffectScopes.Kingdom);
		IReadOnlyList<PolicyEffectModuleSelection> candidates = PolicyEffectModuleRouter.MergeCandidates(
			intentRecalls,
			scopedModules,
			"增加粮食储备，加强治安巡逻并提高稳定度",
			out int cueMatchCount,
			out bool candidateLimitTruncated);
		string[] candidateIds = candidates.Select(selection => selection.Module.Id).ToArray();
		Check(new[] { "prosperityPerDay", "foodPerDay", "securityPerDay" }
			.All(id => candidateIds.Contains(id, StringComparer.Ordinal)),
			"Candidate union must preserve the best semantic hit for every independent query measure.");
		IReadOnlyList<PolicyEffectModuleSelection> duplicatedTopCandidates = PolicyEffectModuleRouter.MergeCandidates(
			new[]
			{
				BuildIntentRecall(0, true, "综合改革", (prosperity, 0.91f), (tax, 0.84f), (food, 0.80f), (stability, 0.20f)),
				BuildIntentRecall(1, false, "增加粮食储备", (prosperity, 0.95f), (food, 0.94f), (tax, 0.40f), (stability, 0.20f)),
				BuildIntentRecall(2, false, "加强治安巡逻", (security, 0.94f), (prosperity, 0.61f), (tax, 0.39f), (stability, 0.20f))
			},
			scopedModules,
			"增加粮食储备，加强治安巡逻并提高稳定度",
			out _,
			out _);
		Check(new[] { "prosperityPerDay", "foodPerDay", "securityPerDay" }.All(id =>
			duplicatedTopCandidates.Any(selection => string.Equals(selection.Module.Id, id, StringComparison.Ordinal))),
			"When an earlier query repeats the same top module, the union must still retain later-query coverage.");
		Check(candidateIds.Contains("kingdomStability", StringComparer.Ordinal)
			&& candidates.Single(selection => string.Equals(selection.Module.Id, "kingdomStability", StringComparison.Ordinal)).CueMatched,
			"A full-policy cue match present in a per-query recall must be retained and reranked ahead of non-cue prose.");
		Check(!candidateIds.Contains(hearth.Id, StringComparer.Ordinal),
			"The internal candidate pool must be a per-query semantic/cue union, not a fill-to-cap scan of unrelated modules.");
		Check(cueMatchCount >= 3 && candidateLimitTruncated == (candidates.Count < scopedModules.Count),
			"Routing diagnostics must report whether the bounded per-query union omitted enabled modules.");
		Check(candidateIds.Distinct(StringComparer.Ordinal).Count() == candidateIds.Length
			&& candidateIds.Length <= PolicyEffectModuleRouter.CandidateHardMaximum,
			"Multi-intent dense and cue hits must deduplicate under the existing Candidate hard cap.");

		IReadOnlyList<PolicyEffectModuleSelection> details = PolicyEffectModuleRouter.SelectDetails(candidates, 3);
		Check(details.Count == 3
			&& details.All(selection => candidates.Contains(selection)),
			"Detail selection must preserve the reranked multi-query union and configured injection bound.");

		IReadOnlyList<PolicyEffectModuleSelection> repeated = PolicyEffectModuleRouter.MergeCandidates(
			intentRecalls,
			scopedModules,
			"增加粮食储备，加强治安巡逻并提高稳定度",
			out _,
			out _);
		Check(repeated.Select(selection => selection.Module.Id).SequenceEqual(candidateIds, StringComparer.Ordinal),
			"Multi-intent Candidate ordering must be deterministic across repeated calls.");
	}

	private static void TestPolicyEffectMultiIntentOnnxBaselineContracts()
	{
		if (string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(OnnxRuntimeDirectoryEnvironmentVariable)))
		{
			return;
		}
		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string baselinePath = Path.Combine(repositoryRoot ?? string.Empty,
			"tools", "PolicyEffectModule.ContractTests", "TestData", "policy_effect_module_retrieval.jsonl");
		Check(File.Exists(baselinePath), "Policy effect module retrieval baseline is missing: " + baselinePath);
		foreach (string line in File.ReadLines(baselinePath, Encoding.UTF8).Where(value => !string.IsNullOrWhiteSpace(value)))
		{
			JObject testCase = JObject.Parse(line);
			string caseId = testCase.Value<string>("case_id") ?? string.Empty;
			string scope = testCase.Value<string>("scope") ?? PolicyEffectScopes.Kingdom;
			string query = ((testCase.Value<string>("policy_name") ?? string.Empty) + "\n"
				+ (testCase.Value<string>("policy_content") ?? string.Empty)).Trim();
			string[] expected = ReadJsonStringList(testCase["expected_source_module_ids"]).ToArray();
			string[] forbidden = ReadJsonStringList(testCase["forbidden_source_module_ids"]).ToArray();
			float[] queryVector = PolicyEffectModuleRouter.GetQueryEmbedding(query);
			PolicyEffectModuleRoutingResult routing = PolicyEffectModuleRouter.Route(queryVector, query, scope);
			string[] candidates = routing.Candidates.Select(selection => selection.Module.Id).ToArray();
			string[] details = routing.Details.Select(selection => selection.Module.Id).ToArray();
			Check(expected.All(id => candidates.Contains(id, StringComparer.Ordinal)),
				"Multi-label Candidate recall missed an expected source module for " + caseId
				+ ": expected=" + string.Join(",", expected) + " actual=" + string.Join(",", candidates));
			Check(forbidden.All(id => !candidates.Contains(id, StringComparer.Ordinal)),
				"Scope filtering admitted a forbidden source module for " + caseId
				+ ": forbidden=" + string.Join(",", forbidden) + " actual=" + string.Join(",", candidates));
			if (testCase.Value<bool?>("require_detail_coverage") == true)
			{
				Check(expected.All(id => details.Contains(id, StringComparer.Ordinal)),
					"Multi-label Detail coverage missed an expected source module for " + caseId
					+ ": expected=" + string.Join(",", expected) + " actual=" + string.Join(",", details));
			}
			Check(candidates.Length <= PolicyEffectModuleRouter.CandidateHardMaximum
				&& details.Length <= PolicyEffectModuleRouter.DetailHardMaximum
				&& details.All(id => candidates.Contains(id, StringComparer.Ordinal)),
				"ONNX effect routing must preserve Candidate/Detail hard boundaries for " + caseId + ".");
			string candidateCatalog = PolicyEffectModuleCatalog.GetCapabilityCatalog(scope, candidates);
			string mainInstructions = PolicyEffectModuleCatalog.BuildMainInstructions(scope, details);
			string payloadRules = PolicyEffectModuleCatalog.BuildPayloadPromptRules(scope, candidates, details);
			IReadOnlyList<IPolicyEffectModule> candidateModuleRecords =
				PolicyEffectModuleCatalog.ResolveModulesForScope(scope, candidates);
			HashSet<string> detailIds = new HashSet<string>(details, StringComparer.Ordinal);
			Check(candidateCatalog.Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries).Length == candidates.Length,
				"Candidate prompt text must contain exactly the bounded short catalog and no hidden full definitions for " + caseId + ".");
			foreach (IPolicyEffectModule candidateOnly in candidateModuleRecords.Where(module => !detailIds.Contains(module.Id)))
			{
				Check(mainInstructions.IndexOf(candidateOnly.MainInstruction.Trim(), StringComparison.Ordinal) < 0
					&& payloadRules.IndexOf(candidateOnly.PostprocessRule.Trim(), StringComparison.Ordinal) >= 0
					&& payloadRules.IndexOf(candidateOnly.Descriptor.PayloadPromptSchema.ToString(Formatting.None), StringComparison.Ordinal) >= 0
					&& payloadRules.IndexOf(PolicyEffectPromptService.GetEvaluationPrompt(candidateOnly), StringComparison.Ordinal) < 0,
					"A Candidate-only module must receive its payload contract without leaking full understanding or editable calibration for "
					+ caseId + ": " + candidateOnly.Id);
			}
			Console.WriteLine("ONNX_EFFECT_MULTI_INTENT case=" + caseId
				+ " intents=" + routing.IntentCount.ToString(CultureInfo.InvariantCulture)
				+ " extraEmbeddings=" + routing.AdditionalQueryEmbeddingCount.ToString(CultureInfo.InvariantCulture)
				+ " candidates=" + string.Join(",", candidates)
				+ " details=" + string.Join(",", details)
				+ " candidateChars=" + candidateCatalog.Length.ToString(CultureInfo.InvariantCulture)
				+ " mainInstructionChars=" + mainInstructions.Length.ToString(CultureInfo.InvariantCulture)
				+ " payloadRuleChars=" + payloadRules.Length.ToString(CultureInfo.InvariantCulture));
		}

		const string failureQuery = "多效果失败关闭\n增加粮食储备；加强治安巡逻";
		float[] failureWholeVector = PolicyEffectModuleRouter.GetQueryEmbedding(failureQuery);
		int failedAdditionalEmbeddingCalls = 0;
		bool additionalEmbeddingFailedClosed = false;
		try
		{
			PolicyEffectModuleRouter.Route(
				failureWholeVector,
				failureQuery,
				PolicyEffectScopes.Kingdom,
				_ =>
				{
					failedAdditionalEmbeddingCalls++;
					return null;
				});
		}
		catch (InvalidOperationException)
		{
			additionalEmbeddingFailedClosed = true;
		}
		Check(additionalEmbeddingFailedClosed && failedAdditionalEmbeddingCalls == 1,
			"Any additional intent embedding failure must fail the entire effect route closed without lexical-only fallback.");

		float[] incompatibleAdditionalVector = new float[Math.Max(1, failureWholeVector.Length - 1)];
		incompatibleAdditionalVector[0] = 1f;
		bool invalidAdditionalEmbeddingFailedClosed = false;
		try
		{
			PolicyEffectModuleRouter.Route(
				failureWholeVector,
				failureQuery,
				PolicyEffectScopes.Kingdom,
				_ => incompatibleAdditionalVector);
		}
		catch (InvalidOperationException)
		{
			invalidAdditionalEmbeddingFailedClosed = true;
		}
		Check(invalidAdditionalEmbeddingFailedClosed,
			"An additional intent embedding with an incompatible shape must fail the entire effect route closed.");
	}

	private static IPolicyEffectModule RequirePolicyEffectModule(string moduleId)
	{
		Check(PolicyEffectModuleCatalog.TryGet(moduleId, out IPolicyEffectModule module),
			"Required policy effect module is missing: " + moduleId);
		return module;
	}

	private static PolicyEffectModuleIntentRecall BuildIntentRecall(
		int ordinal,
		bool isPrimary,
		string queryText,
		params (IPolicyEffectModule Module, float Score)[] ranked)
	{
		return new PolicyEffectModuleIntentRecall
		{
			IntentOrdinal = ordinal,
			IsPrimary = isPrimary,
			QueryText = queryText ?? string.Empty,
			Ranked = (ranked ?? Array.Empty<(IPolicyEffectModule Module, float Score)>())
				.Select((item, rank) => new PolicyEffectModuleSelection
				{
					Module = item.Module,
					RecallScore = item.Score,
					BestIntentOrdinal = ordinal,
					BestIntentRank = rank
				})
				.ToArray()
		};
	}

	private static void TestPlayerVisibleEffectDescriptions()
	{
		PolicyEffectInstanceSaveData prosperity = BuildPlayerVisibleEffectInstance(
			"display-prosperity",
			"M0",
			"prosperityPerDay",
			5f,
			new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "S:display-town" },
				SettlementIds = new List<string> { "display-town" },
				TownIds = new List<string> { "display-town" }
			});
		PolicyEffectInstanceSaveData stability = BuildPlayerVisibleEffectInstance(
			"display-stability",
			"M1",
			"kingdomStabilityNextDayOnce",
			4f,
			new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "K:display-kingdom" },
				KingdomIds = new List<string> { "display-kingdom" }
			});
		List<string> independent = PolicyEffectSaveCodec.DescribePlayerVisibleInstances(new[] { prosperity, stability });
		Check(independent.Count == 2,
			"Two distinct effect modules must remain two independent player-visible descriptions.");
		Check(independent.All(text => !string.IsNullOrWhiteSpace(text) && !ContainsAsciiLetter(text))
			&& independent.Any(text => text.Contains("繁荣变化：每日 +5"))
			&& independent.Any(text => text.Contains("王国稳定度：下一游戏日一次 +4")),
			"Player-visible module descriptions must use Chinese catalog labels without leaking module IDs. actual="
			+ string.Join(" | ", independent)
			+ " technical=" + PolicyEffectSaveCodec.DescribeInstance(prosperity));

		PolicyEffectInstanceSaveData influenceOnce = BuildPlayerVisibleEffectInstance(
			"display-influence-once",
			"M2",
			"clanInfluenceNextDayOnce",
			3f,
			new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "C:display-clan" },
				ClanIds = new List<string> { "display-clan" }
			});
		PolicyEffectInstanceSaveData influenceDaily = BuildPlayerVisibleEffectInstance(
			"display-influence-daily",
			"M2",
			"clanInfluencePerDay",
			-0.5f,
			new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "C:display-clan" },
				ClanIds = new List<string> { "display-clan" }
			});
