		PropertyInfo promptHubAction = settingsType.GetProperty("EditPolicyPrompts", All);
		PropertyInfo legacyPlayerAction = settingsType.GetProperty("EditCustomPolicyEvaluatorPrompt", All);
		PropertyInfo legacyNpcAction = settingsType.GetProperty("EditNpcRulerPolicyPrompt", All);
		Check(promptHubAction != null && HasMcmButtonAttribute(promptHubAction)
			&& legacyPlayerAction != null && !HasMcmButtonAttribute(legacyPlayerAction)
			&& legacyNpcAction != null && !HasMcmButtonAttribute(legacyNpcAction),
			"MCM must expose one policy prompt hub instead of separate player and NPC prompt buttons.");
		string playerEvaluationDefault = (string)settingsType.GetField("DefaultCustomPolicyEvaluatorPrompt", All)?.GetValue(null);
		string npcPolicyDefault = (string)settingsType.GetField("DefaultNpcRulerPolicyPrompt", All)?.GetValue(null);
		Check(IsSafePlayerVisiblePolicyText(playerEvaluationDefault)
			&& IsSafePlayerVisiblePolicyText(npcPolicyDefault),
			"Default player-evaluation and NPC-policy editable text must not expose technical output fields or source concepts.");
		string[] monolithicEffectSectionTokens =
		{
			"当前可落地影响项共有", "数值推荐尺度如下", "每座城镇每日繁荣度", "王国稳定度在政策正式生效时",
			"城镇与城堡主税收百分比表示", "设施建设采用每日固定建造力"
		};
		Check(monolithicEffectSectionTokens.All(token => playerEvaluationDefault.IndexOf(token, StringComparison.Ordinal) < 0)
			&& monolithicEffectSectionTokens.All(token => npcPolicyDefault.IndexOf(token, StringComparison.Ordinal) < 0),
			"General player/NPC prompts must not repeat effect-module responsibilities or numeric calibration.");
		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string policyPromptDirectory = Path.Combine(repositoryRoot, "AnimusForge", "CustomPrompts", "Policy");
		string[] packagedPolicyPromptFileNames =
		{
			"CustomPolicyEvaluatorPrompt.json",
			"NpcRulerPolicyPrompt.json",
			PolicyEffectPromptService.AutoDraftPromptFileName
		};
		Check(packagedPolicyPromptFileNames.All(fileName => File.Exists(Path.Combine(policyPromptDirectory, fileName)))
			&& Directory.Exists(Path.Combine(policyPromptDirectory, PolicyEffectPromptService.EffectPromptDirectoryName))
			&& File.Exists(Path.Combine(policyPromptDirectory, PolicyEffectPromptService.EffectPromptDirectoryName, PolicyEffectPromptService.CommonEffectPromptFileName))
			&& !File.Exists(Path.Combine(policyPromptDirectory, "PolicyEffectPrompts.v1.json"))
			&& packagedPolicyPromptFileNames.All(fileName => !File.Exists(Path.Combine(repositoryRoot, "AnimusForge", "CustomPrompts", fileName)))
			&& string.Equals(
				(string)InvokeStatic(settingsType, "BuildPolicyPromptSubdirectoryForContractTests", new object[] { Path.Combine(repositoryRoot, "AnimusForge", "CustomPrompts") }, 1),
				policyPromptDirectory,
				StringComparison.OrdinalIgnoreCase),
			"All policy prompt files must live together under CustomPrompts/Policy, with no policy prompt copies left at the CustomPrompts root.");
		JObject packagedPlayerPrompt = JObject.Parse(File.ReadAllText(
			Path.Combine(policyPromptDirectory, "CustomPolicyEvaluatorPrompt.json"), Encoding.UTF8));
		JObject packagedNpcPrompt = JObject.Parse(File.ReadAllText(
			Path.Combine(policyPromptDirectory, "NpcRulerPolicyPrompt.json"), Encoding.UTF8));
		JObject packagedAutoDraftPrompt = JObject.Parse(File.ReadAllText(
			Path.Combine(policyPromptDirectory, PolicyEffectPromptService.AutoDraftPromptFileName), Encoding.UTF8));
		Check(string.Equals((string)packagedPlayerPrompt["Text"], playerEvaluationDefault, StringComparison.Ordinal)
			&& string.Equals((string)packagedNpcPrompt["Text"], npcPolicyDefault, StringComparison.Ordinal)
			&& string.Equals((string)packagedAutoDraftPrompt["Text"], PolicyEffectPromptService.DefaultAutoDraftPrompt, StringComparison.Ordinal),
			"Packaged general prompt files must contain the split defaults, not the old monolithic effect prompt.");
		string previousPlayerBuiltIn = (string)settingsType.GetField("PreviousDefaultCustomPolicyEvaluatorPromptBeforeNaturalEditableLayer", All)?.GetValue(null);
		string previousNpcBuiltIn = (string)settingsType.GetField("PreviousDefaultNpcRulerPolicyPromptBeforeNaturalEditableLayer", All)?.GetValue(null);
		Check((bool)InvokeStatic(settingsType, "IsBuiltInCustomPolicyEvaluatorPromptText", new object[] { previousPlayerBuiltIn }, 1)
			&& string.Equals((string)InvokeStatic(settingsType, "NormalizeNpcRulerPolicyPromptText", new object[] { previousNpcBuiltIn }, 1), npcPolicyDefault, StringComparison.Ordinal)
			&& string.Equals((string)InvokeStatic(settingsType, "NormalizeCustomPolicyEvaluatorPromptText", new object[] { "玩家自己的评议偏好" }, 1), "玩家自己的评议偏好", StringComparison.Ordinal)
			&& string.Equals((string)InvokeStatic(settingsType, "NormalizeNpcRulerPolicyPromptText", new object[] { "玩家自己的统治者写作偏好" }, 1), "玩家自己的统治者写作偏好", StringComparison.Ordinal),
			"Only exact legacy built-in policy prompts may migrate; user-authored player and NPC text must remain unchanged.");

		IReadOnlyList<PolicyPromptMenuEntry> rootEntries = PolicyPromptEditorUi.BuildRootEntriesForContractTests();
		Check(rootEntries.Select(entry => entry.Title).SequenceEqual(new[]
		{
			"玩家AI编写",
			"玩家政策评议",
			"NPC 统治者政策",
			"政策效果要求"
		}), "Policy prompt hub must expose the four approved natural-language layers in order.");
		Check(rootEntries.All(entry => IsSafePlayerVisiblePolicyText(entry.Title + "\n" + entry.Hint)),
			"Policy prompt hub titles and hints must not expose source symbols, internal IDs, JSON fields, or target handles.");
		PolicyPromptMenuEntry commonEffectEntry = PolicyPromptEditorUi.BuildCommonEffectEntryForContractTests();
		Check(commonEffectEntry != null
			&& string.Equals(commonEffectEntry.Title, "全部效果共同要求", StringComparison.Ordinal)
			&& IsSafePlayerVisiblePolicyText(commonEffectEntry.Title + "\n" + commonEffectEntry.Hint),
			"The effect editor must expose one natural-language common layer instead of repeating shared rules in every module.");

		IReadOnlyList<PolicyEffectPromptEditorEntry> catalogEntries = PolicyPromptEditorUi.BuildEffectEntriesForContractTests(PolicyEffectModuleCatalog.Modules);
		IReadOnlyList<IPolicyEffectModule> visibleModules = PolicyEffectModuleCatalog.Modules;
		Check(catalogEntries.Count == visibleModules.Count
			&& catalogEntries.Select(entry => entry.ModuleId).SequenceEqual(visibleModules.Select(module => module.Id)),
			"Effect prompt editor must derive its complete module set from the prompt-visible catalog without a fixed module list.");
		Check(catalogEntries.All(entry => !string.IsNullOrWhiteSpace(entry.DisplayName)
			&& !string.Equals(entry.DisplayName, entry.ModuleId, StringComparison.Ordinal)
			&& IsSafePlayerVisiblePolicyText(entry.DisplayName)
			&& IsSafePlayerVisiblePolicyText(entry.DefaultUnderstandingPrompt)
			&& IsSafePlayerVisiblePolicyText(entry.DefaultEvaluationPrompt)
			&& !System.Text.RegularExpressions.Regex.IsMatch(entry.DefaultUnderstandingPrompt ?? string.Empty, "[0-9０-９±%％]")
			&& (entry.DefaultUnderstandingPrompt ?? string.Empty).IndexOf("每日", StringComparison.Ordinal) < 0
			&& (entry.DefaultUnderstandingPrompt ?? string.Empty).IndexOf("下一游戏日", StringComparison.Ordinal) < 0
			&& (entry.DefaultUnderstandingPrompt ?? string.Empty).IndexOf("结算", StringComparison.Ordinal) < 0
			&& (entry.DefaultEvaluationPrompt ?? string.Empty).IndexOf("仅当", StringComparison.Ordinal) < 0
			&& (entry.DefaultEvaluationPrompt ?? string.Empty).IndexOf("才把", StringComparison.Ordinal) < 0
			&& (entry.DefaultEvaluationPrompt ?? string.Empty).IndexOf("不属于这一项", StringComparison.Ordinal) < 0),
			"Effect editor display names and default editable prompts must stay natural-language-only.");
		PolicyEffectPromptEditorEntry prosperityEntry = catalogEntries.Single(entry => string.Equals(entry.ModuleId, "prosperityPerDay", StringComparison.Ordinal));
		PolicyEffectPromptEditorEntry foodEntry = catalogEntries.Single(entry => string.Equals(entry.ModuleId, "foodPerDay", StringComparison.Ordinal));
		PolicyEffectPromptEditorEntry securityEntry = catalogEntries.Single(entry => string.Equals(entry.ModuleId, "securityPerDay", StringComparison.Ordinal));
		PolicyEffectPromptEditorEntry militiaEntry = catalogEntries.Single(entry => string.Equals(entry.ModuleId, "militiaPerDay", StringComparison.Ordinal));
		Check(prosperityEntry.DefaultEvaluationPrompt.Contains("±12 到 ±24")
			&& prosperityEntry.DefaultEvaluationPrompt.Contains("±24 到 ±36")
			&& foodEntry.DefaultEvaluationPrompt.Contains("±18 到 ±30")
			&& securityEntry.DefaultEvaluationPrompt.Contains("±1.5 到 ±2.5")
			&& militiaEntry.DefaultEvaluationPrompt.Contains("±8 到 ±12"),
			"Module numeric calibration must reuse the tested remote ranges instead of newly invented scales.");
		Check(HiddenRuntimeModuleIds.All(hiddenId => catalogEntries.All(entry => !string.Equals(entry.ModuleId, hiddenId, StringComparison.Ordinal))),
			"Hidden runtime descendants must never appear in the effect prompt editor.");
		string packagedEffectDirectory = Path.Combine(policyPromptDirectory, PolicyEffectPromptService.EffectPromptDirectoryName);
		JObject packagedCommonEffectPrompt = JObject.Parse(File.ReadAllText(
			Path.Combine(packagedEffectDirectory, PolicyEffectPromptService.CommonEffectPromptFileName), Encoding.UTF8));
		string[] unsynchronizedEffectPromptIds = visibleModules.Where(module =>
		{
			string modulePath = Path.Combine(packagedEffectDirectory, module.Id + ".json");
			if (!File.Exists(modulePath))
			{
				return true;
			}
			JObject moduleDocument = JObject.Parse(File.ReadAllText(modulePath, Encoding.UTF8));
			return moduleDocument.Value<int?>("Version") != 1
				|| !string.Equals((string)moduleDocument["ModuleId"], module.Id, StringComparison.Ordinal)
				|| !string.Equals((string)moduleDocument["UnderstandingPrompt"], module.Descriptor.EditableUnderstandingPrompt, StringComparison.Ordinal)
				|| !string.Equals((string)moduleDocument["EvaluationPrompt"], module.Descriptor.EditableEvaluationPrompt, StringComparison.Ordinal);
		}).Select(module => module.Id).ToArray();
		Check(string.Equals((string)packagedCommonEffectPrompt["CommonEvaluationPrompt"], PolicyEffectPromptService.DefaultCommonEvaluationPrompt, StringComparison.Ordinal)
			&& IsSafePlayerVisiblePolicyText(PolicyEffectPromptService.DefaultCommonEvaluationPrompt)
			&& PolicyEffectPromptService.DefaultCommonEvaluationPrompt.Contains("合理直接或紧邻一阶结果")
			&& PolicyEffectPromptService.DefaultCommonEvaluationPrompt.Contains("不要求正文逐字命名游戏指标")
			&& PolicyEffectPromptService.DefaultCommonEvaluationPrompt.Contains("同一笔投入")
			&& PolicyEffectPromptService.DefaultCommonEvaluationPrompt.Contains("不算重复计算")
			&& PolicyEffectPromptService.DefaultCommonEvaluationPrompt.Contains("不存在最低效果数量")
			&& PolicyEffectPromptService.DefaultCommonEvaluationPrompt.IndexOf("王国稳定度", StringComparison.Ordinal) < 0
			&& PolicyEffectPromptService.DefaultCommonEvaluationPrompt.IndexOf("家族影响力", StringComparison.Ordinal) < 0
			&& PolicyEffectPromptService.DefaultCommonEvaluationPrompt.IndexOf("家族领袖关系", StringComparison.Ordinal) < 0
			&& unsynchronizedEffectPromptIds.Length == 0,
			"Packaged effect prompt defaults must stay synchronized with the dynamic catalog and shared layer. ids="
			+ string.Join(",", unsynchronizedEffectPromptIds));

		StructuredDummyEffectModule futureModule = new StructuredDummyEffectModule();
		IReadOnlyList<PolicyEffectPromptEditorEntry> futureEntries = PolicyPromptEditorUi.BuildEffectEntriesForContractTests(new[] { futureModule });
		Check(futureEntries.Count == 1
			&& string.Equals(futureEntries[0].ModuleId, StructuredDummyEffectModule.ModuleId, StringComparison.Ordinal)
			&& string.Equals(futureEntries[0].DisplayName, futureModule.Descriptor.PlayerDisplayName, StringComparison.Ordinal),
			"A newly registered prompt-visible module must become editable without a UI branch or fixed-name update.");

		string tempRoot = Path.Combine(Path.GetTempPath(), "af-policy-prompt-contract-" + Guid.NewGuid().ToString("N"));
		Directory.CreateDirectory(tempRoot);
		PolicyEffectPromptService.SetStorageDirectoryOverrideForContractTests(tempRoot);
		try
		{
			string legacyPlayerPath = Path.Combine(tempRoot, "CustomPolicyEvaluatorPrompt.json");
			string legacyNpcPath = Path.Combine(tempRoot, "NpcRulerPolicyPrompt.json");
			File.WriteAllText(legacyPlayerPath, "{\"Version\":1,\"Text\":\"PLAYER_CUSTOM_MUST_STAY\"}", new UTF8Encoding(false));
			File.WriteAllText(legacyNpcPath, "{\"Version\":1,\"Text\":\"NPC_CUSTOM_MUST_STAY\"}", new UTF8Encoding(false));
			Check(PolicyEffectPromptService.EnsureStorageFiles(out string ensureError),
				"Policy prompt storage files must initialize independently: " + ensureError);
			Check(File.ReadAllText(legacyPlayerPath, Encoding.UTF8).Contains("PLAYER_CUSTOM_MUST_STAY")
				&& File.ReadAllText(legacyNpcPath, Encoding.UTF8).Contains("NPC_CUSTOM_MUST_STAY"),
				"Initializing new policy prompt files must not overwrite legacy player or NPC custom prompt files.");
			string autoDraftPath = Path.Combine(tempRoot, PolicyEffectPromptService.AutoDraftPromptFileName);
			JObject initializedAutoDraft = JObject.Parse(File.ReadAllText(autoDraftPath, Encoding.UTF8));
			string effectDirectory = Path.Combine(tempRoot, PolicyEffectPromptService.EffectPromptDirectoryName);
			JObject initializedCommon = JObject.Parse(File.ReadAllText(
				Path.Combine(effectDirectory, PolicyEffectPromptService.CommonEffectPromptFileName), Encoding.UTF8));
			Check(string.Equals((string)initializedAutoDraft["Text"], PolicyEffectPromptService.DefaultAutoDraftPrompt, StringComparison.Ordinal)
				&& string.Equals((string)initializedCommon["CommonEvaluationPrompt"], PolicyEffectPromptService.DefaultCommonEvaluationPrompt, StringComparison.Ordinal)
				&& visibleModules.All(module =>
				{
					JObject moduleDocument = JObject.Parse(File.ReadAllText(Path.Combine(effectDirectory, module.Id + ".json"), Encoding.UTF8));
					return string.Equals((string)moduleDocument["ModuleId"], module.Id, StringComparison.Ordinal)
						&& string.Equals((string)moduleDocument["UnderstandingPrompt"], module.Descriptor.EditableUnderstandingPrompt, StringComparison.Ordinal)
						&& string.Equals((string)moduleDocument["EvaluationPrompt"], module.Descriptor.EditableEvaluationPrompt, StringComparison.Ordinal);
				}),
				"Fresh policy prompt files must contain the complete editable defaults instead of empty lazy placeholders.");

			string firstId = visibleModules[0].Id;
			string secondId = visibleModules[1].Id;
			string commonPath = Path.Combine(effectDirectory, PolicyEffectPromptService.CommonEffectPromptFileName);
			string firstPath = Path.Combine(effectDirectory, firstId + ".json");
			string secondPath = Path.Combine(effectDirectory, secondId + ".json");
			string unknownPath = Path.Combine(effectDirectory, "future.module.kept.json");
			File.WriteAllText(commonPath, new JObject
			{
				["Version"] = 1,
				["CommonEvaluationPrompt"] = "COMMON_EFFECT_OVERRIDE"
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			File.WriteAllText(firstPath, new JObject
			{
				["Version"] = 1,
				["ModuleId"] = firstId,
				["UnderstandingPrompt"] = "FIRST_UNDERSTANDING_OVERRIDE",
				["EvaluationPrompt"] = 42
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			File.WriteAllText(secondPath, new JObject
			{
				["Version"] = 1,
				["ModuleId"] = secondId,
				["UnderstandingPrompt"] = "SECOND_UNDERSTANDING_OVERRIDE",
				["EvaluationPrompt"] = "SECOND_EVALUATION_OVERRIDE"
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			File.WriteAllText(unknownPath, new JObject
			{
				["Version"] = 1,
				["ModuleId"] = "future.module.kept",
				["UnderstandingPrompt"] = "UNKNOWN_OVERRIDE_MUST_STAY_INERT",
				["EvaluationPrompt"] = "UNKNOWN_EVALUATION_MUST_STAY_INERT"
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			PolicyEffectPromptService.ReloadForContractTests();

			string firstMain = PolicyEffectModuleCatalog.BuildMainInstructions(PolicyEffectScopes.Kingdom, new[] { firstId }, new[] { firstId });
			string firstPayload = PolicyEffectModuleCatalog.BuildPayloadPromptRules(PolicyEffectScopes.Kingdom, new[] { firstId, secondId }, new[] { firstId, secondId });
			string unauthorizedDetailed = PolicyEffectModuleCatalog.BuildMainInstructions(PolicyEffectScopes.Kingdom, new[] { firstId }, new[] { secondId });
			Check(firstMain.Contains("FIRST_UNDERSTANDING_OVERRIDE")
				&& !firstMain.Contains("SECOND_UNDERSTANDING_OVERRIDE")
				&& firstMain.IndexOf("numericIntent", StringComparison.OrdinalIgnoreCase) < 0
				&& firstMain.IndexOf("不要输出模块 ID", StringComparison.Ordinal) < 0
				&& !firstPayload.Contains("42")
				&& firstPayload.Contains(visibleModules[0].Descriptor.EditableEvaluationPrompt)
				&& string.IsNullOrEmpty(unauthorizedDetailed)
				&& firstPayload.Split(new[] { "COMMON_EFFECT_OVERRIDE" }, StringSplitOptions.None).Length - 1 == 1,
				"Only frozen candidate modules may receive overrides, and one malformed field must fall back without corrupting other modules.");
			Check(string.IsNullOrEmpty(PolicyEffectModuleCatalog.BuildMainInstructions(PolicyEffectScopes.Kingdom, new[] { "future.module.kept" }, new[] { "future.module.kept" })),
				"Unknown stored module overrides must remain inert and must not create model candidates.");
			Check(PolicyEffectModuleCatalog.ResolveModulesForScope(PolicyEffectScopes.Kingdom, new[] { firstId }).All(module => string.Equals(module.Id, firstId, StringComparison.Ordinal))
				&& !PolicyEffectPromptService.TrySaveModulePrompt(HiddenRuntimeModuleIds[0], PolicyEffectPromptKind.Understanding, "HIDDEN_MUST_NOT_BECOME_VISIBLE", out _),
				"Editable text must not expand the frozen candidate set or make hidden runtime descendants configurable.");

			byte[] secondBeforeSave = File.ReadAllBytes(secondPath);
			byte[] commonBeforeSave = File.ReadAllBytes(commonPath);
			byte[] unknownBeforeSave = File.ReadAllBytes(unknownPath);
			Check(PolicyEffectPromptService.TrySaveModulePrompt(firstId, PolicyEffectPromptKind.Evaluation, "FIRST_EVALUATION_SAVED", out string saveError),
				"A known module evaluation prompt must save successfully: " + saveError);
			JObject saved = JObject.Parse(File.ReadAllText(firstPath, Encoding.UTF8));
			Check((string)saved["EvaluationPrompt"] == "FIRST_EVALUATION_SAVED"
				&& secondBeforeSave.SequenceEqual(File.ReadAllBytes(secondPath))
				&& commonBeforeSave.SequenceEqual(File.ReadAllBytes(commonPath))
				&& unknownBeforeSave.SequenceEqual(File.ReadAllBytes(unknownPath)),
				"Saving one known module must rewrite only that module file.");
			Check(PolicyEffectPromptService.TrySaveModulePrompt(firstId, PolicyEffectPromptKind.Understanding, "", out saveError)
				&& string.Equals(PolicyEffectPromptService.GetUnderstandingPrompt(visibleModules[0]), visibleModules[0].Descriptor.EditableUnderstandingPrompt, StringComparison.Ordinal)
				&& string.Equals((string)JObject.Parse(File.ReadAllText(firstPath, Encoding.UTF8))["UnderstandingPrompt"], visibleModules[0].Descriptor.EditableUnderstandingPrompt, StringComparison.Ordinal),
				"Saving a blank module prompt must restore only that prompt to its module default.");
			Check(PolicyEffectPromptService.TrySaveCommonEvaluationPrompt("COMMON_EFFECT_SAVED", out saveError)
				&& string.Equals(PolicyEffectPromptService.GetCommonEvaluationPrompt(), "COMMON_EFFECT_SAVED", StringComparison.Ordinal)
				&& PolicyEffectModuleCatalog.BuildPayloadPromptRules(PolicyEffectScopes.Kingdom, new[] { firstId, secondId }, new[] { firstId, secondId })
					.Split(new[] { "COMMON_EFFECT_SAVED" }, StringSplitOptions.None).Length - 1 == 1,
				"The shared effect calibration must be editable and injected exactly once per frozen candidate request.");
			Check(PolicyEffectPromptService.TrySaveCommonEvaluationPrompt("", out saveError)
				&& string.Equals(PolicyEffectPromptService.GetCommonEvaluationPrompt(), PolicyEffectPromptService.DefaultCommonEvaluationPrompt, StringComparison.Ordinal)
				&& string.Equals((string)JObject.Parse(File.ReadAllText(commonPath, Encoding.UTF8))["CommonEvaluationPrompt"], PolicyEffectPromptService.DefaultCommonEvaluationPrompt, StringComparison.Ordinal),
				"Blank shared-effect text must restore only the tested shared default.");

			File.WriteAllText(firstPath, "{broken", new UTF8Encoding(false));
			File.WriteAllText(secondPath, new JObject
			{
				["Version"] = 1,
				["ModuleId"] = secondId,
				["UnderstandingPrompt"] = "SECOND_SURVIVES_FIRST_CORRUPTION",
				["EvaluationPrompt"] = "SECOND_EVALUATION_SURVIVES"
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			PolicyEffectPromptService.ReloadForContractTests();
			Check(string.Equals(PolicyEffectPromptService.GetUnderstandingPrompt(visibleModules[0]), visibleModules[0].Descriptor.EditableUnderstandingPrompt, StringComparison.Ordinal)
				&& string.Equals(PolicyEffectPromptService.GetUnderstandingPrompt(visibleModules[1]), "SECOND_SURVIVES_FIRST_CORRUPTION", StringComparison.Ordinal),
				"One malformed module file must fall back independently without corrupting another module.");

			File.WriteAllText(commonPath, "{broken", new UTF8Encoding(false));
			PolicyEffectPromptService.ReloadForContractTests();
			Check(string.Equals(PolicyEffectPromptService.GetCommonEvaluationPrompt(), PolicyEffectPromptService.DefaultCommonEvaluationPrompt, StringComparison.Ordinal)
				&& string.Equals(PolicyEffectPromptService.GetUnderstandingPrompt(visibleModules[1]), "SECOND_SURVIVES_FIRST_CORRUPTION", StringComparison.Ordinal),
				"A malformed common file must fall back without corrupting any module file.");

			File.WriteAllText(firstPath, new JObject
			{
				["Version"] = 2,
				["ModuleId"] = firstId,
				["UnderstandingPrompt"] = "UNSUPPORTED_VERSION_MUST_BE_INERT",
				["EvaluationPrompt"] = "UNSUPPORTED_VERSION_MUST_BE_INERT"
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			PolicyEffectPromptService.ReloadForContractTests();
			Check(string.Equals(PolicyEffectPromptService.GetUnderstandingPrompt(visibleModules[0]), visibleModules[0].Descriptor.EditableUnderstandingPrompt, StringComparison.Ordinal),
				"An unsupported per-module prompt version must fall back only that module.");

			File.WriteAllText(firstPath, new JObject
			{
				["Version"] = 1,
				["ModuleId"] = secondId,
				["UnderstandingPrompt"] = "MISMATCHED_MODULE_ID_MUST_BE_INERT",
				["EvaluationPrompt"] = "MISMATCHED_MODULE_ID_MUST_BE_INERT"
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			PolicyEffectPromptService.ReloadForContractTests();
			Check(string.Equals(PolicyEffectPromptService.GetUnderstandingPrompt(visibleModules[0]), visibleModules[0].Descriptor.EditableUnderstandingPrompt, StringComparison.Ordinal),
				"A ModuleId mismatch at the expected canonical filename must fall back only that module.");

			File.Delete(firstPath);
			PolicyEffectPromptService.ReloadForContractTests();
			Check(string.Equals(PolicyEffectPromptService.GetUnderstandingPrompt(visibleModules[0]), visibleModules[0].Descriptor.EditableUnderstandingPrompt, StringComparison.Ordinal)
				&& string.IsNullOrEmpty(PolicyEffectModuleCatalog.BuildMainInstructions(
					PolicyEffectScopes.Local,
					new[] { "kingdomStability" },
					new[] { "kingdomStability" })),
				"A missing module file must use its built-in fallback, and an out-of-scope registered file must remain unauthorized.");

			JObject validFirst = new JObject
			{
				["Version"] = 1,
				["ModuleId"] = firstId,
				["UnderstandingPrompt"] = "ATOMIC_ORIGINAL",
				["EvaluationPrompt"] = "ATOMIC_EVALUATION"
			};
			File.WriteAllText(firstPath, validFirst.ToString(Formatting.Indented), new UTF8Encoding(false));
			byte[] atomicOriginal = File.ReadAllBytes(firstPath);
			using (FileStream locked = new FileStream(firstPath, FileMode.Open, FileAccess.Read, FileShare.None))
			{
				Check(!PolicyEffectPromptService.TrySaveModulePrompt(firstId, PolicyEffectPromptKind.Understanding, "MUST_NOT_PARTIALLY_REPLACE", out _),
					"An atomic replacement failure must be reported instead of falling back to a non-atomic overwrite.");
			}
			Check(atomicOriginal.SequenceEqual(File.ReadAllBytes(firstPath))
				&& !Directory.EnumerateFiles(effectDirectory, firstId + ".json.tmp-*", SearchOption.TopDirectoryOnly).Any(),
				"An atomic replacement failure must preserve the original bytes and clean its temporary file.");

			string previousAutoDraftGenericExpansion = (string)typeof(PolicyEffectPromptService)
				.GetField("PreviousDefaultAutoDraftPromptGenericExpansion", All)
				.GetRawConstantValue();
			string previousAutoDraftDefault = (string)typeof(PolicyEffectPromptService)
				.GetField("PreviousDefaultAutoDraftPromptWithEditableTransport", All)
				.GetRawConstantValue();
			string previousAutoDraftWithoutActionableMeasures = (string)typeof(PolicyEffectPromptService)
				.GetField("PreviousDefaultAutoDraftPromptWithoutActionableMeasures", All)
				.GetRawConstantValue();
			string previousCommonDefault = (string)typeof(PolicyEffectPromptService)
				.GetField("PreviousDefaultCommonEvaluationPromptWithFixedEffects", All)
				.GetRawConstantValue();
			string previousCommonBeforeReasonableInference = (string)typeof(PolicyEffectPromptService)
				.GetField("PreviousDefaultCommonEvaluationPromptBeforeReasonableInference", All)
				.GetRawConstantValue();
			File.WriteAllText(autoDraftPath, new JObject
			{
				["Version"] = 1,
				["Text"] = previousAutoDraftGenericExpansion
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			File.WriteAllText(commonPath, new JObject
			{
				["Version"] = 1,
				["CommonEvaluationPrompt"] = previousCommonBeforeReasonableInference
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			PolicyEffectPromptService.ReloadForContractTests();
			Check(string.Equals(PolicyEffectPromptService.GetAutoDraftPrompt(), PolicyEffectPromptService.DefaultAutoDraftPrompt, StringComparison.Ordinal)
				&& string.Equals(PolicyEffectPromptService.GetCommonEvaluationPrompt(), PolicyEffectPromptService.DefaultCommonEvaluationPrompt, StringComparison.Ordinal),
				"The immediately previous generic auto-draft default must migrate to the setting-aware default without rewriting custom variants.");
			File.WriteAllText(autoDraftPath, new JObject
			{
				["Version"] = 1,
				["Text"] = previousAutoDraftWithoutActionableMeasures
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			File.WriteAllText(commonPath, new JObject
			{
				["Version"] = 1,
				["CommonEvaluationPrompt"] = previousCommonBeforeReasonableInference
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			PolicyEffectPromptService.ReloadForContractTests();
			Check(string.Equals(PolicyEffectPromptService.GetAutoDraftPrompt(), PolicyEffectPromptService.DefaultAutoDraftPrompt, StringComparison.Ordinal)
				&& string.Equals(PolicyEffectPromptService.GetCommonEvaluationPrompt(), PolicyEffectPromptService.DefaultCommonEvaluationPrompt, StringComparison.Ordinal),
				"Exact immediately previous built-in prompts must migrate to the more actionable and inference-permissive defaults without rewriting custom variants.");
			File.WriteAllText(autoDraftPath, new JObject
			{
				["Version"] = 1,
				["Text"] = previousAutoDraftDefault
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			File.WriteAllText(commonPath, new JObject
			{
				["Version"] = 1,
				["CommonEvaluationPrompt"] = previousCommonDefault
			}.ToString(Formatting.Indented), new UTF8Encoding(false));
			PolicyEffectPromptService.ReloadForContractTests();
			Check(string.Equals(PolicyEffectPromptService.GetAutoDraftPrompt(), PolicyEffectPromptService.DefaultAutoDraftPrompt, StringComparison.Ordinal)
				&& string.Equals(PolicyEffectPromptService.GetCommonEvaluationPrompt(), PolicyEffectPromptService.DefaultCommonEvaluationPrompt, StringComparison.Ordinal),
				"Exact previous built-in editable defaults must migrate to the natural generic defaults without rewriting user-authored variants.");

			Check(PolicyEffectPromptService.TrySaveAutoDraftPrompt("AUTO_DRAFT_CUSTOM_ONLY", out saveError)
				&& string.Equals(PolicyEffectPromptService.GetAutoDraftPrompt(), "AUTO_DRAFT_CUSTOM_ONLY", StringComparison.Ordinal),
				"Smart writing must persist and read its dedicated prompt independently.");
			Check(PolicyEffectPromptService.TrySaveAutoDraftPrompt("", out saveError)
				&& string.Equals(PolicyEffectPromptService.GetAutoDraftPrompt(), PolicyEffectPromptService.DefaultAutoDraftPrompt, StringComparison.Ordinal)
				&& PolicyEffectPromptService.DefaultAutoDraftPrompt.Contains("《骑马与砍杀2：霸主》")
				&& PolicyEffectPromptService.DefaultAutoDraftPrompt.Contains("卡拉迪亚不是现代国家")
				&& PolicyEffectPromptService.DefaultAutoDraftPrompt.Contains("不要评议")
				&& IsSafePlayerVisiblePolicyText(PolicyEffectPromptService.DefaultAutoDraftPrompt)
				&& !PolicyEffectPromptService.DefaultAutoDraftPrompt.Contains("policyName")
				&& !PolicyEffectPromptService.DefaultAutoDraftPrompt.Contains("policyContent"),
				"Blank AI-writing prompt must restore the natural-language default without exposing the built-in transport contract.");
		}
		finally
		{
			PolicyEffectPromptService.SetStorageDirectoryOverrideForContractTests(null);
			try { Directory.Delete(tempRoot, recursive: true); } catch { }
		}
	}

	private static void TestPolicyEffectModuleManagerContracts()
	{
		Type settingsType = SutType("AnimusForge.DuelSettings");
		PropertyInfo managerAction = settingsType.GetProperty("ManagePolicyEffectModules", All);
		Check(managerAction != null && HasMcmButtonAttribute(managerAction),
			"MCM policy group must expose one policy effect module manager launcher.");

		Dictionary<string, PolicyEffectModuleRetrievalState> staged
			= PolicyEffectModuleRetrievalSettings.CreateEditableStateSnapshot();
		Type managerVmType = SutType("AnimusForge.PolicyEffects.PolicyEffectModuleManagerVM");
		object rowsObject = InvokeStatic(
			managerVmType,
			"BuildRowsForContractTests",
			new object[] { staged },
			1);
		object[] rows = Items(rowsObject).ToArray();
		string[] rowIds = rows
			.Select(row => (string)Property(row.GetType(), row, "ModuleIdText"))
			.ToArray();
		Check(rowIds.SequenceEqual(PolicyEffectModuleCatalog.Modules.Select(module => module.Id), StringComparer.Ordinal)
			&& HiddenRuntimeModuleIds.All(hiddenId => !rowIds.Contains(hiddenId, StringComparer.Ordinal)),
			"Module manager rows must be dynamically built from prompt-visible Catalog.Modules only.");

		object stabilityRow = rows.Single(row => string.Equals(
			(string)Property(row.GetType(), row, "ModuleIdText"),
			"kingdomStability",
			StringComparison.Ordinal));
		Check(!(bool)Property(stabilityRow.GetType(), stabilityRow, "CanToggleLocal")
			&& !(bool)Property(stabilityRow.GetType(), stabilityRow, "LocalPolicyEnabled")
			&& string.Equals((string)Property(stabilityRow.GetType(), stabilityRow, "LocalStatusText"), "不可用", StringComparison.Ordinal)
			&& (bool)Property(stabilityRow.GetType(), stabilityRow, "CanTogglePlayer")
			&& (bool)Property(stabilityRow.GetType(), stabilityRow, "CanToggleRuler")
			&& (bool)Property(stabilityRow.GetType(), stabilityRow, "CanToggleVassal"),
			"Module AllowedScopes must lock unsupported manager cells while leaving supported channels editable.");
		Check(stabilityRow.GetType().GetMethod("ExecuteTogglePlayer", All) != null
			&& stabilityRow.GetType().GetMethod("ExecuteToggleLocal", All) != null
			&& stabilityRow.GetType().GetMethod("ExecuteToggleRuler", All) != null
			&& stabilityRow.GetType().GetMethod("ExecuteToggleVassal", All) != null
			&& managerVmType.GetMethod("ExecuteRestoreDefaults", All) != null
			&& managerVmType.GetMethod("ExecuteCancel", All) != null
			&& managerVmType.GetMethod("ExecuteSave", All) != null,
			"Manager VM must expose four independent row toggles plus staged reset, cancel, and save actions.");

		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string prefabPath = Path.Combine(repositoryRoot, "AnimusForge", "GUI", "Prefabs", "PolicyEffectModuleManagerPopup.xml");
		Check(File.Exists(prefabPath), "Policy effect module manager prefab is missing.");
		string prefab = File.ReadAllText(prefabPath, Encoding.UTF8);
		Check(prefab.Contains("SuggestedWidth=\"1540\"")
			&& prefab.Contains("SuggestedHeight=\"900\"")
			&& prefab.Contains("DataSource=\"{ModuleItems}\"")
			&& prefab.Contains("Command.Click=\"ExecuteTogglePlayer\"")
			&& prefab.Contains("Command.Click=\"ExecuteToggleLocal\"")
			&& prefab.Contains("Command.Click=\"ExecuteToggleRuler\"")
			&& prefab.Contains("Command.Click=\"ExecuteToggleVassal\"")
			&& prefab.Contains("Command.Click=\"ExecuteRestoreDefaults\"")
			&& prefab.Contains("Command.Click=\"ExecuteCancel\"")
			&& prefab.Contains("Command.Click=\"ExecuteSave\""),
			"Manager prefab must be a 1540x900 scrolling four-channel editor with explicit reset/cancel/save actions.");
	}

	private static bool HasMcmButtonAttribute(PropertyInfo property)
	{
		return property?.GetCustomAttributes(inherit: true)
			.Any(attribute => attribute.GetType().Name.IndexOf("SettingPropertyButton", StringComparison.Ordinal) >= 0) == true;
	}

	private static bool IsSafePlayerVisiblePolicyText(string text)
	{
		string value = text ?? string.Empty;
		string[] forbidden =
		{
			"numericIntent", "moduleId", "targetHandles", "SourceModuleId", "PolicyEffect", "payload",
			"policyName", "policyContent", "effectIntents", "intentLeg", "assignments", "mechanismId", "durationDays",
			"JSON", "C#", "K0", "P0", "S0", "taxIncomePct", "clanInfluence", "PerDayEffectModule"
		};
		return forbidden.All(token => value.IndexOf(token, StringComparison.OrdinalIgnoreCase) < 0);
	}

	private static void TestSharedCompilerAllowlistsSelectorsAndDuplicates()
	{
		PolicyEffectWireEffect wire = BuildStructuredCompilerWire("S:alpha", "outside-detailed", 0.25f, 0.75f);
		PolicyEffectCompilerRequest outsideDetailedRequest = BuildCompilerRequest(
			"compiler-outside-detailed",
			PolicyEffectScopes.Local,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: true,
			detailedIncludesDummy: false);
		Check(TryCompileForContract(new[] { wire }, outsideDetailedRequest, "outside-detailed",
			out PolicyEffectCompilerResult outsideDetailedResult, out string outsideDetailedError),
			"Candidate outside detailed recall must remain compilable: " + outsideDetailedError);
		Check(outsideDetailedResult.Effects.Single().OutsideDetailedRecall,
			"Candidate outside detailed recall must be explicitly marked.");
		PolicyEffectCompilerRequest playerPromptAuthorization = BuildCompilerRequest(
			"compiler-player-prompt-authorization",
			PolicyEffectScopes.Local,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: true,
			detailedIncludesDummy: false);
		playerPromptAuthorization.EnforceDetailedModuleAuthorization = true;
		playerPromptAuthorization.PromptAuthorizedModuleIds = Array.Empty<string>();
		Check(!TryCompileForContract(new[] { wire }, playerPromptAuthorization, "player-not-injected",
			out PolicyEffectCompilerResult notInjectedResult, out string notInjectedError)
			&& HasNoCompiledEffects(notInjectedResult)
			&& notInjectedError.IndexOf("detailed prompt", StringComparison.OrdinalIgnoreCase) >= 0,
			"A player effect module not injected into stage two must fail closed even when it exists in the internal candidate pool.");
		playerPromptAuthorization.PromptAuthorizedModuleIds = new[] { StructuredDummyEffectModule.ModuleId };
		Check(TryCompileForContract(new[] { wire }, playerPromptAuthorization, "player-injected",
			out _, out string injectedError),
			"The same player module may compile only after it is explicitly prompt-authorized: " + injectedError);
		PolicyEffectWireEffect invalidPayload = BuildStructuredCompilerWire("S:alpha", "invalid-payload", 0.25f, 0.75f);
		invalidPayload.Payload = new JObject
		{
			["mode"] = "invalid-payload",
			["enabled"] = true,
			["bands"] = new JArray()
		};
		Check(!TryCompileForContract(new[] { invalidPayload }, playerPromptAuthorization, "player-invalid-payload",
			out PolicyEffectCompilerResult invalidPayloadResult, out string invalidPayloadError)
			&& HasNoCompiledEffects(invalidPayloadResult)
			&& invalidPayloadError.IndexOf("payload is invalid", StringComparison.OrdinalIgnoreCase) >= 0,
			"Structured target-directory changes must not relax strict payload validation.");

		PolicyEffectCompilerRequest outsideCandidateRequest = BuildCompilerRequest(
			"compiler-outside-candidate",
			PolicyEffectScopes.Local,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: false,
			detailedIncludesDummy: true);
		Check(!TryCompileForContract(new[] { wire }, outsideCandidateRequest, "outside-candidate",
			out PolicyEffectCompilerResult outsideCandidateResult, out string outsideCandidateError),
			"A module outside CandidateModuleIds must fail closed.");
		Check(HasNoCompiledEffects(outsideCandidateResult) && !string.IsNullOrWhiteSpace(outsideCandidateError),
			"Outside-candidate rejection must not return a partial result and must explain the failure.");

		PolicyEffectWireEffect wrongSelector = BuildStructuredCompilerWire("C:wrong", "wrong-selector", 0.5f, 0.5f);
		PolicyEffectCompilerRequest selectorRequest = BuildCompilerRequest(
			"compiler-selector",
			PolicyEffectScopes.Local,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: true,
			detailedIncludesDummy: true);
		Check(!TryCompileForContract(new[] { wrongSelector }, selectorRequest, "wrong-selector",
			out PolicyEffectCompilerResult selectorResult, out string selectorError),
			"A selector kind outside the module descriptor must fail closed.");
		Check(HasNoCompiledEffects(selectorResult) && !string.IsNullOrWhiteSpace(selectorError),
			"Selector rejection must not return a partial result.");

		PolicyEffectWireEffect dynamicPlan = BuildStructuredCompilerWire("P0", "dynamic-plan", 0.5f, 0.5f);
		Check(TryCompileForContract(new[] { dynamicPlan }, selectorRequest, "dynamic-plan",
			out PolicyEffectCompilerResult dynamicPlanResult, out string dynamicPlanError),
			"A non-one-shot TargetPlan must compile before its live targets are materialized: " + dynamicPlanError);
		PolicyEffectCanonicalTargetSet dynamicTargetSet = dynamicPlanResult.Effects.Single().SaveData.TargetSet;
		Check(dynamicTargetSet.TargetPlans.Count == 1
			&& dynamicTargetSet.SettlementIds.Count == 0
			&& dynamicTargetSet.VillageIds.Count == 0,
			"A compiled TargetPlan must remain authoritative and must not eagerly persist settlement or village IDs.");

		PolicyEffectWireEffect mixedPlanWire = BuildStructuredCompilerWire("P0", "mixed-plan", 0.5f, 0.5f);
		mixedPlanWire.TargetHandles.Add("S:alpha");
		Check(!TryCompileForContract(new[] { mixedPlanWire }, selectorRequest, "mixed-plan",
			out PolicyEffectCompilerResult mixedPlanResult, out string mixedPlanError)
			&& HasNoCompiledEffects(mixedPlanResult)
			&& mixedPlanError.IndexOf("sole authoritative", StringComparison.OrdinalIgnoreCase) >= 0,
			"TargetPlan and direct handles in the same wire must fail closed.");

		PolicyEffectWireEffect planCoalesce = BuildStructuredCompilerWire("P0", "mixed-coalesce", 0.5f, 0.5f);
		PolicyEffectWireEffect directCoalesce = BuildStructuredCompilerWire("S:alpha", "mixed-coalesce", 0.5f, 0.5f);
		Check(!TryCompileForContract(new[] { planCoalesce, directCoalesce }, selectorRequest, "mixed-coalesce",
			out PolicyEffectCompilerResult mixedCoalesceResult, out string mixedCoalesceError)
			&& HasNoCompiledEffects(mixedCoalesceResult)
			&& mixedCoalesceError.IndexOf("cannot be coalesced", StringComparison.OrdinalIgnoreCase) >= 0,
			"TargetPlan and direct handles must not be silently coalesced across wires.");

		PolicyEffectWireEffect canonicalA = BuildStructuredCompilerWire("S:alpha", "duplicate-a", 0.5f, 0.5f);
		PolicyEffectWireEffect canonicalAlias = BuildStructuredCompilerWire("S:alias-alpha", "duplicate-b", 0.4f, 0.6f);
		PolicyEffectCompilerRequest duplicateRequest = BuildCompilerRequest(
			"compiler-duplicate",
			PolicyEffectScopes.Local,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: true,
			detailedIncludesDummy: true);
		Check(!TryCompileForContract(new[] { canonicalA, canonicalAlias }, duplicateRequest, "duplicate",
			out PolicyEffectCompilerResult duplicateResult, out string duplicateError),
			"Different selector aliases resolving to the same module/canonical target must be rejected as duplicates.");
		Check(HasNoCompiledEffects(duplicateResult) && !string.IsNullOrWhiteSpace(duplicateError),
			"Duplicate canonical target rejection must be atomic.");

		PolicyEffectWireEffect mergeA = BuildStructuredCompilerWire("S:alpha", "merge-same", 0.5f, 0.5f);
		PolicyEffectWireEffect mergeAlias = BuildStructuredCompilerWire("S:alias-alpha", "merge-same", 0.5f, 0.5f);
		Check(TryCompileForContract(new[] { mergeA, mergeAlias }, duplicateRequest, "merge-overlap",
			out PolicyEffectCompilerResult mergeOverlapResult, out string mergeOverlapError),
			"Same module/payload effects with overlapping canonical targets must coalesce: " + mergeOverlapError);
		Check(mergeOverlapResult.Effects.Count == 1
			&& mergeOverlapResult.Effects[0].TargetHandles.OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
				.SequenceEqual(new[] { "S:alias-alpha", "S:alpha" }, StringComparer.OrdinalIgnoreCase)
			&& mergeOverlapResult.Effects[0].TargetSet.SettlementIds.SequenceEqual(new[] { "settlement-alpha" }, StringComparer.Ordinal),
			"Overlapping aliases with the same funded payload must produce one logical instance and one canonical target.");

		PolicyEffectWireEffect mergeDisjointA = BuildStructuredCompilerWire("S:alpha", "merge-disjoint", 0.25f, 0.75f);
		PolicyEffectWireEffect mergeDisjointB = BuildStructuredCompilerWire("S:beta", "merge-disjoint", 0.25f, 0.75f);
		Check(TryCompileForContract(new[] { mergeDisjointA, mergeDisjointB }, duplicateRequest, "merge-disjoint",
			out PolicyEffectCompilerResult mergeDisjointResult, out string mergeDisjointError),
			"Same module/payload effects with disjoint targets must coalesce: " + mergeDisjointError);
		Check(mergeDisjointResult.Effects.Count == 1
			&& mergeDisjointResult.Effects[0].TargetSet.SettlementIds
				.SequenceEqual(new[] { "settlement-alpha", "settlement-beta" }, StringComparer.Ordinal),
			"Disjoint targets with the same funded payload must be represented by one union instance.");

		PolicyEffectWireEffect disjointDifferentPayload = BuildStructuredCompilerWire("S:beta", "different-payload", 0.2f, 0.8f);
		Check(TryCompileForContract(new[] { canonicalA, disjointDifferentPayload }, duplicateRequest, "different-disjoint",
			out PolicyEffectCompilerResult disjointDifferentResult, out string disjointDifferentError),
			"Different payloads may coexist when their executable targets are disjoint: " + disjointDifferentError);
		Check(disjointDifferentResult.Effects.Count == 2,
			"Different payloads on disjoint targets must remain separate instances.");

		PolicyEffectCompilerRequest differentModuleRequest = BuildCompilerRequest(
			"compiler-different-modules",
			PolicyEffectScopes.Local,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: true,
			detailedIncludesDummy: true);
		differentModuleRequest.CandidateModuleIds = new[]
		{
			StructuredDummyEffectModule.ModuleId,
			CompilerSecondDummyModule.Id
		};
		PolicyEffectWireEffect secondModuleSameTarget = BuildStructuredCompilerWire("S:alpha", "second-module", 0.3f, 0.7f);
		secondModuleSameTarget.ModuleId = CompilerSecondDummyModule.Id;
		Check(TryCompileForContract(new[] { canonicalA, secondModuleSameTarget }, differentModuleRequest, "different-modules",
			out PolicyEffectCompilerResult differentModuleResult, out string differentModuleError),
			"Different modules must remain allowed on the same executable target: " + differentModuleError);
		Check(differentModuleResult.Effects.Count == 2,
			"Canonical overlap protection must not suppress a different module.");
	}

	private static void TestPolicyTargetSelectorContracts()
	{
		Type catalog = SutType("AnimusForge.PolicyTargets.PolicyTargetSelectorCatalog");
		Type descriptorType = SutType("AnimusForge.PolicyTargets.PolicyTargetSelectorDescriptor");
		object[] descriptors = Items(Property(catalog, null, "Descriptors")).ToArray();
		Check(Convert.ToInt32(catalog.GetField("RecallLimit", All).GetRawConstantValue(), CultureInfo.InvariantCulture) == 6
			&& Convert.ToInt32(catalog.GetField("PromptLimit", All).GetRawConstantValue(), CultureInfo.InvariantCulture) == 4,
			"Selector routing must cap dense recall at six and prompt injection at four candidates.");
		Check(descriptors.Length >= 1, "Policy target selector catalog must retain legacy descriptors for save compatibility.");
		Check(descriptors.Select(item => (string)Property(descriptorType, item, "Id"))
			.Distinct(StringComparer.Ordinal).Count() == descriptors.Length,
			"Policy target selector descriptor IDs must be unique.");
		object otherFiefs = descriptors.Single(item => string.Equals(
			(string)Property(descriptorType, item, "Id"),
			"currentKingdomPrimaryFiefsExceptPlayerClan",
			StringComparison.Ordinal));
		Check(Items(Property(descriptorType, otherFiefs, "SupportedScopes")).Cast<string>()
			.SequenceEqual(new[] { "local" }, StringComparer.Ordinal),
			"The other-fiefs selector must be limited to local policy scope.");
		Check(string.Equals(Property(descriptorType, otherFiefs, "OutputTargetKind").ToString(), "Settlement", StringComparison.Ordinal),
			"The other-fiefs selector must resolve to settlement targets.");
		Check((bool)Property(descriptorType, otherFiefs, "LegacyOnly"),
			"The legacy other-fiefs selector must not participate in new policy recall.");
		string retrievalText = (string)Property(descriptorType, otherFiefs, "RetrievalText");
		Check(retrievalText.Contains("排除玩家家族") && !retrievalText.Contains("其他地方"),
			"The legacy descriptor must state its exact exclusion semantics without claiming generic other-place wording.");
		float[] selectorQueryVector = new[] { 1f };
		object[] recalledSelectors = Items(InvokeStatic(
			catalog,
			"RecallAndRerank",
			new object[] { selectorQueryVector, retrievalText, "local" },
			3)).ToArray();
		Check(recalledSelectors.Length == 0,
			"Legacy selector descriptors must not be recalled for newly generated policies.");

		Type entityType = SutType("AnimusForge.PolicyTargets.PolicyTargetSelectorEntitySnapshot");
		Type contextType = SutType("AnimusForge.PolicyTargets.PolicyTargetSelectorResolutionContext");
		Type resolutionType = SutType("AnimusForge.PolicyTargets.PolicyTargetSelectorResolution");
		object playerTown = BuildSelectorEntity(entityType, "player-town", "k1", "player", true, "player-village");
		object otherTown = BuildSelectorEntity(entityType, "other-town", "k1", "other", true, "other-village");
		object otherCastle = BuildSelectorEntity(entityType, "other-castle", "k1", "other2", true, "castle-village");
		object foreignTown = BuildSelectorEntity(entityType, "foreign-town", "k2", "foreign", true, "foreign-village");
		object unownedTown = BuildSelectorEntity(entityType, "unowned-town", "k1", "", true, "unowned-village");
		object nonPrimary = BuildSelectorEntity(entityType, "standalone-village", "k1", "other", false);
		Array entities = Array.CreateInstance(entityType, 6);
		new[] { playerTown, otherTown, otherCastle, foreignTown, unownedTown, nonPrimary }.CopyTo(entities, 0);
		object context = Activator.CreateInstance(contextType, nonPublic: true);
		SetProperty(contextType, context, "Scope", "local");
		SetProperty(contextType, context, "TargetKingdomId", "k1");
		SetProperty(contextType, context, "ExcludedClanId", "player");
		SetProperty(contextType, context, "Entities", entities);
		object[] resolveArguments = { "currentKingdomPrimaryFiefsExceptPlayerClan", context, null, null };
		Check((bool)InvokeStatic(catalog, "TryResolve", resolveArguments, 4),
			"The other-fiefs selector must resolve a valid synthetic kingdom: " + resolveArguments[3]);
		object resolution = resolveArguments[2];
		Check(ReadStringPropertyValues(resolution, "PrimarySettlementIds")
			.SequenceEqual(new[] { "other-castle", "other-town" }, StringComparer.Ordinal)
			&& ReadStringPropertyValues(resolution, "SettlementIds")
				.SequenceEqual(new[] { "castle-village", "other-castle", "other-town", "other-village" }, StringComparer.Ordinal),
			"The legacy selector must preserve its original primary-and-bound-village compatibility collection.");

		SetProperty(entityType, otherTown, "OwnerClanId", "player");
		resolveArguments = new object[] { "currentKingdomPrimaryFiefsExceptPlayerClan", context, null, null };
		Check((bool)InvokeStatic(catalog, "TryResolve", resolveArguments, 4),
			"The selector must remain resolvable after an ownership change.");
		resolution = resolveArguments[2];
		Check(!ReadStringPropertyValues(resolution, "SettlementIds").Contains("other-town", StringComparer.Ordinal),
			"A fief transferred to the excluded clan must disappear on the next resolution.");

		SetProperty(entityType, otherCastle, "OwnerClanId", "player");
		resolveArguments = new object[] { "currentKingdomPrimaryFiefsExceptPlayerClan", context, null, null };
		Check(!(bool)InvokeStatic(catalog, "TryResolve", resolveArguments, 4)
			&& resolveArguments[2] == null,
			"A selector whose live expansion becomes empty must fail closed instead of retaining stale targets.");

		SetProperty(contextType, context, "TargetKingdomId", "");
		resolveArguments = new object[] { "currentKingdomPrimaryFiefsExceptPlayerClan", context, null, null };
		Check(!(bool)InvokeStatic(catalog, "TryResolve", resolveArguments, 4)
			&& resolveArguments[2] == null
			&& !string.IsNullOrWhiteSpace(resolveArguments[3] as string),
			"A selector without a bound policy kingdom must fail closed.");
	}

	private static bool TryDumpNpcPolicyApiProbeMessages(string[] args)
	{
		int optionIndex = Array.FindIndex(args ?? Array.Empty<string>(),
			value => string.Equals(value, "--dump-npc-policy-api-probe", StringComparison.OrdinalIgnoreCase));
		if (optionIndex < 0)
		{
			return false;
		}
		if (optionIndex + 1 >= args.Length)
		{
			throw new ArgumentException("--dump-npc-policy-api-probe requires <scenario>.");
		}
		string scenario = (args[optionIndex + 1] ?? string.Empty).Trim().ToLowerInvariant();
		string proposalText;
		List<string> candidateModuleIds;
		switch (scenario)
		{
			case "npc_centralization":
				proposalText = "请推行中央集权：除发布者家族外的本国其他家族一次性与每日影响力都下降，发布者家族一次性与每日影响力都上升；正负两腿必须属于同一个联动机制。";
				candidateModuleIds = new List<string> { "clanInfluence" };
				break;
			case "npc_relations":
				proposalText = "请举办全国贵族和解大会；政策通过后的下一游戏日，发布统治者与除发布者家族外的本国其他家族领袖关系一次性提高，不产生每日关系变化。";
				candidateModuleIds = new List<string> { "clanLeaderRelationOnce" };
				break;
			default:
				throw new ArgumentException("Unknown NPC policy API probe scenario: " + scenario);
		}

		Type behavior = SutType("AnimusForge.NpcRulerPolicyBehavior");
		Type contextType = behavior.GetNestedType("NpcRulerPolicyBatchContext", BindingFlags.NonPublic);
		Type kingdomContextType = behavior.GetNestedType("NpcRulerPolicyKingdomContext", BindingFlags.NonPublic);
		Type allowedTargetType = behavior.GetNestedType("NpcRulerPolicyAllowedEffectTarget", BindingFlags.NonPublic);
		object context = Activator.CreateInstance(contextType, nonPublic: true);
		SetField(contextType, context, "BatchId", "real-api-probe-" + scenario);
		SetField(contextType, context, "Day", 42);
		SetField(contextType, context, "GameDate", "测试纪元第42日");
		SetField(contextType, context, "BatchSize", 1);
		SetField(contextType, context, "IsSuggestedPolicy", true);
		SetField(contextType, context, "ProposalText", proposalText);
		SetField(contextType, context, "NpcReplyText", "我接受这项建议，并将把它正式制定为王国政策。");
		SetField(contextType, context, "CompactWorldContext",
			"CurrentWorldFacts{kingdom=西境王国,ruler=阿尔德里克,clans=4,policyNeed=整合贵族政治秩序}; MechanicalFacts{influence=ordinary,relations=ordinary}");
		SetField(contextType, context, "CandidateModuleIds", new List<string>(candidateModuleIds));
		SetField(contextType, context, "DetailedModuleIds", new List<string>(candidateModuleIds));

		object kingdomContext = Activator.CreateInstance(kingdomContextType, nonPublic: true);
		SetField(kingdomContextType, kingdomContext, "KingdomId", "kingdom_west");
		SetField(kingdomContextType, kingdomContext, "KingdomName", "西境王国");
		SetField(kingdomContextType, kingdomContext, "RulerHeroId", "hero_west_ruler");
		SetField(kingdomContextType, kingdomContext, "RulerName", "阿尔德里克");
		SetField(kingdomContextType, kingdomContext, "EnemyPolicyMemory",
			"EnemyPolicyMemory{anchorKingdomId=kingdom_west,enemyCount=2,withPolicyCount=1}\n"
			+ "Enemy{kingdomId=kingdom_east,name=东境王国,latest={day=40,status=active,name=东境边贸管制令,summary=限制西境商队进入东境市场。}}\n"
			+ "Enemy{kingdomId=kingdom_north,name=北境王国,latest=none}");
		object selfTarget = Activator.CreateInstance(allowedTargetType, nonPublic: true);
		SetField(allowedTargetType, selfTarget, "KingdomId", "kingdom_west");
		SetField(allowedTargetType, selfTarget, "KingdomName", "西境王国");
		SetField(allowedTargetType, selfTarget, "IsIssuer", true);
		SetField(allowedTargetType, selfTarget, "PublisherClanId", "clan_west_ruler");
		SetField(allowedTargetType, selfTarget, "AllClansHandle", "P:npc:kingdom_west:clans:all");
		SetField(allowedTargetType, selfTarget, "OtherClansHandle", "P:npc:kingdom_west:clans:others");
		SetField(allowedTargetType, selfTarget, "PublisherClanHandle", "P:npc:kingdom_west:clans:publisher");
		SetField(allowedTargetType, selfTarget, "TerritoryOwnerClansHandle", "P:npc:kingdom_west:clans:territory-owners");
		IList allowedTargets = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(allowedTargetType));
		allowedTargets.Add(selfTarget);
		SetField(kingdomContextType, kingdomContext, "AllowedEffectTargets", allowedTargets);
		IList kingdoms = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(kingdomContextType));
		kingdoms.Add(kingdomContext);
		SetField(contextType, context, "Kingdoms", kingdoms);
		JObject probeCapabilities = new JObject();
		foreach (string moduleId in candidateModuleIds)
		{
			probeCapabilities[moduleId] = new JObject
			{
				["defaultTargetHandle"] = string.Empty,
				["allowedSubsetTargetHandles"] = new JArray(
					"P:npc:kingdom_west:clans:publisher",
					"P:npc:kingdom_west:clans:others"),
				["allowedTargetHandles"] = new JArray(
					"P:npc:kingdom_west:clans:publisher",
					"P:npc:kingdom_west:clans:others")
			};
		}
		SetField(kingdomContextType, kingdomContext, "EffectTargetDirectory", TokenToObject(new JObject
		{
			["structureVersion"] = 3,
			["targets"] = new JObject
			{
				["P:npc:kingdom_west:clans:publisher"] = new JObject
				{
					["kind"] = "clan", ["description"] = "政策发布家族",
					["selectorId"] = "P:npc:kingdom_west:clans:publisher"
				},
				["P:npc:kingdom_west:clans:others"] = new JObject
				{
					["kind"] = "clan", ["description"] = "除发布家族外的当前家族",
					["selectorId"] = "P:npc:kingdom_west:clans:others"
				}
			},
			["capabilities"] = probeCapabilities
		}, SutType("AnimusForge.PolicyTargets.PolicyTargetHandleDirectory")));
		SetField(contextType, context, "CompactWorldContext",
			(string)InvokeStatic(behavior, "BuildKingdomPromptContext", new[] { kingdomContext }, 1));

		object draftPrompt = InvokeStatic(behavior, "ComposeNpcPolicyDraftPrompt", new object[] { context, string.Empty }, 2);
		string draftSystemPrompt = Convert.ToString(Property(draftPrompt.GetType(), draftPrompt, "SystemPrompt"), CultureInfo.InvariantCulture);
		JObject output = new JObject
		{
			["scenario"] = scenario,
			["proposalText"] = proposalText,
			["candidateModuleIds"] = new JArray(candidateModuleIds),
			["draftMessages"] = BuildNpcPolicyProbeMessages(draftSystemPrompt)
		};

		string rawDraft = (Environment.GetEnvironmentVariable("ANIMUSFORGE_NPC_POLICY_PROBE_DRAFT_JSON") ?? string.Empty).Trim();
		if (rawDraft.Length > 0)
		{
			object[] parseDraftArguments = { rawDraft, context, null, null };
			bool draftSuccess = (bool)InvokeStatic(behavior, "TryParseNpcPolicyDraftResponse", parseDraftArguments, 4);
			string draftError = Convert.ToString(parseDraftArguments[3], CultureInfo.InvariantCulture) ?? string.Empty;
			output["draftValidation"] = new JObject { ["success"] = draftSuccess, ["error"] = draftError };
			if (draftSuccess)
			{
				object draft = parseDraftArguments[2];
				object effectPrompt = InvokeStatic(behavior, "ComposeNpcPolicyEffectPrompt", new[] { context, draft }, 2);
				string effectSystemPrompt = Convert.ToString(Property(effectPrompt.GetType(), effectPrompt, "SystemPrompt"), CultureInfo.InvariantCulture);
				output["effectMessages"] = BuildNpcPolicyProbeMessages(effectSystemPrompt);
				string rawEffect = (Environment.GetEnvironmentVariable("ANIMUSFORGE_NPC_POLICY_PROBE_EFFECT_JSON") ?? string.Empty).Trim();
				if (rawEffect.Length > 0)
				{
					int durationDays = Convert.ToInt32(Property(draft.GetType(), draft, "DurationDays"), CultureInfo.InvariantCulture);
					object[] parseEffectArguments = { rawEffect, durationDays, null, null };
					bool parseSuccess = (bool)InvokeStatic(behavior, "TryParseNpcPolicyEffectPlanResponse", parseEffectArguments, 4);
					string parseError = Convert.ToString(parseEffectArguments[3], CultureInfo.InvariantCulture) ?? string.Empty;
					bool compileSuccess = false;
					string compileError = string.Empty;
					PolicyEffectCompilerResult compiled = null;
					if (parseSuccess)
					{
						List<PolicyEffectWireEffect> wires = Items(Property(parseEffectArguments[2].GetType(), parseEffectArguments[2], "Effects"))
							.Cast<PolicyEffectWireEffect>().ToList();
						PolicyEffectTargetResolver resolver = delegate(string handle, IPolicyEffectModule module,
							out PolicyEffectResolvedTarget resolved, out string targetError)
						{
							targetError = string.Empty;
							string normalized = (handle ?? string.Empty).Trim();
							bool isPublisherHandle = normalized.EndsWith(":publisher", StringComparison.OrdinalIgnoreCase)
								|| string.Equals(normalized, "publisherClan", StringComparison.OrdinalIgnoreCase);
							List<string> clanIds = isPublisherHandle
								? new List<string> { "clan_west_ruler" }
								: new List<string> { "clan_west_vassal_1", "clan_west_vassal_2", "clan_west_mercenary" };
							resolved = new PolicyEffectResolvedTarget
							{
								Handle = normalized,
								SelectorKind = PolicyEffectTargetKind.Clan,
								CanonicalTargetSet = new PolicyEffectCanonicalTargetSet
								{
									SelectorHandles = new List<string> { normalized },
									ClanIds = clanIds,
									KingdomIds = new List<string> { "kingdom_west" }
								}
							};
							return true;
						};
						compileSuccess = PolicyEffectCompiler.TryCompile(
							wires,
							new PolicyEffectCompilerRequest
							{
								Scope = PolicyEffectScopes.Kingdom,
								PolicyId = "npc-real-api-probe",
								ActorHeroId = "hero_west_ruler",
								StartDay = 42,
								EndDay = 42 + durationDays,
								Funding = new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
								CandidateModuleIds = candidateModuleIds,
								DetailedModuleIds = candidateModuleIds,
								MaxInstances = 12,
								MaxCompiledInstances = 24
							},
							resolver,
							(ordinal, moduleId, targetSet) => "npc-real-api-probe:effect:" + ordinal.ToString(CultureInfo.InvariantCulture),
							out compiled,
							out compileError);
					}
					output["effectValidation"] = new JObject
					{
						["parseSuccess"] = parseSuccess,
						["parseError"] = parseError,
						["compileSuccess"] = compileSuccess,
						["compileError"] = compileError,
						["compiledCount"] = compiled?.Effects?.Count ?? 0,
						["moduleIds"] = new JArray((compiled?.Effects ?? Array.Empty<PolicyEffectCompiledWireEffect>())
							.Select(item => item.SaveData.ModuleId).Distinct(StringComparer.Ordinal)),
						["actorHeroIds"] = new JArray((compiled?.Effects ?? Array.Empty<PolicyEffectCompiledWireEffect>())
							.Select(item => item.SaveData.ActorHeroId).Distinct(StringComparer.Ordinal))
					};
					if (!parseSuccess || !compileSuccess)
					{
						output["automaticSemanticRepair"] = false;
					}
				}
			}
		}
		Console.WriteLine(output.ToString(Formatting.None));
		return true;
	}

	private static JArray BuildNpcPolicyProbeMessages(string systemPrompt)
	{
		return new JArray
		{
			new JObject { ["role"] = "system", ["content"] = systemPrompt ?? string.Empty },
			new JObject { ["role"] = "user", ["content"] = "请根据以上规则生成本次统治者政策，只输出 JSON。" }
		};
	}

	private static bool TryDumpPolicyApiProbeMessages(string[] args)
	{
		int optionIndex = Array.FindIndex(args ?? Array.Empty<string>(),
			value => string.Equals(value, "--dump-policy-api-probe", StringComparison.OrdinalIgnoreCase));
		if (optionIndex < 0)
		{
			return false;
		}
		if (optionIndex + 2 >= args.Length
			|| !int.TryParse(args[optionIndex + 2], NumberStyles.Integer, CultureInfo.InvariantCulture, out int requestedCount))
		{
			throw new ArgumentException("--dump-policy-api-probe requires <scenario> <positive-count>.");
		}
		string scenario = (args[optionIndex + 1] ?? string.Empty).Trim().ToLowerInvariant();
		int count = Math.Max(1, Math.Min(100, requestedCount));
		Type behaviorType = SutType("AnimusForge.CustomPolicyBehavior");
		Type requestType = behaviorType.GetNestedType("PolicyDraftRequest", All);
		Type promptContextType = behaviorType.GetNestedType("PolicyPromptContextBundle", All);
		Type assessmentType = behaviorType.GetNestedType("PolicyMainAssessmentResult", All);
		Type handleType = behaviorType.GetNestedType("PolicyTargetHandleSaveData", All);
		Type planType = SutType("AnimusForge.PolicyTargets.PolicyTargetPlanSaveData");
		Type snapshotType = SutType("AnimusForge.PolicyTargets.PolicyTargetWorldSnapshot");
		Type entityType = SutType("AnimusForge.PolicyTargets.PolicyTargetEntitySnapshot");
		Type historyRetrievalType = SutType("AnimusForge.PolicyHistoryRetrievalResult");

		string policyText;
		string displayName;
		string branchJson;
		string targetKingdomId;
		string targetClanId;
		bool targetIsCity;
		bool targetIsCastle;
		bool targetIsBorder;
		string scopeKind = "local";
		string issuerHandle = "S";
		string issuerHandleKind = "source";
		string issuerDisplayName = "政策发布地；发布者 source/cost/beneficiary/destination 腿仅在正文要求时使用此目标";
		List<string> candidateModuleIds = new List<string> { "taxIncomePct" };
		string defaultImpactSummary = "显著改变政策原文所指目标的领主主税收收入。";
		string defaultNumericIntent = "对政策原文所指范围显著改变领主主税收；范围由最终后处理依据合法目录确定。";
		string[] warPairs = Array.Empty<string>();
		string[] alliancePairs = Array.Empty<string>();
		string secondaryBranchJson = null;
		string secondaryDisplayName = null;
		object secondaryPlan = null;
		string heroSelectorId = null;
		string heroSelectorDisplayName = null;
		bool includePrimaryPlanHandle = true;
		int planVersion = 2;
		int primaryPlanTargetCount = count;
		int secondaryPlanTargetCount = 0;
		List<string> selectedFiefIds = new List<string>();
		switch (scenario)
		{
			case "foreign_all":
				policyText = "对其他王国控制的全部城镇和城堡显著加征领主主税收。";
				displayName = "外国全部城镇/城堡";
				branchJson = "{\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"PrimaryFief\",\"relation\":\"Foreign\",\"cardinality\":\"All\"}";
				targetKingdomId = "k2";
				targetClanId = "foreign";
				targetIsCity = true;
				targetIsCastle = false;
				targetIsBorder = false;
				break;
			case "exclude_player_clan":
				policyText = "除玩家家族外，对本国全部城镇和城堡显著加征领主主税收。";
				displayName = "除玩家家族外的本国全部城镇/城堡";
				branchJson = "{\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"PrimaryFief\",\"relation\":\"Domestic\",\"ownerClanPredicate\":\"ExcludeProposerClan\",\"cardinality\":\"All\"}";
				targetKingdomId = "k1";
				targetClanId = "other";
				targetIsCity = true;
				targetIsCastle = false;
				targetIsBorder = false;
				break;
			case "other_places":
				policyText = "去其他地方抢税收，当前发布地不要执行。";
				displayName = "除当前发布地外的本国全部城镇/城堡";
				branchJson = "{\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"PrimaryFief\",\"relation\":\"Domestic\",\"exclusions\":[\"PublicationParents\"],\"cardinality\":\"All\"}";
				targetKingdomId = "k1";
				targetClanId = "other";
				targetIsCity = true;
				targetIsCastle = false;
				targetIsBorder = false;
				break;
			case "enemy_border_castles":
				policyText = "对所有敌国边境城堡显著加征领主主税收。";
				displayName = "全部敌国边境城堡";
				branchJson = "{\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"Castle\",\"relation\":\"Enemy\",\"borderOnly\":true,\"cardinality\":\"All\"}";
				targetKingdomId = "k2";
				targetClanId = "enemy";
				targetIsCity = false;
				targetIsCastle = true;
				targetIsBorder = true;
				warPairs = new[] { "k1\nk2" };
				break;
			case "ally_top2":
				policyText = "只对盟国中最繁荣的两个城镇显著加征领主主税收。";
				displayName = "盟国最繁荣的两个城镇";
				branchJson = "{\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"Town\",\"relation\":\"Ally\",\"metric\":\"Prosperity\",\"sortDirection\":\"Descending\",\"cardinality\":\"TopN\",\"limit\":2}";
				targetKingdomId = "k3";
				targetClanId = "ally";
				targetIsCity = true;
				targetIsCastle = false;
				targetIsBorder = false;
				alliancePairs = new[] { "k1\nk3" };
				break;
			case "effect_target_hearth_low3":
				policyText = "只向本国户数最低的三个一级封地每日补充少量粮食，不改变户数本身。";
				displayName = "本国户数最低的三个一级封地";
				branchJson = "{\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"PrimaryFief\",\"relation\":\"Domestic\",\"metric\":\"Hearth\",\"sortDirection\":\"Ascending\",\"cardinality\":\"TopN\",\"limit\":3}";
				targetKingdomId = "k1";
				targetClanId = "domestic";
				targetIsCity = true;
				targetIsCastle = false;
				targetIsBorder = false;
				planVersion = 3;
				candidateModuleIds = new List<string> { "foodPerDay" };
				defaultImpactSummary = "本国户数最低的三个一级封地每日粮食增加，户数不变。";
				defaultNumericIntent = "仅对 P0 目标给予小幅每日粮食正向变化，不产生户数变化。";
				break;
			case "effect_target_hearth_gte300_high2":
				policyText = "在本国户数不低于300的一级封地中，只取户数最高的两处每日提升忠诚，不改变户数本身。";
				displayName = "本国户数不低于300且户数最高的两个一级封地";
				branchJson = "{\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"PrimaryFief\",\"relation\":\"Domestic\",\"metric\":\"Hearth\",\"sortDirection\":\"Descending\",\"metricComparison\":\"GreaterThanOrEqual\",\"metricThreshold\":300,\"cardinality\":\"TopN\",\"limit\":2}";
				targetKingdomId = "k1";
				targetClanId = "domestic";
				targetIsCity = true;
				targetIsCastle = false;
				targetIsBorder = false;
				planVersion = 3;
				candidateModuleIds = new List<string> { "loyaltyPerDay" };
				defaultImpactSummary = "符合户数阈值且户数最高的两个一级封地每日忠诚提高，户数不变。";
				defaultNumericIntent = "仅对 P0 目标给予每日忠诚正向变化，不产生户数变化。";
				break;
			case "effect_target_hearth_lt300_all":
				policyText = "对本国户数低于300的全部一级封地附属村庄实施安置，使每个村庄每日户数小幅增加。";
				displayName = "本国户数低于300的全部一级封地及其附属村庄";
				branchJson = "{\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"PrimaryFief\",\"relation\":\"Domestic\",\"metric\":\"Hearth\",\"sortDirection\":\"Ascending\",\"metricComparison\":\"LessThan\",\"metricThreshold\":300,\"cardinality\":\"All\"}";
				targetKingdomId = "k1";
				targetClanId = "domestic";
				targetIsCity = true;
				targetIsCastle = false;
				targetIsBorder = false;
				planVersion = 3;
				candidateModuleIds = new List<string> { "hearthPerDay" };
				defaultImpactSummary = "本国户数低于300的目标附属村庄每日户数增加。";
				defaultNumericIntent = "仅对 P0 父级范围内的附属村庄给予小幅每日户数正向变化。";
				break;
			case "effect_target_militia_high2":
				policyText = "只向本国民兵最高的两座城镇派遣工程队，使其每日建造力提高，不改变民兵。";
				displayName = "本国民兵最高的两座城镇";
				branchJson = "{\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"Town\",\"relation\":\"Domestic\",\"metric\":\"Militia\",\"sortDirection\":\"Descending\",\"cardinality\":\"TopN\",\"limit\":2}";
				targetKingdomId = "k1";
				targetClanId = "domestic";
				targetIsCity = true;
				targetIsCastle = false;
				targetIsBorder = false;
				planVersion = 3;
				candidateModuleIds = new List<string> { "constructionPerDay" };
				defaultImpactSummary = "本国民兵最高的两座城镇每日建造力提高，民兵不变。";
				defaultNumericIntent = "仅对 P0 目标给予每日建造力正向变化，不产生民兵变化。";
				break;
			case "effect_target_militia_low2":
				policyText = "只在本国民兵最低的两座城镇训练乡勇，使其每日民兵小幅增加。";
				displayName = "本国民兵最低的两座城镇";
				branchJson = "{\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"Town\",\"relation\":\"Domestic\",\"metric\":\"Militia\",\"sortDirection\":\"Ascending\",\"cardinality\":\"TopN\",\"limit\":2}";
				targetKingdomId = "k1";
				targetClanId = "domestic";
				targetIsCity = true;
				targetIsCastle = false;
				targetIsBorder = false;
				planVersion = 3;
				candidateModuleIds = new List<string> { "militiaPerDay" };
				defaultImpactSummary = "本国民兵最低的两座城镇每日民兵增加。";
				defaultNumericIntent = "仅对 P0 目标给予小幅每日民兵正向变化。";
				break;
			case "effect_target_militia_gte200_asc2":
				policyText = "在本国民兵至少200的城镇中，按民兵升序取前两座加强巡逻，使其每日治安提高，不改变民兵。";
				displayName = "本国民兵至少200且按民兵升序取前两座城镇";
				branchJson = "{\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"Town\",\"relation\":\"Domestic\",\"metric\":\"Militia\",\"sortDirection\":\"Ascending\",\"metricComparison\":\"GreaterThanOrEqual\",\"metricThreshold\":200,\"cardinality\":\"TopN\",\"limit\":2}";
				targetKingdomId = "k1";
				targetClanId = "domestic";
				targetIsCity = true;
				targetIsCastle = false;
				targetIsBorder = false;
				planVersion = 3;
				candidateModuleIds = new List<string> { "securityPerDay" };
				defaultImpactSummary = "符合民兵阈值且民兵较低的两座城镇每日治安提高，民兵不变。";
				defaultNumericIntent = "仅对 P0 目标给予每日治安正向变化，不产生民兵变化。";
