		SetProperty(entityType, sameClanOther, "Militia", 100f);
		SetProperty(entityType, otherClan, "Hearth", 100f);
		SetProperty(entityType, otherClan, "Militia", 450f);
		SetProperty(entityType, source, "Militia", 300f);
