		object hearthDescendingPlan = TokenToObject(JObject.Parse(
			"{\"planVersion\":3,\"resolverVersion\":2,\"branches\":[{"
			+ "\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\","
			+ "\"entityType\":\"PrimaryFief\",\"relation\":\"Domestic\","
