		Check(mergePlanHandles != null && mergePlanHandles.ReturnType == typeof(int),
			"TargetPlan handle merging must report how many candidates actually survived runtime resolution.");
		Check(buildModuleConstrainedDirectory != null && buildModuleConstrainedDirectory.ReturnType == typeof(bool),
			"Player policy generation must build the legal target directory only after detailed modules are injected.");
		string targetGenerationSource = File.ReadAllText(Path.Combine(
			FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory),
			"PolicySystem", "Core", "CustomPolicyBehavior.Generation.cs"), Encoding.UTF8);
		Check(targetGenerationSource.Contains("RouteAfterAssessment(")
			&& targetGenerationSource.Contains("TryBuildModuleConstrainedPolicyTargetDirectory(")
			&& targetGenerationSource.IndexOf("RouteAfterAssessment(", StringComparison.Ordinal)
				< targetGenerationSource.IndexOf("TryBuildModuleConstrainedPolicyTargetDirectory(", StringComparison.Ordinal)
			&& !targetGenerationSource.Contains("TryRefreshPolicyTargetPlanHandlesFromSemanticPlan(")
			&& !targetGenerationSource.Contains("BuildPlayerExecutableSemanticPlan("),
			"Player targets must be built after module retrieval without restoring the frozen intent-leg projection.");
		Check(Convert.ToInt32(InvokeStatic(routerType, "ParseRequestedCount",
			new object[] { "户数低于300的全部一级封地" }, 1), CultureInfo.InvariantCulture) == 0
			&& Convert.ToInt32(InvokeStatic(routerType, "ParseRequestedCount",
				new object[] { "民兵最高的2座城镇" }, 1), CultureInfo.InvariantCulture) == 2,
			"Threshold numbers must not leak into cardinality parsing while explicit target counts remain supported.");
		foreach ((string Query, string Metric, string Comparison, float? Threshold, string Sort, string Cardinality, int Limit) routeCase in new[]
		{
			("户数低于300的全部一级封地", "Hearth", "LessThan", (float?)300f, "Ascending", "All", 0),
			("民兵最高的2座城镇", "Militia", "None", (float?)null, "Descending", "TopN", 2),
			("民兵至少200的前1座城镇", "Militia", "GreaterThanOrEqual", (float?)200f, "Descending", "TopN", 1),
			("民兵至少100且按民兵升序取前2座城镇", "Militia", "GreaterThanOrEqual", (float?)100f, "Ascending", "TopN", 2)
		})
		{
			SetProperty(semanticContextType, semanticContext, "QueryText", routeCase.Query);
			object[] metricRouteArguments = { routeCase.Query, semanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", metricRouteArguments, 4),
				"Deterministic Hearth/Militia TargetPlan routing failed for '" + routeCase.Query + "': " + metricRouteArguments[3]);
			object metricCandidate = Items(metricRouteArguments[2]).Single();
			object metricPlan = Property(metricCandidate.GetType(), metricCandidate, "Plan");
			object metricBranch = Items(Property(metricPlan.GetType(), metricPlan, "Branches")).Single();
			object actualThreshold = Property(metricBranch.GetType(), metricBranch, "MetricThreshold");
			Check(Convert.ToInt32(Property(metricPlan.GetType(), metricPlan, "PlanVersion"), CultureInfo.InvariantCulture) == 3
				&& string.Equals(Property(metricBranch.GetType(), metricBranch, "Metric").ToString(), routeCase.Metric, StringComparison.Ordinal)
				&& string.Equals(Property(metricBranch.GetType(), metricBranch, "MetricComparison").ToString(), routeCase.Comparison, StringComparison.Ordinal)
				&& (!routeCase.Threshold.HasValue || Math.Abs(Convert.ToSingle(actualThreshold, CultureInfo.InvariantCulture) - routeCase.Threshold.Value) < 0.0001f)
				&& (routeCase.Threshold.HasValue || actualThreshold == null)
				&& string.Equals(Property(metricBranch.GetType(), metricBranch, "SortDirection").ToString(), routeCase.Sort, StringComparison.Ordinal)
				&& string.Equals(Property(metricBranch.GetType(), metricBranch, "Cardinality").ToString(), routeCase.Cardinality, StringComparison.Ordinal)
				&& Convert.ToInt32(Property(metricBranch.GetType(), metricBranch, "Limit"), CultureInfo.InvariantCulture) == routeCase.Limit,
				"Unexpected Hearth/Militia TargetPlan shape for '" + routeCase.Query + "'.");
		}
		object deterministicKingdomSemanticContext = Activator.CreateInstance(semanticContextType, nonPublic: true);
		SetProperty(semanticContextType, deterministicKingdomSemanticContext, "Scope", "kingdom");
		SetProperty(semanticContextType, deterministicKingdomSemanticContext, "TargetKingdomId", "k1");
		SetProperty(semanticContextType, deterministicKingdomSemanticContext, "IssuerKingdomId", "k1");
		SetProperty(semanticContextType, deterministicKingdomSemanticContext, "PlayerClanId", "player");
		SetProperty(semanticContextType, deterministicKingdomSemanticContext, "ProposerClanId", "player");
		SetProperty(semanticContextType, deterministicKingdomSemanticContext, "SourceSettlementIds", Array.Empty<string>());
		SetProperty(semanticContextType, deterministicKingdomSemanticContext, "Snapshot", snapshot);
		const string namedForeignRelationCuePolicy = "派遣税吏进入敌国k2王国境内所有城镇和城堡征税，所得充实本国财政";
		object[] namedForeignRelationCueArguments = { namedForeignRelationCuePolicy, deterministicKingdomSemanticContext, null, null };
		Check((bool)InvokeStatic(routerType, "TryRoute", namedForeignRelationCueArguments, 4),
			"A named foreign kingdom must override generic enemy/domestic prose cues before relation conflict validation: "
			+ namedForeignRelationCueArguments[3]);
		object[] namedForeignRelationCueCandidates = Items(namedForeignRelationCueArguments[2]).ToArray();
		Check(namedForeignRelationCueCandidates.Length == 1,
			"A single named foreign kingdom with enemy/domestic prose cues must produce one bounded TargetPlan candidate.");
		object namedForeignRelationCuePlan = Property(namedForeignRelationCueCandidates[0].GetType(), namedForeignRelationCueCandidates[0], "Plan");
		object namedForeignRelationCueBranch = Items(Property(planType, namedForeignRelationCuePlan, "Branches")).Single();
		Check(string.Equals(Property(branchType, namedForeignRelationCueBranch, "Universe").ToString(), "PrimaryFiefs", StringComparison.Ordinal)
			&& string.Equals(Property(branchType, namedForeignRelationCueBranch, "EntityType").ToString(), "PrimaryFief", StringComparison.Ordinal)
			&& string.Equals(Property(branchType, namedForeignRelationCueBranch, "Relation").ToString(), "Specific", StringComparison.Ordinal)
			&& ReadStringPropertyValues(namedForeignRelationCueBranch, "NamedKingdomIds").SequenceEqual(new[] { "k2" }, StringComparer.Ordinal)
			&& string.Equals(Property(branchType, namedForeignRelationCueBranch, "Cardinality").ToString(), "All", StringComparison.Ordinal),
			"A named foreign kingdom with prose relation cues must remain Specific(k2)/PrimaryFief/All.");
		object[] routeArguments = { "去其他地方抢税收", semanticContext, null, null };
		bool routeSucceeded = (bool)InvokeStatic(routerType, "TryRoute", routeArguments, 4);
		object[] routedCandidates = Items(routeArguments[2]).ToArray();
		bool requireOnnxRoute = !string.IsNullOrWhiteSpace(
			Environment.GetEnvironmentVariable(OnnxRuntimeDirectoryEnvironmentVariable));
		object[] unboundAtomArguments =
		{
			new[] { "exclude_publication" },
			new HashSet<string>(StringComparer.Ordinal),
			true,
			false,
			false,
			null,
			null
		};
		Check((bool)InvokeStatic(routerType, "TryGetUnboundSemanticAtomIds", unboundAtomArguments, 7),
			"An embedding-only atom without its runtime operand must be prunable without throwing.");
		Check(Items(unboundAtomArguments[5]).Select(value => value.ToString()).SequenceEqual(
			new[] { "exclude_publication" }, StringComparer.Ordinal),
			"The unbound semantic atom check must report the pruned atom id.");
		Check(string.IsNullOrWhiteSpace(unboundAtomArguments[6]?.ToString()),
			"Pruning an embedding-only atom must not surface a user-facing validation error.");
		object[] unvalidatedSpecificAtomArguments =
		{
			new[] { "exclude_specific_entity" },
			new HashSet<string>(StringComparer.Ordinal),
			true,
			true,
			false,
			null,
			null
		};
		Check((bool)InvokeStatic(routerType, "TryGetUnboundSemanticAtomIds", unvalidatedSpecificAtomArguments, 7)
			&& Items(unvalidatedSpecificAtomArguments[5]).Select(value => value.ToString()).SequenceEqual(
				new[] { "exclude_specific_entity" }, StringComparer.Ordinal),
			"A specific-entity exclusion must be pruned unless C# supplied a validated entity operand.");
		object[] validatedSpecificAtomArguments =
		{
			new[] { "exclude_specific_entity" },
			new HashSet<string>(new[] { "exclude_specific_entity" }, StringComparer.Ordinal),
			true,
			true,
			true,
			null,
			null
		};
		Check((bool)InvokeStatic(routerType, "TryGetUnboundSemanticAtomIds", validatedSpecificAtomArguments, 7)
			&& !Items(validatedSpecificAtomArguments[5]).Any(),
			"A C#-validated specific entity operand must preserve its exclusion atom.");
		object[] nonLocalExplicitPublicationArguments =
		{
			new[] { "exclude_publication" },
			new HashSet<string>(new[] { "exclude_publication" }, StringComparer.Ordinal),
			false,
			false,
			false,
			null,
			null
		};
		Check((bool)InvokeStatic(routerType, "TryGetUnboundSemanticAtomIds", nonLocalExplicitPublicationArguments, 7)
			&& Items(nonLocalExplicitPublicationArguments[5]).Select(value => value.ToString()).SequenceEqual(
				new[] { "exclude_publication" }, StringComparer.Ordinal)
			&& string.IsNullOrWhiteSpace(nonLocalExplicitPublicationArguments[6]?.ToString()),
			"Kingdom and vassal scopes must prune even an explicit publication exclusion without reporting a missing anchor.");
		if (requireOnnxRoute)
		{
			Check(routeSucceeded && routedCandidates.Length > 0,
				"The staged module's existing embedding ONNX must produce a TargetPlan: " + routeArguments[3]);
		}
		if (routeSucceeded && routedCandidates.Length > 0)
		{
			object routedPlan = Property(routedCandidates[0].GetType(), routedCandidates[0], "Plan");
			object routedBranch = Items(Property(planType, routedPlan, "Branches")).Single();
			object[] routedExclusions = Items(Property(branchType, routedBranch, "Exclusions")).ToArray();
			Check(routedExclusions.Length == 1
				&& routedExclusions.Any(value => string.Equals(value.ToString(), "PublicationParents", StringComparison.Ordinal))
				&& !string.Equals(Property(branchType, routedBranch, "OwnerClanPredicate").ToString(), "ExcludePlayerClan", StringComparison.Ordinal),
				"Regression: other places must exclude the publication parent, never the player's entire clan.");
			string routedShape = "universe=" + Property(branchType, routedBranch, "Universe")
				+ " type=" + Property(branchType, routedBranch, "EntityType")
				+ " relation=" + Property(branchType, routedBranch, "Relation")
				+ " owner=" + Property(branchType, routedBranch, "OwnerClanPredicate")
				+ " metric=" + Property(branchType, routedBranch, "Metric")
				+ " direction=" + Property(branchType, routedBranch, "Direction")
				+ " distance=" + Property(branchType, routedBranch, "Distance")
				+ " border=" + Property(branchType, routedBranch, "BorderOnly")
				+ " cardinality=" + Property(branchType, routedBranch, "Cardinality");
			Check(string.Equals(Property(branchType, routedBranch, "Universe").ToString(), "PrimaryFiefs", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, routedBranch, "EntityType").ToString(), "PrimaryFief", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, routedBranch, "Relation").ToString(), "Domestic", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, routedBranch, "OwnerClanPredicate").ToString(), "Any", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, routedBranch, "Metric").ToString(), "None", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, routedBranch, "Direction").ToString(), "Any", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, routedBranch, "Distance").ToString(), "None", StringComparison.Ordinal)
				&& !(bool)Property(branchType, routedBranch, "BorderOnly")
				&& string.Equals(Property(branchType, routedBranch, "Cardinality").ToString(), "All", StringComparison.Ordinal),
				"Regression: other places must mean all other domestic primary fiefs without invented ranking or geography filters. " + routedShape);
			if (requireOnnxRoute)
			{
				Console.WriteLine("ONNX_TARGET_ROUTE verified=all-other-domestic-primary-fiefs model=existing-embedding");
			}
		}
		else
		{
			Check(routedCandidates.Length == 0,
				"When the existing embedding ONNX is unavailable, the compound TargetPlan route must abstain.");
		}
		if (requireOnnxRoute)
		{
			object kingdomSemanticContext = Activator.CreateInstance(semanticContextType, nonPublic: true);
			SetProperty(semanticContextType, kingdomSemanticContext, "Scope", "kingdom");
			SetProperty(semanticContextType, kingdomSemanticContext, "TargetKingdomId", "k1");
			SetProperty(semanticContextType, kingdomSemanticContext, "IssuerKingdomId", "k1");
			SetProperty(semanticContextType, kingdomSemanticContext, "PlayerClanId", "player");
			SetProperty(semanticContextType, kingdomSemanticContext, "ProposerClanId", "player");
			SetProperty(semanticContextType, kingdomSemanticContext, "SourceSettlementIds", Array.Empty<string>());
			SetProperty(semanticContextType, kingdomSemanticContext, "Snapshot", snapshot);
			const string nationwidePolicy = "全国范围内所有城镇和城堡统一征税";
			SetProperty(semanticContextType, kingdomSemanticContext, "QueryText", nationwidePolicy);
			object[] nationwideRouteArguments = { nationwidePolicy, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", nationwideRouteArguments, 4),
				"A nationwide geographic policy must not fail because ONNX proposed an unbound publication exclusion: "
				+ nationwideRouteArguments[3]);
			object[] nationwideCandidates = Items(nationwideRouteArguments[2]).ToArray();
			Check(nationwideCandidates.Length == 1,
				"A nationwide all-fiefs policy must produce one deterministic TargetPlan.");
			object nationwidePlan = Property(nationwideCandidates[0].GetType(), nationwideCandidates[0], "Plan");
			object nationwideBranch = Items(Property(planType, nationwidePlan, "Branches")).Single();
			Check(string.Equals(Property(branchType, nationwideBranch, "Universe").ToString(), "PrimaryFiefs", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, nationwideBranch, "EntityType").ToString(), "PrimaryFief", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, nationwideBranch, "Relation").ToString(), "Domestic", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, nationwideBranch, "Cardinality").ToString(), "All", StringComparison.Ordinal)
				&& !Items(Property(branchType, nationwideBranch, "Exclusions"))
					.Any(value => string.Equals(value.ToString(), "PublicationParents", StringComparison.Ordinal)),
				"Nationwide geographic policy must remain Domestic/PrimaryFief/All without PublicationParents.");

			const string generatedSubsidyPolicy = "向k1王国全境城镇、城堡及村庄发放百万补贴，各领地长官负责分配";
			SetProperty(semanticContextType, kingdomSemanticContext, "QueryText", generatedSubsidyPolicy);
			object[] generatedSubsidyArguments = { generatedSubsidyPolicy, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", generatedSubsidyArguments, 4),
				"A generated nationwide policy must treat the named target kingdom as scope, not a conflicting target type: "
				+ generatedSubsidyArguments[3]);
			object[] generatedSubsidyCandidates = Items(generatedSubsidyArguments[2]).ToArray();
			Check(generatedSubsidyCandidates.Length == 1,
				"A generated nationwide subsidy must produce one deterministic TargetPlan.");
			object generatedSubsidyPlan = Property(generatedSubsidyCandidates[0].GetType(), generatedSubsidyCandidates[0], "Plan");
			object generatedSubsidyBranch = Items(Property(planType, generatedSubsidyPlan, "Branches")).Single();
			string generatedSubsidyShape = "universe=" + Property(branchType, generatedSubsidyBranch, "Universe")
				+ " type=" + Property(branchType, generatedSubsidyBranch, "EntityType")
				+ " relation=" + Property(branchType, generatedSubsidyBranch, "Relation")
				+ " cardinality=" + Property(branchType, generatedSubsidyBranch, "Cardinality");
			Check(string.Equals(Property(branchType, generatedSubsidyBranch, "Universe").ToString(), "PrimaryFiefs", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, generatedSubsidyBranch, "EntityType").ToString(), "PrimaryFief", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, generatedSubsidyBranch, "Relation").ToString(), "Domestic", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, generatedSubsidyBranch, "Cardinality").ToString(), "All", StringComparison.Ordinal),
				"Generated nationwide subsidy must resolve to all domestic primary fiefs without world-scope expansion. "
				+ generatedSubsidyShape);

			const string namedForeignFiefPolicy = "向k2王国全境所有城镇和城堡发放补贴";
			object[] namedForeignArguments = { namedForeignFiefPolicy, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", namedForeignArguments, 4),
				"A named foreign kingdom must act as the exact scope of its lower-level fiefs: " + namedForeignArguments[3]);
			object[] namedForeignCandidates = Items(namedForeignArguments[2]).ToArray();
			Check(namedForeignCandidates.Length == 1,
				"A single named foreign kingdom must produce one bounded TargetPlan candidate.");
			object namedForeignPlan = Property(namedForeignCandidates[0].GetType(), namedForeignCandidates[0], "Plan");
			object namedForeignBranch = Items(Property(planType, namedForeignPlan, "Branches")).Single();
			Check(string.Equals(Property(branchType, namedForeignBranch, "Universe").ToString(), "PrimaryFiefs", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, namedForeignBranch, "EntityType").ToString(), "PrimaryFief", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, namedForeignBranch, "Relation").ToString(), "Specific", StringComparison.Ordinal)
				&& ReadStringPropertyValues(namedForeignBranch, "NamedKingdomIds").SequenceEqual(new[] { "k2" }, StringComparer.Ordinal)
				&& string.Equals(Property(branchType, namedForeignBranch, "Cardinality").ToString(), "All", StringComparison.Ordinal),
				"A named foreign fief policy must remain Specific(k2)/PrimaryFief/All.");

			const string namedKingdomOnlyPolicy = "调整k2王国整体稳定度";
			object[] namedKingdomOnlyArguments = { namedKingdomOnlyPolicy, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", namedKingdomOnlyArguments, 4),
				"Masking a named entity's type suffix must not erase a genuine kingdom target: " + namedKingdomOnlyArguments[3]);
			object[] namedKingdomOnlyCandidates = Items(namedKingdomOnlyArguments[2]).ToArray();
			Check(namedKingdomOnlyCandidates.Length == 1,
				"A policy naming one kingdom without a lower-level target must retain one kingdom candidate.");
			object namedKingdomOnlyPlan = Property(namedKingdomOnlyCandidates[0].GetType(), namedKingdomOnlyCandidates[0], "Plan");
			object namedKingdomOnlyBranch = Items(Property(planType, namedKingdomOnlyPlan, "Branches")).Single();
			Check(string.Equals(Property(branchType, namedKingdomOnlyBranch, "Universe").ToString(), "Kingdoms", StringComparison.Ordinal)
				&& string.Equals(Property(branchType, namedKingdomOnlyBranch, "EntityType").ToString(), "Kingdom", StringComparison.Ordinal)
				&& ReadStringPropertyValues(namedKingdomOnlyBranch, "EntityReferences").SequenceEqual(new[] { "k2" }, StringComparer.Ordinal),
				"A genuine named kingdom target must remain an exact Kingdom target.");

			const string twoKingdomFiefPolicy = "k1王国与k2王国全境所有城镇和城堡共同减税";
			object[] twoKingdomArguments = { twoKingdomFiefPolicy, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", twoKingdomArguments, 4),
				"Multiple named kingdoms must remain bounded target alternatives: " + twoKingdomArguments[3]);
			object[] twoKingdomCandidates = Items(twoKingdomArguments[2]).ToArray();
			Check(twoKingdomCandidates.Length == 2,
				"Two named kingdom scopes must produce two exact handles instead of Relation.Any or one world-wide handle. actual="
				+ twoKingdomCandidates.Length.ToString(CultureInfo.InvariantCulture)
				+ " signatures=" + string.Join(",", twoKingdomCandidates.Select(candidate =>
					Property(planType, Property(candidate.GetType(), candidate, "Plan"), "NormalizedSignature"))));
			string[] boundedKingdomIds = twoKingdomCandidates
				.Select(candidate => Property(candidate.GetType(), candidate, "Plan"))
				.Select(plan => Items(Property(planType, plan, "Branches")).Single())
				.SelectMany(branch => ReadStringPropertyValues(branch, "NamedKingdomIds"))
				.OrderBy(id => id, StringComparer.Ordinal)
				.ToArray();
			Check(boundedKingdomIds.SequenceEqual(new[] { "k1", "k2" }, StringComparer.Ordinal)
				&& twoKingdomCandidates.All(candidate =>
				{
					object plan = Property(candidate.GetType(), candidate, "Plan");
					object branch = Items(Property(planType, plan, "Branches")).Single();
					return string.Equals(Property(branchType, branch, "Universe").ToString(), "PrimaryFiefs", StringComparison.Ordinal)
						&& string.Equals(Property(branchType, branch, "Relation").ToString(), "Specific", StringComparison.Ordinal)
						&& string.Equals(Property(branchType, branch, "Cardinality").ToString(), "All", StringComparison.Ordinal);
				}),
				"Each named kingdom alternative must be an exact Specific/PrimaryFief/All plan.");

			const string independentTargetKindsPolicy = "同时提高王国稳定度和城镇繁荣度";
			object[] independentTargetKindsArguments = { independentTargetKindsPolicy, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", independentTargetKindsArguments, 4)
				&& !Items(independentTargetKindsArguments[2]).Any()
				&& string.IsNullOrWhiteSpace(independentTargetKindsArguments[3]?.ToString()),
				"Independent kingdom and settlement effects must cause a safe TargetPlan abstention, not type precedence or a fatal technical-data error.");

			const string ordinaryDurationOrPolicy = "对本国城镇发放补贴，持续至补贴资金用尽或另行调整";
			object[] ordinaryDurationOrArguments = { ordinaryDurationOrPolicy, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", ordinaryDurationOrArguments, 4),
				"An ordinary duration phrase containing 或 must fall back to one whole-query TargetPlan parse: "
				+ ordinaryDurationOrArguments[3]);
			object[] ordinaryDurationOrCandidates = Items(ordinaryDurationOrArguments[2]).ToArray();
			Check(ordinaryDurationOrCandidates.Length == 1
				&& Items(Property(
					planType,
					Property(ordinaryDurationOrCandidates[0].GetType(), ordinaryDurationOrCandidates[0], "Plan"),
					"Branches")).Count() == 1,
				"An ordinary duration phrase containing 或 must stay a single-branch TargetPlan.");

			const string ordinaryActionOrPolicy = "对本国城镇实施减税或补贴";
			object[] ordinaryActionOrArguments = { ordinaryActionOrPolicy, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", ordinaryActionOrArguments, 4),
				"An ordinary action phrase containing 或 must fall back to one whole-query TargetPlan parse: "
				+ ordinaryActionOrArguments[3]);
			object[] ordinaryActionOrCandidates = Items(ordinaryActionOrArguments[2]).ToArray();
			Check(ordinaryActionOrCandidates.Length == 1
				&& Items(Property(
					planType,
					Property(ordinaryActionOrCandidates[0].GetType(), ordinaryActionOrCandidates[0], "Plan"),
					"Branches")).Count() == 1,
				"An ordinary action phrase containing 或 must stay a single-branch TargetPlan.");

			const string ordinaryExecutorOrPolicy = "由执行者或财政官对本国城镇统一征税";
			object[] ordinaryExecutorOrArguments = { ordinaryExecutorOrPolicy, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", ordinaryExecutorOrArguments, 4),
				"An executor phrase containing 或 must not widen TargetPlan parsing: " + ordinaryExecutorOrArguments[3]);
			object[] ordinaryExecutorOrCandidates = Items(ordinaryExecutorOrArguments[2]).ToArray();
			Check(ordinaryExecutorOrCandidates.Length == 1
				&& Items(Property(
					planType,
					Property(ordinaryExecutorOrCandidates[0].GetType(), ordinaryExecutorOrCandidates[0], "Plan"),
					"Branches")).Count() == 1,
				"An executor phrase containing 或 must stay a single-branch TargetPlan.");

			const string sameUniverseOrPolicy = "对本国城镇或本国城堡统一征税";
			object[] sameUniverseOrArguments = { sameUniverseOrPolicy, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", sameUniverseOrArguments, 4),
				"Two independently parseable same-universe targets must remain a legal OR TargetPlan: "
				+ sameUniverseOrArguments[3]);
			object[] sameUniverseOrCandidates = Items(sameUniverseOrArguments[2]).ToArray();
			Check(sameUniverseOrCandidates.Length == 1,
				"A same-universe OR query must still produce one bounded TargetPlan candidate.");
			object sameUniverseOrPlan = Property(sameUniverseOrCandidates[0].GetType(), sameUniverseOrCandidates[0], "Plan");
			object[] sameUniverseOrBranches = Items(Property(planType, sameUniverseOrPlan, "Branches")).ToArray();
			Check(sameUniverseOrBranches.Length == 2
				&& sameUniverseOrBranches.All(branch =>
					string.Equals(Property(branchType, branch, "Universe").ToString(), "PrimaryFiefs", StringComparison.Ordinal))
				&& sameUniverseOrBranches.Select(branch => Property(branchType, branch, "EntityType").ToString())
					.OrderBy(value => value, StringComparer.Ordinal)
					.SequenceEqual(new[] { "Castle", "Town" }, StringComparer.Ordinal),
				"A same-universe OR query must preserve two PrimaryFiefs branches with exact Town/Castle typing.");

			const string differentUniverseOrPolicy = "同时提高王国稳定度或城镇繁荣度";
			object[] differentUniverseOrArguments = { differentUniverseOrPolicy, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", differentUniverseOrArguments, 4)
				&& !Items(differentUniverseOrArguments[2]).Any()
				&& string.IsNullOrWhiteSpace(differentUniverseOrArguments[3]?.ToString()),
				"A mixed-universe OR query must never widen permissions; it must fall back to a safe whole-query abstention.");

			const string explicitOtherPlaces = "其他地方的所有城镇和城堡统一征税";
			SetProperty(semanticContextType, kingdomSemanticContext, "QueryText", explicitOtherPlaces);
			object[] kingdomExplicitArguments = { explicitOtherPlaces, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", kingdomExplicitArguments, 4),
				"Kingdom scope must prune an explicit publication exclusion instead of requiring a local anchor: "
				+ kingdomExplicitArguments[3]);
			object[] kingdomExplicitCandidates = Items(kingdomExplicitArguments[2]).ToArray();
			Check(kingdomExplicitCandidates.Length == 1
				&& Property(kingdomExplicitCandidates[0].GetType(), kingdomExplicitCandidates[0], "Evidence")
					.ToString().IndexOf("pruned=exclude_publication", StringComparison.Ordinal) >= 0,
				"Kingdom scope must record the pruned publication exclusion atom.");
			const string publicationExclusionOnly = "其他地方";
			SetProperty(semanticContextType, kingdomSemanticContext, "QueryText", publicationExclusionOnly);
			object[] exclusionOnlyArguments = { publicationExclusionOnly, kingdomSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", exclusionOnlyArguments, 4)
				&& !Items(exclusionOnlyArguments[2]).Any()
				&& string.IsNullOrWhiteSpace(exclusionOnlyArguments[3]?.ToString()),
				"Pruning the only non-local atom must abstain instead of creating a broad default TargetPlan.");

			object vassalSemanticContext = Activator.CreateInstance(semanticContextType, nonPublic: true);
			SetProperty(semanticContextType, vassalSemanticContext, "QueryText", explicitOtherPlaces);
			SetProperty(semanticContextType, vassalSemanticContext, "Scope", "vassal");
			SetProperty(semanticContextType, vassalSemanticContext, "TargetKingdomId", "k2");
			SetProperty(semanticContextType, vassalSemanticContext, "IssuerKingdomId", "k1");
			SetProperty(semanticContextType, vassalSemanticContext, "PlayerClanId", "player");
			SetProperty(semanticContextType, vassalSemanticContext, "ProposerClanId", "player");
			SetProperty(semanticContextType, vassalSemanticContext, "SourceSettlementIds", Array.Empty<string>());
			SetProperty(semanticContextType, vassalSemanticContext, "Snapshot", snapshot);
			object[] vassalExplicitArguments = { explicitOtherPlaces, vassalSemanticContext, null, null };
			Check((bool)InvokeStatic(routerType, "TryRoute", vassalExplicitArguments, 4),
				"Vassal scope must prune an explicit publication exclusion: " + vassalExplicitArguments[3]);
			object[] vassalCandidates = Items(vassalExplicitArguments[2]).ToArray();
			Check(vassalCandidates.Length == 1
				&& Property(vassalCandidates[0].GetType(), vassalCandidates[0], "Evidence")
					.ToString().IndexOf("pruned=exclude_publication", StringComparison.Ordinal) >= 0,
				"Vassal scope must retain its target-kingdom plan and record the pruned atom.");

			object localMissingAnchorContext = Activator.CreateInstance(semanticContextType, nonPublic: true);
			SetProperty(semanticContextType, localMissingAnchorContext, "QueryText", explicitOtherPlaces);
			SetProperty(semanticContextType, localMissingAnchorContext, "Scope", "local");
			SetProperty(semanticContextType, localMissingAnchorContext, "TargetKingdomId", "k1");
			SetProperty(semanticContextType, localMissingAnchorContext, "IssuerKingdomId", "k1");
			SetProperty(semanticContextType, localMissingAnchorContext, "PlayerClanId", "player");
			SetProperty(semanticContextType, localMissingAnchorContext, "ProposerClanId", "player");
			SetProperty(semanticContextType, localMissingAnchorContext, "SourceSettlementIds", Array.Empty<string>());
			SetProperty(semanticContextType, localMissingAnchorContext, "Snapshot", snapshot);
			object[] localMissingAnchorArguments = { explicitOtherPlaces, localMissingAnchorContext, null, null };
			Check(!(bool)InvokeStatic(routerType, "TryRoute", localMissingAnchorArguments, 4)
				&& localMissingAnchorArguments[3]?.ToString().IndexOf("缺少当前发布地锚点", StringComparison.Ordinal) >= 0,
				"Only local scope must reject an explicit publication exclusion without a source anchor.");
			object localMissingAnchorRoute = InvokeStatic(
				routerType,
				"Route",
				new object[] { explicitOtherPlaces, localMissingAnchorContext },
				2);
			Check(Convert.ToBoolean(Property(routeResultType, localMissingAnchorRoute, "ShouldRejectPolicy"), CultureInfo.InvariantCulture)
				&& Items(Property(routeResultType, localMissingAnchorRoute, "Issues")).Any(issue =>
					string.Equals(Property(issue.GetType(), issue, "Kind").ToString(), "MissingRuntimeAnchor", StringComparison.Ordinal)),
				"An explicit local target without its publication source must be classified as MissingRuntimeAnchor.");

			CheckPolicyTargetSemanticRoute(
				routerType, resolverType, planType, branchType, semanticContext, context,
				"对其他王国的全部定居点征税", "Foreign", "PrimaryFief", "All", "None", false,
				new[] { "ally-town-high", "ally-town-low", "enemy-border-castle", "foreign-town", "neutral-castle" });
			CheckPolicyTargetSemanticRoute(
				routerType, resolverType, planType, branchType, semanticContext, context,
				"敌国全部城镇和城堡", "Enemy", "PrimaryFief", "All", "None", false,
				new[] { "enemy-border-castle", "foreign-town" });
			CheckPolicyTargetSemanticRoute(
				routerType, resolverType, planType, branchType, semanticContext, context,
				"盟国最繁荣的两个城镇", "Ally", "Town", "TopN", "Prosperity", false,
				new[] { "ally-town-high", "ally-town-low" });
			CheckPolicyTargetSemanticRoute(
				routerType, resolverType, planType, branchType, semanticContext, context,
				"除玩家家族外的本国全部城镇和城堡", "Domestic", "PrimaryFief", "All", "None", false,
				new[] { "other-clan-castle" });
			CheckPolicyTargetSemanticRoute(
				routerType, resolverType, planType, branchType, semanticContext, context,
				"所有敌国边境城堡", "Enemy", "Castle", "All", "None", true,
				new[] { "enemy-border-castle" });
		}
	}

	private static void TestPendingPlayerPolicySemanticTargetSnapshotRehydration()
	{
		Type behaviorType = SutType("AnimusForge.CustomPolicyBehavior");
		Type pendingType = behaviorType.GetNestedType("PendingPlayerPolicyAgendaSaveData", All);
		Type requestType = behaviorType.GetNestedType("PolicyDraftRequest", All);
		Type handleType = behaviorType.GetNestedType("PolicyTargetHandleSaveData", All);
		Type effectType = behaviorType.GetNestedType("PolicyEffectDto", All);
		Type directoryType = SutType("AnimusForge.PolicyTargets.PolicyTargetHandleDirectory");
		Type planType = SutType("AnimusForge.PolicyTargets.PolicyTargetPlanSaveData");
		Type entityType = SutType("AnimusForge.PolicyTargets.PolicyTargetEntitySnapshot");
		Type snapshotType = SutType("AnimusForge.PolicyTargets.PolicyTargetWorldSnapshot");
		Check(pendingType != null && directoryType != null,
			"Pending authorization and request-time execution-directory contract types must remain available.");
		object otherClanEntity = BuildPlanNamedEntity(entityType, "other", "clan", "k1");
		object playerClanEntity = BuildPlanNamedEntity(entityType, "player", "clan", "k1");
		object targetKingdomEntity = BuildPlanNamedEntity(entityType, "k1", "kingdom", "k1");
		Array entities = Array.CreateInstance(entityType, 3);
		new[] { otherClanEntity, playerClanEntity, targetKingdomEntity }.CopyTo(entities, 0);
		object snapshot = Activator.CreateInstance(snapshotType, nonPublic: true);
		SetProperty(snapshotType, snapshot, "StableVersion", 1L);
		SetProperty(snapshotType, snapshot, "DynamicVersion", 1L);
		SetProperty(snapshotType, snapshot, "Entities", entities);
		SetProperty(snapshotType, snapshot, "WarPairs", Array.Empty<string>());
		SetProperty(snapshotType, snapshot, "AlliancePairs", Array.Empty<string>());
		object clanPlan = TokenToObject(JObject.Parse(
			"{\"planVersion\":3,\"resolverVersion\":2,\"branches\":[{"
			+ "\"universe\":\"Clans\",\"scopeAnchor\":\"TargetKingdom\","
			+ "\"entityType\":\"Clan\",\"relation\":\"Any\","
			+ "\"entityReferences\":[\"other\"],\"cardinality\":\"All\"}]}"), planType);
		object planHandle = BuildLocalPolicyGateHandle(handleType, "P1", "plan");
		SetProperty(handleType, planHandle, "TargetPlan", clanPlan);
		SetProperty(handleType, planHandle, "IsSemanticTarget", true);
		IList handles = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(handleType));
		handles.Add(planHandle);

		object request = Activator.CreateInstance(requestType, nonPublic: true);
		SetField(requestType, request, "RequestId", "pending-roundtrip-semantic-snapshot");
		SetField(requestType, request, "ScopeKind", "kingdom");
		SetField(requestType, request, "ManualDurationDays", 30);
		SetField(requestType, request, "SubmittedDay", 10);
		SetField(requestType, request, "PlayerKingdomId", "k1");
		SetField(requestType, request, "PlayerKingdomName", "玩家王国");
		SetField(requestType, request, "IssuerKingdomId", "k1");
		SetField(requestType, request, "ProposerClanId", "player");
		SetField(requestType, request, "PolicyName", "other 家族影响政策");
		SetField(requestType, request, "PolicyContent", "只调整 other 家族的影响力。");
		SetField(requestType, request, "TargetHandles", handles);
		SetField(requestType, request, "SemanticTargetSnapshot", snapshot);
		SetField(requestType, request, "EffectTargetDirectory", TokenToObject(JObject.Parse(
			"{\"structureVersion\":3,\"targets\":{\"P1\":{\"kind\":\"plan\",\"description\":\"other clan\"}},"
			+ "\"capabilities\":{\"clanInfluence\":{\"defaultTargetHandle\":\"\",\"allowedSubsetTargetHandles\":[\"P1\"],\"allowedTargetHandles\":[\"P1\"]}}}"), directoryType));
		string serializedRequest = JsonConvert.SerializeObject(request);
		object roundTripRequest = JsonConvert.DeserializeObject(serializedRequest, requestType);
		Check(requestType.GetField("SemanticTargetSnapshot", All).GetValue(roundTripRequest) == null,
			"Pending player-policy request JSON must continue dropping SemanticTargetSnapshot so approval must rehydrate it explicitly.");
		Check(requestType.GetField("EffectTargetDirectory", All).GetValue(roundTripRequest) == null,
			"Pending player-policy request JSON must continue dropping the request-time execution directory.");
		object roundTripPlanHandle = Items(requestType.GetField("TargetHandles", All).GetValue(roundTripRequest)).Single();
		Check(!(bool)Property(handleType, roundTripPlanHandle, "IsSemanticTarget"),
			"Pending JSON must continue dropping IsSemanticTarget; authorization must not depend on that runtime flag.");
		object[] missingSnapshotAllowedArguments = { roundTripRequest, roundTripPlanHandle };
		Check(!(bool)InvokeStatic(behaviorType, "IsPolicyTargetHandleAllowedForRequest", missingSnapshotAllowedArguments, 2),
			"Global target validation must remain fail-closed when a pending request has no semantic snapshot.");
		object[] missingRequestAttachArguments = { null, snapshot, null };
		Check(!(bool)InvokeStatic(behaviorType, "TryAttachPendingPlayerPolicySemanticTargetSnapshot", missingRequestAttachArguments, 3)
			&& !string.IsNullOrWhiteSpace(missingRequestAttachArguments[2] as string),
			"Approval-bound snapshot attachment must fail closed when the pending request is missing.");

		object[] missingSnapshotAttachArguments = { roundTripRequest, null, null };
		Check(!(bool)InvokeStatic(behaviorType, "TryAttachPendingPlayerPolicySemanticTargetSnapshot", missingSnapshotAttachArguments, 3)
			&& !string.IsNullOrWhiteSpace(missingSnapshotAttachArguments[2] as string)
			&& requestType.GetField("SemanticTargetSnapshot", All).GetValue(roundTripRequest) == null,
			"Approval-bound snapshot attachment must fail closed without a usable snapshot.");
		object invalidSnapshot = Activator.CreateInstance(snapshotType, nonPublic: true);
		object[] invalidSnapshotAttachArguments = { roundTripRequest, invalidSnapshot, null };
		Check(!(bool)InvokeStatic(behaviorType, "TryAttachPendingPlayerPolicySemanticTargetSnapshot", invalidSnapshotAttachArguments, 3)
			&& !string.IsNullOrWhiteSpace(invalidSnapshotAttachArguments[2] as string),
			"Approval-bound snapshot attachment must reject a snapshot with no entity collection.");

		object requestWithoutPlan = Activator.CreateInstance(requestType, nonPublic: true);
		IList nonPlanHandles = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(handleType));
		nonPlanHandles.Add(BuildLocalPolicyGateHandle(handleType, "K0", "kingdom"));
		SetField(requestType, requestWithoutPlan, "TargetHandles", nonPlanHandles);
		object[] noPlanAttachArguments = { requestWithoutPlan, null, null };
		Check(!(bool)InvokeStatic(behaviorType, "TryAttachPendingPlayerPolicySemanticTargetSnapshot", noPlanAttachArguments, 3),
			"Every pending request with executable target handles must rebuild authorization from a current snapshot.");
		object[] noPlanSnapshotAttachArguments = { requestWithoutPlan, snapshot, null };
		Check((bool)InvokeStatic(behaviorType, "TryAttachPendingPlayerPolicySemanticTargetSnapshot", noPlanSnapshotAttachArguments, 3)
			&& ReferenceEquals(requestType.GetField("SemanticTargetSnapshot", All).GetValue(requestWithoutPlan), snapshot),
			"A direct-handle pending request must attach the current snapshot before approval replay.");

		object[] attachArguments = { roundTripRequest, snapshot, null };
		Check((bool)InvokeStatic(behaviorType, "TryAttachPendingPlayerPolicySemanticTargetSnapshot", attachArguments, 3)
			&& ReferenceEquals(requestType.GetField("SemanticTargetSnapshot", All).GetValue(roundTripRequest), snapshot),
			"Approval-bound recovery must attach the captured snapshot to the round-tripped request: "
			+ (attachArguments[2] as string));
		object[] allowedArguments = { roundTripRequest, roundTripPlanHandle };
		object[] recoveredPlanResolutionArguments =
		{
			roundTripRequest,
			Property(handleType, roundTripPlanHandle, "TargetPlan"),
			null,
			null
		};
		bool recoveredPlanResolved = (bool)InvokeStatic(
			behaviorType,
			"TryResolvePolicyTargetPlanForRequest",
			recoveredPlanResolutionArguments,
			4);
		object recoveredAuthorization = InvokeStatic(
			behaviorType,
			"EnsurePlayerPolicyTargetAuthorization",
			new[] { roundTripRequest },
			1);
		object recoveredRoute = Property(recoveredAuthorization.GetType(), recoveredAuthorization, "PlanRoute");
		string recoveredSignatures = string.Join(",", Items(Property(recoveredRoute.GetType(), recoveredRoute, "Candidates"))
			.Select(candidate => Property(Property(candidate.GetType(), candidate, "Plan").GetType(),
				Property(candidate.GetType(), candidate, "Plan"), "NormalizedSignature")?.ToString()));
		Check((bool)InvokeStatic(behaviorType, "IsPolicyTargetHandleAllowedForRequest", allowedArguments, 2),
			"TargetPlan handle P1 must become valid only after objective-evidence authorization is rebuilt from the current snapshot."
			+ " resolved=" + recoveredPlanResolved + " error=" + recoveredPlanResolutionArguments[3]
			+ " authorizationSignatures=" + recoveredSignatures);
		object legacyUnprovenRequest = JsonConvert.DeserializeObject(serializedRequest, requestType);
		SetField(requestType, legacyUnprovenRequest, "PolicyName", string.Empty);
		SetField(requestType, legacyUnprovenRequest, "PolicyContent", string.Empty);
		object[] legacyUnprovenAttach = { legacyUnprovenRequest, snapshot, null };
		Check((bool)InvokeStatic(behaviorType, "TryAttachPendingPlayerPolicySemanticTargetSnapshot", legacyUnprovenAttach, 3),
			"The old pending fixture must attach a snapshot before its authorization is evaluated.");
		object legacyUnprovenHandle = Items(requestType.GetField("TargetHandles", All).GetValue(legacyUnprovenRequest)).Single();
		Check(!(bool)InvokeStatic(behaviorType, "IsPolicyTargetHandleAllowedForRequest", new[] { legacyUnprovenRequest, legacyUnprovenHandle }, 2),
			"An old pending P handle that cannot be re-proven from policy text must fail closed.");

		object forgedPlan = TokenToObject(JObject.Parse(
			"{\"planVersion\":2,\"resolverVersion\":1,\"branches\":[{"
			+ "\"universe\":\"Clans\",\"scopeAnchor\":\"TargetKingdom\","
			+ "\"entityType\":\"Clan\",\"relation\":\"Any\","
			+ "\"entityReferences\":[\"not-in-snapshot\"],\"cardinality\":\"All\"}]}"), planType);
		object forgedHandle = BuildLocalPolicyGateHandle(handleType, "P9", "plan");
		SetProperty(handleType, forgedHandle, "TargetPlan", forgedPlan);
		object[] forgedArguments = { roundTripRequest, forgedHandle };
		Check(!(bool)InvokeStatic(behaviorType, "IsPolicyTargetHandleAllowedForRequest", forgedArguments, 2),
			"Snapshot recovery must not authorize a TargetPlan entity reference outside the captured snapshot.");

		object pending = Activator.CreateInstance(pendingType, nonPublic: true);
		SetProperty(pendingType, pending, "Version", 5);
		SetProperty(pendingType, pending, "Request", request);
		SetProperty(pendingType, pending, "CandidateModuleIds", new List<string> { "militiaPerDay" });
		SetProperty(pendingType, pending, "DetailedModuleIds", new List<string> { "militiaPerDay" });
		object roundTripPending = JsonConvert.DeserializeObject(JsonConvert.SerializeObject(pending), pendingType);
		object identityEffect = Activator.CreateInstance(effectType, nonPublic: true);
		SetProperty(effectType, identityEffect, "ModuleId", "militiaPerDay");
		SetProperty(effectType, identityEffect, "SourceModuleId", "militiaPerDay");
		IList identityEffects = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(effectType));
		identityEffects.Add(identityEffect);
		object[] identityAuthorizationArguments = { roundTripPending, "local", identityEffects, null, null, null };
		Check((bool)InvokeStatic(
				behaviorType,
				"TryResolvePendingPlayerPolicyModuleAllowlists",
				identityAuthorizationArguments,
				6)
			&& Items(identityAuthorizationArguments[3]).Select(value => value.ToString())
				.SequenceEqual(new[] { "militiaPerDay" }, StringComparer.Ordinal),
			"A round-tripped pending authorization must preserve an identity source/runtime lineage: "
			+ identityAuthorizationArguments[5]);
		SetProperty(effectType, identityEffect, "SourceModuleId", "foodPerDay");
		object[] forgedIdentityAuthorizationArguments = { roundTripPending, "local", identityEffects, null, null, null };
		Check(!(bool)InvokeStatic(
				behaviorType,
				"TryResolvePendingPlayerPolicyModuleAllowlists",
				forgedIdentityAuthorizationArguments,
				6),
			"A round-tripped pending authorization must reject a forged source/runtime lineage.");

		object runtimeEffect = Activator.CreateInstance(effectType, nonPublic: true);
		SetProperty(effectType, runtimeEffect, "ModuleId", "clanInfluenceNextDayOnce");
		SetProperty(effectType, runtimeEffect, "SourceModuleId", "clanInfluence");
		SetProperty(effectType, runtimeEffect, "TargetHandles", new List<string> { "P1" });
		SetProperty(effectType, runtimeEffect, "Payload", new JObject { ["value"] = -4f });
		SetProperty(effectType, runtimeEffect, "Reason", "pending approval recompile");
		IList runtimeEffects = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(effectType));
		runtimeEffects.Add(runtimeEffect);
		EnsurePolicyApiProbeMainHero();
		object[] compileArguments =
		{
			roundTripRequest,
			(int?)30,
			runtimeEffects,
			new[] { "clanInfluence" },
			new[] { "clanInfluence" },
			null,
			null,
			false
		};
		Check((bool)InvokeStatic(behaviorType, "TryCompileSparsePolicyEffects", compileArguments, 8),
			"A recovered P1 plan must allow the frozen clanInfluence -> clanInfluenceNextDayOnce lineage to recompile: "
			+ (compileArguments[6] as string));
		object[] compiledEffects = Items(compileArguments[5]).ToArray();
		Check(compiledEffects.Length == 1
			&& string.Equals((string)Property(effectType, compiledEffects[0], "ModuleId"), "clanInfluenceNextDayOnce", StringComparison.Ordinal)
			&& string.Equals((string)Property(effectType, compiledEffects[0], "SourceModuleId"), "clanInfluence", StringComparison.Ordinal),
			"Pending approval recompile must preserve the authorized source/runtime lineage for P1.");
		object[] missingAuthorizationCompileArguments =
		{
			roundTripRequest,
			(int?)30,
			runtimeEffects,
			Array.Empty<string>(),
			Array.Empty<string>(),
			null,
			null,
			false
		};
		Check(!(bool)InvokeStatic(
				behaviorType,
				"TryCompileSparsePolicyEffects",
				missingAuthorizationCompileArguments,
				8),
			"Pending approval recompile must fail closed when its explicit frozen authorization is empty.");

		PolicyEffectInstanceSaveData integerReplayInstance = new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "M1",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "pending-troop-xp-once",
			PolicyId = "pending-troop-xp-contract",
			ActorHeroId = "policy-actor",
			ModuleId = "soldierTroopXpOnce",
			SourceModuleId = "soldierTroopXp",
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = "soldierTroopXpOnce",
				["schemaVersion"] = 1,
				["value"] = 250f
			},
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "P1" },
				ClanIds = new List<string> { "other-clan" }
			},
			LifecycleState = PolicyEffectLifecycleState.Prepared,
			StateSchemaVersion = 1,
			StartDay = 10f,
			EndDay = 40f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "pending integer replay"
		};
		PolicyEffectInstanceSaveData unchangedReplay = JsonConvert.DeserializeObject<PolicyEffectInstanceSaveData>(
			JsonConvert.SerializeObject(integerReplayInstance));
		object[] unchangedSnapshotArguments =
		{
			new List<PolicyEffectInstanceSaveData> { integerReplayInstance },
			new List<PolicyEffectInstanceSaveData> { unchangedReplay },
			null
		};
		Check((bool)InvokeStatic(
				behaviorType,
				"TryValidatePendingPlayerPolicyTargetSnapshot",
				unchangedSnapshotArguments,
				3),
			"Pending approval must accept an identical module/source/mechanism/selector/canonical target snapshot: "
			+ unchangedSnapshotArguments[2]);
		unchangedReplay.TargetSet.ClanIds = new List<string> { "replacement-clan" };
		object[] driftedSnapshotArguments =
		{
			new List<PolicyEffectInstanceSaveData> { integerReplayInstance },
			new List<PolicyEffectInstanceSaveData> { unchangedReplay },
			null
		};
		Check(!(bool)InvokeStatic(
				behaviorType,
				"TryValidatePendingPlayerPolicyTargetSnapshot",
				driftedSnapshotArguments,
				3),
			"Pending approval must fail closed when a canonical target is expanded, reduced or replaced.");
		Check(PolicyEffectSaveCodec.TryNormalizeInstance(
				integerReplayInstance,
				out PolicyEffectNormalizedInstance normalizedIntegerReplay,
				out string integerReplayNormalizeError)
			&& normalizedIntegerReplay?.IsInert == false
			&& integerReplayInstance.Payload?["value"]?.Type == JTokenType.Integer,
			"Canonical save normalization must serialize integer-schema values as JSON integer tokens: "
			+ integerReplayNormalizeError);
		object[] integerPendingReadArguments =
		{
			new List<PolicyEffectInstanceSaveData> { integerReplayInstance },
			roundTripRequest,
			null,
			null,
			null
		};
		Check((bool)InvokeStatic(
				behaviorType,
				"TryReadPendingPlayerPolicyCanonicalEffects",
				integerPendingReadArguments,
				5),
			"Pending approval must read a canonicalized soldierTroopXpOnce integer payload: "
			+ integerPendingReadArguments[4]);
		object integerReplayWire = Items(integerPendingReadArguments[2]).Single();
		JToken integerReplayPayload = (JToken)Property(effectType, integerReplayWire, "Payload");
		bool integerReplayCompiles = PolicyEffectModuleCatalog.TryNormalizePayload(
				"soldierTroopXpOnce",
				integerReplayPayload,
				PolicyEffectScopes.Kingdom,
				out _,
				out string integerReplayCompileError);
		Check(integerReplayPayload?["value"]?.Type == JTokenType.Integer
			&& integerReplayCompiles,
			"Pending approval recompile must consume the canonical integer token without weakening the runtime module contract: "
			+ integerReplayCompileError);
		Check(!PolicyEffectModuleCatalog.TryNormalizePayload(
				"soldierTroopXpOnce",
				new JObject { ["value"] = 250.5 },
				PolicyEffectScopes.Kingdom,
				out _,
				out _),
			"Raw fractional troop-XP payloads must remain rejected after internal save canonicalization.");

		List<PolicyEffectInstanceSaveData> linkedPendingEffects = new List<PolicyEffectInstanceSaveData>
		{
			new PolicyEffectInstanceSaveData
			{
				EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
				MechanismId = "M0",
				MechanismKind = PolicyEffectMechanismKind.Linked,
				MechanismRole = PolicyEffectMechanismRole.Source,
				InstanceId = "pending-linked-source",
				PolicyId = "pending-linked-contract",
				ActorHeroId = "policy-actor",
				ModuleId = "foodPerDay",
				SourceModuleId = "foodPerDay",
				PayloadSchemaVersion = 1,
				Payload = new JObject { ["moduleId"] = "foodPerDay", ["schemaVersion"] = 1, ["value"] = -2f },
				TargetSet = new PolicyEffectCanonicalTargetSet
				{
					SelectorHandles = new List<string> { "S0" },
					SettlementIds = new List<string> { "pending-source-settlement" }
				},
				LifecycleState = PolicyEffectLifecycleState.Prepared,
				StateSchemaVersion = 1,
				StartDay = 10f,
				EndDay = 40f,
				SourceScope = PolicyEffectScopes.Kingdom,
				Reason = "linked source"
			},
			new PolicyEffectInstanceSaveData
			{
				EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
				MechanismId = "M0",
				MechanismKind = PolicyEffectMechanismKind.Linked,
				MechanismRole = PolicyEffectMechanismRole.Beneficiary,
				InstanceId = "pending-linked-beneficiary",
				PolicyId = "pending-linked-contract",
				ActorHeroId = "policy-actor",
				ModuleId = "foodPerDay",
				SourceModuleId = "foodPerDay",
				PayloadSchemaVersion = 1,
				Payload = new JObject { ["moduleId"] = "foodPerDay", ["schemaVersion"] = 1, ["value"] = 2f },
				TargetSet = new PolicyEffectCanonicalTargetSet
				{
					SelectorHandles = new List<string> { "S1" },
					SettlementIds = new List<string> { "pending-beneficiary-settlement" }
				},
				LifecycleState = PolicyEffectLifecycleState.Prepared,
				StateSchemaVersion = 1,
				StartDay = 10f,
				EndDay = 40f,
				SourceScope = PolicyEffectScopes.Kingdom,
				Reason = "linked beneficiary"
			}
		};
		Check(PolicyEffectMechanismContract.TryFreeze(linkedPendingEffects, out string linkedFreezeError),
			"The linked pending fixture must freeze before replay: " + linkedFreezeError);
		object[] linkedPendingReadArguments = { linkedPendingEffects, roundTripRequest, null, null, null };
		Check((bool)InvokeStatic(
				behaviorType,
				"TryReadPendingPlayerPolicyCanonicalEffects",
				linkedPendingReadArguments,
				5),
			"Pending approval must accept a frozen linked mechanism: " + linkedPendingReadArguments[4]);
		object[] replayWires = Items(linkedPendingReadArguments[2]).ToArray();
		Check(replayWires.Length == 2
			&& replayWires.All(wire => Convert.ToInt32(Property(effectType, wire, "EffectPlanVersion"), CultureInfo.InvariantCulture)
				== PolicyEffectPlanVersions.CurrentVersion)
			&& replayWires.All(wire => string.Equals((string)Property(effectType, wire, "MechanismId"), "M0", StringComparison.Ordinal))
			&& replayWires.All(wire => string.Equals(Property(effectType, wire, "MechanismKind").ToString(), "Linked", StringComparison.Ordinal))
			&& replayWires.Select(wire => Property(effectType, wire, "MechanismRole").ToString())
				.ToHashSet(StringComparer.Ordinal).SetEquals(new[] { "Source", "Beneficiary" }),
			"Pending approval replay must preserve canonical linked identity and roles instead of downgrading them to legacy independent wires.");

		List<PolicyEffectInstanceSaveData> legacyUnfrozenPending = JsonConvert.DeserializeObject<List<PolicyEffectInstanceSaveData>>(
			JsonConvert.SerializeObject(linkedPendingEffects));
		foreach (PolicyEffectInstanceSaveData leg in legacyUnfrozenPending)
		{
			leg.MechanismContractVersion = 0;
			leg.MechanismContractHash = string.Empty;
			leg.ExpectedMechanismLegIds.Clear();
		}
		object[] legacyUnfrozenReadArguments = { legacyUnfrozenPending, roundTripRequest, null, null, null };
		Check((bool)InvokeStatic(
				behaviorType,
				"TryReadPendingPlayerPolicyCanonicalEffects",
				legacyUnfrozenReadArguments,
				5),
			"A wholly unfrozen pre-fix pending linked group must be frozen internally and replayed instead of being discarded: "
			+ legacyUnfrozenReadArguments[4]);

		List<PolicyEffectInstanceSaveData> partiallyTamperedPending = JsonConvert.DeserializeObject<List<PolicyEffectInstanceSaveData>>(
			JsonConvert.SerializeObject(linkedPendingEffects));
		partiallyTamperedPending[0].MechanismContractHash = "tampered";
		object[] partiallyTamperedReadArguments = { partiallyTamperedPending, roundTripRequest, null, null, null };
		Check(!(bool)InvokeStatic(
				behaviorType,
				"TryReadPendingPlayerPolicyCanonicalEffects",
				partiallyTamperedReadArguments,
				5),
			"Partially present or tampered linked contract metadata must still fail closed.");
	}

	private static void CheckPolicyTargetSemanticRoute(
		Type routerType,
		Type resolverType,
		Type planType,
		Type branchType,
		object semanticContext,
		object resolutionContext,
		string query,
		string expectedRelation,
		string expectedEntityType,
		string expectedCardinality,
		string expectedMetric,
		bool expectedBorderOnly,
		IReadOnlyCollection<string> expectedSettlementIds)
	{
		object[] routeArguments = { query, semanticContext, null, null };
		Check((bool)InvokeStatic(routerType, "TryRoute", routeArguments, 4),
			"Existing embedding ONNX route failed for '" + query + "': " + routeArguments[3]);
		object[] candidates = Items(routeArguments[2]).ToArray();
		Check(candidates.Length == 1, "Existing embedding ONNX must produce one deterministic plan for '" + query + "'.");
		object plan = Property(candidates[0].GetType(), candidates[0], "Plan");
		object branch = Items(Property(planType, plan, "Branches")).Single();
		string actualShape = "relation=" + Property(branchType, branch, "Relation")
			+ " type=" + Property(branchType, branch, "EntityType")
			+ " cardinality=" + Property(branchType, branch, "Cardinality")
			+ " metric=" + Property(branchType, branch, "Metric")
			+ " border=" + Property(branchType, branch, "BorderOnly");
		Check(string.Equals(Property(branchType, branch, "Relation").ToString(), expectedRelation, StringComparison.Ordinal)
			&& string.Equals(Property(branchType, branch, "EntityType").ToString(), expectedEntityType, StringComparison.Ordinal)
			&& string.Equals(Property(branchType, branch, "Cardinality").ToString(), expectedCardinality, StringComparison.Ordinal)
			&& string.Equals(Property(branchType, branch, "Metric").ToString(), expectedMetric, StringComparison.Ordinal)
			&& (bool)Property(branchType, branch, "BorderOnly") == expectedBorderOnly,
			"Unexpected TargetPlan shape for '" + query + "': " + actualShape);
		object[] resolveArguments = { plan, resolutionContext, null, null };
		Check((bool)InvokeStatic(resolverType, "TryResolve", resolveArguments, 4),
			"TargetPlan resolution failed for '" + query + "': " + resolveArguments[3]);
		string[] actualIds = ReadStringPropertyValues(resolveArguments[2], "PrimarySettlementIds");
		Check(actualIds.SequenceEqual(expectedSettlementIds.OrderBy(value => value, StringComparer.Ordinal), StringComparer.Ordinal),
			"Unexpected resolved settlements for '" + query + "': " + string.Join(",", actualIds));
		Console.WriteLine("ONNX_TARGET_SEMANTIC query=" + query
			+ " shape=" + actualShape.Replace(' ', '/')
			+ " settlements=" + string.Join(",", actualIds));
	}

	private static object BuildPlanEntity(
		Type entityType,
		string id,
		string ownerKingdomId,
		string ownerClanId,
		bool isCity,
		bool isCastle,
		float x,
		float y,
		float prosperity,
		bool isBorder = false)
	{
		object entity = Activator.CreateInstance(entityType, nonPublic: true);
		SetProperty(entityType, entity, "DocumentId", "settlement:" + id);
		SetProperty(entityType, entity, "Kind", "settlement");
		SetProperty(entityType, entity, "EntityId", id);
		SetProperty(entityType, entity, "OwnerKingdomId", ownerKingdomId);
		SetProperty(entityType, entity, "OwnerClanId", ownerClanId);
		SetProperty(entityType, entity, "DisplayName", id);
		SetProperty(entityType, entity, "IsCity", isCity);
		SetProperty(entityType, entity, "IsCastle", isCastle);
		SetProperty(entityType, entity, "HasPosition", true);
		SetProperty(entityType, entity, "PositionX", x);
		SetProperty(entityType, entity, "PositionY", y);
		SetProperty(entityType, entity, "Prosperity", prosperity);
		SetProperty(entityType, entity, "IsBorder", isBorder);
		return entity;
	}

	private static object BuildPlanNamedEntity(Type entityType, string id, string kind, string ownerKingdomId)
	{
		object entity = Activator.CreateInstance(entityType, nonPublic: true);
		SetProperty(entityType, entity, "DocumentId", kind + ":" + id);
		SetProperty(entityType, entity, "Kind", kind);
		SetProperty(entityType, entity, "EntityId", id);
		SetProperty(entityType, entity, "OwnerKingdomId", ownerKingdomId);
		SetProperty(entityType, entity, "DisplayName", id);
		SetProperty(entityType, entity, "MentionAliases", new[] { id });
		return entity;
	}

	private static object BuildPlanClanEntity(Type entityType, string id, string ownerKingdomId, string displayName)
	{
		object entity = BuildPlanNamedEntity(entityType, id, "clan", ownerKingdomId);
		SetProperty(entityType, entity, "OwnerClanId", id);
		SetProperty(entityType, entity, "DisplayName", displayName);
		SetProperty(entityType, entity, "MentionAliases", new[] { id, displayName });
		return entity;
	}

	private static void TestLocalPolicyCanonicalPublicationGate()
	{
		Type behaviorType = SutType("AnimusForge.CustomPolicyBehavior");
		Type requestType = behaviorType.GetNestedType("PolicyDraftRequest", All);
		Type assessmentType = behaviorType.GetNestedType("PolicyMainAssessmentResult", All);
		Type effectType = behaviorType.GetNestedType("PolicyEffectDto", All);
		Type handleType = behaviorType.GetNestedType("PolicyTargetHandleSaveData", All);
		Check(requestType != null && assessmentType != null && effectType != null && handleType != null,
			"Local policy gate contract types must remain discoverable.");

		object request = Activator.CreateInstance(requestType, nonPublic: true);
		SetField(requestType, request, "RequestId", "local-canonical-gate");
		SetField(requestType, request, "ScopeKind", "local");
		IList handles = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(handleType));
		handles.Add(BuildLocalPolicyGateHandle(handleType, "S", "source"));
		handles.Add(BuildLocalPolicyGateHandle(handleType, "K0", "kingdom"));
		SetField(requestType, request, "TargetHandles", handles);
		object lifecycleAnchor = Activator.CreateInstance(effectType, nonPublic: true);
		SetProperty(effectType, lifecycleAnchor, "TargetHandle", "S");
		SetProperty(effectType, lifecycleAnchor, "DurationDays", 12);
		object lifecycleAnchorAssessment = BuildLocalPolicyGateAssessment(assessmentType, effectType, lifecycleAnchor);
		object[] lifecycleAnchorArguments = { request, lifecycleAnchorAssessment, null };
		Check((bool)InvokeStatic(behaviorType, "TryValidateLocalPolicyAssessment", lifecycleAnchorArguments, 3),
			"A zero-value S lifecycle anchor must remain legal: " + lifecycleAnchorArguments[2]);

		object sameCanonicalAssessment = BuildLocalPolicyGateAssessment(
			assessmentType,
			effectType,
			BuildLocalPolicyGateEffect(effectType, "module-a", "S", "publication-settlement"),
			BuildLocalPolicyGateEffect(effectType, "module-b", "S", "publication-settlement"));
		object[] sameCanonicalArguments = { request, sameCanonicalAssessment, null };
		Check((bool)InvokeStatic(behaviorType, "TryValidateLocalPolicyAssessment", sameCanonicalArguments, 3),
			"Different modules must be legal when they share the same canonical S publication target: "
			+ sameCanonicalArguments[2]);

		object moduleProjectedAssessment = BuildLocalPolicyGateAssessment(
			assessmentType,
			effectType,
			BuildLocalPolicyGateEffect(effectType, "module-settlement", "S", "publication-settlement", "settlement"),
			BuildLocalPolicyGateEffect(effectType, "module-town", "S", "publication-settlement", "town"),
			BuildLocalPolicyGateEffect(effectType, "module-village", "S", "publication-settlement", "village"));
		object[] moduleProjectedArguments = { request, moduleProjectedAssessment, null };
		Check((bool)InvokeStatic(behaviorType, "TryValidateLocalPolicyAssessment", moduleProjectedArguments, 3),
			"Module-specific town/village projections of the same S parent must share one publication identity: "
			+ moduleProjectedArguments[2]);

		object mismatchedAssessment = BuildLocalPolicyGateAssessment(
			assessmentType,
			effectType,
			BuildLocalPolicyGateEffect(effectType, "module-a", "S", "publication-settlement"),
			BuildLocalPolicyGateEffect(effectType, "module-b", "S", "different-settlement"));
		object[] mismatchedArguments = { request, mismatchedAssessment, null };
		Check(!(bool)InvokeStatic(behaviorType, "TryValidateLocalPolicyAssessment", mismatchedArguments, 3)
			&& !string.IsNullOrWhiteSpace(mismatchedArguments[2] as string),
			"S module effects with different canonical publication targets must fail closed.");

		object outsideScopeAssessment = BuildLocalPolicyGateAssessment(
			assessmentType,
			effectType,
			BuildLocalPolicyGateEffect(effectType, "module-a", "S", "publication-settlement"),
			BuildLocalPolicyGateEffect(effectType, "module-b", "S", "publication-settlement"),
			BuildLocalPolicyGateEffect(effectType, "module-c", "K0", "outside-settlement"));
		object[] outsideScopeArguments = { request, outsideScopeAssessment, null };
		Check(!(bool)InvokeStatic(behaviorType, "TryValidateLocalPolicyAssessment", outsideScopeArguments, 3)
			&& !string.IsNullOrWhiteSpace(outsideScopeArguments[2] as string),
			"Canonical S validation must not admit a target handle outside local policy scope.");
	}

	private static void TestLocalPolicyPromptAndEmptyApplicationContracts()
	{
		Type behaviorType = SutType("AnimusForge.CustomPolicyBehavior");
		Type requestType = behaviorType.GetNestedType("PolicyDraftRequest", All);
		Type promptContextType = behaviorType.GetNestedType("PolicyPromptContextBundle", All);
		Type handleType = behaviorType.GetNestedType("PolicyTargetHandleSaveData", All);
		Type directoryType = SutType("AnimusForge.PolicyTargets.PolicyTargetHandleDirectory");
		Check(requestType != null && promptContextType != null && handleType != null && directoryType != null,
			"Local policy prompt contract types must remain discoverable.");

		object request = Activator.CreateInstance(requestType, nonPublic: true);
		SetField(requestType, request, "RequestId", "local-selector-prompt");
		SetField(requestType, request, "ScopeKind", "local");
		SetField(requestType, request, "PolicyName", "selector prompt contract");
		SetField(requestType, request, "PolicyContent", "apply the recalled complete collection selector");
		SetField(requestType, request, "DateText", "contract-date");
		SetField(requestType, request, "ManualDurationDays", 12);
		object promptContext = Activator.CreateInstance(promptContextType, nonPublic: true);
		SetField(promptContextType, promptContext, "PolicyRuleContext", "contract-policy-rule");
		SetField(requestType, request, "PromptContext", promptContext);

		IList handles = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(handleType));
		object source = BuildLocalPolicyGateHandle(handleType, "S", "source");
		SetProperty(handleType, source, "DisplayName", "publication source");
		handles.Add(source);
		object selector = BuildLocalPolicyGateHandle(handleType, "X0", "selector");
		SetProperty(handleType, selector, "SelectorId", "currentKingdomPrimaryFiefsExceptPlayerClan");
		SetProperty(handleType, selector, "DisplayName", "all other primary fiefs");
		SetProperty(handleType, selector, "CurrentSettlementCount", 7);
		SetProperty(handleType, selector, "IsSemanticTarget", true);
		SetProperty(handleType, selector, "SemanticEvidence", "selector:contract mode=embedding score=1.000");
		handles.Add(selector);
		SetField(requestType, request, "TargetHandles", handles);
		SetField(requestType, request, "EffectTargetDirectory", TokenToObject(JObject.Parse(
			"{\"structureVersion\":3,\"targets\":{"
			+ "\"S\":{\"kind\":\"source\",\"description\":\"publication source\"},"
			+ "\"X0\":{\"kind\":\"selector\","
			+ "\"description\":\"all other primary fiefs；当前7处城镇/城堡；descriptor=从当前王国全部城市和城堡中明确排除玩家家族\","
			+ "\"selectorId\":\"currentKingdomPrimaryFiefsExceptPlayerClan\",\"currentSettlementCount\":7}},"
			+ "\"capabilities\":{\"foodPerDay\":{\"defaultTargetHandle\":\"S\",\"allowedSubsetTargetHandles\":[\"X0\"],\"allowedTargetHandles\":[\"S\",\"X0\"]}}}"), directoryType));

		IEnumerable messages = (IEnumerable)InvokeStatic(
			behaviorType,
			"BuildMainMessages",
			new object[] { request, string.Empty },
			2);
		List<object> messageList = messages.Cast<object>().ToList();
		string prompt = string.Join("\n", messageList
			.Select(message => (string)Property(message.GetType(), message, "content")));
		string stableSystemPrompt = messageList
			.Where(message => string.Equals((string)Property(message.GetType(), message, "role"), "system", StringComparison.Ordinal))
			.Select(message => (string)Property(message.GetType(), message, "content"))
			.FirstOrDefault() ?? string.Empty;
		const string selectorRuleNeedle = "X* 仅用于旧请求兼容；只能在目录实际出现且语义完全一致时使用。";
		Check(prompt.Contains("numericIntent")
			&& prompt.Contains("金额")
			&& prompt.Contains("每日/一次性")
			&& !prompt.Contains("effectIntentVersion")
			&& !prompt.Contains("effectIntents")
			&& prompt.IndexOf("payload", StringComparison.OrdinalIgnoreCase) < 0
			&& prompt.IndexOf("targetHandles", StringComparison.OrdinalIgnoreCase) < 0,
			"The main stage must emit a generic assessment and natural-language numeric intent without execution authority.");
		Check(stableSystemPrompt.Contains("通用政策评议阶段")
			&& stableSystemPrompt.Contains("历史政策只能帮助判断重复、冲突、延续")
			&& stableSystemPrompt.Contains("绝不能授权新目标、复制旧数值、扩大范围")
			&& stableSystemPrompt.Contains("不决定后续可执行能力、具体目标或最终执行值"),
			"The shared player main contract must keep history read-only and defer all executable decisions to stage two.");
		Check(!prompt.Contains("【本次可引用的合法目标句柄】")
			&& !prompt.Contains("【目标句柄选择规则】")
			&& !prompt.Contains("descriptor=")
			&& !prompt.Contains("X0="),
			"The main stage must not receive the target catalog or selector authority.");
		Check(!prompt.Contains("all other primary fiefs")
			&& !prompt.Contains("当前7处城镇/城堡")
			&& !prompt.Contains("X0|selector"),
			"The main stage must not receive target handles, target counts, or selector-derived scope authority.");
		Check(prompt.Contains("只评价冻结发布地与原文明示对象可能受到的直接影响；不得扩大范围"),
			"Local stage-one assessment must stay within the frozen publication scope without resolving targets.");

		string emptyConcreteTargetSummary = (string)InvokeStatic(
			behaviorType,
			"BuildLocalPolicyMentionSummary",
			new object[] { null },
			1);
		Check(emptyConcreteTargetSummary.Contains("合法具体实体目标：无")
			&& emptyConcreteTargetSummary.Contains("集合 TargetPlan/legacy selector")
			&& !emptyConcreteTargetSummary.Contains("本国检索目标：无"),
			"An empty concrete-target route must not contradict a subsequently recalled selector.");

		Type assessmentType = behaviorType.GetNestedType("PolicyMainAssessmentResult", All);
		Check(assessmentType != null, "Policy main assessment type must remain discoverable.");
		object assessment = Activator.CreateInstance(assessmentType, nonPublic: true);
		SetProperty(assessmentType, assessment, "ImpactSummary", "contract impact");
		SetProperty(assessmentType, assessment, "NumericIntent", "S contract intent");
		JArray semanticIntents = new JArray
		{
			new JObject
			{
				["omittedSide"] = "none",
				["legs"] = new JArray
				{
					new JObject
					{
						["role"] = "subject",
						["targetDescription"] = "the publication settlement",
						["effectDescription"] = "prosperity rises each day",
						["strength"] = "moderate",
						["reason"] = "the local reform improves commerce"
					}
				}
			}
		};
		Check(TryNormalizeSemanticPlanForContract(semanticIntents, out object semanticPlan, out string semanticError),
			"The local policy test requires one frozen semantic leg: " + semanticError);
		SetField(requestType, request, "SemanticEffectPlan", semanticPlan);
		IEnumerable postprocessMessages = (IEnumerable)InvokeStatic(
			behaviorType,
			"BuildEffectPostprocessMessages",
			new[] { request, assessment },
			2);
		string postprocessPrompt = string.Join("\n", postprocessMessages.Cast<object>()
			.Select(message => (string)Property(message.GetType(), message, "content")));
		bool hasPlayerFoodModule = PolicyEffectModuleCatalog.TryGetCanonical("foodPerDay", out IPolicyEffectModule playerFoodModule);
		bool hasPlayerStabilityModule = PolicyEffectModuleCatalog.TryGetCanonical("kingdomStability", out IPolicyEffectModule playerStabilityModule);
		Check(hasPlayerFoodModule && hasPlayerStabilityModule,
			"Player prompt authorization test modules must remain registered.");
		SetField(requestType, request, "CandidateEffectModuleIds", new List<string> { playerFoodModule.Id });
		SetField(requestType, request, "SelectedEffectModuleIds", new List<string> { playerStabilityModule.Id });
		string unauthorizedPlayerMain = JsonConvert.SerializeObject(
			((IEnumerable)InvokeStatic(behaviorType, "BuildMainMessages", new object[] { request, string.Empty }, 2)).Cast<object>());
		string unauthorizedPlayerPost = JsonConvert.SerializeObject(
			((IEnumerable)InvokeStatic(behaviorType, "BuildEffectPostprocessMessages", new[] { request, assessment }, 2)).Cast<object>());
		Check(!unauthorizedPlayerMain.Contains(PolicyEffectPromptService.GetUnderstandingPrompt(playerStabilityModule))
			&& !unauthorizedPlayerPost.Contains(PolicyEffectPromptService.GetEvaluationPrompt(playerStabilityModule)),
			"Player main and postprocess prompts must reject a Detail module outside the frozen Candidate set.");
		SetField(requestType, request, "SelectedEffectModuleIds", new List<string> { playerFoodModule.Id });
		string authorizedPlayerMain = JsonConvert.SerializeObject(
			((IEnumerable)InvokeStatic(behaviorType, "BuildMainMessages", new object[] { request, string.Empty }, 2)).Cast<object>());
		string authorizedPlayerPost = JsonConvert.SerializeObject(
			((IEnumerable)InvokeStatic(behaviorType, "BuildEffectPostprocessMessages", new[] { request, assessment }, 2)).Cast<object>());
		Check(!authorizedPlayerMain.Contains(PolicyEffectPromptService.GetUnderstandingPrompt(playerFoodModule))
			&& authorizedPlayerPost.Contains(PolicyEffectPromptService.GetEvaluationPrompt(playerFoodModule)),
			"Only stage two may receive the actual injected module detail; stage one must stay module-neutral.");
		SetField(requestType, request, "CandidateEffectModuleIds", new List<string>());
		SetField(requestType, request, "SelectedEffectModuleIds", new List<string>());
		Check(postprocessPrompt.Split(new[] { selectorRuleNeedle }, StringSplitOptions.None).Length == 2
			&& postprocessPrompt.Contains("effectPlanVersion")
			&& postprocessPrompt.Contains("disposition")
			&& postprocessPrompt.Contains("narrativeOnly")
			&& postprocessPrompt.Contains("unsupported")
			&& !postprocessPrompt.Contains("冻结语义账本")
			&& !postprocessPrompt.Contains("intentLeg"),
			"The postprocess stage must directly judge the final EffectPlan after seeing the actual detail and legal target directory.");
		Check(postprocessPrompt.Contains("descriptor=从当前王国全部城市和城堡中明确排除玩家家族")
			&& !postprocessPrompt.Contains("descriptor=当前王国的其他地方"),
			"The compact postprocess target catalog must retain exact legacy selector semantics.");
		Check(postprocessPrompt.Contains("当前7处城镇/城堡")
			&& postprocessPrompt.Contains("相同单点值作用于更多目标会产生更大的总影响")
			&& !postprocessPrompt.Contains("CrossEncoder"),
			"The effect stage must see the C#-resolved target count without claiming a second ONNX model.");
		Check(!postprocessPrompt.Contains("effectMappingVersion")
			&& !postprocessPrompt.Contains("assignments")
			&& postprocessPrompt.Contains("mechanismId")
			&& postprocessPrompt.Contains("mechanismKind")
			&& postprocessPrompt.Contains("targetHandles")
			&& postprocessPrompt.Contains("linked 必须在同一 mechanismId 下包含至少两条真实可执行资源流转腿")
			&& !postprocessPrompt.Contains("Village 选择类型"),
			"The production postprocess prompt must expose only the direct final EffectPlan contract.");
		string validMappingJson = "{\"effectPlanVersion\":1,\"disposition\":\"executable\","
			+ "\"reason\":\"政策明确改善发布地繁荣。\",\"effects\":[{"
			+ "\"mechanismId\":\"M0\",\"mechanismKind\":\"independent\",\"role\":\"subject\","
			+ "\"moduleId\":\"prosperityPerDay\",\"targetHandles\":[\"S\"],"
			+ "\"payload\":{\"value\":2},\"reason\":\"发布地商业改善。\"}]}";
		object[] validMappingParse = { validMappingJson, request, 12, null, null, null, null };
		Check((bool)InvokeStatic(behaviorType, "TryParsePolicyPostprocessResult", validMappingParse, 7),
			"A direct executable EffectPlan v1 must parse without semantic-leg expansion: " + validMappingParse[6]);
		object[] oldEffectPlanParse =
		{
			"{\"effectMappingVersion\":1,\"assignments\":[]}",
			request, 12, null, null, null, null
		};
		Check(!(bool)InvokeStatic(behaviorType, "TryParsePolicyPostprocessResult", oldEffectPlanParse, 7),
			"The player second stage must reject the old semantic-leg mapping shape.");
		object[] narrativeParse =
		{
			"{\"effectPlanVersion\":1,\"disposition\":\"narrativeOnly\",\"reason\":\"仅为叙事后果。\",\"effects\":[]}",
			request, 12, null, null, null, null
		};
		Check((bool)InvokeStatic(behaviorType, "TryParsePolicyPostprocessResult", narrativeParse, 7),
			"narrativeOnly with an empty effects array must be a valid direct player result: " + narrativeParse[6]);

		Type applicationType = behaviorType.GetNestedType("PolicyApplicationResult", All);
		Type appliedEffectType = behaviorType.GetNestedType("AppliedKingdomEffect", All);
		Check(applicationType != null && appliedEffectType != null,
			"Local policy application contract types must remain discoverable.");
		object application = Activator.CreateInstance(applicationType, nonPublic: true);
		IList appliedEffects = (IList)applicationType.GetField("KingdomEffects", All).GetValue(application);
		object lifecycleShell = Activator.CreateInstance(appliedEffectType, nonPublic: true);
		SetField(appliedEffectType, lifecycleShell, "TargetHandle", "S");
		SetField(appliedEffectType, lifecycleShell, "DurationDays", 12);
		appliedEffects.Add(lifecycleShell);
		Check(!(bool)InvokeStatic(behaviorType, "HasExecutablePolicyModuleInstances", new[] { application }, 1),
			"A lifecycle-only S shell must be diagnosed before bundle activation.");
		IList moduleEffects = (IList)appliedEffectType.GetField("ModuleEffects", All).GetValue(lifecycleShell);
		moduleEffects.Add(new PolicyEffectInstanceSaveData());
		Check((bool)InvokeStatic(behaviorType, "HasExecutablePolicyModuleInstances", new[] { application }, 1),
			"A local policy application with a real module instance must remain executable.");
	}

	private static object BuildLocalPolicyGateHandle(Type handleType, string key, string kind)
	{
		object handle = Activator.CreateInstance(handleType, nonPublic: true);
		SetProperty(handleType, handle, "Key", key);
		SetProperty(handleType, handle, "Kind", kind);
		return handle;
	}

	private static object BuildLocalPolicyGateAssessment(Type assessmentType, Type effectType, params object[] effects)
	{
		object assessment = Activator.CreateInstance(assessmentType, nonPublic: true);
		IList effectList = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(effectType));
		foreach (object effect in effects)
		{
			effectList.Add(effect);
		}
		SetProperty(assessmentType, assessment, "Effects", effectList);
		SetProperty(assessmentType, assessment, "UsesSparseEffectIr", true);
		return assessment;
	}

	private static object BuildLocalPolicyGateEffect(
		Type effectType,
		string moduleId,
		string targetHandle,
		string settlementId,
		string projection = "settlement")
	{
		object effect = Activator.CreateInstance(effectType, nonPublic: true);
		SetProperty(effectType, effect, "ModuleId", moduleId);
		SetProperty(effectType, effect, "TargetHandle", targetHandle);
		SetProperty(effectType, effect, "DurationDays", 12);
		PolicyEffectCanonicalTargetSet targetSet = new PolicyEffectCanonicalTargetSet
		{
			SelectorHandles = new List<string> { targetHandle },
			ParentSettlementIds = new List<string> { settlementId }
		};
		if (string.Equals(projection, "town", StringComparison.OrdinalIgnoreCase))
		{
			targetSet.TownIds.Add(settlementId);
		}
		else if (string.Equals(projection, "village", StringComparison.OrdinalIgnoreCase))
		{
			targetSet.VillageIds.Add("bound-village-for-" + settlementId);
		}
		else
		{
			targetSet.SettlementIds.Add(settlementId);
		}
		SetProperty(effectType, effect, "PreparedModuleEffect", new PolicyEffectPreparedInstance
		{
			Instance = new PolicyEffectInstance
			{
				ModuleId = moduleId,
				TargetSet = targetSet
			}
		});
		return effect;
	}

	private static object BuildSelectorEntity(
		Type entityType,
		string id,
		string ownerKingdomId,
		string ownerClanId,
		bool isPrimaryFief,
		params string[] boundVillageIds)
	{
		object entity = Activator.CreateInstance(entityType, nonPublic: true);
		SetProperty(entityType, entity, "EntityId", id);
		SetProperty(entityType, entity, "OwnerKingdomId", ownerKingdomId);
		SetProperty(entityType, entity, "OwnerClanId", ownerClanId);
		SetProperty(entityType, entity, "IsPrimaryFief", isPrimaryFief);
		SetProperty(entityType, entity, "BoundVillageIds", boundVillageIds ?? Array.Empty<string>());
		return entity;
	}

	private static void TestSharedCompilerWireLimits()
	{
		PolicyEffectCompilerRequest request = BuildCompilerRequest(
			"compiler-limits",
			PolicyEffectScopes.Local,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: true,
			detailedIncludesDummy: true);
		List<PolicyEffectWireEffect> twelve = Enumerable.Range(0, 12)
			.Select(index => BuildStructuredCompilerWire("S:limit-" + index.ToString(CultureInfo.InvariantCulture),
				"small-" + index.ToString(CultureInfo.InvariantCulture), 0.5f, 0.5f))
			.ToList();
		Check(TryCompileForContract(twelve, request, "limit-12", out PolicyEffectCompilerResult twelveResult, out string twelveError),
			"Exactly twelve compiler instances must be accepted: " + twelveError);
		Check(twelveResult?.Effects?.Count == 12, "Exactly twelve compiled effects must be returned.");

		List<PolicyEffectWireEffect> thirteen = Enumerable.Range(0, 13)
			.Select(index => BuildStructuredCompilerWire("S:limit-" + index.ToString(CultureInfo.InvariantCulture),
				"small-" + index.ToString(CultureInfo.InvariantCulture), 0.5f, 0.5f))
			.ToList();
		Check(!TryCompileForContract(thirteen, request, "limit-13", out PolicyEffectCompilerResult thirteenResult, out _),
			"Thirteen compiler instances must fail MaxInstances.");
		Check(HasNoCompiledEffects(thirteenResult), "MaxInstances failure must not return a partial result.");

		PolicyEffectWireEffect overFourKiB = BuildStructuredCompilerWire("S:oversized", new string('x', 5 * 1024), 0.5f, 0.5f);
		Check(!TryCompileForContract(new[] { overFourKiB }, request, "limit-4k", out PolicyEffectCompilerResult fourKiBResult, out _),
			"A compiler wire payload over 4KiB must fail closed.");
		Check(HasNoCompiledEffects(fourKiBResult), "Per-payload size failure must not return a partial result.");

		List<PolicyEffectWireEffect> overTotal = Enumerable.Range(0, 12)
			.Select(index => BuildStructuredCompilerWire("S:total-" + index.ToString(CultureInfo.InvariantCulture),
				new string((char)('a' + (index % 20)), 2800), 0.5f, 0.5f))
			.ToList();
		Check(!TryCompileForContract(overTotal, request, "limit-total", out PolicyEffectCompilerResult totalResult, out _),
			"Aggregate compiler payloads over 32KiB must fail closed.");
		Check(HasNoCompiledEffects(totalResult), "Aggregate payload size failure must not return a partial result.");

		PolicyEffectWireEffect typeMetadata = BuildStructuredCompilerWire("S:type-metadata", "typed", 0.5f, 0.5f);
		((JObject)typeMetadata.Payload)["$type"] = "System.IO.FileInfo";
		Check(!TryCompileForContract(new[] { typeMetadata }, request, "limit-type", out PolicyEffectCompilerResult typeResult, out _),
			"Compiler must reject recursive CLR $type metadata.");
		Check(HasNoCompiledEffects(typeResult), "$type rejection must not return a partial result.");
	}

	private static bool HasNoCompiledEffects(PolicyEffectCompilerResult result)
	{
		return result?.Effects == null || result.Effects.Count == 0;
	}

	private static void TestSharedCompilerNpcNeutralParity()
	{
		PolicyEffectWireEffect wire = BuildStructuredCompilerWire("S:npc", "neutral-parity", 0.35f, 0.65f);
		PolicyEffectFundingContext neutralFunding = new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f };
		PolicyEffectCompilerRequest playerRequest = BuildCompilerRequest(
			"player-neutral-policy", PolicyEffectScopes.Kingdom, neutralFunding,
			candidateIncludesDummy: true, detailedIncludesDummy: true);
		PolicyEffectCompilerRequest npcRequest = BuildCompilerRequest(
			"npc-neutral-policy", PolicyEffectScopes.Kingdom,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: true, detailedIncludesDummy: true);
		Check(TryCompileForContract(new[] { wire }, playerRequest, "player-neutral",
			out PolicyEffectCompilerResult playerResult, out string playerError),
			"Player neutral compile must succeed: " + playerError);
		Check(TryCompileForContract(new[] { wire }, npcRequest, "npc-neutral",
			out PolicyEffectCompilerResult npcResult, out string npcError),
			"NPC neutral compile through the same compiler must succeed: " + npcError);
		PolicyEffectCompiledWireEffect player = playerResult.Effects.Single();
		PolicyEffectCompiledWireEffect npc = npcResult.Effects.Single();
		Check(JToken.DeepEquals(JToken.FromObject(player.NormalizedPayload), JToken.FromObject(npc.NormalizedPayload)),
			"Player and NPC neutral normalization must be equivalent.");
		Check(JToken.DeepEquals(JToken.FromObject(player.FundedPayload), JToken.FromObject(npc.FundedPayload)),
			"Player and NPC neutral funding must be equivalent.");
		Check(JToken.DeepEquals(player.SaveData.Payload, npc.SaveData.Payload),
			"Player and NPC must persist the same neutral module payload.");
		Check(string.Equals(BuildCanonicalTargetSignatureForTest(player.TargetSet), BuildCanonicalTargetSignatureForTest(npc.TargetSet), StringComparison.Ordinal),
			"Player and NPC must resolve the same canonical target set.");
		Check(!player.OutsideDetailedRecall && !npc.OutsideDetailedRecall,
			"Equivalent detailed player/NPC candidates must not be marked outsideDetailed.");
	}

	private static void TestPolicyEffectShellCoalescingAndProgressSync()
	{
		Type behavior = SutType("AnimusForge.CustomPolicyBehavior");
		Type saveDataType = SutType("AnimusForge.PolicyEffects.PolicyEffectInstanceSaveData");
		Type receiptType = SutType("AnimusForge.PolicyEffects.PolicyEffectExecutionReceipt");
		Type lifecycleStateType = SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState");
		Type executionStatusType = SutType("AnimusForge.PolicyEffects.PolicyEffectExecutionStatus");
		int activeState = Convert.ToInt32(EnumValue(lifecycleStateType, "Active"), CultureInfo.InvariantCulture);
		int failedState = Convert.ToInt32(EnumValue(lifecycleStateType, "Failed"), CultureInfo.InvariantCulture);
		int appliedStatus = Convert.ToInt32(EnumValue(executionStatusType, "Applied"), CultureInfo.InvariantCulture);
		int alreadyAppliedStatus = Convert.ToInt32(EnumValue(executionStatusType, "AlreadyApplied"), CultureInfo.InvariantCulture);

		JObject shellTargetA = new JObject
		{
			["structureVersion"] = 1,
			["selectorHandles"] = new JArray("S:s1"),
			["selectorIds"] = new JArray("selector.a"),
			["settlementIds"] = new JArray("s1"),
			["townIds"] = new JArray("t1"),
			["villageIds"] = new JArray("v1"),
			["parentSettlementIds"] = new JArray("p1"),
			["followCurrentRulingClan"] = false
		};
		JObject shellTargetB = new JObject
		{
			["structureVersion"] = 2,
			["selectorHandles"] = new JArray("K:k1"),
			["selectorIds"] = new JArray("selector.b"),
			["clanIds"] = new JArray("c1"),
			["kingdomIds"] = new JArray("k1"),
			["followCurrentRulingClan"] = true
		};
		JObject shellAJson = BuildPolicyEffectShellFixture(
			shellTargetA, "shell", 1, activeState, 1, 1, appliedStatus, "shell-receipt");
		JObject shellBJson = BuildPolicyEffectShellFixture(
			shellTargetB, "shell", 1, activeState, 1, 1, appliedStatus, "shell-receipt");
		object shellA = TokenToObject(shellAJson, saveDataType);
		object shellB = TokenToObject(shellBJson, saveDataType);
		Array shells = Array.CreateInstance(saveDataType, 2);
		shells.SetValue(shellA, 0);
		shells.SetValue(shellB, 1);

		object[] coalesce = { shells, null, null };
		Check((bool)InvokeStatic(behavior, "TryCoalescePolicyEffectShellInstances", coalesce, 3),
			"Compatible target shells must coalesce: " + coalesce[2]);
		object[] coalesced = Items(coalesce[1]).ToArray();
		Check(coalesced.Length == 1, "Two shells with the same stable InstanceId must become one logical active instance.");
		object aggregate = coalesced[0];
		Check(string.Equals((string)Property(saveDataType, aggregate, "InstanceId"), "shell-shared-1", StringComparison.Ordinal),
			"Coalescing must retain the stable InstanceId.");
		object aggregateTargetSet = Property(saveDataType, aggregate, "TargetSet");
		Check(ReadStringPropertyValues(aggregateTargetSet, "SelectorHandles").SequenceEqual(new[] { "K:k1", "S:s1" }, StringComparer.Ordinal)
			&& ReadStringPropertyValues(aggregateTargetSet, "SelectorIds").SequenceEqual(new[] { "selector.a", "selector.b" }, StringComparer.Ordinal)
			&& ReadStringPropertyValues(aggregateTargetSet, "SettlementIds").SequenceEqual(new[] { "s1" }, StringComparer.Ordinal)
			&& ReadStringPropertyValues(aggregateTargetSet, "TownIds").SequenceEqual(new[] { "t1" }, StringComparer.Ordinal)
			&& ReadStringPropertyValues(aggregateTargetSet, "VillageIds").SequenceEqual(new[] { "v1" }, StringComparer.Ordinal)
			&& ReadStringPropertyValues(aggregateTargetSet, "ClanIds").SequenceEqual(new[] { "c1" }, StringComparer.Ordinal)
			&& ReadStringPropertyValues(aggregateTargetSet, "KingdomIds").SequenceEqual(new[] { "k1" }, StringComparer.Ordinal)
			&& ReadStringPropertyValues(aggregateTargetSet, "ParentSettlementIds").SequenceEqual(new[] { "p1" }, StringComparer.Ordinal)
			&& (bool)Property(aggregateTargetSet.GetType(), aggregateTargetSet, "FollowCurrentRulingClan"),
			"Coalescing must union S/T/V/C/K/P/R target fields without loss.");

		JObject incompatibleJson = BuildPolicyEffectShellFixture(
			shellTargetB, "incompatible", 1, activeState, 1, 1, appliedStatus, "shell-receipt");
		Array incompatibleShells = Array.CreateInstance(saveDataType, 2);
		incompatibleShells.SetValue(shellA, 0);
		incompatibleShells.SetValue(TokenToObject(incompatibleJson, saveDataType), 1);
		object[] incompatibleCoalesce = { incompatibleShells, null, null };
		Check(!(bool)InvokeStatic(behavior, "TryCoalescePolicyEffectShellInstances", incompatibleCoalesce, 3)
			&& !string.IsNullOrWhiteSpace(incompatibleCoalesce[2] as string),
			"Shells with incompatible payloads must fail closed with an error.");

		object actorShellA = TokenToObject(shellAJson, saveDataType);
		object actorShellB = TokenToObject(shellBJson, saveDataType);
		SetProperty(saveDataType, actorShellA, "ActorHeroId", "actor-alpha");
		SetProperty(saveDataType, actorShellB, "ActorHeroId", "actor-beta");
		Array actorConflictShells = Array.CreateInstance(saveDataType, 2);
		actorConflictShells.SetValue(actorShellA, 0);
		actorConflictShells.SetValue(actorShellB, 1);
		object[] actorConflictCoalesce = { actorConflictShells, null, null };
		Check(!(bool)InvokeStatic(behavior, "TryCoalescePolicyEffectShellInstances", actorConflictCoalesce, 3)
			&& !string.IsNullOrWhiteSpace(actorConflictCoalesce[2] as string),
			"Target shells sharing an InstanceId must reject conflicting frozen ActorHeroId values.");
		SetProperty(saveDataType, actorShellA, "ActorHeroId", string.Empty);
		SetProperty(saveDataType, actorShellB, "ActorHeroId", "actor-beta");
		object[] actorAdoptionCoalesce = { actorConflictShells, null, null };
		Check((bool)InvokeStatic(behavior, "TryCoalescePolicyEffectShellInstances", actorAdoptionCoalesce, 3)
			&& string.Equals(
				(string)Property(saveDataType, Items(actorAdoptionCoalesce[1]).Single(), "ActorHeroId"),
				"actor-beta",
				StringComparison.Ordinal),
			"A legacy actor-empty shell may adopt the single non-empty frozen actor during coalescing.");

		JObject unionTarget = JObject.FromObject(aggregateTargetSet);
		JObject activeJson = BuildPolicyEffectShellFixture(
			unionTarget, "active", 3, failedState, 3, 99, alreadyAppliedStatus, "active-receipt");
		object activeInstance = TokenToObject(activeJson, saveDataType);
		object activeReceipt = TokenToObject((JObject)activeJson["executionReceipt"], receiptType);
		Array activeInstances = Array.CreateInstance(saveDataType, 1);
		activeInstances.SetValue(activeInstance, 0);
		Array activeReceipts = Array.CreateInstance(receiptType, 1);
		activeReceipts.SetValue(activeReceipt, 0);
		object[] synchronize = { shells, activeInstances, activeReceipts, null, null };
		InvokeStatic(behavior, "SynchronizeOwnedPolicyEffectProgress", synchronize, 5);
		object[] synchronizedInstances = Items(synchronize[3]).ToArray();
		Check(synchronizedInstances.Length == 2,
			"Progress synchronization must retain both owner target shells.");
		string shellSignatureA = BuildTargetSetSignature(Property(saveDataType, shellA, "TargetSet"));
		string shellSignatureB = BuildTargetSetSignature(Property(saveDataType, shellB, "TargetSet"));
		Check(string.Equals(BuildTargetSetSignature(Property(saveDataType, synchronizedInstances[0], "TargetSet")), shellSignatureA, StringComparison.Ordinal)
			&& string.Equals(BuildTargetSetSignature(Property(saveDataType, synchronizedInstances[1], "TargetSet")), shellSignatureB, StringComparison.Ordinal),
			"Progress synchronization must not overwrite shell target sets with the active union.");
		foreach (object synchronized in synchronizedInstances)
		{
			Check(string.Equals(Property(saveDataType, synchronized, "LifecycleState").ToString(), "Failed", StringComparison.Ordinal)
				&& Convert.ToInt32(Property(saveDataType, synchronized, "PayloadSchemaVersion"), CultureInfo.InvariantCulture) == 3
				&& Convert.ToInt32(Property(saveDataType, synchronized, "StateSchemaVersion"), CultureInfo.InvariantCulture) == 3,
				"Progress synchronization must copy lifecycle and schema versions from the active instance.");
			JObject synchronizedPayload = JObject.Parse(TokenText(Property(saveDataType, synchronized, "Payload")));
			JObject synchronizedRuntime = JObject.Parse(TokenText(Property(saveDataType, synchronized, "RuntimeState")));
			Check(string.Equals((string)synchronizedPayload["mode"], "active", StringComparison.Ordinal)
				&& (int?)synchronizedRuntime["progress"] == 99,
				"Progress synchronization must copy active payload and runtime state.");
			object synchronizedReceipt = Property(saveDataType, synchronized, "ExecutionReceipt");
			Check(synchronizedReceipt != null
				&& string.Equals((string)Property(receiptType, synchronizedReceipt, "Message"), "active-receipt", StringComparison.Ordinal)
				&& string.Equals(
					BuildTargetSetSignature(Property(receiptType, synchronizedReceipt, "TargetSet")),
					BuildTargetSetSignature(Property(saveDataType, synchronized, "TargetSet")),
					StringComparison.Ordinal),
				"Synchronized instance receipts must use active progress while retaining each shell target set.");
		}
		object[] synchronizedReceipts = Items(synchronize[4]).ToArray();
		Check(synchronizedReceipts.Length == 1
			&& string.Equals((string)Property(receiptType, synchronizedReceipts[0], "Message"), "active-receipt", StringComparison.Ordinal),
			"Active execution receipt progress must remain synchronized for the owned instance.");

		IPolicyEffectModule heroModule = RequirePolicyEffectModule("heroGoldPerDay");
		IPolicyEffectModule clanModule = RequirePolicyEffectModule("clanInfluencePerDay");
		IPolicyEffectModule settlementModule = RequirePolicyEffectModule("prosperityPerDay");
		IPolicyEffectModule kingdomModule = RequirePolicyEffectModule("kingdomStability");
		PolicyEffectCanonicalTargetSet heroOnlyTarget = new PolicyEffectCanonicalTargetSet
		{
			SelectorHandles = new List<string> { "H0" },
			SelectorIds = new List<string> { "hero:v1:specific:hero-a" },
			HeroIds = new List<string> { "hero-a" }
		};
		PolicyEffectCanonicalTargetSet clanOnlyTarget = new PolicyEffectCanonicalTargetSet
		{
			SelectorHandles = new List<string> { "H1" },
			SelectorIds = new List<string> { "hero:v1:specific:hero-b" },
			ClanIds = new List<string> { "clan-b" }
		};
		PolicyEffectCanonicalTargetSet settlementOnlyTarget = new PolicyEffectCanonicalTargetSet
		{
			SelectorHandles = new List<string> { "S0" },
			SettlementIds = new List<string> { "settlement-a" },
			TownIds = new List<string> { "settlement-a" }
		};
		PolicyEffectCanonicalTargetSet kingdomOnlyTarget = new PolicyEffectCanonicalTargetSet
		{
			SelectorHandles = new List<string> { "K0" },
			KingdomIds = new List<string> { "kingdom-a" }
		};
		PolicyTargetPlanSaveData targetPlan = BuildPolicyTwoStageSyntheticPlan(PolicyEffectTargetKind.Settlement);
		Check(PolicyTargetPlanResolver.TryNormalizeAndValidate(targetPlan, out PolicyTargetPlanSaveData normalizedPlan, out string planError),
			"Shared bundle target-plan fixture must normalize: " + planError);
		PolicyEffectCanonicalTargetSet planOnlyTarget = new PolicyEffectCanonicalTargetSet
		{
			SelectorHandles = new List<string> { "P0" },
			TargetPlans = new List<PolicyTargetPlanSaveData> { normalizedPlan }
		};
		Check(PolicyEffectBundleContract.HasTargetsForModule(heroModule, heroOnlyTarget)
			&& PolicyEffectBundleContract.HasTargetsForModule(clanModule, clanOnlyTarget)
			&& PolicyEffectBundleContract.HasTargetsForModule(settlementModule, settlementOnlyTarget)
			&& PolicyEffectBundleContract.HasTargetsForModule(kingdomModule, kingdomOnlyTarget)
			&& PolicyEffectBundleContract.HasTargetsForModule(settlementModule, planOnlyTarget),
			"Hero, projected-Clan, Settlement, Kingdom, and TargetPlan shapes must share one module-target contract without redundant KingdomIds.");

		PolicyEffectInstanceSaveData heroShellA = new PolicyEffectInstanceSaveData
		{
			MechanismContractVersion = 1,
			MechanismContractHash = "shared-bundle-contract",
			ExpectedMechanismLegIds = new List<string> { "subject" },
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "shared-bundle-mechanism",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "shared-hero-instance",
			PolicyId = "shared-policy",
			ActorHeroId = "ruler-a",
			ModuleId = "heroGoldPerDay",
			SourceModuleId = "heroGold",
			PayloadSchemaVersion = heroModule.Descriptor.PayloadSchemaVersion,
			Payload = new JObject { ["moduleId"] = "heroGoldPerDay", ["schemaVersion"] = heroModule.Descriptor.PayloadSchemaVersion, ["value"] = 10 },
			TargetSet = heroOnlyTarget,
			LifecycleState = PolicyEffectLifecycleState.Prepared,
			StateSchemaVersion = heroModule.Descriptor.RuntimeStateSchemaVersion,
			StartDay = 10f,
			EndDay = 20f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "shared contract"
		};
		PolicyEffectInstanceSaveData heroShellB = PolicyEffectBundleContract.CloneInstance(heroShellA);
		heroShellB.TargetSet = new PolicyEffectCanonicalTargetSet
		{
			SelectorHandles = new List<string> { "H2" },
			SelectorIds = new List<string> { "hero:v1:specific:hero-c" },
			HeroIds = new List<string> { "hero-c" }
		};
		Check(PolicyEffectBundleContract.TryCoalesceShellInstances(
			new[] { heroShellA, heroShellB },
			out List<PolicyEffectInstanceSaveData> sharedHeroBundle,
			out string sharedHeroError),
			"Shared bundle coalescing must accept Hero-only shells without KingdomIds: " + sharedHeroError);
		Check(sharedHeroBundle.Count == 1
			&& sharedHeroBundle[0].TargetSet.HeroIds.SequenceEqual(new[] { "hero-a", "hero-c" }, StringComparer.Ordinal)
			&& sharedHeroBundle[0].TargetSet.KingdomIds.Count == 0,
			"Shared bundle coalescing must preserve precise HeroIds and must not synthesize executable KingdomIds.");

		Type npcBehavior = SutType("AnimusForge.NpcRulerPolicyBehavior");
		object[] npcCoalesce = { new[] { heroShellA, heroShellB }, null, null };
		Check((bool)InvokeStatic(npcBehavior, "TryCoalesceNpcPolicyEffectShellInstances", npcCoalesce, 3)
			&& PolicyEffectBundleContract.AreSameTargetSets(
				sharedHeroBundle[0].TargetSet,
				((PolicyEffectInstanceSaveData)Items(npcCoalesce[1]).Single()).TargetSet),
			"NPC persistence must delegate shell coalescing to the same canonical bundle contract as the player chain.");
		PolicyEffectInstanceSaveData mechanismConflict = PolicyEffectBundleContract.CloneInstance(heroShellB);
		mechanismConflict.MechanismContractHash = "conflict";
		Check(!PolicyEffectBundleContract.TryCoalesceShellInstances(
			new[] { heroShellA, mechanismConflict },
			out _,
			out string mechanismConflictError)
			&& !string.IsNullOrWhiteSpace(mechanismConflictError),
			"Shared player/NPC shell coalescing must fail closed on mechanism-contract conflicts.");
	}

	private static PolicyEffectWireEffect BuildStructuredCompilerWire(
		string handle,
		string mode,
		float lowWeight,
		float highWeight)
	{
		return new PolicyEffectWireEffect
		{
			ModuleId = StructuredDummyEffectModule.ModuleId,
			TargetHandles = new List<string> { handle },
			Payload = new JObject
			{
				["mode"] = mode,
				["enabled"] = true,
				["bands"] = new JArray
				{
					new JObject { ["name"] = "low", ["weight"] = lowWeight },
					new JObject { ["name"] = "high", ["weight"] = highWeight }
				}
			},
			Reason = "shared compiler contract"
		};
	}

	private static PolicyEffectWireEffect BuildEffectPlanWire(
		string handle,
		string mode,
		string mechanismId,
		PolicyEffectMechanismKind mechanismKind,
		PolicyEffectMechanismRole mechanismRole,
		bool sourceOmitted = false,
		bool destinationOmitted = false)
	{
		PolicyEffectWireEffect wire = BuildStructuredCompilerWire(handle, mode, 0.4f, 0.6f);
		wire.EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion;
		wire.MechanismId = mechanismId;
		wire.MechanismKind = mechanismKind;
		wire.MechanismRole = mechanismRole;
		wire.SourceOmitted = sourceOmitted;
		wire.DestinationOmitted = destinationOmitted;
		return wire;
	}

	private static PolicyEffectCompilerRequest BuildCompilerRequest(
		string policyId,
		string scope,
		PolicyEffectFundingContext funding,
		bool candidateIncludesDummy,
		bool detailedIncludesDummy)
	{
		return new PolicyEffectCompilerRequest
		{
			Scope = scope,
			PolicyId = policyId,
			StartDay = 10f,
			EndDay = 20f,
			Funding = funding,
			CandidateModuleIds = candidateIncludesDummy
				? new List<string> { StructuredDummyEffectModule.ModuleId }
				: new List<string> { "prosperityPerDay" },
			DetailedModuleIds = detailedIncludesDummy
				? new List<string> { StructuredDummyEffectModule.ModuleId }
				: new List<string>(),
			MaxInstances = 12,
			MaxCompiledInstances = 24,
			MaxPayloadBytes = 4 * 1024,
			MaxTotalPayloadBytes = 32 * 1024,
			ModuleResolver = ResolveCompilerModule
		};
	}

	private static bool TryCompileForContract(
		IReadOnlyList<PolicyEffectWireEffect> effects,
		PolicyEffectCompilerRequest request,
		string instancePrefix,
		out PolicyEffectCompilerResult result,
		out string error)
	{
		PolicyEffectTargetResolver targetResolver = ResolveCompilerTarget;
		PolicyEffectInstanceIdFactory instanceIdFactory = (ordinal, moduleId, targetSet) =>
			instancePrefix + ":" + ordinal.ToString(CultureInfo.InvariantCulture) + ":" + moduleId;
		return PolicyEffectCompiler.TryCompile(
			effects,
			request,
			targetResolver,
			instanceIdFactory,
			out result,
			out error);
	}

	private static bool ResolveCompilerModule(string moduleId, out IPolicyEffectModule module)
	{
		if (string.Equals((moduleId ?? string.Empty).Trim(), StructuredDummyEffectModule.ModuleId, StringComparison.Ordinal))
		{
			module = CompilerDummyModule;
			return true;
		}
		if (string.Equals((moduleId ?? string.Empty).Trim(), CompilerSecondDummyModule.Id, StringComparison.Ordinal))
		{
			module = CompilerSecondDummyModule;
			return true;
		}
		return PolicyEffectModuleCatalog.TryGet((moduleId ?? string.Empty).Trim(), out module);
	}

	private static bool ResolveCompilerTarget(
		string handle,
		IPolicyEffectModule module,
		out PolicyEffectResolvedTarget resolvedTarget,
		out string error)
	{
		resolvedTarget = null;
		error = string.Empty;
		string normalized = (handle ?? string.Empty).Trim();
		if (string.Equals(normalized, "P0", StringComparison.OrdinalIgnoreCase))
		{
			PolicyTargetPlanSaveData sourcePlan = new PolicyTargetPlanSaveData
			{
				Branches = new List<PolicyTargetPlanBranchSaveData>
				{
					new PolicyTargetPlanBranchSaveData
					{
						Universe = PolicyTargetPlanUniverse.PrimaryFiefs,
						ScopeAnchor = PolicyTargetPlanScopeAnchor.TargetKingdom,
						EntityType = PolicyTargetPlanEntityType.Town,
						Relation = PolicyTargetPlanRelation.Domestic,
						Cardinality = PolicyTargetPlanCardinality.All
					}
				}
			};
			if (!PolicyTargetPlanResolver.TryNormalizeAndValidate(sourcePlan, out PolicyTargetPlanSaveData normalizedPlan, out error))
			{
				return false;
			}
			resolvedTarget = new PolicyEffectResolvedTarget
			{
				Handle = normalized,
				SelectorKind = PolicyEffectTargetKind.Settlement,
				CanonicalTargetSet = new PolicyEffectCanonicalTargetSet
				{
					SelectorHandles = new List<string> { normalized },
					TargetPlans = new List<PolicyTargetPlanSaveData> { normalizedPlan }
				}
			};
			return true;
		}
		if (string.Equals(normalized, "C:wrong", StringComparison.OrdinalIgnoreCase))
		{
			resolvedTarget = new PolicyEffectResolvedTarget
			{
				Handle = normalized,
				SelectorKind = PolicyEffectTargetKind.Clan,
				CanonicalTargetSet = new PolicyEffectCanonicalTargetSet
				{
					SelectorHandles = new List<string> { normalized },
					ClanIds = new List<string> { "clan-wrong" }
				}
			};
			return true;
		}
		if (normalized.StartsWith("C:", StringComparison.OrdinalIgnoreCase))
		{
			string clanId = normalized.Substring(2).Trim().ToLowerInvariant();
			if (clanId.Length == 0)
			{
				error = "empty clan selector handle";
				return false;
			}
			resolvedTarget = new PolicyEffectResolvedTarget
			{
				Handle = normalized,
				SelectorKind = PolicyEffectTargetKind.Clan,
				CanonicalTargetSet = new PolicyEffectCanonicalTargetSet
				{
					SelectorHandles = new List<string> { normalized },
					ClanIds = new List<string> { "clan-" + clanId }
				}
			};
			return true;
		}
		if (normalized.StartsWith("K:", StringComparison.OrdinalIgnoreCase))
		{
			string kingdomId = normalized.Substring(2).Trim().ToLowerInvariant();
			if (kingdomId.Length == 0)
			{
				error = "empty kingdom selector handle";
				return false;
			}
			resolvedTarget = new PolicyEffectResolvedTarget
			{
				Handle = normalized,
				SelectorKind = PolicyEffectTargetKind.Kingdom,
				CanonicalTargetSet = new PolicyEffectCanonicalTargetSet
				{
					SelectorHandles = new List<string> { normalized },
					KingdomIds = new List<string> { "kingdom-" + kingdomId }
				}
			};
			return true;
		}
		if (!normalized.StartsWith("S:", StringComparison.OrdinalIgnoreCase))
		{
			error = "unknown selector handle: " + normalized;
			return false;
		}
		string targetId = string.Equals(normalized, "S:alpha", StringComparison.OrdinalIgnoreCase)
			|| string.Equals(normalized, "S:alias-alpha", StringComparison.OrdinalIgnoreCase)
			? "settlement-alpha"
			: "settlement-" + normalized.Substring(2).Trim().ToLowerInvariant();
		resolvedTarget = new PolicyEffectResolvedTarget
		{
			Handle = normalized,
			SelectorKind = PolicyEffectTargetKind.Settlement,
			CanonicalTargetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { normalized },
				SettlementIds = new List<string> { targetId }
			}
		};
		return true;
	}

	private static string BuildCanonicalTargetSignatureForTest(PolicyEffectCanonicalTargetSet targetSet)
	{
		if (targetSet == null)
		{
			return string.Empty;
		}
		return string.Join("|", new[]
		{
			"TP=" + string.Join(",", PolicyTargetPlanResolver.NormalizePlans(targetSet.TargetPlans)
				.Select(plan => plan.NormalizedSignature)),
			"S=" + string.Join(",", (targetSet.SettlementIds ?? new List<string>()).OrderBy(value => value, StringComparer.Ordinal)),
			"T=" + string.Join(",", (targetSet.TownIds ?? new List<string>()).OrderBy(value => value, StringComparer.Ordinal)),
			"V=" + string.Join(",", (targetSet.VillageIds ?? new List<string>()).OrderBy(value => value, StringComparer.Ordinal)),
			"C=" + string.Join(",", (targetSet.ClanIds ?? new List<string>()).OrderBy(value => value, StringComparer.Ordinal)),
			"K=" + string.Join(",", (targetSet.KingdomIds ?? new List<string>()).OrderBy(value => value, StringComparer.Ordinal)),
			"H=" + string.Join(",", (targetSet.HeroIds ?? new List<string>()).OrderBy(value => value, StringComparer.Ordinal))
		});
	}

	private static JObject BuildPolicyEffectShellFixture(
		JObject targetSet,
		string payloadMode,
		int payloadSchemaVersion,
		int lifecycleState,
		int stateSchemaVersion,
		int progress,
		int executionStatus,
		string receiptMessage)
	{
		JObject payload = new JObject
		{
			["moduleId"] = "contract.shell",
			["schemaVersion"] = payloadSchemaVersion,
			["mode"] = payloadMode
		};
		return new JObject
		{
			["instanceId"] = "shell-shared-1",
			["policyId"] = "shell-policy",
			["moduleId"] = "contract.shell",
			["payloadSchemaVersion"] = payloadSchemaVersion,
			["payload"] = payload.DeepClone(),
			["targetSet"] = targetSet.DeepClone(),
			["lifecycleState"] = lifecycleState,
			["stateSchemaVersion"] = stateSchemaVersion,
			["runtimeState"] = new JObject { ["progress"] = progress },
			["executionReceipt"] = new JObject
			{
				["receiptId"] = "shell-receipt-1",
				["instanceId"] = "shell-shared-1",
				["policyId"] = "shell-policy",
				["moduleId"] = "contract.shell",
				["targetSet"] = targetSet.DeepClone(),
				["status"] = executionStatus,
				["requestedPayload"] = payload.DeepClone(),
				["appliedPayload"] = payload.DeepClone(),
				["campaignDay"] = 12,
				["message"] = receiptMessage
			},
			["startDay"] = 10,
			["endDay"] = 20,
			["sourceScope"] = "kingdom",
			["reason"] = "shell contract"
		};
	}

	private static string[] ReadStringPropertyValues(object instance, string propertyName)
	{
		return Items(Property(instance.GetType(), instance, propertyName))
			.Cast<string>()
			.OrderBy(value => value, StringComparer.Ordinal)
			.ToArray();
	}

	private static string BuildTargetSetSignature(object targetSet)
	{
		if (targetSet == null)
		{
			return string.Empty;
		}
		return string.Join("|", new[]
		{
			"H=" + string.Join(",", ReadStringPropertyValues(targetSet, "SelectorHandles")),
			"S=" + string.Join(",", ReadStringPropertyValues(targetSet, "SettlementIds")),
			"T=" + string.Join(",", ReadStringPropertyValues(targetSet, "TownIds")),
			"V=" + string.Join(",", ReadStringPropertyValues(targetSet, "VillageIds")),
			"C=" + string.Join(",", ReadStringPropertyValues(targetSet, "ClanIds")),
			"K=" + string.Join(",", ReadStringPropertyValues(targetSet, "KingdomIds")),
			"P=" + string.Join(",", ReadStringPropertyValues(targetSet, "ParentSettlementIds")),
			"R=" + ((bool)Property(targetSet.GetType(), targetSet, "FollowCurrentRulingClan") ? "1" : "0")
		});
	}

	private static void TestFundingStrategies()
	{
		PolicyEffectFundingContext funding = new PolicyEffectFundingContext
		{
			GoldScale = 0.25f,
			InfluenceScale = 0.5f
		};
		Check(Math.Abs(funding.ResolveScale(PolicyEffectFundingMode.InheritPolicy) - 0.25f) < 0.0001f,
			"InheritPolicy funding scale must use the lower paid fraction.");
		Check(Math.Abs(funding.ResolveScale(PolicyEffectFundingMode.Unscaled) - 1f) < 0.0001f,
			"Unscaled funding mode must resolve to one.");

		NumericFundingDummyModule none = new NumericFundingDummyModule(PolicyEffectFundingStrategy.None);
		NumericFundingDummyModule linear = new NumericFundingDummyModule(PolicyEffectFundingStrategy.Linear);
		NumericFundingDummyModule fullOnly = new NumericFundingDummyModule(PolicyEffectFundingStrategy.FullOnly);
		NumericFundingDummyModule customWithoutOverride = new NumericFundingDummyModule(PolicyEffectFundingStrategy.Custom);
		SetFundingStrategyAndAssert(none, funding, 8f, expectSuccess: true);
		SetFundingStrategyAndAssert(linear, funding, 2f, expectSuccess: true);
		SetFundingStrategyAndAssert(fullOnly, funding, 0f, expectSuccess: true);
		funding.GoldScale = 1f;
		funding.InfluenceScale = 1f;
		SetFundingStrategyAndAssert(fullOnly, funding, 8f, expectSuccess: true);
		SetFundingStrategyAndAssert(customWithoutOverride, funding, 0f, expectSuccess: false);

		StructuredDummyEffectModule customModule = new StructuredDummyEffectModule();
		Check(customModule.Descriptor.FundingStrategy == PolicyEffectFundingStrategy.Custom,
			"Structured dummy must declare Custom funding.");

		MethodInfo validation = typeof(PolicyEffectModuleCatalog).GetMethod("ValidateModuleSetForContractTests", All);
		Check(validation != null, "Catalog contract validation entry point is missing.");
		validation.Invoke(null, new object[] { new IPolicyEffectModule[] { none, linear, fullOnly, customModule } });
		Check(ContractValidationRejects(validation, new IPolicyEffectModule[] { customWithoutOverride }),
			"Catalog must reject numeric Custom funding without a module override.");

		MissingStructuredFundingContractDummyModule missingStructuredFunding = new MissingStructuredFundingContractDummyModule();
		JObject structuredRaw = JObject.Parse("{\"mode\":\"weighted\",\"enabled\":true,"
			+ "\"bands\":[{\"name\":\"only\",\"weight\":1}]}");
		Check(missingStructuredFunding.TryNormalizePayload(structuredRaw, PolicyEffectScopes.Local,
			out PolicyEffectPayload structuredPayload, out string normalizeError),
			"Structured funding fixture must normalize: " + normalizeError);
		Check(!missingStructuredFunding.TryApplyFunding(structuredPayload, funding,
			out PolicyEffectPayload rejectedStructuredPayload, out string structuredFundingError)
			&& rejectedStructuredPayload == null
			&& !string.IsNullOrWhiteSpace(structuredFundingError),
			"Structured non-None funding without an override must fail closed.");
		Check(ContractValidationRejects(validation, new IPolicyEffectModule[] { missingStructuredFunding }),
			"Catalog must reject structured non-None funding without a module transform.");
	}

	private static void TestPlayerPolicyPermanentDurationContract()
	{
		PolicyEffectCompilerRequest permanentRequest = BuildCompilerRequest(
			"player-permanent",
			PolicyEffectScopes.Kingdom,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: true,
			detailedIncludesDummy: true);
		permanentRequest.IsPermanentEffect = true;
		permanentRequest.EndDay = 0f;
		Check(TryCompileForContract(Array.Empty<PolicyEffectWireEffect>(), permanentRequest, "permanent", out _, out string permanentError),
			"Explicit permanent effects must accept EndDay=0: " + permanentError);
		PolicyEffectCompilerRequest permanentVassalRequest = BuildCompilerRequest(
			"player-vassal-permanent",
			PolicyEffectScopes.Vassal,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: false,
			detailedIncludesDummy: false);
		permanentVassalRequest.IsPermanentEffect = true;
		permanentVassalRequest.EndDay = 0f;
		permanentVassalRequest.TargetKingdomId = "kingdom-permanent-vassal";
		permanentVassalRequest.IssuerKingdomId = "kingdom-permanent-issuer";
		permanentVassalRequest.CandidateModuleIds = new List<string> { "kingdomStability" };
		permanentVassalRequest.DetailedModuleIds = new List<string> { "kingdomStability" };
		PolicyEffectWireEffect permanentVassalWire = new PolicyEffectWireEffect
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "vassal_permanent",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			ModuleId = "kingdomStability",
			TargetHandles = new List<string> { "K:permanent-vassal" },
			Payload = new JObject { ["value"] = 5f },
			Reason = "permanent vassal runtime contract"
		};
		Check(TryCompileForContract(new[] { permanentVassalWire }, permanentVassalRequest,
			"permanent-vassal", out PolicyEffectCompilerResult permanentVassalCompilation, out string permanentVassalError),
			"A permanent vassal EffectPlan must accept durationDays=0: " + permanentVassalError);

		PolicyEffectCompilerRequest implicitZeroEndDay = BuildCompilerRequest(
			"implicit-zero-end",
			PolicyEffectScopes.Kingdom,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: true,
			detailedIncludesDummy: true);
		implicitZeroEndDay.EndDay = 0f;
		Check(!TryCompileForContract(Array.Empty<PolicyEffectWireEffect>(), implicitZeroEndDay, "implicit", out _, out _),
			"EndDay=0 must fail closed without the explicit permanent flag.");

		PolicyEffectCompilerRequest finiteRequest = BuildCompilerRequest(
			"finite",
			PolicyEffectScopes.Kingdom,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: true,
			detailedIncludesDummy: true);
		Check(TryCompileForContract(Array.Empty<PolicyEffectWireEffect>(), finiteRequest, "finite", out _, out string finiteError),
			"Finite effects must retain the existing positive EndDay contract: " + finiteError);

		Type behavior = SutType("AnimusForge.CustomPolicyBehavior");
		Type requestType = behavior.GetNestedType("PolicyDraftRequest", All);
		Check(requestType != null, "Player policy draft request contract type is missing.");
		object playerKingdom = Activator.CreateInstance(requestType, nonPublic: true);
		SetField(requestType, playerKingdom, "ScopeKind", "kingdom");
		SetField(requestType, playerKingdom, "ManualDurationDays", 0);
		Check((bool)InvokeStatic(behavior, "IsPermanentPlayerPolicyEffect", new[] { playerKingdom }, 1),
			"Blank player kingdom duration must mean a permanent effect.");
		SetField(requestType, playerKingdom, "ManualDurationDays", 9);
		Check(!(bool)InvokeStatic(behavior, "IsPermanentPlayerPolicyEffect", new[] { playerKingdom }, 1),
			"A positive player duration must remain finite.");
		object vassal = Activator.CreateInstance(requestType, nonPublic: true);
		SetField(requestType, vassal, "ScopeKind", "vassal");
		SetField(requestType, vassal, "ManualDurationDays", 0);
		Check((bool)InvokeStatic(behavior, "IsPermanentPlayerPolicyEffect", new[] { vassal }, 1),
			"Blank player-issued vassal policy duration must mean a permanent effect.");
		SetField(requestType, vassal, "ManualDurationDays", 9);
		Check(!(bool)InvokeStatic(behavior, "IsPermanentPlayerPolicyEffect", new[] { vassal }, 1),
			"A positive player-issued vassal policy duration must remain finite.");

		Type resultType = behavior.GetNestedType("PolicyGenerationResult", All);
		Type postprocessType = behavior.GetNestedType("PolicyPostprocessResult", All);
		Type appliedEffectType = behavior.GetNestedType("AppliedKingdomEffect", All);
		Check(resultType != null && postprocessType != null && appliedEffectType != null,
			"Vassal policy persistence contract types are missing.");
		object result = Activator.CreateInstance(resultType, nonPublic: true);
		object postprocess = Activator.CreateInstance(postprocessType, nonPublic: true);
		SetProperty(postprocessType, postprocess, "Disposition", "executable");
		SetField(resultType, result, "Postprocess", postprocess);
		object permanentEffect = Activator.CreateInstance(appliedEffectType, nonPublic: true);
		SetField(appliedEffectType, permanentEffect, "KingdomId", "vassal-contract");
		SetField(appliedEffectType, permanentEffect, "KingdomName", "Vassal Contract");
		SetField(appliedEffectType, permanentEffect, "DurationDays", 0);
		SetField(appliedEffectType, permanentEffect, "RemainingDays", 0);
		SetField(appliedEffectType, permanentEffect, "IsPermanentEffect", true);
		IList effects = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(appliedEffectType));
		effects.Add(permanentEffect);
		SetField(requestType, vassal, "ManualDurationDays", 0);
		SetField(requestType, vassal, "IsPermanentEffect", true);
		SetField(requestType, vassal, "SubmittedDay", 1);
		SetField(requestType, vassal, "DateText", "contract-date");
		SetField(requestType, vassal, "PolicyName", "Permanent vassal contract");
		SetField(requestType, vassal, "PolicyContent", "Permanent while the vassal relationship remains valid.");
		SetField(requestType, vassal, "PlayerKingdomId", "vassal-contract");
		SetField(requestType, vassal, "PlayerKingdomName", "Vassal Contract");
		SetField(requestType, vassal, "IssuerKingdomId", "issuer-contract");
		SetField(requestType, vassal, "IssuerKingdomName", "Issuer Contract");
		object behaviorInstance = Activator.CreateInstance(behavior);
		PolicyEffectBundleRegistration permanentBundle = new PolicyEffectBundleRegistration
		{
			ScopeKind = PolicyEffectScopes.Vassal,
			EffectId = "vassal-permanent-active",
			RecordId = "vassal-permanent-record",
			PolicyName = "Permanent vassal contract",
			SubmittedDay = 1,
			IssuerKingdomId = "kingdom-permanent-issuer",
			TargetKingdomId = "kingdom-permanent-vassal",
			TargetKingdomName = "Vassal Contract",
			DurationDays = 0,
			IsPermanentEffect = true,
			MaintenanceFunded = true,
			ModuleEffects = permanentVassalCompilation.Effects.Select(effect => effect.SaveData).ToList()
		};
		object[] registerArguments = { permanentBundle, null, null };
		Check((bool)InvokeInstance(behavior, behaviorInstance, "TryRegisterPolicyEffectBundleInternal", registerArguments, 3),
			"A permanent vassal bundle must register with durationDays=0: " + Convert.ToString(registerArguments[2], CultureInfo.InvariantCulture));
		Dictionary<string, string> activeEffects = (Dictionary<string, string>)behavior.GetField("_activePolicyEffects", All).GetValue(behaviorInstance);
		JObject activePermanentBundle = JObject.Parse(activeEffects["vassal-permanent-active"]);
		Check(activePermanentBundle.Value<bool>("IsPermanentEffect")
			&& activePermanentBundle.Value<int>("TotalDurationDays") == 0
			&& activePermanentBundle.Value<int>("RemainingDays") == 0
			&& activePermanentBundle["ModuleEffects"].Values<JObject>().All(effect => effect.Value<float>("EndDay") == 0f),
			"The registered permanent vassal bundle and all runtime instances must retain the permanent zero-duration contract.");

		PolicyEffectCompilerRequest orderedCrossVassalRequest = BuildCompilerRequest(
			"player-vassal-order",
			PolicyEffectScopes.Vassal,
			new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			candidateIncludesDummy: false,
			detailedIncludesDummy: false);
		orderedCrossVassalRequest.TargetKingdomId = "kingdom-vassal-order";
		orderedCrossVassalRequest.IssuerKingdomId = "kingdom-issuer-order";
		orderedCrossVassalRequest.AuthorizedCrossKingdomIds = new[] { "kingdom-issuer-order" };
		orderedCrossVassalRequest.CandidateModuleIds = new List<string> { "kingdomStability" };
		orderedCrossVassalRequest.DetailedModuleIds = new List<string> { "kingdomStability" };
		PolicyEffectWireEffect issuerFirstWire = new PolicyEffectWireEffect
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "issuer_first",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			ModuleId = "kingdomStability",
			TargetHandles = new List<string> { "K:issuer-order" },
			Payload = new JObject { ["value"] = 3f },
			Reason = "issuer consequence deliberately appears first"
		};
		PolicyEffectWireEffect vassalSecondWire = new PolicyEffectWireEffect
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "vassal_second",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			ModuleId = "kingdomStability",
			TargetHandles = new List<string> { "K:vassal-order" },
			Payload = new JObject { ["value"] = 4f },
			Reason = "vassal consequence deliberately appears second"
		};
		Check(TryCompileForContract(
			new[] { issuerFirstWire, vassalSecondWire },
			orderedCrossVassalRequest,
			"vassal-order",
			out PolicyEffectCompilerResult orderedCrossVassalCompilation,
			out string orderedCrossVassalError),
			"A vassal policy may compile authorized effects for both the suzerain and vassal: " + orderedCrossVassalError);
		PolicyEffectBundleRegistration orderedCrossVassalBundle = new PolicyEffectBundleRegistration
		{
			ScopeKind = PolicyEffectScopes.Vassal,
			EffectId = "vassal-order-active",
			RecordId = "vassal-order-record",
			IssuerKingdomId = "kingdom-issuer-order",
			PolicyName = "Ordered bilateral vassal policy",
			SubmittedDay = 10,
			TargetKingdomId = "kingdom-vassal-order",
			TargetKingdomName = "Vassal Order",
			DurationDays = 9,
			MaintenanceFunded = true,
			ModuleEffects = orderedCrossVassalCompilation.Effects.Select(effect => effect.SaveData).ToList()
		};
		object[] orderedRegistrationArguments = { orderedCrossVassalBundle, null, null };
		Check((bool)InvokeInstance(behavior, behaviorInstance, "TryRegisterPolicyEffectBundleInternal", orderedRegistrationArguments, 3),
			"A bilateral vassal bundle must register when its publication boundary remains the selected vassal: "
			+ Convert.ToString(orderedRegistrationArguments[2], CultureInfo.InvariantCulture));
		JObject orderedActiveBundle = JObject.Parse(activeEffects["vassal-order-active"]);
		Check(string.Equals(orderedActiveBundle.Value<string>("TargetKingdomId"), "kingdom-vassal-order", StringComparison.Ordinal)
			&& string.Equals(orderedActiveBundle.Value<string>("IssuerKingdomId"), "kingdom-issuer-order", StringComparison.Ordinal),
			"The persisted vassal bundle root must be the selected vassal, independently of EffectPlan ordering.");
		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string effectSource = File.ReadAllText(Path.Combine(
			repositoryRoot, "PolicySystem", "Core", "CustomPolicyBehavior.Effects.cs"), Encoding.UTF8);
		Check(effectSource.Contains("TargetKingdomId = FirstNonEmpty(request?.PlayerKingdomId, source?.KingdomId)"),
			"Vassal activation must derive the bundle publication boundary from the request, never from the first AI-ordered effect shell.");
		InvokeInstance(behavior, behaviorInstance, "RecordSuccessfulVassalPolicy",
			new object[] { vassal, result, "feedback", effects, "vassal-permanent-record" }, 5);
		IDictionary localRecords = (IDictionary)behavior.GetField("_localPolicyRecords", All).GetValue(behaviorInstance);
		JObject permanentRecord = JObject.Parse(Convert.ToString(localRecords["vassal-permanent-record"], CultureInfo.InvariantCulture));
		Check(permanentRecord.Value<bool>("IsPermanentEffect")
			&& permanentRecord.Value<int>("OriginalDurationDays") == 0
			&& permanentRecord.Value<int>("RemainingDays") == 0,
			"A permanent vassal record must persist the explicit permanent flag with zero duration counters.");
		InvokeInstance(behavior, behaviorInstance, "OnVassalRelationshipEndedInternal",
			new object[] { "vassal-contract", "contract relationship ended" }, 2);
		JObject endedPermanentRecord = JObject.Parse(Convert.ToString(localRecords["vassal-permanent-record"], CultureInfo.InvariantCulture));
		Check(string.Equals(endedPermanentRecord.Value<string>("Status"), "relationship_ended", StringComparison.Ordinal)
			&& endedPermanentRecord.Value<int>("RemainingDays") == 0
			&& !activeEffects.ContainsKey("vassal-permanent-active"),
			"Ending the vassal relationship must terminate both the permanent record and its active bundle.");

		object finiteVassal = Activator.CreateInstance(requestType, nonPublic: true);
		SetField(requestType, finiteVassal, "ScopeKind", "vassal");
		SetField(requestType, finiteVassal, "ManualDurationDays", 9);
		SetField(requestType, finiteVassal, "IsPermanentEffect", false);
		SetField(requestType, finiteVassal, "PlayerKingdomId", "finite-vassal-contract");
		SetField(requestType, finiteVassal, "PlayerKingdomName", "Finite Vassal Contract");
		object finiteEffect = Activator.CreateInstance(appliedEffectType, nonPublic: true);
		SetField(appliedEffectType, finiteEffect, "KingdomId", "finite-vassal-contract");
		SetField(appliedEffectType, finiteEffect, "DurationDays", 9);
		SetField(appliedEffectType, finiteEffect, "RemainingDays", 9);
		IList finiteEffects = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(appliedEffectType));
		finiteEffects.Add(finiteEffect);
		InvokeInstance(behavior, behaviorInstance, "RecordSuccessfulVassalPolicy",
			new object[] { finiteVassal, result, "feedback", finiteEffects, "vassal-finite-record" }, 5);
		JObject finiteRecord = JObject.Parse(Convert.ToString(localRecords["vassal-finite-record"], CultureInfo.InvariantCulture));
		Check(!finiteRecord.Value<bool>("IsPermanentEffect")
			&& finiteRecord.Value<int>("OriginalDurationDays") == 9
			&& finiteRecord.Value<int>("RemainingDays") == 9,
			"A positive player-issued vassal duration must retain the existing finite persistence contract.");

		Type localRecordType = behavior.GetNestedType("LocalPolicyRecordSaveData", All);
		object legacyFiniteRecord = Activator.CreateInstance(localRecordType, nonPublic: true);
		SetProperty(localRecordType, legacyFiniteRecord, "Version", 5);
		SetProperty(localRecordType, legacyFiniteRecord, "ScopeKind", "vassal");
		SetProperty(localRecordType, legacyFiniteRecord, "OriginalDurationDays", 7);
		SetProperty(localRecordType, legacyFiniteRecord, "RemainingDays", 4);
		object normalizedLegacyFiniteRecord = InvokeStatic(behavior, "NormalizeLocalPolicyRecord", new[] { legacyFiniteRecord }, 1);
		Check(!(bool)Property(localRecordType, normalizedLegacyFiniteRecord, "IsPermanentEffect")
			&& (int)Property(localRecordType, normalizedLegacyFiniteRecord, "OriginalDurationDays") == 7
			&& (int)Property(localRecordType, normalizedLegacyFiniteRecord, "RemainingDays") == 4,
			"A legacy vassal save without IsPermanentEffect must remain finite after normalization.");

		Type dynamicPolicyType = behavior.GetNestedType("DynamicPolicySaveData", All);
		object legacyPlayerExpiry = Activator.CreateInstance(dynamicPolicyType, nonPublic: true);
		SetProperty(dynamicPolicyType, legacyPlayerExpiry, "Source", "player");
		SetProperty(dynamicPolicyType, legacyPlayerExpiry, "Status", "expiry_vote_pending");
		Check((bool)InvokeStatic(behavior, "ShouldCancelLegacyPlayerExpiryAgenda", new[] { legacyPlayerExpiry, (object)true }, 2),
			"An active legacy player policy must cancel its obsolete automatic expiry agenda during load reconciliation.");
		SetProperty(dynamicPolicyType, legacyPlayerExpiry, "Source", "npc");
		Check(!(bool)InvokeStatic(behavior, "ShouldCancelLegacyPlayerExpiryAgenda", new[] { legacyPlayerExpiry, (object)true }, 2),
			"NPC expiry agendas must retain their existing lifecycle.");
	}

	private static void TestPolicyResultRetryPopupContract()
	{
		int closeCount = 0;
		int retryCount = 0;
		int dismissCount = 0;
		CustomPolicyResultPopupVM retryVm = new CustomPolicyResultPopupVM(
			"政策评议失败",
			"未扣费、未应用效果。",
			string.Empty,
			"手动重试",
			showRetryButton: true,
			showDismissButton: true,
			onClose: () => closeCount++,
			onRetry: () => retryCount++,
			onDismiss: () => dismissCount++);
		Check(retryVm.ShowRetryButton && retryVm.ShowDismissButton && !retryVm.ShowCloseButton
			&& string.Equals(retryVm.RetryText, "手动重试", StringComparison.Ordinal),
			"The failure result VM must expose a manual retry button and an independent dismiss X.");
		retryVm.ExecuteRetry();
		retryVm.ExecuteDismiss();
		Check(retryCount == 1 && dismissCount == 1 && closeCount == 0,
			"Retry and dismiss must dispatch independent callbacks.");

		CustomPolicyResultPopupVM successVm = new CustomPolicyResultPopupVM(
			"政策已经发布",
			"success",
			"知道了",
			() => closeCount++);
		Check(successVm.ShowCloseButton && !successVm.ShowRetryButton && !successVm.ShowDismissButton,
			"Existing success result popups must retain their single close action.");
		successVm.ExecuteClose();
		Check(closeCount == 1, "The existing success popup close callback must remain intact.");
		MethodInfo showRetry = typeof(CustomPolicyResultPopup).GetMethod("ShowRetry", BindingFlags.NonPublic | BindingFlags.Static);
		Check(showRetry != null && showRetry.GetParameters().Length == 4,
			"The result popup must expose one internal retry-mode entry point without adding an external API.");
	}

	private static void TestNpcSuggestedPolicyAgendaFlowContracts()
	{
		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string behaviorSource = File.ReadAllText(Path.Combine(
			repositoryRoot, "PolicySystem", "Npc", "NpcRulerPolicyBehavior.cs"), Encoding.UTF8);
		int engineStart = behaviorSource.IndexOf("public void OnEngineTick()", StringComparison.Ordinal);
		int campaignStart = behaviorSource.IndexOf("private void OnCampaignTick(float dt)", engineStart, StringComparison.Ordinal);
		int campaignEnd = behaviorSource.IndexOf("public static bool RegisterPlayerPolicyForExternal", campaignStart, StringComparison.Ordinal);
		Check(engineStart >= 0 && campaignStart > engineStart && campaignEnd > campaignStart,
			"NPC policy engine/campaign tick method boundaries are missing.");
		string engineTick = behaviorSource.Substring(engineStart, campaignStart - engineStart);
		string campaignTick = behaviorSource.Substring(campaignStart, campaignEnd - campaignStart);
		int snapshotIndex = engineTick.IndexOf("ProcessPendingPolicySnapshotJobs();", StringComparison.Ordinal);
		int commitIndex = engineTick.IndexOf("ProcessPendingPolicyCommits();", StringComparison.Ordinal);
		Check(snapshotIndex >= 0 && commitIndex > snapshotIndex,
			"Engine tick must drain pending policy snapshots before pending commits so conversation missions cannot strand accepted proposals.");
		Check(campaignTick.IndexOf("ProcessPendingPolicySnapshotJobs();", StringComparison.Ordinal) < 0,
			"Campaign tick must not remain a second consumer of the policy snapshot queue.");

		string agendaSource = File.ReadAllText(Path.Combine(
			repositoryRoot, "PolicySystem", "Agenda", "KingdomAgendaCustomPolicyBehavior.cs"), Encoding.UTF8);
		Check(agendaSource.IndexOf("统治者已接受建议，AF 正在拟定；完成后将直接提交目标王国议程，无需再次确认。", StringComparison.Ordinal) >= 0
			&& agendaSource.IndexOf("Colors.Green", StringComparison.Ordinal) >= 0,
			"An accepted agenda action tag must keep a green acknowledgement and promise direct submission without a second confirmation.");

		string generationSource = File.ReadAllText(Path.Combine(
			repositoryRoot, "PolicySystem", "Npc", "NpcRulerPolicyBehavior.Generation.cs"), Encoding.UTF8);
		int submitStart = generationSource.IndexOf("case PendingNpcPolicyCommitStage.SubmitAgenda:", StringComparison.Ordinal);
		int submitEnd = generationSource.IndexOf("case PendingNpcPolicyCommitStage.UpsertPolicyEvent:", submitStart, StringComparison.Ordinal);
		Check(submitStart >= 0 && submitEnd > submitStart,
			"NPC policy submit-agenda stage boundaries are missing.");
		string submitStage = generationSource.Substring(submitStart, submitEnd - submitStart);
		int submitCall = submitStage.IndexOf("CustomPolicyBehavior.TrySubmitNpcPolicyAgendaForExternal", StringComparison.Ordinal);
		int submittedNotice = submitStage.IndexOf("NotifySuggestedPolicyAgendaSubmitted(record);", StringComparison.Ordinal);
		Check(submitCall >= 0 && submittedNotice > submitCall,
			"A player-suggested policy must publish its green submitted notice only after the shared agenda submitter confirms the decision.");
		Check(generationSource.IndexOf("ShowSuggestedPolicyGenerationRetry(job, error);", StringComparison.Ordinal) >= 0
			&& generationSource.IndexOf("RetrySuggestedPolicyGeneration(", StringComparison.Ordinal) >= 0,
			"Deterministic player-suggested generation failures must reuse the manual retry flow with a fresh generation job.");

		string lifecycleSource = File.ReadAllText(Path.Combine(
			repositoryRoot, "PolicySystem", "Core", "CustomPolicyBehavior.Lifecycle.cs"), Encoding.UTF8);
		string coreSource = File.ReadAllText(Path.Combine(
			repositoryRoot, "PolicySystem", "Core", "CustomPolicyBehavior.cs"), Encoding.UTF8);
		Check(coreSource.IndexOf("PlayerKingdomDynamicPolicyAdoptionReviewDays = 21f", StringComparison.Ordinal) >= 0
			&& coreSource.IndexOf("ForeignKingdomDynamicPolicyAdoptionReviewDays = 3f", StringComparison.Ordinal) >= 0,
			"Player and foreign dynamic policy review periods must remain 21 and 3 days respectively.");
		Check(lifecycleSource.IndexOf("Patch_KingdomElection_GetAiChoice_Postfix", StringComparison.Ordinal) >= 0
			&& lifecycleSource.IndexOf("outcome.ShouldDecisionBeEnforced", StringComparison.Ordinal) >= 0
			&& lifecycleSource.IndexOf("__result = adoption;", StringComparison.Ordinal) >= 0,
			"NPC ruler agendas must retain the forced adoption election outcome.");
	}

	private static void TestPlayerVassalPolicyAttributionContracts()
	{
		NpcRulerPolicyRecord record = new NpcRulerPolicyRecord
		{
			PolicyId = "player-vassal-attribution",
			PolicyKind = "vassal",
			IsPlayerPolicy = true,
			IssuerKingdomId = "kingdom_suzerain",
			IssuerKingdomName = "宗主王国",
			KingdomId = "kingdom_vassal",
			KingdomName = "附庸王国",
			RulerHeroId = "main_hero",
			RulerName = "玩家",
			PolicyName = "自治保障令",
			PolicyContent = "保障附庸自治。",
			PolicyDigest = "保障附庸自治"
		};

		Type behaviorType = SutType("AnimusForge.CustomPolicyBehavior");
		string announcement = (string)InvokeStatic(
			behaviorType,
			"BuildPolicyAnnouncementText",
			new object[] { record },
			1);
		Check(announcement.IndexOf("【附庸国政策】", StringComparison.Ordinal) >= 0
			&& announcement.IndexOf("宗主玩家（宗主王国）发布", StringComparison.Ordinal) >= 0
			&& announcement.IndexOf("对附庸国附庸王国生效", StringComparison.Ordinal) >= 0,
			"Player-issued vassal announcements must identify the player suzerain as publisher and the vassal kingdom as target.");

		Type serviceType = SutType("AnimusForge.PolicyHistoryRetrievalService");
		Type entryType = SutType("AnimusForge.NpcPolicyHistoryEntry");
		object entry = Activator.CreateInstance(entryType);
		SetProperty(entryType, entry, "EntryId", record.PolicyId);
		SetProperty(entryType, entry, "SourceKind", "player_vassal");
		SetProperty(entryType, entry, "ScopeKind", "vassal");
		SetProperty(entryType, entry, "OwnerKingdomId", record.KingdomId);
		SetProperty(entryType, entry, "OwnerKingdomName", record.KingdomName);
		SetProperty(entryType, entry, "IssuerKingdomId", record.IssuerKingdomId);
		SetProperty(entryType, entry, "IssuerKingdomName", record.IssuerKingdomName);
		SetProperty(entryType, entry, "PolicyName", record.PolicyName);
		SetProperty(entryType, entry, "PolicyContent", record.PolicyContent);
		SetProperty(entryType, entry, "PolicyStatus", "active");
		SetProperty(entryType, entry, "RawPolicyStatus", "active");
		SetProperty(entryType, entry, "TargetKingdomIds", new List<string> { record.KingdomId });
		IList current = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(entryType));
		IList historical = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(entryType));
		current.Add(entry);
		string dialoguePrompt = (string)InvokeStatic(serviceType, "BuildDialoguePrompt", new object[] { current, historical }, 2);
		string retrievalText = (string)InvokeStatic(serviceType, "BuildDialogueRetrievalText", new[] { entry }, 1);
		Check(dialoguePrompt.IndexOf("发布方：宗主玩家（宗主王国）", StringComparison.Ordinal) >= 0
			&& dialoguePrompt.IndexOf("生效对象：附庸国附庸王国", StringComparison.Ordinal) >= 0
			&& dialoguePrompt.IndexOf("不是附庸统治者自行颁布", StringComparison.Ordinal) >= 0,
			"Dialogue policy knowledge must distinguish the player suzerain publisher from the vassal target.");
		Check(retrievalText.IndexOf("政策发布方：宗主玩家（宗主王国）", StringComparison.Ordinal) >= 0
			&& retrievalText.IndexOf("政策生效国：附庸王国", StringComparison.Ordinal) >= 0,
			"Vassal policy retrieval documents must preserve target ownership while embedding correct publisher attribution.");

		Type npcBehaviorType = SutType("AnimusForge.NpcRulerPolicyBehavior");
		object attribution = InvokeStatic(npcBehaviorType, "ResolveUnifiedPolicyWeeklyAttribution", new object[] { record }, 1);
		Type attributionType = attribution.GetType();
		Check((bool)Property(attributionType, attribution, "IsPlayerVassalPolicy")
			&& string.Equals((string)Property(attributionType, attribution, "MaterialKind"), "player_vassal_policy", StringComparison.Ordinal)
			&& string.Equals((string)Property(attributionType, attribution, "IssuerKingdomId"), record.IssuerKingdomId, StringComparison.Ordinal)
			&& string.Equals((string)Property(attributionType, attribution, "TargetKingdomId"), record.KingdomId, StringComparison.Ordinal),
			"Weekly material routing must use the suzerain as issuer and the vassal as target.");
		string weeklySnapshot = (string)InvokeStatic(npcBehaviorType, "BuildUnifiedPolicyWeeklySnapshot",
			new[] { (object)record, attribution, "附庸王国", "无持续数值变化" }, 4);
		Check(weeklySnapshot.IndexOf("玩家附庸政策", StringComparison.Ordinal) >= 0
			&& weeklySnapshot.IndexOf("发布方：宗主玩家（宗主王国）", StringComparison.Ordinal) >= 0
			&& weeklySnapshot.IndexOf("生效对象：附庸王国", StringComparison.Ordinal) >= 0
			&& weeklySnapshot.IndexOf("不是附庸统治者自行颁布", StringComparison.Ordinal) >= 0,
			"Weekly material text must not attribute a player-issued vassal policy to the target ruler.");

		NpcRulerPolicyEffectDto weeklyShell = new NpcRulerPolicyEffectDto
		{
			TargetKingdomId = record.KingdomId,
			TargetKingdomName = record.KingdomName,
			DurationDays = 30,
			RemainingDays = 30,
			ModuleEffects = new List<PolicyEffectInstanceSaveData>
			{
				BuildPlayerVisibleEffectInstance(
					"weekly-instance-0", "M0", "kingdomStabilityNextDayOnce", 1f,
					new PolicyEffectCanonicalTargetSet { KingdomIds = new List<string> { record.KingdomId } }),
				BuildPlayerVisibleEffectInstance(
					"weekly-instance-1", "M1", "kingdomStabilityOnce", 1f,
					new PolicyEffectCanonicalTargetSet { KingdomIds = new List<string> { record.KingdomId } })
			}
		};
		int activeExecutableCount = Convert.ToInt32(InvokeStatic(
			npcBehaviorType,
			"CountActiveExecutablePolicyEffectInstances",
			new object[] { new List<NpcRulerPolicyEffectDto> { weeklyShell } },
			1), CultureInfo.InvariantCulture);
		Check(activeExecutableCount == 2,
			"Weekly effects= must count active executable ModuleEffects, not the one outer effect shell.");
		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string weeklySource = File.ReadAllText(Path.Combine(
			repositoryRoot, "PolicySystem", "Npc", "NpcRulerPolicyBehavior.Persistence.cs"), Encoding.UTF8);
		Check(weeklySource.Contains("List<NpcRulerPolicyEffectDto> relevantEffects = isIssuer ? effects : recipient.Value;")
			&& weeklySource.Contains("route=\" + (isIssuer ? \"issuer\" : \"affected\")")
			&& weeklySource.Contains("effects=\" + activeExecutableEffects")
			&& weeklySource.Contains("effectShells=\" + relevantEffects.Count"),
			"Weekly issuer/affected routes must use the same module-instance count while retaining an explicit shell count.");
	}

	private static void TestPlayerPolicyDualGoldCostContract()
	{
		Type behavior = SutType("AnimusForge.CustomPolicyBehavior");
		Type assessmentType = behavior.GetNestedType("PolicyMainAssessmentResult", All);
		Check(assessmentType != null, "Policy assessment contract type is missing.");
		object assessment = Activator.CreateInstance(assessmentType, nonPublic: true);
		SetProperty(assessmentType, assessment, "StartupGoldCost", 0f);
		SetProperty(assessmentType, assessment, "DailyMaintenanceGoldCost", 2.01f);
		object[] validArgs = { assessment, 0, 0, null };
		Check((bool)InvokeStatic(behavior, "TryReadAiPolicyGoldCosts", validArgs, 4),
			"Both non-negative player policy cost fields must be accepted: " + validArgs[3]);
		Check((int)validArgs[1] == 0 && (int)validArgs[2] == 3,
			"Player policy costs must allow zero and round positive fractions upward.");

		SetProperty(assessmentType, assessment, "DailyMaintenanceGoldCost", null);
		object[] missingArgs = { assessment, 0, 0, null };
		Check(!(bool)InvokeStatic(behavior, "TryReadAiPolicyGoldCosts", missingArgs, 4),
			"New AI player policy responses must include dailyMaintenanceGoldCost.");

		SetProperty(assessmentType, assessment, "DailyMaintenanceGoldCost", -1f);
		object[] negativeArgs = { assessment, 0, 0, null };
		Check(!(bool)InvokeStatic(behavior, "TryReadAiPolicyGoldCosts", negativeArgs, 4),
			"Negative maintenance costs must fail closed.");
	}

	private static void TestPlayerPolicyMaintenanceAllocationContract()
	{
		Type planner = SutType("AnimusForge.PolicyEffects.PlayerPolicyMaintenancePlanner");
		Check(!(bool)InvokeStatic(planner, "IsSettlementDue", new object[] { 20, 19, 20 }, 3),
			"The activation day must be covered by the startup payment.");
		Check((bool)InvokeStatic(planner, "IsSettlementDue", new object[] { 20, 20, 21 }, 3),
			"The first maintenance payment must become due on the next game day.");
		Check(!(bool)InvokeStatic(planner, "IsSettlementDue", new object[] { 20, 21, 21 }, 3),
			"A settled bundle must not be processed twice on the same game day.");
		Check((int)InvokeStatic(planner, "AdvanceEffectDay", new object[] { false, 2 }, 2) == 1,
			"A finite effect must consume one duration day even when maintenance is unfunded.");
		Check((int)InvokeStatic(planner, "AdvanceEffectDay", new object[] { true, 0 }, 2) == 0,
			"A permanent effect must never consume duration days.");
		bool[] exact = (bool[])InvokeStatic(planner, "AllocateStrictOldestPrefix", new object[] { new[] { 4, 6 }, 10 }, 2);
		Check(exact.SequenceEqual(new[] { true, true }), "An exactly funded oldest-first prefix must be fully funded.");
		bool[] blocked = (bool[])InvokeStatic(planner, "AllocateStrictOldestPrefix", new object[] { new[] { 6, 5, 1 }, 10 }, 2);
		Check(blocked.SequenceEqual(new[] { true, false, false }),
			"The first unaffordable charged policy must block every later charged policy.");
		bool[] zeroCosts = (bool[])InvokeStatic(planner, "AllocateStrictOldestPrefix", new object[] { new[] { 7, 0, 1, 0 }, 6 }, 2);
		Check(zeroCosts.SequenceEqual(new[] { false, true, false, true }),
			"Zero-maintenance policies must remain funded even after the charged prefix is blocked.");
		Check((bool)InvokeStatic(planner, "IsSettlementGoldDeltaConfirmed", new object[] { 100, 90, -10 }, 3),
			"Maintenance settlement must confirm the exact player-gold delta after GiveGoldAction.");
		Check(!(bool)InvokeStatic(planner, "IsSettlementGoldDeltaConfirmed", new object[] { 100, 91, -10 }, 3),
			"A mismatched player-gold delta must not be persisted as funded or paid.");

		Type behavior = SutType("AnimusForge.CustomPolicyBehavior");
		MethodInfo goldChangePatch = behavior.GetMethod("Patch_PolicyClanGoldChange_Postfix", All);
		MethodInfo incomePatch = behavior.GetMethod("Patch_PolicyClanIncome_Postfix", All);
		MethodInfo expensesPatch = behavior.GetMethod("Patch_PolicyClanExpenses_Postfix", All);
		Check(goldChangePatch != null && goldChangePatch.GetParameters().Length == 5
			&& incomePatch != null && incomePatch.GetParameters().Length == 5
			&& expensesPatch != null && expensesPatch.GetParameters().Length == 5,
			"Vanilla ClanFinanceModel gold-change, income and expenses entry points must remain patched.");
		Check(behavior.GetMethod("Patch_PolicyClanDailyTick_Prefix", All) != null
			&& behavior.GetMethod("Patch_PolicyClanDailyTick_Postfix", All) != null
			&& behavior.GetMethod("Patch_PolicyClanDailyTick_Finalizer", All) != null,
			"Maintenance settlement must observe ClanVariablesCampaignBehavior.DailyTickClan around the actual debit.");
		Type clanType = Type.GetType(
			"TaleWorlds.CampaignSystem.Clan, TaleWorlds.CampaignSystem", throwOnError: true);
		Type clanVariablesBehaviorType = Type.GetType(
			"TaleWorlds.CampaignSystem.CampaignBehaviors.ClanVariablesCampaignBehavior, TaleWorlds.CampaignSystem", throwOnError: true);
		Check(clanVariablesBehaviorType.GetMethod(
			"DailyTickClan", All, binder: null, types: new[] { clanType }, modifiers: null) != null,
			"Both supported Bannerlord reference lines must expose private DailyTickClan(Clan).");
		object incomeText = InvokeStatic(behavior, "BuildPlayerPolicyIncomeExplanation", new object[] { "粮政" }, 1);
		Check(incomeText != null && incomeText.ToString().Contains("《粮政》政策收入"),
			"Vanilla finance output must identify each positive player policy income.");

		List<PolicyEffectRuntimeContribution> contributions = new List<PolicyEffectRuntimeContribution>
		{
			new PolicyEffectRuntimeContribution("effect-a", "policy-a", "heroGoldPerDay", "粮政", PolicyEffectHook.DailyScheduler, PolicyEffectTargetKind.Hero, "main", PolicyEffectAggregationKind.IntegerDelta, 300f),
			new PolicyEffectRuntimeContribution("effect-b", "policy-b", "heroGoldPerDay", "军饷", PolicyEffectHook.DailyScheduler, PolicyEffectTargetKind.Hero, "main", PolicyEffectAggregationKind.IntegerDelta, 50f),
			new PolicyEffectRuntimeContribution("effect-c", "policy-c", "heroGoldPerDay", "倒扣", PolicyEffectHook.DailyScheduler, PolicyEffectTargetKind.Hero, "main", PolicyEffectAggregationKind.IntegerDelta, -20f),
			new PolicyEffectRuntimeContribution("effect-d", "policy-d", "clanInfluencePerDay", "影响力", PolicyEffectHook.DailyScheduler, PolicyEffectTargetKind.Hero, "main", PolicyEffectAggregationKind.IntegerDelta, 7f)
		};
		Type explainedNumberType = typeof(CustomPolicyBehavior).Assembly
			.GetType("TaleWorlds.CampaignSystem.ExplainedNumber", throwOnError: false)
			?? Type.GetType("TaleWorlds.CampaignSystem.ExplainedNumber, TaleWorlds.CampaignSystem", throwOnError: true);
		object income = Activator.CreateInstance(explainedNumberType, new object[] { 0f, true, null });
		object[] incomeArgs = { contributions, true, income };
		InvokeStatic(behavior, "AddPlayerPolicyGoldIncomeContributions", incomeArgs, 3);
		income = incomeArgs[2];
		string explanations = (string)explainedNumberType.GetMethod("GetExplanations", All).Invoke(income, Array.Empty<object>());
		float resultNumber = Convert.ToSingle(Property(explainedNumberType, income, "ResultNumber"), CultureInfo.InvariantCulture);
		Check(Math.Abs(resultNumber - 350f) <= 0.0001f
			&& explanations.Contains("《粮政》政策收入")
			&& explanations.Contains("《军饷》政策收入")
			&& !explanations.Contains("《倒扣》")
			&& !explanations.Contains("《影响力》"),
			"Only positive heroGoldPerDay contributions may be projected as one vanilla income line per policy.");

		CustomPolicyBehavior.ActivePolicyEffectSaveData activeIncome = new CustomPolicyBehavior.ActivePolicyEffectSaveData
		{
			EffectId = "active-income",
			RecordId = "policy-income",
			PolicyName = "粮政"
		};
		activeIncome.ModuleEffects.Add(new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "M0",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "active-income:heroGoldPerDay",
			PolicyId = "policy-income",
			ModuleId = "heroGoldPerDay",
			SourceModuleId = "heroGold",
			PayloadSchemaVersion = 1,
			Payload = new JObject { ["moduleId"] = "heroGoldPerDay", ["schemaVersion"] = 1, ["value"] = 75 },
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				StructureVersion = 1,
				SelectorHandles = new List<string> { "H8" },
				HeroIds = new List<string> { "main" }
			},
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			StartDay = 10,
			EndDay = 20,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "contract"
		});
		IEnumerable projectedIncome = (IEnumerable)InvokeStatic(
			behavior,
			"BuildModulePolicyEffectRuntimeContributions",
			new object[] { activeIncome },
			1);
		PolicyEffectRuntimeContribution projectedIncomeItem = projectedIncome.Cast<PolicyEffectRuntimeContribution>().Single();
		Check(string.Equals(projectedIncomeItem.ModuleId, "heroGoldPerDay", StringComparison.Ordinal)
			&& string.Equals(projectedIncomeItem.TargetId, "main", StringComparison.Ordinal)
			&& Math.Abs(projectedIncomeItem.Value - 75f) <= 0.0001f,
			"The bounded runtime index projection must expose an active heroGoldPerDay value for its frozen Hero target.");
		activeIncome.IsPermanentEffect = true;
		activeIncome.MaintenanceFunded = true;
		object dailyPlanBehavior = Activator.CreateInstance(behavior);
		InvokeInstance(behavior, dailyPlanBehavior, "RebuildDailyPolicyEffectRuntimePlan",
			new object[] { activeIncome }, 1);
		IDictionary dailyPlans = (IDictionary)behavior.GetField("_policyEffectDailyRuntimePlans", All)
			.GetValue(dailyPlanBehavior);
		object heroOnlyPlan = dailyPlans[activeIncome.EffectId];
		Check(heroOnlyPlan != null
			&& !Items(heroOnlyPlan.GetType().GetField("SettlementTargetIds", All).GetValue(heroOnlyPlan)).Any()
			&& !Items(heroOnlyPlan.GetType().GetField("CanonicalSettlementTargetIds", All).GetValue(heroOnlyPlan)).Any()
			&& ((Array)heroOnlyPlan.GetType().GetField("NonSettlementEntries", All).GetValue(heroOnlyPlan)).Length == 1
			&& (int)heroOnlyPlan.GetType().GetField("TargetExecutionCount", All).GetValue(heroOnlyPlan) == 1,
			"A Hero-only daily policy must build one canonical Hero execution and no settlement work-list entry or kingdom settlement scan.");

		object maintenance = Activator.CreateInstance(explainedNumberType, new object[] { 0f, true, null });
		object[] maintenanceArgs = { 10, true, maintenance };
		InvokeStatic(behavior, "AddPlayerPolicyMaintenanceTotal", maintenanceArgs, 3);
		maintenance = maintenanceArgs[2];
		string maintenanceExplanations = (string)explainedNumberType.GetMethod("GetExplanations", All)
			.Invoke(maintenance, Array.Empty<object>());
		float maintenanceResult = Convert.ToSingle(
			Property(explainedNumberType, maintenance, "ResultNumber"), CultureInfo.InvariantCulture);
		Check(Math.Abs(maintenanceResult + 10f) <= 0.0001f
			&& maintenanceExplanations.Split(new[] { "自定义政策维护费" }, StringSplitOptions.None).Length == 2,
			"All due player policy maintenance must enter vanilla finance as one aggregated negative line.");
	}

	private static void TestVersionedModuleContractsAndHookCapabilities()
	{
		MethodInfo validation = typeof(PolicyEffectModuleCatalog).GetMethod("ValidateModuleSetForContractTests", All);
		Check(validation != null, "Catalog contract validation entry point is missing.");

		VersionedContractDummyModule versioned = new VersionedContractDummyModule();
		validation.Invoke(null, new object[] { new IPolicyEffectModule[] { versioned } });
		Check(versioned.Descriptor.PayloadSchemaVersion == 3
			&& versioned.Descriptor.MinimumReadablePayloadSchemaVersion == 1
			&& versioned.Descriptor.PayloadMigrationSourceVersions.SequenceEqual(new[] { 1, 2 }),
			"Payload migration chain metadata must be continuous from v1 to v3.");
		Check(versioned.Descriptor.RuntimeStateSchemaVersion == 3
			&& versioned.Descriptor.MinimumReadableRuntimeStateSchemaVersion == 1
			&& versioned.Descriptor.RuntimeStateMigrationSourceVersions.SequenceEqual(new[] { 1, 2 }),
			"Runtime-state migration chain metadata must be continuous from v1 to v3.");
		Check(versioned.TryMigratePayload(
			new JObject { ["legacyName"] = "v1" },
			1,
			out PolicyEffectPayload migratedPayload,
			out string payloadError)
			&& migratedPayload is VersionedContractPayload typedPayload
			&& typedPayload.SchemaVersion == 3
			&& string.Equals(typedPayload.Name, "v1", StringComparison.Ordinal),
			"Payload v1->v3 migration failed: " + payloadError);
		JObject legacyRuntimeState = new JObject
		{
			["counter"] = 4,
			["nested"] = new JObject { ["marker"] = "preserved" }
		};
		Check(versioned.TryMigrateRuntimeState(
			legacyRuntimeState,
			1,
			out JToken migratedState,
			out string stateError)
			&& (int?)migratedState?["counter"] == 4
			&& (int?)migratedState?["migratedTo"] == 3
			&& JToken.DeepEquals(legacyRuntimeState["nested"], migratedState?["nested"])
			&& legacyRuntimeState["migratedTo"] == null,
			"Runtime state v1->v3 migration failed: " + stateError);

		PolicyEffectWireEffect versionedWire = new PolicyEffectWireEffect
		{
			ModuleId = versioned.Id,
			TargetHandles = new List<string> { "S:versioned" },
			Payload = new JObject { ["name"] = "compiled-v3" },
			Reason = "versioned compiler contract"
		};
		PolicyEffectCompilerRequest versionedRequest = new PolicyEffectCompilerRequest
		{
			Scope = PolicyEffectScopes.Kingdom,
			PolicyId = "versioned-compiler",
			StartDay = 1f,
			EndDay = 2f,
			Funding = new PolicyEffectFundingContext { GoldScale = 1f, InfluenceScale = 1f },
			CandidateModuleIds = new List<string> { versioned.Id },
			DetailedModuleIds = new List<string> { versioned.Id },
			ModuleResolver = delegate(string moduleId, out IPolicyEffectModule module)
			{
				module = string.Equals(moduleId, versioned.Id, StringComparison.Ordinal) ? versioned : null;
				return module != null;
			}
		};
		Check(TryCompileForContract(new[] { versionedWire }, versionedRequest, "versioned",
			out PolicyEffectCompilerResult versionedResult, out string versionedError),
			"Versioned compiler contract must succeed: " + versionedError);
		PolicyEffectInstanceSaveData versionedSave = versionedResult.Effects.Single().SaveData;
		Check(versionedSave.PayloadSchemaVersion == versioned.Descriptor.PayloadSchemaVersion
			&& versionedSave.StateSchemaVersion == versioned.Descriptor.RuntimeStateSchemaVersion,
			"Compiler SaveData must use both current module schema versions.");

		PolicyEffectModuleDescriptor schemaOne = StructuredDummyEffectModule.DescriptorForContractTests;
		Check(schemaOne.PayloadSchemaVersion == 1
			&& schemaOne.MinimumReadablePayloadSchemaVersion == 1
			&& schemaOne.PayloadMigrationSourceVersions.Count == 0
			&& schemaOne.RuntimeStateSchemaVersion == 1
			&& schemaOne.MinimumReadableRuntimeStateSchemaVersion == 1
			&& schemaOne.RuntimeStateMigrationSourceVersions.Count == 0,
			"Schema-v1 descriptors must default to no migration chain.");

		Check(ContractValidationRejects(validation, new IPolicyEffectModule[]
		{
			new BrokenMigrationContractDummyModule("contractDummy.payloadMissing1", new[] { 2 }, new[] { 1, 2 })
		}), "Catalog must reject a payload migration chain missing source v1.");
		Check(ContractValidationRejects(validation, new IPolicyEffectModule[]
		{
			new BrokenMigrationContractDummyModule("contractDummy.payloadMissing2", new[] { 1 }, new[] { 1, 2 })
		}), "Catalog must reject a payload migration chain missing source v2.");
		Check(ContractValidationRejects(validation, new IPolicyEffectModule[]
		{
			new BrokenMigrationContractDummyModule("contractDummy.stateMissing1", new[] { 1, 2 }, new[] { 2 })
		}), "Catalog must reject a runtime-state migration chain missing source v1.");
		Check(ContractValidationRejects(validation, new IPolicyEffectModule[]
		{
			new BrokenMigrationContractDummyModule("contractDummy.stateMissing2", new[] { 1, 2 }, new[] { 1 })
		}), "Catalog must reject a runtime-state migration chain missing source v2.");
		Check(ContractValidationRejects(validation, new IPolicyEffectModule[]
		{
			new UnimplementedMigrationContractDummyModule()
		}), "Catalog must reject declared migration chains without module migrators.");
		Check(ContractValidationRejects(validation, new IPolicyEffectModule[]
		{
			new InvalidExecutionHookContractDummyModule()
		}), "Catalog must reject an executionKind incompatible with its hook.");
		Check(ContractValidationRejects(validation, new IPolicyEffectModule[]
		{
			new InvalidHookContractDummyModule(HookContractDefect.TargetKinds)
		}), "Catalog must reject targetKinds incompatible with its hook.");
		Check(ContractValidationRejects(validation, new IPolicyEffectModule[]
		{
			new InvalidHookContractDummyModule(HookContractDefect.Aggregation)
		}), "Catalog must reject aggregation incompatible with its hook.");
		Check(ContractValidationRejects(validation, new IPolicyEffectModule[]
		{
			new InvalidHookContractDummyModule(HookContractDefect.ValueUnit)
		}), "Catalog must reject valueUnit incompatible with its hook.");
		Check(ContractValidationRejects(validation, new IPolicyEffectModule[]
		{
			new InvalidHookContractDummyModule(HookContractDefect.VillageSelector)
		}), "Catalog must reject Village as a first-level selector.");
		Check(versioned.Descriptor.Hook == PolicyEffectHook.DailyScheduler
			&& versioned.Descriptor.ExecutionKind == PolicyEffectExecutionKind.DailyMutation
			&& new HashSet<PolicyEffectTargetKind>(versioned.Descriptor.TargetKinds).SetEquals(
				Enum.GetValues(typeof(PolicyEffectTargetKind)).Cast<PolicyEffectTargetKind>()),
			"DailyScheduler must accept DailyMutation targets across Settlement/Town/Village/Clan/Kingdom.");
	}

	private static void SetFundingStrategyAndAssert(
		NumericFundingDummyModule module,
		PolicyEffectFundingContext funding,
		float expectedValue,
		bool expectSuccess)
	{
		string strategyName = module.Descriptor.FundingStrategy.ToString();
		Check(module.TryNormalizePayload(new JObject { ["value"] = 8f }, PolicyEffectScopes.Kingdom,
			out PolicyEffectPayload payload, out string normalizeError),
			"Funding fixture payload must normalize for " + strategyName + ": " + normalizeError);
		bool success = module.TryApplyFunding(payload, funding, out PolicyEffectPayload fundedPayload, out string error);
		Check(success == expectSuccess, "Unexpected " + strategyName + " funding result: " + error);
		if (expectSuccess)
		{
			Check(fundedPayload is NumericFundingDummyPayload, strategyName + " funding must return a typed payload.");
			float actual = ((NumericFundingDummyPayload)fundedPayload).Value;
			Check(Math.Abs(actual - expectedValue) < 0.0001f,
				strategyName + " funding mismatch. expected=" + expectedValue + " actual=" + actual);
		}
		else
		{
			Check(fundedPayload == null, strategyName + " base strategy must fail closed without a module override.");
			Check(!string.IsNullOrWhiteSpace(error), strategyName + " failure must explain the missing override.");
		}
	}

	private static void TestLegacyFieldReadAdapter()
	{
		Type adapterType = SutType("AnimusForge.PolicyEffects.LegacyPolicyEffectFieldAdapter");
		const string allFieldsJson = "{\"prosperityDailyDeltaPerTown\":1,\"foodDailyDeltaPerTown\":2,"
			+ "\"hearthDailyDeltaPerVillage\":3,\"loyaltyDailyDeltaPerTown\":4,\"securityDailyDeltaPerTown\":5,"
			+ "\"militiaDailyDeltaPerTown\":6,\"townTaxPercent\":7,\"constructionPowerDailyDelta\":8,"
			+ "\"kingdomStabilityDailyDelta\":9}";
		string[] adapterModuleIds = Items(Property(adapterType, null, "CanonicalModuleIds")).Cast<string>().ToArray();
		Check(adapterModuleIds.Length == 9 && new HashSet<string>(adapterModuleIds, StringComparer.Ordinal).SetEquals(LegacyMigratedModuleIds),
			"Legacy field adapter must expose the nine canonical modules exactly once.");
		foreach (KeyValuePair<string, string> pair in LegacyIds)
		{
			object[] resolve = { pair.Key, null };
			Check((bool)InvokeStatic(adapterType, "TryResolveModuleId", resolve, 2),
				"Legacy field adapter must resolve " + pair.Key);
			Check(string.Equals((string)resolve[1], pair.Value, StringComparison.Ordinal),
				"Legacy field adapter resolved incorrectly: " + pair.Key + " -> " + resolve[1]);
		}

		object[] readFields = { ParseToken(allFieldsJson), null, null };
		Check((bool)InvokeStatic(adapterType, "TryReadLegacyFields", readFields, 3),
			"Legacy field adapter must decode all nine fields: " + readFields[2]);
		Dictionary<string, float> decoded = ReadStringFloatDictionary(readFields[1]);
		Check(decoded.Count == 9, "Legacy field adapter must decode nine non-zero module values.");
		for (int i = 0; i < LegacyMigratedModuleIds.Length; i++)
		{
			Check(decoded.TryGetValue(LegacyMigratedModuleIds[i], out float value) && Math.Abs(value - (i + 1f)) < 0.0001f,
				"Legacy field adapter decoded wrong value for " + LegacyMigratedModuleIds[i]);
		}

		object[] aliasRead = { ParseToken("{\"constructionSpeedPercent\":12.5}"), null, null };
		Check((bool)InvokeStatic(adapterType, "TryReadLegacyFields", aliasRead, 3),
			"constructionSpeedPercent alias must be readable: " + aliasRead[2]);
		Dictionary<string, float> aliasValues = ReadStringFloatDictionary(aliasRead[1]);
		Check(aliasValues.TryGetValue("constructionPerDay", out float aliasValue) && Math.Abs(aliasValue - 12.5f) < 0.0001f,
			"constructionSpeedPercent alias must migrate to constructionPerDay.");

		object[] canonicalWins = { ParseToken("{\"constructionPowerDailyDelta\":8,\"constructionSpeedPercent\":99}"), null, null };
		Check((bool)InvokeStatic(adapterType, "TryReadLegacyFields", canonicalWins, 3),
			"Canonical construction legacy field must be readable: " + canonicalWins[2]);
		Dictionary<string, float> canonicalValues = ReadStringFloatDictionary(canonicalWins[1]);
		Check(canonicalValues.TryGetValue("constructionPerDay", out float canonicalValue) && Math.Abs(canonicalValue - 8f) < 0.0001f,
			"constructionPowerDailyDelta must win when both legacy aliases are present.");
	}

	private static void TestSaveMigrations()
	{
		Type codec = SutType("AnimusForge.PolicyEffects.PolicyEffectSaveCodec");

		object active = NormalizeJObject(codec, "TryNormalizeActiveV4ToV5",
			"{\"Version\":4,\"EffectId\":\"active-v4\",\"RecordId\":\"record-v4\",\"ScopeKind\":\"kingdom\"," +
			"\"TargetKingdomId\":\"k1\",\"RemainingDays\":4,\"TotalDurationDays\":7,\"prosperityDailyDeltaPerTown\":1.5}",
			out object activeSummary);
		Check(TokenInt(active, "Version") == 5, "Active v4 must migrate to v5.");
		object[] activeInstances = TokenArray(active, "ModuleEffects");
		Check(HasModule(activeInstances, "prosperityPerDay"), "Active v4 prosperity field must migrate.");
		Check(HasModule(activeInstances, "kingdomStabilityOnce"),
			"Every legacy Active v4 must receive a completed stability marker, even when the old value was zero/absent.");
		object stabilityInstance = activeInstances.Single(item =>
			string.Equals(TokenString(item, "ModuleId"), "kingdomStabilityOnce", StringComparison.Ordinal));
		Check(string.Equals(TokenString(GetToken(stabilityInstance, "ExecutionReceipt"), "Message"), "legacyAssumedCompleted", StringComparison.Ordinal),
			"Legacy Active stability must be marked legacyAssumedCompleted and never replayed.");
		Check(Convert.ToInt32(Property(activeSummary.GetType(), activeSummary, "LegacyAssumedCompletedReceipts"), CultureInfo.InvariantCulture) == 1,
			"Active v4 migration must count its assumed-completed stability receipt.");

		object policyRecord = NormalizeJObject(codec, "TryNormalizePolicyRecordV1ToV2",
			"{\"Version\":1,\"RecordId\":\"policy-v1\",\"ScopeKind\":\"kingdom\",\"SubmittedDay\":11," +
			"\"Effects\":[{\"EffectId\":\"effect-v1\",\"TargetKingdomId\":\"k1\",\"foodDailyDeltaPerTown\":2.25}]}",
			out _);
		Check(TokenInt(policyRecord, "Version") == 2, "PolicyRecord v1 must migrate to v2.");
		object policyEffect = TokenArray(policyRecord, "Effects").Single();
		Check(HasModule(TokenArray(policyEffect, "ModuleEffects"), "foodPerDay"),
			"PolicyRecord v1 fixed effect must migrate to moduleEffects.");

		for (int version = 1; version <= 3; version++)
		{
			object local = NormalizeJObject(codec, "TryNormalizeLocalV1ToV4",
				"{\"Version\":" + version.ToString(CultureInfo.InvariantCulture) +
				",\"RecordId\":\"local-v" + version.ToString(CultureInfo.InvariantCulture) +
				"\",\"ScopeKind\":\"local\",\"TargetHandle\":\"S:s1\",\"TargetSettlementIds\":[\"s1\"]," +
				"\"Effects\":[{\"EffectId\":\"local-effect-v" + version.ToString(CultureInfo.InvariantCulture) +
				"\",\"TargetHandle\":\"S:s1\",\"TargetSettlementIds\":[\"s1\"],\"loyaltyDailyDeltaPerTown\":1.75}]}",
				out _);
			Check(TokenInt(local, "Version") == 4, "Local v" + version + " must migrate to v4.");
			object localEffect = TokenArray(local, "Effects").Single();
			Check(HasModule(TokenArray(localEffect, "ModuleEffects"), "loyaltyPerDay"),
				"Local v" + version + " fixed effect must migrate to moduleEffects.");
		}

		object dynamicRecord = NormalizeJObject(codec, "TryNormalizeDynamicV1ToV2",
			"{\"Version\":1,\"PolicyObjectId\":\"dynamic-v1\",\"futureState\":{\"mode\":\"opaque\"}}", out _);
		Check(TokenInt(dynamicRecord, "Version") == 2, "DynamicPolicy v1 must migrate to v2.");
		Check(TokenText(GetToken(dynamicRecord, "futureState")).Contains("opaque"),
			"DynamicPolicy migration must preserve unknown forward-compatible state.");
		object dynamicV3 = NormalizeJObject(codec, "TryNormalizeDynamicV1ToV3",
			"{\"Version\":2,\"PolicyObjectId\":\"dynamic-v2\",\"OwnerKingdomId\":\"k1\"}", out _);
		Check(TokenInt(dynamicV3, "Version") == 3
			&& string.Equals(TokenString(dynamicV3, "IssuerKingdomId"), "k1", StringComparison.Ordinal),
			"DynamicPolicy v2 must migrate to v3 with a stable issuer anchor.");

		object activeV6 = NormalizeJObject(codec, "TryNormalizeActiveV4ToV6",
			"{\"Version\":5,\"EffectId\":\"active-v5\",\"RemainingDays\":3,\"LastAppliedDay\":7,\"ModuleEffects\":[]}", out _);
		Check(TokenInt(activeV6, "Version") == 6
			&& !TokenBool(activeV6, "IsPermanentEffect")
			&& TokenInt(activeV6, "DailyMaintenanceGoldCost") == 0
			&& !TokenBool(activeV6, "MaintenanceChargeEnabled")
			&& TokenBool(activeV6, "MaintenanceFunded")
			&& TokenInt(activeV6, "LastEffectProcessedDay") == 7,
			"Active v5 must migrate as a finite, funded, no-maintenance v6 effect.");
		object activeV7 = NormalizeJObject(codec, "TryNormalizeActiveV4ToV7",
			"{\"Version\":6,\"EffectId\":\"active-v6\",\"TargetKingdomId\":\"k1\",\"RemainingDays\":3,\"ModuleEffects\":[]}", out _);
		Check(TokenInt(activeV7, "Version") == 7
			&& string.Equals(TokenString(activeV7, "IssuerKingdomId"), "k1", StringComparison.Ordinal),
			"Active effect v6 must migrate to v7 with a stable issuer anchor for TargetPlan refresh.");
		object activeV8 = NormalizeJObject(codec, "TryNormalizeActiveV4ToV8",
			TokenText(activeV7), out _);
		Check(TokenInt(activeV8, "Version") == 8,
			"Active effect v7 must migrate to v8 without fabricating a Linked mechanism contract.");
		object dynamicV4 = NormalizeJObject(codec, "TryNormalizeDynamicV1ToV4",
			"{\"Version\":3,\"PolicyObjectId\":\"dynamic-v3\",\"Status\":\"active\",\"IssuerKingdomId\":\"k1\"}", out _);
		Check(TokenInt(dynamicV4, "Version") == 4
			&& string.IsNullOrWhiteSpace(TokenString(dynamicV4, "ActiveEffectId"))
			&& !TokenBool(dynamicV4, "RequiresEffectBundle")
			&& string.Equals(TokenString(dynamicV4, "CommitState"), "commitPending", StringComparison.Ordinal),
			"Ambiguous legacy active dynamic policies must enter commitPending for cross-store reconciliation.");

		object policyV3 = NormalizeJObject(codec, "TryNormalizePolicyRecordV1ToV3",
			"{\"Version\":2,\"RecordId\":\"policy-v2\",\"RequiredGoldCost\":12,\"GoldCost\":9,\"Effects\":[]}", out _);
		Check(TokenInt(policyV3, "Version") == 3
			&& TokenInt(policyV3, "RequiredGoldCost") == 12
			&& TokenInt(policyV3, "GoldCost") == 9
			&& TokenInt(policyV3, "DailyMaintenanceGoldCost") == 0,
			"Policy v2 startup cost fields must survive v3 migration while missing maintenance defaults to zero.");

		object localV5 = NormalizeJObject(codec, "TryNormalizeLocalV1ToV5",
			"{\"Version\":4,\"RecordId\":\"local-v4-expired\",\"ScopeKind\":\"local\",\"Status\":\"expired\",\"RequiredGoldCost\":8,\"InitialActualGoldCost\":6,\"Effects\":[]}", out _);
		Check(TokenInt(localV5, "Version") == 5
			&& string.Equals(TokenString(localV5, "Status"), "active", StringComparison.Ordinal)
			&& string.Equals(TokenString(localV5, "EffectStatus"), "expired", StringComparison.Ordinal)
			&& TokenInt(localV5, "DailyMaintenanceGoldCost") == 0,
			"An old expired local effect must migrate to an active policy record with a separately expired effect state.");

		object vassalV5 = NormalizeJObject(codec, "TryNormalizeLocalV1ToV5",
			"{\"Version\":4,\"RecordId\":\"vassal-v4-expired\",\"ScopeKind\":\"vassal\",\"Status\":\"expired\",\"Effects\":[]}", out _);
		Check(TokenInt(vassalV5, "Version") == 5
			&& string.Equals(TokenString(vassalV5, "Status"), "expired", StringComparison.Ordinal)
			&& string.Equals(TokenString(vassalV5, "EffectStatus"), "expired", StringComparison.Ordinal),
			"Vassal policy migration must preserve the legacy policy lifecycle instead of applying player-local permanence rules.");
		object localV6 = NormalizeJObject(codec, "TryNormalizeLocalV1ToV6",
			"{\"Version\":5,\"RecordId\":\"vassal-rollback\",\"ScopeKind\":\"vassal\","
			+ "\"Status\":\"active\",\"EndReason\":\"rollbackPending:legacy\",\"Effects\":[]}", out _);
		Check(TokenInt(localV6, "Version") == 6
			&& string.Equals(TokenString(localV6, "ExternalCommitState"), "externalCommitPending", StringComparison.Ordinal)
			&& TokenString(localV6, "ExternalLastError").Contains("rollbackPending:"),
			"Legacy rollbackPending vassal records must migrate to observable external reconciliation, not treaty reconstruction.");

		Type localSaveType = SutType("AnimusForge.CustomPolicyBehavior+LocalPolicyRecordSaveData");
		foreach (string propertyName in new[]
		{
			"ExternalTransactionId", "ExternalAgreementId", "ExternalIdempotencyKey", "ExternalCommitState",
			"ExternalInputsCaptured", "ExternalPublicationCost", "ExternalQualityDelta",
			"ExternalIndependenceBefore", "ExternalIndependenceExpected", "ExternalIndependenceActual",
			"ExternalBreakawayExpected", "ExternalBreakawayActual", "ExternalLastError"
		})
		{
			Check(localSaveType.GetProperty(propertyName, All) != null,
				"Vassal external commit save contract is missing " + propertyName + ".");
		}
		Type vassalageBehavior = SutType("AnimusForge.VassalageBehavior");
		Check(vassalageBehavior.GetMethod("TryPrepareDirectVassalPolicyIndependenceForExternal", All) != null
			&& vassalageBehavior.GetMethod("ObserveDirectVassalPolicyIndependenceForExternal", All) != null
			&& vassalageBehavior.GetMethod("CommitDirectVassalPolicyIndependenceForExternal", All) != null,
			"Vassal mutation must expose separate prepare, commit and observe contracts.");
		Type externalObservationType = SutType("AnimusForge.VassalPolicyExternalCommitObservation");
		object unchangedObservation = Activator.CreateInstance(externalObservationType, nonPublic: true);
		SetProperty(externalObservationType, unchangedObservation, "Observable", true);
		SetProperty(externalObservationType, unchangedObservation, "AgreementPresent", true);
		SetProperty(externalObservationType, unchangedObservation, "AgreementMatches", true);
		SetProperty(externalObservationType, unchangedObservation, "IndependenceActual", 20);
		object rollbackAction = InvokeStatic(SutType("AnimusForge.CustomPolicyBehavior"),
			"ClassifyVassalExternalReconciliationAction",
			new object[] { true, unchangedObservation, 20, 4, 5 }, 5);
		object retryAction = InvokeStatic(SutType("AnimusForge.CustomPolicyBehavior"),
			"ClassifyVassalExternalReconciliationAction",
			new object[] { false, unchangedObservation, 20, 4, 5 }, 5);
		SetProperty(externalObservationType, unchangedObservation, "IndependenceActual", 21);
		object acceptAction = InvokeStatic(SutType("AnimusForge.CustomPolicyBehavior"),
			"ClassifyVassalExternalReconciliationAction",
			new object[] { true, unchangedObservation, 20, 4, 5 }, 5);
		Check(string.Equals(rollbackAction.ToString(), "RollbackAfState", StringComparison.Ordinal)
			&& string.Equals(retryAction.ToString(), "RetryExternalCommit", StringComparison.Ordinal)
			&& string.Equals(acceptAction.ToString(), "AcceptExternalState", StringComparison.Ordinal),
			"A rollbackPending vassal record may reconcile changed external state, but must never retry the external mutation when unchanged.");
		object[] capturedInputs = { true, 9, -3, 20, 26, null, null };
		InvokeStatic(SutType("AnimusForge.CustomPolicyBehavior"),
			"ResolveVassalExternalMutationInputs", capturedInputs, 7);
		object[] legacyInputs = { false, 9, -3, 20, 25, null, null };
		InvokeStatic(SutType("AnimusForge.CustomPolicyBehavior"),
			"ResolveVassalExternalMutationInputs", legacyInputs, 7);
		Check((int)capturedInputs[5] == 9 && (int)capturedInputs[6] == -3
			&& (int)legacyInputs[5] == 5 && (int)legacyInputs[6] == 0,
			"Vassal external replay must preserve captured mutation inputs and derive legacy retries only from the frozen before/expected contract.");
		Type customPolicyBehavior = SutType("AnimusForge.CustomPolicyBehavior");
		object reconciliationBehavior = Activator.CreateInstance(customPolicyBehavior);
		Dictionary<string, string> localRecords = (Dictionary<string, string>)customPolicyBehavior
			.GetField("_localPolicyRecords", All).GetValue(reconciliationBehavior);
		localRecords["vassal-reconciled"] = new JObject
		{
			["Version"] = 6,
			["RecordId"] = "vassal-reconciled",
			["ScopeKind"] = "vassal",
			["Status"] = "relationship_ended",
			["EndReason"] = "rollbackPending:legacy-compensation",
			["ExternalCommitState"] = "externalCommittedReconciled",
			["ExternalIndependenceActual"] = 31,
			["Effects"] = new JArray()
		}.ToString(Formatting.None);
		InvokeInstance(customPolicyBehavior, reconciliationBehavior,
			"FinalizeVassalRollbackPendingAfterExternalCommit",
			new object[] { "vassal-reconciled", "observed external state" }, 2);
		JObject finalizedVassalRecord = JObject.Parse(localRecords["vassal-reconciled"]);
		Check(TokenString(finalizedVassalRecord, "EndReason").StartsWith("externalCommittedReconciled:", StringComparison.Ordinal)
			&& string.Equals(TokenString(finalizedVassalRecord, "ExternalCommitState"), "externalCommittedReconciled", StringComparison.Ordinal)
			&& TokenInt(finalizedVassalRecord, "ExternalIndependenceActual") == 31,
			"Observed external mutation must close the rollbackPending reconciliation lane without erasing authoritative external state.");
		TestPolicySystemStructuredLogContracts();
	}

	private static void TestPolicySystemStructuredLogContracts()
	{
		Type policyLog = SutType("AnimusForge.PolicySystemLog");
		FieldInfo fileName = policyLog.GetField("FileName", All);
		MethodInfo transactionWriter = policyLog.GetMethod("Transaction", All);
		MethodInfo lifecycleWriter = policyLog.GetMethod("Lifecycle", All);
		MethodInfo nextSequence = policyLog.GetMethod("NextSequence", All);
		MethodInfo buildEventJson = policyLog.GetMethod("BuildEventJson", All);
		MethodInfo buildLegacyContext = policyLog.GetMethod("BuildLegacyContext", All);
		MethodInfo shouldEmitRelease = policyLog.GetMethod("ShouldEmitRelease", All);
		Type contextType = SutType("AnimusForge.PolicyLogContext");
		HashSet<string> releaseStages = new HashSet<string>(
			Items(policyLog.GetField("ReleaseStages", All)?.GetValue(null))
				.Select(value => value?.ToString() ?? string.Empty),
			StringComparer.OrdinalIgnoreCase);
		Check(fileName != null
			&& string.Equals(Convert.ToString(fileName.GetRawConstantValue()), "PolicySystem.txt", StringComparison.Ordinal)
			&& policyLog.GetField("TransactionFileName", All) == null,
			"PolicySystem logging must have exactly one source-level file target: PolicySystem.txt.");
		Check(transactionWriter != null
			&& lifecycleWriter != null
			&& nextSequence != null
			&& buildEventJson != null
			&& buildLegacyContext != null
			&& shouldEmitRelease != null
			&& contextType != null,
			"PolicySystem logging must expose the compatible transaction writer plus the structured lifecycle serializer/context.");
		Check(new[]
		{
			"generation-complete", "published", "adopted", "abolished", "commit-complete",
			"active-bundle-created", "renewal-committed", "abolition-complete", "expiry-complete",
			"save-summary", "load-summary", "load-normalized"
		}.All(releaseStages.Contains)
			&& !releaseStages.Contains("generation-start")
			&& !releaseStages.Contains("daily-start")
			&& !releaseStages.Contains("daily-complete")
			&& !releaseStages.Contains("receipt-created")
			&& !releaseStages.Contains("llm-stage-usage"),
			"Release policy logging must retain outcomes and save/load summaries while suppressing detailed and recurring success stages.");
		Check((bool)shouldEmitRelease.Invoke(null, new object[] { "generation-complete", false, false })
			&& (bool)shouldEmitRelease.Invoke(null, new object[] { "daily-complete", true, false })
			&& (bool)shouldEmitRelease.Invoke(null, new object[] { "daily-complete", false, true })
			&& !(bool)shouldEmitRelease.Invoke(null, new object[] { "generation-start", false, false })
			&& !(bool)shouldEmitRelease.Invoke(null, new object[] { "daily-start", false, false })
			&& !(bool)shouldEmitRelease.Invoke(null, new object[] { "daily-complete", false, false }),
			"Release filter must always retain summaries, failures, and warnings while dropping detailed recurring successes.");
		long[] concurrentSequences = new long[128];
		Parallel.For(0, concurrentSequences.Length, index =>
		{
			concurrentSequences[index] = Convert.ToInt64(nextSequence.Invoke(null, null), CultureInfo.InvariantCulture);
		});
		long[] orderedSequences = concurrentSequences.OrderBy(value => value).ToArray();
		Check(orderedSequences.Distinct().Count() == orderedSequences.Length
			&& orderedSequences.Zip(orderedSequences.Skip(1), (left, right) => right - left).All(delta => delta == 1L),
			"Concurrent policy log sequence allocation must remain unique and contiguous.");
		Check(transactionWriter.GetParameters().Select(parameter => parameter.Name).SequenceEqual(new[]
		{
			"transactionId", "recordId", "effectId", "mechanismId", "stage", "result", "errorKind",
			"targetHash", "targetCount", "costReceipt", "executionReceipt", "stateBefore", "stateAfter"
		}, StringComparer.Ordinal),
			"Policy transaction writer must retain its existing call contract while changing only the sink.");

		object context = Activator.CreateInstance(contextType, nonPublic: true);
		SetField(contextType, context, "RequestId", "request-contract");
		SetField(contextType, context, "Version", "1.2.3.4");
		SetField(contextType, context, "GenerationId", "request-contract");
		SetField(contextType, context, "TransactionId", "transaction-contract");
		SetField(contextType, context, "RecordId", "record-contract");
		SetField(contextType, context, "EffectId", "effect-contract");
		SetField(contextType, context, "MechanismId", "mechanism-contract");
		SetField(contextType, context, "InstanceId", "instance-contract");
		SetField(contextType, context, "ReceiptId", "receipt-contract");
		SetField(contextType, context, "Attempt", (int?)2);
		SetField(contextType, context, "TargetHash", "target-hash-contract");
		SetField(contextType, context, "TargetCount", (int?)3);
		SetField(contextType, context, "Gold", (long?)120L);
		SetField(contextType, context, "Influence", (double?)4.5d);
		SetField(contextType, context, "Route", "https://private.example/v1/chat/completions");
		string json = Convert.ToString(buildEventJson.Invoke(null, new object[]
		{
			"Player", "commit-complete", "success", "lifecycle", "info", context,
			42L, new DateTime(2026, 8, 25, 1, 2, 3, DateTimeKind.Utc)
		}), CultureInfo.InvariantCulture);
		JObject parsed = JObject.Parse(json);
		Check(!json.Contains("\r") && !json.Contains("\n")
			&& TokenInt(parsed, "schema") == 1
			&& TokenInt(parsed, "sequence") == 42
			&& TokenString(parsed, "stage") == "commit-complete"
			&& TokenString(parsed, "version") == "1.2.3.4"
			&& TokenString(parsed, "requestId") == "request-contract"
			&& TokenString(parsed, "generationId") == "request-contract"
			&& TokenString(parsed, "transactionId") == "transaction-contract"
			&& TokenString(parsed, "recordId") == "record-contract"
			&& TokenString(parsed, "effectId") == "effect-contract"
			&& TokenString(parsed, "instanceId") == "instance-contract"
			&& TokenString(parsed, "receiptId") == "receipt-contract"
			&& TokenInt(parsed, "attempt") == 2
			&& TokenInt(parsed, "targetCount") == 3
			&& json.IndexOf("private.example", StringComparison.OrdinalIgnoreCase) < 0,
			"Policy lifecycle events must be independently parseable one-line JSON with the complete correlation chain.");

		const string sensitive = "Bearer secret-key https://private.example prompt player-private response-body";
		object legacyContext = buildLegacyContext.Invoke(null, new object[] { sensitive, "raw response\n" + sensitive });
		string redactedJson = Convert.ToString(buildEventJson.Invoke(null, new object[]
		{
			"Npc", "generation-api-parse-failed", "failed", "failure", "error", legacyContext,
			43L, new DateTime(2026, 8, 25, 1, 2, 4, DateTimeKind.Utc)
		}), CultureInfo.InvariantCulture);
		JObject redacted = JObject.Parse(redactedJson);
		Check(redactedJson.IndexOf("secret-key", StringComparison.OrdinalIgnoreCase) < 0
			&& redactedJson.IndexOf("private.example", StringComparison.OrdinalIgnoreCase) < 0
			&& redactedJson.IndexOf("player-private", StringComparison.OrdinalIgnoreCase) < 0
			&& TokenInt(redacted, "messageChars") == sensitive.Length
			&& !string.IsNullOrWhiteSpace(TokenString(redacted, "messageHash"))
			&& !string.IsNullOrWhiteSpace(TokenString(redacted, "detailHash")),
			"Legacy policy log text must be represented only by bounded metadata and stable hashes.");

		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string policyRoot = Path.Combine(repositoryRoot, "PolicySystem");
		string[] policySources = Directory.GetFiles(policyRoot, "*.cs", SearchOption.AllDirectories);
		string combinedPolicySource = string.Join("\n", policySources.Select(path => File.ReadAllText(path, Encoding.UTF8)));
		foreach (string requiredStage in new[]
		{
			"generation-start", "generation-complete", "generation-failed", "generation-stale-discarded",
			"pending-created", "agenda-submitted", "agenda-approved", "agenda-rejected",
			"commit-start", "commit-step", "commit-complete", "commit-failed",
			"cost-committed", "cost-refunded", "active-bundle-created", "instance-created", "instance-ended",
			"one-shot-start", "one-shot-complete", "scheduled-start", "scheduled-complete",
			"daily-start", "daily-complete", "receipt-created", "compensation-start", "compensation-complete",
			"rollback-start", "rollback-complete", "save-summary", "load-summary", "load-normalized",
			"renewal-start", "renewal-committed", "abolition-start", "abolition-complete", "expiry-complete"
		})
		{
			Check(combinedPolicySource.Contains("\"" + requiredStage + "\""),
				"Policy lifecycle stage is missing from source: " + requiredStage);
		}
		Check(combinedPolicySource.IndexOf("PolicySystemTransactions.jsonl", StringComparison.Ordinal) < 0,
			"PolicySystem source must stop appending the legacy transaction JSONL file.");
		foreach (string sourcePath in policySources.Where(path => !path.EndsWith("PolicySystemLog.cs", StringComparison.OrdinalIgnoreCase)))
		{
			string source = File.ReadAllText(sourcePath, Encoding.UTF8);
			Check(source.IndexOf("Logger.Log(", StringComparison.Ordinal) < 0
				&& source.IndexOf("Logger.RecordTokenStats", StringComparison.Ordinal) < 0
				&& source.IndexOf("Logger.LogToFile(", StringComparison.Ordinal) < 0,
				"PolicySystem source must not bypass the single PolicySystemLog sink: " + sourcePath);
		}
		string llmSource = File.ReadAllText(Path.Combine(policyRoot, "Npc", "PolicyLlmClient.cs"), Encoding.UTF8);
		Check(llmSource.IndexOf("BuildHttpErrorTokenStatsText", StringComparison.Ordinal) < 0
			&& llmSource.IndexOf("BuildHttpSuccessTokenStatsText", StringComparison.Ordinal) < 0
			&& llmSource.IndexOf("raw_sample=", StringComparison.Ordinal) < 0
			&& llmSource.IndexOf("response_body=", StringComparison.Ordinal) < 0,
			"Policy API logging must not retain request/response or raw parse samples.");
		string policyLogSource = File.ReadAllText(Path.Combine(policyRoot, "Core", "PolicySystemLog.cs"), Encoding.UTF8);
		Check(policyLogSource.Contains("Logger.IsVerboseModLogicEnabled")
			&& policyLogSource.Contains("ContainsOperationalWarningMarker")
			&& policyLogSource.Contains("if (!ShouldEmit(normalizedStage, failed, warning))")
			&& policyLogSource.Contains("if (!ShouldEmit(normalizedStage, failure, warning))"),
			"Policy logging must keep failures/warnings, gate detailed events centrally, and restore them through the existing verbose-log switch.");
	}

	private static void TestNpcLegacyMigrations()
	{
		Type behavior = SutType("AnimusForge.NpcRulerPolicyBehavior");
		MethodInfo deserialize = behavior.GetMethods(All).Single(method =>
			method.Name == "DeserializeRecord" && method.IsStatic && method.GetParameters().Length == 1
			&& method.GetParameters()[0].ParameterType == typeof(string));
		for (int versionIndex = 0; versionIndex < 3; versionIndex++)
		{
			int version = new[] { 1, 3, 4 }[versionIndex];
			string json = "{\"Version\":" + version.ToString(CultureInfo.InvariantCulture)
				+ ",\"policyId\":\"npc-v" + version.ToString(CultureInfo.InvariantCulture)
				+ "\",\"kingdomId\":\"k1\",\"kingdomName\":\"Kingdom\",\"Day\":10,\"durationDays\":8,"
				+ "\"effects\":[{\"effectId\":\"npc-effect-v" + version.ToString(CultureInfo.InvariantCulture)
				+ "\",\"targetKingdomId\":\"k1\",\"targetKingdomName\":\"Kingdom\",\"durationDays\":8,"
				+ "\"remainingDays\":8,\"prosperityDailyDeltaPerTown\":2,\"kingdomStabilityDailyDelta\":3}]}";
			object record = deserialize.Invoke(null, new object[] { json });
			Check(record != null, "NPC v" + version + " legacy record must deserialize.");
			Check(Convert.ToInt32(Property(record.GetType(), record, "Version"), CultureInfo.InvariantCulture) == 6,
				"NPC v" + version + " must normalize to the current v6 envelope.");
			Check(string.Equals(Convert.ToString(Property(record.GetType(), record, "AgendaStatus"), CultureInfo.InvariantCulture), "abolished", StringComparison.Ordinal),
				"NPC v" + version + " fixed-field policy must be stopped instead of executing legacy effects.");
			object effect = Items(Property(record.GetType(), record, "Effects")).Single();
			object[] moduleEffects = Items(Property(effect.GetType(), effect, "ModuleEffects")).ToArray();
			Check(moduleEffects.Length == 0
				&& Convert.ToBoolean(Property(effect.GetType(), effect, "IsEnded"), CultureInfo.InvariantCulture)
				&& Convert.ToInt32(Property(effect.GetType(), effect, "RemainingDays"), CultureInfo.InvariantCulture) == 0,
				"NPC v" + version + " fixed-field effects must become inert ended history rows.");
		}
	}

	private static void TestPolicyReReviewContracts()
	{
		Type codec = SutType("AnimusForge.PolicyEffects.PolicyEffectSaveCodec");
		MethodInfo legacyActiveShape = codec.GetMethod("IsLegacyStoppedActiveV5Shape", All);
		Check(legacyActiveShape != null,
			"Save codec must expose a shape-first legacy Active v5 stop discriminator.");
		JObject legacyActive = JObject.Parse(
			"{\"Version\":5,\"EffectId\":\"legacy-active\",\"RecordId\":\"legacy-record\"," +
			"\"prosperityDailyDeltaPerTown\":1,\"volunteerProductionPercent\":0,\"clanInfluenceDailyDelta\":0}");
		JObject modularActive = JObject.Parse(
			"{\"Version\":5,\"EffectId\":\"module-active\",\"RecordId\":\"module-record\",\"ModuleEffects\":[]}");
		Check((bool)legacyActiveShape.Invoke(null, new object[] { legacyActive })
			&& !(bool)legacyActiveShape.Invoke(null, new object[] { modularActive }),
			"Legacy Active v5 detection must use fixed-field shape and must not stop modular v5 rows.");

		MethodInfo stopDynamic = codec.GetMethod("TryNormalizeLegacyStoppedDynamicPolicy", All);
		object[] dynamicArgs =
		{
			JObject.Parse("{\"Version\":1,\"PolicyObjectId\":\"af_policy:legacy\",\"RecordId\":\"legacy-record\"," +
				"\"Source\":\"player\",\"OwnerKingdomId\":\"k1\",\"PolicyName\":\"旧政策\"," +
				"\"PolicyContent\":\"这是必须保留的完整旧政策正文。\",\"Status\":\"active\"," +
				"\"PlayerPayloadJson\":\"{bad legacy payload}\"}"),
			null,
			null
		};
		Check(stopDynamic != null && (bool)stopDynamic.Invoke(null, dynamicArgs),
			"Legacy Dynamic v1 must have a dedicated stopped-history normalization path.");
		JObject stoppedDynamic = (JObject)dynamicArgs[1];
		Check(TokenInt(stoppedDynamic, "Version") == 4
			&& string.Equals(TokenString(stoppedDynamic, "Status"), "abolished", StringComparison.Ordinal)
			&& string.Equals(TokenString(stoppedDynamic, "CommitState"), "ended", StringComparison.Ordinal)
			&& string.Equals(TokenString(stoppedDynamic, "PolicyContent"), "这是必须保留的完整旧政策正文。", StringComparison.Ordinal)
			&& string.IsNullOrWhiteSpace(TokenString(stoppedDynamic, "PlayerPayloadJson")),
			"Stopped Dynamic normalization must preserve the published text and discard incompatible execution payloads.");

		MethodInfo stopLocal = codec.GetMethod("TryNormalizeLegacyStoppedLocalPolicy", All);
		object[] localArgs =
		{
			JObject.Parse("{\"Version\":4,\"RecordId\":\"legacy-local\",\"ScopeKind\":\"local\"," +
				"\"PolicyName\":\"旧地方政策\",\"PolicyContent\":\"地方政策完整正文\",\"Status\":\"active\"," +
				"\"OriginalDurationDays\":20,\"OriginalTargetFiefIds\":[\"town-a\"]," +
				"\"prosperityDailyDeltaPerTown\":2,\"Effects\":[{\"prosperityDailyDeltaPerTown\":2}]}"),
			null,
			null
		};
		Check(stopLocal != null && (bool)stopLocal.Invoke(null, localArgs),
			"Legacy Local v4 must have a dedicated stopped-history normalization path.");
		JObject stoppedLocal = (JObject)localArgs[1];
		Check(TokenInt(stoppedLocal, "Version") == 6
			&& string.Equals(TokenString(stoppedLocal, "Status"), "abolished", StringComparison.Ordinal)
			&& string.Equals(TokenString(stoppedLocal, "EffectStatus"), "abolished", StringComparison.Ordinal)
			&& string.Equals(TokenString(stoppedLocal, "PolicyContent"), "地方政策完整正文", StringComparison.Ordinal)
			&& TokenArray(stoppedLocal, "Effects").Length == 0,
			"Stopped Local normalization must preserve reusable text/targets while removing legacy runtime effects.");

		Type requestType = SutType("AnimusForge.CustomPolicyBehavior+PolicyDraftRequest");
		Type dynamicType = SutType("AnimusForge.CustomPolicyBehavior+DynamicPolicySaveData");
		Type localType = SutType("AnimusForge.CustomPolicyBehavior+LocalPolicyRecordSaveData");
		Type npcType = SutType("AnimusForge.NpcRulerPolicyRecord");
		foreach (Type type in new[] { requestType, dynamicType, localType, npcType })
		{
			foreach (string propertyName in new[]
			{
				"ReReviewRootRecordId", "ReReviewSourceRecordId", "SupersedesRecordId", "ReReviewReplacementCommitted"
			})
			{
				Check(type.GetProperty(propertyName, All) != null,
					type.FullName + " must persist re-review lineage field " + propertyName + ".");
			}
		}

		Type behavior = SutType("AnimusForge.CustomPolicyBehavior");
		Check(behavior.GetMethod("TryBuildPolicyReReviewContext", All) != null
			&& behavior.GetMethod("FinalizePolicyReReviewReplacement", All) != null
			&& behavior.GetMethod("ReconcilePolicyReReviewReplacementsAfterLoad", All) != null,
			"Policy behavior must provide template resolution, post-commit replacement, and reload reconciliation.");

		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string kingdomUi = File.ReadAllText(Path.Combine(repositoryRoot, "PolicySystem", "UI", "KingdomPolicyUi.cs"), Encoding.UTF8);
		string localUi = File.ReadAllText(Path.Combine(repositoryRoot, "PolicySystem", "UI", "LocalPolicyUi.cs"), Encoding.UTF8);
		string kingdomPrefab = File.ReadAllText(Path.Combine(repositoryRoot, "AnimusForge", "GUI", "Prefabs", "CustomPolicyHistoryPopup.xml"), Encoding.UTF8);
		string localPrefab = File.ReadAllText(Path.Combine(repositoryRoot, "AnimusForge", "GUI", "Prefabs", "LocalPolicyHistoryPopup.xml"), Encoding.UTF8);
		Check(kingdomUi.Contains("ExecuteReReview") && kingdomUi.Contains("CanReReview")
			&& localUi.Contains("ExecuteReReview") && localUi.Contains("CanReReview")
			&& kingdomPrefab.Contains("Command.Click=\"ExecuteReReview\"")
			&& localPrefab.Contains("Command.Click=\"ExecuteReReview\""),
			"Kingdom, local, and vassal history UI must expose enabled re-review commands.");

		string worldInboxSource = File.ReadAllText(Path.Combine(repositoryRoot, "WorldEvents", "WorldEventInbox.cs"), Encoding.UTF8);
		string worldDiplomacySource = File.ReadAllText(Path.Combine(repositoryRoot, "WorldDiplomacyBehavior.cs"), Encoding.UTF8);
		string policyGenerationSource = File.ReadAllText(Path.Combine(repositoryRoot, "PolicySystem", "Npc", "NpcRulerPolicyBehavior.Generation.cs"), Encoding.UTF8);
		string policyManagementSource = File.ReadAllText(Path.Combine(repositoryRoot, "PolicySystem", "Core", "CustomPolicyBehavior.Management.cs"), Encoding.UTF8);
		string terminalSource = File.ReadAllText(Path.Combine(repositoryRoot, "AnimusForgeTerminalBehavior.cs"), Encoding.UTF8);
		string worldInboxPrefab = File.ReadAllText(Path.Combine(repositoryRoot, "AnimusForge", "GUI", "Prefabs", "AnimusForgeWorldEventInboxPopup.xml"), Encoding.UTF8);
		Check(terminalSource.Contains("WorldDiplomacyBehavior.ShowRoyalAnnouncementArchive()")
			&& worldInboxPrefab.Contains("Command.Click=\"ExecuteReReview\"")
			&& worldInboxPrefab.Contains("IsVisible=\"@ShowSelectedRecordReReview\"")
			&& worldInboxPrefab.Contains("IsEnabled=\"@CanReReviewSelectedRecord\""),
			"The real royal-announcement route and prefab must expose the kingdom policy re-review command.");
		Check(worldInboxSource.Contains("PolicyRecordId")
			&& worldInboxSource.Contains("IsPlayerPolicy")
			&& policyGenerationSource.Contains("PolicyRecordId = record.PolicyId")
			&& policyGenerationSource.Contains("IsPlayerPolicy = record.IsPlayerPolicy"),
			"New policy announcements must persist an explicit player-policy record association.");
		Check(worldDiplomacySource.Contains("entry.Version >= 2")
			&& worldDiplomacySource.Contains("legacyPrefix = \"npc_ruler_policy:\"")
			&& worldDiplomacySource.Contains("TryGetKingdomPolicyReReviewAvailabilityForExternal")
			&& policyManagementSource.Contains("OpenComposePopup(context, returnToSource)"),
			"Legacy announcement IDs must be an old-version-only candidate and must pass authoritative policy eligibility before re-review opens with the correct return route.");

		Type inboxEntryType = SutType("AnimusForge.AnimusForgeWorldEventInboxEntry");
		object inboxEntry = Activator.CreateInstance(inboxEntryType);
		Check(Convert.ToInt32(Property(inboxEntryType, inboxEntry, "Version"), CultureInfo.InvariantCulture) == 2
			&& inboxEntryType.GetProperty("PolicyRecordId", All) != null
			&& inboxEntryType.GetProperty("IsPlayerPolicy", All) != null,
			"World-event inbox v2 must expose additive policy identity fields while old JSON remains readable.");

		Type recordDataType = SutType("AnimusForge.WorldEventRecordData");
		Type countryDataType = SutType("AnimusForge.WorldEventCountryData");
		Type popupDataType = SutType("AnimusForge.WorldEventInboxPopupData");
		Type popupVmType = SutType("AnimusForge.AnimusForgeWorldEventInboxPopupVM");
		object recordData = Activator.CreateInstance(recordDataType);
		SetField(recordDataType, recordData, "EventId", "npc_ruler_policy:player-policy-record");
		SetField(recordDataType, recordData, "PolicyRecordId", "player-policy-record");
		SetField(recordDataType, recordData, "TitleText", "玩家王国政策");
		SetField(recordDataType, recordData, "ShowReReview", true);
		SetField(recordDataType, recordData, "CanReReview", true);
		object countryData = Activator.CreateInstance(countryDataType);
		SetField(countryDataType, countryData, "KingdomName", "Player Kingdom");
		((IList)countryDataType.GetField("Records", All).GetValue(countryData)).Add(recordData);
		object popupData = Activator.CreateInstance(popupDataType);
		((IList)popupDataType.GetField("Countries", All).GetValue(popupData)).Add(countryData);
		string selectedReReviewRecordId = string.Empty;
		object popupVm = Activator.CreateInstance(
			popupVmType,
			new object[]
			{
				popupData,
				new Action<string>(recordId => selectedReReviewRecordId = recordId),
				new Action(() => { })
			});
		InvokeInstance(popupVmType, popupVm, "ExecuteReReview", Array.Empty<object>(), 0);
		Check(string.Equals(selectedReReviewRecordId, "player-policy-record", StringComparison.Ordinal),
			"The selected royal-announcement VM record must pass its explicit policy record ID to the re-review callback.");

		SetField(recordDataType, recordData, "ShowReReview", false);
		SetField(recordDataType, recordData, "CanReReview", false);
		selectedReReviewRecordId = string.Empty;
		object nonPolicyPopupVm = Activator.CreateInstance(
			popupVmType,
			new object[]
			{
				popupData,
				new Action<string>(recordId => selectedReReviewRecordId = recordId),
				new Action(() => { })
			});
		InvokeInstance(popupVmType, nonPolicyPopupVm, "ExecuteReReview", Array.Empty<object>(), 0);
		Check(string.IsNullOrWhiteSpace(selectedReReviewRecordId),
			"A non-policy announcement must never invoke the kingdom policy re-review callback.");
	}

	private static void TestNpcUnifiedMultiTargetCanonicalization()
	{
		Type behavior = SutType("AnimusForge.NpcRulerPolicyBehavior");
		MethodInfo deserialize = behavior.GetMethods(All).Single(method =>
			method.Name == "DeserializeRecord" && method.IsStatic && method.GetParameters().Length == 1
			&& method.GetParameters()[0].ParameterType == typeof(string));
		JObject multiTarget = BuildNpcUnifiedMultiTargetRecord();
		object record = deserialize.Invoke(null, new object[] { multiTarget.ToString(Formatting.None) });
		Check(record != null, "A player unified record may persist one logical module instance in two kingdom display shells.");
		object[] effects = Items(Property(record.GetType(), record, "Effects")).ToArray();
		Check(effects.Length == 2, "NPC persistence must retain both player display shells.");
		object[] shellInstances = effects
			.SelectMany(effect => Items(Property(effect.GetType(), effect, "ModuleEffects")))
			.ToArray();
		Check(shellInstances.Length == 2,
			"NPC persistence must not discard a later shell merely because it shares the logical InstanceId.");
		string[] shellKingdomIds = shellInstances
			.Select(instance => ReadStringPropertyValues(Property(instance.GetType(), instance, "TargetSet"), "KingdomIds").Single())
			.OrderBy(value => value, StringComparer.Ordinal)
			.ToArray();
		Check(shellKingdomIds.SequenceEqual(new[] { "k1", "k2" }, StringComparer.Ordinal),
			"Each persisted display shell must retain its own target subset.");

		Array typedShells = Array.CreateInstance(shellInstances[0].GetType(), shellInstances.Length);
		for (int index = 0; index < shellInstances.Length; index++)
		{
			typedShells.SetValue(shellInstances[index], index);
		}
		object[] coalesce = { typedShells, null, null };
		Check((bool)InvokeStatic(behavior, "TryCoalesceNpcPolicyEffectShellInstances", coalesce, 3),
			"NPC target shells must coalesce into a canonical logical instance: " + coalesce[2]);
		object canonical = Items(coalesce[1]).Single();
		Check(ReadStringPropertyValues(Property(canonical.GetType(), canonical, "TargetSet"), "KingdomIds")
			.SequenceEqual(new[] { "k1", "k2" }, StringComparer.Ordinal),
			"NPC canonical-by-InstanceId authority must union both kingdom targets without loss.");
		object[] receipts = Items(Property(record.GetType(), record, "ExecutionReceipts")).ToArray();
		Check(receipts.Length == 1,
			"Mirrored shell receipts must normalize to one receipt per logical InstanceId.");
		Check(ReadStringPropertyValues(Property(receipts[0].GetType(), receipts[0], "TargetSet"), "KingdomIds")
			.SequenceEqual(new[] { "k1", "k2" }, StringComparer.Ordinal),
			"The canonical receipt must retain the union target set.");

		Type lifecycleStateType = SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState");
		SetProperty(canonical.GetType(), canonical, "LifecycleState", EnumValue(lifecycleStateType, "Failed"));
		SetProperty(canonical.GetType(), canonical, "RuntimeState", new JObject { ["retryCount"] = 3 });
		JObject updatedPayload = JObject.Parse(TokenText(Property(canonical.GetType(), canonical, "Payload")));
		updatedPayload["value"] = 4.25;
		SetProperty(canonical.GetType(), canonical, "Payload", updatedPayload);
		Array canonicalArray = Array.CreateInstance(canonical.GetType(), 1);
		canonicalArray.SetValue(canonical, 0);
		for (int index = 0; index < effects.Length; index++)
		{
			object existingShell = Items(Property(effects[index].GetType(), effects[index], "ModuleEffects")).Single();
			string originalTarget = ReadStringPropertyValues(
				Property(existingShell.GetType(), existingShell, "TargetSet"),
				"KingdomIds").Single();
			InvokeStatic(behavior, "MergeNpcPolicyModuleEffects", new object[] { effects[index], canonicalArray }, 2);
			object synchronized = Items(Property(effects[index].GetType(), effects[index], "ModuleEffects")).Single();
			Check(ReadStringPropertyValues(Property(synchronized.GetType(), synchronized, "TargetSet"), "KingdomIds")
				.SequenceEqual(new[] { originalTarget }, StringComparer.Ordinal),
				"Snapshot synchronization must preserve each display shell target subset.");
			Check(string.Equals(Property(synchronized.GetType(), synchronized, "LifecycleState").ToString(), "Failed", StringComparison.Ordinal)
				&& Math.Abs(JObject.Parse(TokenText(Property(synchronized.GetType(), synchronized, "Payload"))).Value<double>("value") - 4.25d) < 0.0001d
				&& JObject.Parse(TokenText(Property(synchronized.GetType(), synchronized, "RuntimeState"))).Value<int>("retryCount") == 3,
				"Snapshot synchronization must copy canonical payload, runtime state, and lifecycle to every shell.");
		}

		JObject conflict = (JObject)multiTarget.DeepClone();
		JObject conflictingInstance = (JObject)((JArray)((JObject)((JArray)conflict["effects"])[1])["moduleEffects"])[0];
		((JObject)conflictingInstance["payload"])["value"] = 9.5;
		object rejectedConflict = deserialize.Invoke(null, new object[] { conflict.ToString(Formatting.None) });
		Check(rejectedConflict == null,
			"Shells sharing an InstanceId but carrying conflicting payloads must fail closed.");
		JObject actorConflict = (JObject)multiTarget.DeepClone();
		JArray actorConflictEffects = (JArray)actorConflict["effects"];
		((JObject)((JArray)((JObject)actorConflictEffects[0])["moduleEffects"])[0])["actorHeroId"] = "ruler-alpha";
		((JObject)((JArray)((JObject)actorConflictEffects[1])["moduleEffects"])[0])["actorHeroId"] = "ruler-beta";
		Check(deserialize.Invoke(null, new object[] { actorConflict.ToString(Formatting.None) }) == null,
			"NPC shells sharing an InstanceId must reject conflicting frozen ActorHeroId values.");

		object twentyFour = deserialize.Invoke(null, new object[] { BuildNpcUniqueInstanceLimitRecord(24).ToString(Formatting.None) });
		Check(twentyFour != null,
			"Exactly 24 unique logical NPC runtime instances must be accepted after Composite expansion.");
		object twentyFive = deserialize.Invoke(null, new object[] { BuildNpcUniqueInstanceLimitRecord(25).ToString(Formatting.None) });
		Check(twentyFive == null,
			"A 25th unique logical NPC runtime instance must fail closed even though shell count is independent.");
		object mirroredPayload = deserialize.Invoke(null, new object[]
		{
			BuildNpcMirroredPayloadAccountingRecord(12).ToString(Formatting.None)
		});
		Check(mirroredPayload != null
			&& Items(Property(mirroredPayload.GetType(), mirroredPayload, "Effects")).Count() == 12,
			"The 32KiB aggregate limit must count a 3KiB payload once per logical InstanceId, not once per display shell.");
	}

	private static void TestNpcPlannedSnapshotDistributionContract()
	{
		Type behavior = SutType("AnimusForge.NpcRulerPolicyBehavior");
		MethodInfo deserialize = behavior.GetMethods(All).Single(method =>
			method.Name == "DeserializeRecord" && method.IsStatic && method.GetParameters().Length == 1
			&& method.GetParameters()[0].ParameterType == typeof(string));
		JObject persistedJson = BuildNpcUnifiedMultiTargetRecord();
		JArray effects = (JArray)persistedJson["effects"];
		effects.RemoveAt(1);
		JObject persistedInstanceJson = (JObject)((JArray)((JObject)effects[0])["moduleEffects"])[0];
		persistedInstanceJson["executionReceipt"] = null;
		JObject persistedTargetSetJson = (JObject)persistedInstanceJson["targetSet"];
		persistedTargetSetJson["selectorHandles"] = new JArray("P0");
		persistedTargetSetJson["targetPlans"] = new JArray(new JObject
		{
			["planVersion"] = 3,
			["resolverVersion"] = 2,
			["branches"] = new JArray(new JObject
			{
				["universe"] = "PrimaryFiefs",
				["scopeAnchor"] = "TargetKingdom",
				["entityType"] = "Town",
				["relation"] = "Domestic",
				["metric"] = "Militia",
				["sortDirection"] = "Descending",
				["cardinality"] = "TopN",
				["limit"] = 1
			})
		});
		object record = deserialize.Invoke(null, new object[] { persistedJson.ToString(Formatting.None) });
		Check(record != null, "The planned NPC snapshot fixture must deserialize.");
		object persistedInstance = Items(Property(
			Items(Property(record.GetType(), record, "Effects")).Single().GetType(),
			Items(Property(record.GetType(), record, "Effects")).Single(),
			"ModuleEffects")).Single();
		JObject canonicalInstanceJson = (JObject)persistedInstanceJson.DeepClone();
		((JObject)canonicalInstanceJson["targetSet"])["kingdomIds"] = new JArray();
		object canonicalInstance = TokenToObject(canonicalInstanceJson, persistedInstance.GetType());
		Array canonicalInstances = Array.CreateInstance(persistedInstance.GetType(), 1);
		canonicalInstances.SetValue(canonicalInstance, 0);
		Array receipts = Array.CreateInstance(SutType("AnimusForge.PolicyEffects.PolicyEffectExecutionReceipt"), 0);
		object[] distribute = { record, "npc-planned-effect", canonicalInstances, receipts, null };
		Check((bool)InvokeStatic(behavior, "TryDistributeNpcPolicyEffectBundle", distribute, 5),
			"A plan-authorized canonical snapshot must not inherit the NPC shell's direct KingdomIds: " + distribute[4]);
	}

	private static void TestNpcSingleKingdomTwoStageContracts()
	{
		Type behavior = SutType("AnimusForge.NpcRulerPolicyBehavior");
		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string npcGenerationSource = File.ReadAllText(Path.Combine(
			repositoryRoot, "PolicySystem", "Npc", "NpcRulerPolicyBehavior.Generation.cs"), Encoding.UTF8);
		Check(npcGenerationSource.Contains("CustomPolicyBehavior.AddPolicyEffectPrimaryTargetForModule")
			&& npcGenerationSource.Contains("PolicyEffectPrimaryTargetOrigin.TargetPlanPrimarySettlement")
			&& npcGenerationSource.Contains("targetSet.HeroIds = NormalizeNpcPolicyIds(targetSet.HeroIds)"),
			"NPC TargetPlan materialization must reuse the shared descriptor-driven primary-settlement projection path.");
		int bundleBuilderStart = npcGenerationSource.IndexOf(
			"private static bool TryBuildNpcEffectBundleRegistration", StringComparison.Ordinal);
		int bundleBuilderEnd = bundleBuilderStart >= 0
			? npcGenerationSource.IndexOf(
				"private static PolicyEffectCanonicalTargetSet BuildNpcKingdomTargetSet", bundleBuilderStart, StringComparison.Ordinal)
			: -1;
		string bundleBuilderSource = bundleBuilderStart >= 0 && bundleBuilderEnd > bundleBuilderStart
			? npcGenerationSource.Substring(bundleBuilderStart, bundleBuilderEnd - bundleBuilderStart)
			: string.Empty;
		Check(bundleBuilderSource.Contains("CloneNpcModuleEffectForBundle(instance, instance.TargetSet)")
			&& !bundleBuilderSource.Contains("instance.TargetSet?.KingdomIds")
			&& !bundleBuilderSource.Contains("BuildNpcKingdomTargetSet")
			&& !bundleBuilderSource.Contains("ApplyActorClanTargetExclusion")
			&& !bundleBuilderSource.Contains("PolicyEffectTargetJurisdiction.TryApply"),
			"NPC agenda adoption must preserve compiler-materialized targets and delegate target validation to the shared player bundle registrar.");
		int distributionStart = npcGenerationSource.IndexOf(
			"private static bool TryDistributeNpcPolicyEffectBundle", StringComparison.Ordinal);
		int distributionEnd = distributionStart >= 0
			? npcGenerationSource.IndexOf(
				"private static bool NpcPolicyIdSetsEqual", distributionStart, StringComparison.Ordinal)
			: -1;
		string distributionSource = distributionStart >= 0 && distributionEnd > distributionStart
			? npcGenerationSource.Substring(distributionStart, distributionEnd - distributionStart)
			: string.Empty;
		Check(distributionSource.Contains("PolicyEffectBundleContract.AreSameTargetSets")
			&& !distributionSource.Contains("canonical-kingdom-ids-empty")
			&& !distributionSource.Contains("BuildNpcKingdomTargetSet")
			&& !distributionSource.Contains("ApplyActorClanTargetExclusion"),
			"NPC canonical snapshot distribution must retain precise shared targets without reintroducing KingdomIds ownership or whole-kingdom expansion.");
		Check(npcGenerationSource.Contains("PolicyEffectModuleRouter.RouteAfterAssessment")
			&& npcGenerationSource.Contains("PolicyTargetHandleDirectoryBuilder.Build")
			&& npcGenerationSource.Contains("PolicyEffectDirectPlanContract.BuildOutputContract")
			&& npcGenerationSource.Contains("PolicyEffectPlanWireNormalizer.TryParseDirectPlayerEffectPlan")
			&& !npcGenerationSource.Contains("effectMappingVersion")
			&& !npcGenerationSource.Contains("effectIntents")
			&& !npcGenerationSource.Contains("TryExpandSemanticEffectMapping"),
			"NPC generation must share the player module router, target directory, direct plan contract, and wire parser without the old semantic mapper.");
		Check(Convert.ToInt32(InvokeStatic(behavior, "ResolveNpcRulerPolicyBatchSize", Array.Empty<object>(), 0), CultureInfo.InvariantCulture) == 1,
			"NPC policy scheduling must remain hard-limited to one kingdom per generation cycle.");
		string npcBehaviorSource = File.ReadAllText(Path.Combine(
			repositoryRoot, "PolicySystem", "Npc", "NpcRulerPolicyBehavior.cs"), Encoding.UTF8);
		string duelSettingsSource = File.ReadAllText(Path.Combine(repositoryRoot, "DuelSettings.cs"), Encoding.UTF8);
		int fixedBatchGetterIndex = duelSettingsSource.IndexOf(
			"public static int GetNpcRulerPolicyMaxKingdomsPerRequestForExternal()", StringComparison.Ordinal);
		string fixedBatchGetterSource = fixedBatchGetterIndex < 0
			? string.Empty
			: duelSettingsSource.Substring(fixedBatchGetterIndex, Math.Min(240, duelSettingsSource.Length - fixedBatchGetterIndex));
		Check(npcBehaviorSource.Contains("private const int MaxPoliciesPerBatch = 1;")
			&& fixedBatchGetterSource.Contains("return 1;")
			&& duelSettingsSource.Contains("[Obsolete(\"NPC ruler policy generation is fixed to one policy per check.\")]")
			&& duelSettingsSource.Contains("public int NpcRulerPolicyMaxKingdomsPerRequest { get; set; } = 1;")
			&& !duelSettingsSource.Contains("SettingPropertyInteger(\"单次生成政策数\""),
			"NPC publication must be fail-safe capped to one policy and expose no adjustable MCM batch-size setting.");

		Type contextType = behavior.GetNestedType("NpcRulerPolicyBatchContext", BindingFlags.NonPublic);
		Type kingdomContextType = behavior.GetNestedType("NpcRulerPolicyKingdomContext", BindingFlags.NonPublic);
		Type allowedTargetType = behavior.GetNestedType("NpcRulerPolicyAllowedEffectTarget", BindingFlags.NonPublic);
		Check(contextType != null && kingdomContextType != null && allowedTargetType != null,
			"NPC two-stage generation requires the existing single-kingdom context contracts.");
		Check(allowedTargetType.GetField("PlanHandle", All) != null
			&& allowedTargetType.GetField("TargetPlan", All) != null
			&& allowedTargetType.GetField("TargetPlanResolution", All) != null
			&& allowedTargetType.GetField("TargetPlanSnapshot", All) != null,
			"NPC frozen targets must carry an immutable generic TargetPlan handle, plan, resolution, and request snapshot.");
		object context = Activator.CreateInstance(contextType, nonPublic: true);
		SetField(contextType, context, "BatchId", "npc-two-stage-contract");
		SetField(contextType, context, "Day", 42);
		SetField(contextType, context, "GameDate", "contract-day");
		SetField(contextType, context, "BatchSize", 1);
		SetField(contextType, context, "CompactWorldContext", "CurrentWorldFacts{only=Kingdom West}");
		SetField(contextType, context, "CandidateModuleIds", new List<string>());
		SetField(contextType, context, "DetailedModuleIds", new List<string>());
		object kingdomContext = Activator.CreateInstance(kingdomContextType, nonPublic: true);
		SetField(kingdomContextType, kingdomContext, "KingdomId", "kingdom_west");
		SetField(kingdomContextType, kingdomContext, "KingdomName", "Kingdom West");
		SetField(kingdomContextType, kingdomContext, "RulerHeroId", "hero_west");
		SetField(kingdomContextType, kingdomContext, "RulerName", "Ruler West");
		SetField(kingdomContextType, kingdomContext, "EnemyPolicyMemory", "NPC_ENEMY_HISTORY_PROMPT_MARKER");
		Type npcDirectoryEntryType = SutType("AnimusForge.PolicyTargets.PolicyTargetHandleDirectoryEntry");
		IPolicyEffectModule npcFoodForDefaults = RequirePolicyEffectModule("foodPerDay");
		IPolicyEffectModule npcHeroGoldForDefaults = RequirePolicyEffectModule("heroGold");
		IPolicyEffectModule npcRaidBanForDefaults = RequirePolicyEffectModule("kingdomVillageRaidBan");
		object npcHomeKingdomEntry = Activator.CreateInstance(npcDirectoryEntryType);
		SetProperty(npcDirectoryEntryType, npcHomeKingdomEntry, "Kind", "kingdom");
		SetProperty(npcDirectoryEntryType, npcHomeKingdomEntry, "EntityId", "kingdom_west");
		object npcForeignKingdomEntry = Activator.CreateInstance(npcDirectoryEntryType);
		SetProperty(npcDirectoryEntryType, npcForeignKingdomEntry, "Kind", "kingdom");
		SetProperty(npcDirectoryEntryType, npcForeignKingdomEntry, "EntityId", "kingdom_east");
		object npcHeroEntry = Activator.CreateInstance(npcDirectoryEntryType);
		SetProperty(npcDirectoryEntryType, npcHeroEntry, "Kind", "hero");
		Check((bool)InvokeStatic(behavior, "IsNpcPolicyDefaultTargetHandle",
				new object[] { kingdomContext, npcHomeKingdomEntry, npcFoodForDefaults }, 3)
			&& !(bool)InvokeStatic(behavior, "IsNpcPolicyDefaultTargetHandle",
				new object[] { kingdomContext, npcForeignKingdomEntry, npcFoodForDefaults }, 3)
			&& !(bool)InvokeStatic(behavior, "IsNpcPolicyDefaultTargetHandle",
				new object[] { kingdomContext, npcHeroEntry, npcHeroGoldForDefaults }, 3)
			&& !(bool)InvokeStatic(behavior, "IsNpcPolicyDefaultTargetHandle",
				new object[] { kingdomContext, npcHomeKingdomEntry, npcHeroGoldForDefaults }, 3)
			&& (bool)InvokeStatic(behavior, "IsNpcPolicyDefaultTargetHandle",
				new object[] { kingdomContext, npcHomeKingdomEntry, npcRaidBanForDefaults }, 3)
			&& !(bool)InvokeStatic(behavior, "IsNpcPolicyDefaultTargetHandle",
				new object[] { kingdomContext, npcForeignKingdomEntry, npcRaidBanForDefaults }, 3),
			"NPC capability default-target classifier must default to the frozen ruler kingdom and leave hero-only or foreign targets as subsets.");
		object selfTarget = Activator.CreateInstance(allowedTargetType, nonPublic: true);
		SetField(allowedTargetType, selfTarget, "KingdomId", "kingdom_west");
		SetField(allowedTargetType, selfTarget, "KingdomName", "Kingdom West");
		SetField(allowedTargetType, selfTarget, "IsIssuer", true);
		IList allowedTargets = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(allowedTargetType));
		allowedTargets.Add(selfTarget);
		object npcPlanTarget = Activator.CreateInstance(allowedTargetType, nonPublic: true);
		SetField(allowedTargetType, npcPlanTarget, "KingdomId", "kingdom_west");
		SetField(allowedTargetType, npcPlanTarget, "KingdomName", "Kingdom West");
		SetField(allowedTargetType, npcPlanTarget, "IsIssuer", true);
		SetField(allowedTargetType, npcPlanTarget, "PlanHandle", "P0");
		SetField(allowedTargetType, npcPlanTarget, "PlanDisplayName", "民兵最高的城镇");
		SetField(allowedTargetType, npcPlanTarget, "PlanTargetCount", 1);
		Type npcTargetPlanType = SutType("AnimusForge.PolicyTargets.PolicyTargetPlanSaveData");
		object npcFrozenPlan = TokenToObject(JObject.Parse(
			"{\"planVersion\":3,\"resolverVersion\":2,\"branches\":[{"
			+ "\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\","
			+ "\"entityType\":\"Town\",\"relation\":\"Domestic\","
			+ "\"metric\":\"Militia\",\"sortDirection\":\"Descending\","
			+ "\"cardinality\":\"TopN\",\"limit\":1}]}"), npcTargetPlanType);
		SetField(allowedTargetType, npcPlanTarget, "TargetPlan", npcFrozenPlan);
		allowedTargets.Add(npcPlanTarget);
		SetField(kingdomContextType, kingdomContext, "AllowedEffectTargets", allowedTargets);
		IList kingdoms = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(kingdomContextType));
		kingdoms.Add(kingdomContext);
		SetField(contextType, context, "Kingdoms", kingdoms);
		SetField(contextType, context, "CompactWorldContext",
			(string)InvokeStatic(behavior, "BuildKingdomPromptContext", new[] { kingdomContext }, 1));

		object draftPrompt = InvokeStatic(behavior, "ComposeNpcPolicyDraftPrompt", new object[] { context, string.Empty }, 2);
		string draftPromptText = (string)Property(draftPrompt.GetType(), draftPrompt, "SystemPrompt");
		Check(draftPromptText.Contains("禁止输出任何效果模块、目标句柄、效果参数或效果数组")
			&& !draftPromptText.Contains("\"moduleId\"")
			&& !draftPromptText.Contains("effectIntentVersion")
			&& !draftPromptText.Contains("effectIntents")
			&& !draftPromptText.Contains("effectPlanVersion")
			&& !draftPromptText.Contains("P:npc:")
			&& !draftPromptText.Contains("allCurrentClans")
			&& draftPromptText.Contains("NPC_ENEMY_HISTORY_PROMPT_MARKER"),
			"NPC stage one must freeze one policy draft without module, target, semantic-ledger, or EffectPlan authority.");
		Check(draftPromptText.Contains("政策正文是后续效果规划的最高语义权威")
			&& draftPromptText.Contains("与玩家政策共用的独立效果规划阶段")
			&& !draftPromptText.Contains("startupGoldCost 与 dailyMaintenanceGoldCost 是政策资金元数据"),
			"NPC stage one must hand policy prose to the shared direct effect planner without player-only funding metadata.");
		Check(!draftPromptText.Contains("【本次候选效果的政策理解要求】"),
			"NPC stage one must remain policy-generic before the generated draft can be routed to modules.");
		SetField(contextType, context, "CandidateModuleIds", new List<string> { "foodPerDay" });
		SetField(contextType, context, "DetailedModuleIds", new List<string> { "kingdomStability" });
		bool rejectedNpcDetailOutsideCandidate = false;
		try
		{
			InvokeStatic(behavior, "EnsureNpcPolicyModuleAllowlists", new object[] { context, string.Empty }, 2);
		}
		catch (Exception exception)
		{
			rejectedNpcDetailOutsideCandidate = Unwrap(exception).Message.IndexOf("allowlist", StringComparison.OrdinalIgnoreCase) >= 0;
		}
		Check(rejectedNpcDetailOutsideCandidate,
			"NPC effect mapping must fail closed when Detail is outside the frozen Candidate set.");
		SetField(contextType, context, "DetailedModuleIds", new List<string> { "foodPerDay" });
		Check(PolicyEffectModuleCatalog.TryGetCanonical("foodPerDay", out IPolicyEffectModule sharedFoodModule),
			"The NPC two-stage fixture requires the shared food module.");

		string draftJson = new JObject
		{
			["policy"] = new JObject
			{
				["kingdomId"] = "kingdom_west",
				["kingdomName"] = "Kingdom West",
				["rulerHeroId"] = "hero_west",
				["rulerName"] = "Ruler West",
				["creativePremise"] = "A focused reform",
				["policyName"] = "Western Granary Reform",
				["policyContent"] = "Kingdom West will fund granaries and reduce food losses.",
				["policyDigest"] = "Fund granaries",
				["eventPremise"] = "Merchants begin reorganizing deliveries.",
				["feedbackTitle"] = "Granary debate",
				["publicFeedback"] = "Towns welcome the reserve plan.",
				["feedbackDigest"] = "The reserve plan draws support.",
				["impactSummary"] = "Food reserves should improve.",
				["numericIntent"] = "Increase food reserves moderately each day.",
				["authoritarianWeight"] = 0.2,
				["oligarchicWeight"] = 0.1,
				["egalitarianWeight"] = 0.4,
				["durationDays"] = 30
			}
		}.ToString(Formatting.None);
		object[] parseDraft = { draftJson, context, null, null };
		Check((bool)InvokeStatic(behavior, "TryParseNpcPolicyDraftResponse", parseDraft, 4)
			&& parseDraft[2] != null && string.IsNullOrWhiteSpace((string)parseDraft[3]),
			"NPC stage one must parse exactly one identity-locked policy draft: " + parseDraft[3]);
		Type directoryType = SutType("AnimusForge.PolicyTargets.PolicyTargetHandleDirectory");
		JObject directoryJson = new JObject
		{
			["structureVersion"] = 3,
			["targets"] = new JObject
			{
				["kingdom_west"] = new JObject
				{
					["kind"] = "kingdom",
					["description"] = "Kingdom West",
					["entityId"] = "kingdom_west"
				},
				["P0"] = new JObject
				{
					["kind"] = "selector",
					["description"] = "民兵最高的城镇 TargetPlan",
					["selectorId"] = "P0",
					["targetPlanVersion"] = 3,
					["currentSettlementCount"] = 1
				}
			},
			["capabilities"] = new JObject
			{
				["foodPerDay"] = new JObject
				{
					["defaultTargetHandle"] = "kingdom_west",
					["allowedSubsetTargetHandles"] = new JArray("P0"),
					["allowedTargetHandles"] = new JArray("kingdom_west", "P0")
				}
			}
		};
		SetField(kingdomContextType, kingdomContext, "EffectTargetDirectory", TokenToObject(directoryJson, directoryType));
		object effectHistoryPrompt = InvokeStatic(behavior, "ComposeNpcPolicyEffectPrompt", new[] { context, parseDraft[2] }, 2);
		string effectHistoryPromptText = (string)Property(effectHistoryPrompt.GetType(), effectHistoryPrompt, "SystemPrompt");
		Check(!effectHistoryPromptText.Contains("NPC_ENEMY_HISTORY_PROMPT_MARKER")
			&& effectHistoryPromptText.Contains("numericIntent")
			&& effectHistoryPromptText.Contains("effectPlanVersion")
			&& effectHistoryPromptText.Contains("disposition")
			&& effectHistoryPromptText.Contains("\"capabilities\":{\"foodPerDay\"")
			&& !effectHistoryPromptText.Contains("effectMappingVersion")
			&& !effectHistoryPromptText.Contains("assignments")
			&& !effectHistoryPromptText.Contains("intentLeg"),
			"NPC stage two must use the player-style direct EffectPlan contract and shared capability directory.");
		Check(effectHistoryPromptText.Contains("P0")
			&& effectHistoryPromptText.Contains("TargetPlan")
			&& effectHistoryPromptText.Contains("targetPlanVersion")
			&& effectHistoryPromptText.Contains("不得改写或猜测内部实体"),
			"NPC stage two must receive the frozen P handle only through the shared opaque target directory.");
		Check(ReferenceEquals(InvokeStatic(behavior, "ResolveAllowedEffectTarget", new object[] { "P0", kingdomContext }, 2), npcPlanTarget)
			&& InvokeStatic(behavior, "ResolveAllowedEffectTarget", new object[] { "P1", kingdomContext }, 2) == null
			&& string.Equals((string)InvokeStatic(behavior, "ResolveCanonicalNpcPolicyEffectTargetHandle",
				new object[] { "p0", npcPlanTarget }, 2), "P0", StringComparison.Ordinal),
			"NPC P handles must resolve only through the frozen catalog and canonicalize without exposing plan internals.");
		Check(effectHistoryPromptText.Contains(PolicyEffectPromptService.GetEvaluationPrompt(sharedFoodModule)),
			"NPC effect postprocess must consume the same selected-module evaluation prompt as the player policy path.");
		JObject draftWithEffects = JObject.Parse(draftJson);
		((JObject)draftWithEffects["policy"])["effects"] = new JArray();
		object[] rejectDraftEffects = { draftWithEffects.ToString(Formatting.None), context, null, null };
		Check(!(bool)InvokeStatic(behavior, "TryParseNpcPolicyDraftResponse", rejectDraftEffects, 4),
			"NPC stage one must fail closed when the model tries to emit effects.");
		JObject draftWithSemanticLedger = JObject.Parse(draftJson);
		((JObject)draftWithSemanticLedger["policy"])["effectIntents"] = new JArray();
		object[] rejectDraftSemanticLedger = { draftWithSemanticLedger.ToString(Formatting.None), context, null, null };
		Check(!(bool)InvokeStatic(behavior, "TryParseNpcPolicyDraftResponse", rejectDraftSemanticLedger, 4),
			"NPC stage one must fail closed when the model tries to revive the removed semantic ledger.");
		JObject draftWithStringDuration = JObject.Parse(draftJson);
		((JObject)draftWithStringDuration["policy"])["durationDays"] = "30";
		object[] rejectCoercedDraft = { draftWithStringDuration.ToString(Formatting.None), context, null, null };
		Check(!(bool)InvokeStatic(behavior, "TryParseNpcPolicyDraftResponse", rejectCoercedDraft, 4),
			"NPC stage one must reject JSON type coercion instead of silently changing the frozen draft.");
		object[] rejectCaseChangedDraft = { draftJson.Replace("\"policy\":", "\"Policy\":"), context, null, null };
		Check(!(bool)InvokeStatic(behavior, "TryParseNpcPolicyDraftResponse", rejectCaseChangedDraft, 4),
			"NPC stage one must treat contract field names as case-sensitive.");
		string duplicateDraftRoot = draftJson.Insert(draftJson.Length - 1, ",\"policy\":{}");
		object[] rejectDuplicateDraft = { duplicateDraftRoot, context, null, null };
		Check(!(bool)InvokeStatic(behavior, "TryParseNpcPolicyDraftResponse", rejectDuplicateDraft, 4),
			"NPC stage one must reject duplicate JSON fields instead of accepting the last value.");
		object[] rejectDraftPrefix = { "Here is the requested JSON:\n" + draftJson, context, null, null };
		Check(!(bool)InvokeStatic(behavior, "TryParseNpcPolicyDraftResponse", rejectDraftPrefix, 4),
			"NPC stage one must reject explanatory text outside the JSON contract.");
		JObject wrongIdentityDraft = JObject.Parse(draftJson);
		wrongIdentityDraft["policy"]["kingdomId"] = "kingdom_east";
		wrongIdentityDraft["policy"]["kingdomName"] = "Kingdom East";
		wrongIdentityDraft["policy"]["rulerHeroId"] = "hero_east";
		wrongIdentityDraft["policy"]["rulerName"] = "Ruler East";
		object[] rejectWrongIdentity = { wrongIdentityDraft.ToString(Formatting.None), context, null, null };
		Check(!(bool)InvokeStatic(behavior, "TryParseNpcPolicyDraftResponse", rejectWrongIdentity, 4)
			&& rejectWrongIdentity[3]?.ToString().IndexOf("身份", StringComparison.OrdinalIgnoreCase) >= 0,
			"NPC draft validation must reject a model-selected kingdom/ruler outside the frozen single target.");
		JArray draftRepairMessages = (JArray)InvokeStatic(
			behavior,
			"BuildNpcPolicyDraftRepairMessages",
			new object[]
			{
				draftPromptText,
				wrongIdentityDraft.ToString(Formatting.None),
				rejectWrongIdentity[3]?.ToString(),
				kingdomContext
			},
			4);
		Check(draftRepairMessages.Count == 3
			&& string.Equals(draftRepairMessages[1]?["role"]?.ToString(), "assistant", StringComparison.Ordinal)
			&& draftRepairMessages[1]?["content"]?.ToString().Contains("kingdom_east") == true
			&& string.Equals(draftRepairMessages[2]?["role"]?.ToString(), "user", StringComparison.Ordinal)
			&& draftRepairMessages[2]?["content"]?.ToString().Contains("\"kingdomId\":\"kingdom_west\"") == true
			&& draftRepairMessages[2]?["content"]?.ToString().Contains("\"rulerHeroId\":\"hero_west\"") == true
			&& draftRepairMessages[2]?["content"]?.ToString().Contains("only constrained repair attempt") == true,
			"NPC draft repair must preserve the rejected output as untrusted assistant data and freeze the one legal kingdom/ruler identity.");
		Check(string.Equals(
			(string)InvokeStatic(behavior, "ClassifyNpcPolicySemanticRepairError",
				new object[] { "draft", rejectWrongIdentity[3]?.ToString() }, 2),
			"identity_mismatch",
			StringComparison.Ordinal),
			"Wrong NPC kingdom/ruler responses must use the stable identity_mismatch repair diagnostic.");
		TestNpcDraftSemanticRepairOrchestrationContract(
			behavior,
			contextType,
			context,
			kingdomContext,
			draftPrompt,
			draftJson,
			wrongIdentityDraft.ToString(Formatting.None));

		string directEffectPlanJson = new JObject
		{
			["effectPlanVersion"] = 1,
			["disposition"] = "executable",
			["reason"] = "Granary funding directly improves food reserves.",
			["effects"] = new JArray
			{
				new JObject
				{
					["mechanismId"] = "M0",
					["mechanismKind"] = "independent",
					["role"] = "subject",
					["moduleId"] = "foodPerDay",
					["targetHandles"] = new JArray("kingdom_west"),
					["payload"] = new JObject { ["value"] = 1.0 },
					["reason"] = "Funded granaries reduce daily food losses."
				}
			}
		}.ToString(Formatting.None);
		object[] parsePlan = { directEffectPlanJson, 30, null, null };
		Check((bool)InvokeStatic(behavior, "TryParseNpcPolicyEffectPlanResponse", parsePlan, 4),
			"NPC stage two must parse the same direct EffectPlan wire shape as the player path: " + parsePlan[3]);
		TestNpcEffectSemanticRepairOrchestrationContract(
			behavior,
			context,
			kingdomContext,
			parseDraft[2],
			effectHistoryPrompt,
			directEffectPlanJson);
		JObject pHandlePlan = JObject.Parse(directEffectPlanJson);
		pHandlePlan["effects"][0]["targetHandles"] = new JArray("P0");
		object[] parsePHandlePlan = { pHandlePlan.ToString(Formatting.None), 30, null, null };
		Check((bool)InvokeStatic(behavior, "TryParseNpcPolicyEffectPlanResponse", parsePHandlePlan, 4)
			&& ReadStringPropertyValues(
				Items(Property(parsePHandlePlan[2].GetType(), parsePHandlePlan[2], "Effects")).Single(),
				"TargetHandles").SequenceEqual(new[] { "P0" }, StringComparer.Ordinal),
			"NPC stage two must copy an opaque TargetPlan handle without receiving plan JSON.");
		JObject pHandleRewrite = (JObject)pHandlePlan.DeepClone();
		pHandleRewrite["effects"][0]["targetPlan"] = JObject.FromObject(npcFrozenPlan);
		object[] stripPHandleMetadata = { pHandleRewrite.ToString(Formatting.None), 30, null, null };
		Check((bool)InvokeStatic(behavior, "TryParseNpcPolicyEffectPlanResponse", stripPHandleMetadata, 4)
			&& ReadStringPropertyValues(
				Items(Property(stripPHandleMetadata[2].GetType(), stripPHandleMetadata[2], "Effects")).Single(),
				"TargetHandles").SequenceEqual(new[] { "P0" }, StringComparer.Ordinal),
			"NPC stage two must share the player parser's harmless-metadata stripping while retaining only the opaque P handle.");
		object parsedPlan = parsePlan[2];
		object parsedWire = Items(Property(parsedPlan.GetType(), parsedPlan, "Effects")).Single();
		Check(Convert.ToInt32(Property(parsedPlan.GetType(), parsedPlan, "DurationDays"), CultureInfo.InvariantCulture) == 30
			&& Convert.ToInt32(Property(parsedWire.GetType(), parsedWire, "EffectPlanVersion"), CultureInfo.InvariantCulture) == 1
			&& string.Equals((string)Property(parsedWire.GetType(), parsedWire, "MechanismId"), "M0", StringComparison.Ordinal)
			&& string.Equals(Property(parsedWire.GetType(), parsedWire, "MechanismKind").ToString(), "Independent", StringComparison.Ordinal)
			&& string.Equals(Property(parsedWire.GetType(), parsedWire, "MechanismRole").ToString(), "Subject", StringComparison.Ordinal)
			&& !(bool)Property(parsedWire.GetType(), parsedWire, "SourceOmitted")
			&& !(bool)Property(parsedWire.GetType(), parsedWire, "DestinationOmitted"),
			"NPC direct EffectPlan must preserve model-authored player-compatible mechanism metadata and the frozen duration.");
		JObject forbiddenCostRole = JObject.Parse(directEffectPlanJson);
		forbiddenCostRole["effects"][0]["role"] = "cost";
		object[] rejectCostRole = { forbiddenCostRole.ToString(Formatting.None), 30, null, null };
		Check(!(bool)InvokeStatic(behavior, "TryParseNpcPolicyEffectPlanResponse", rejectCostRole, 4),
			"NPC direct EffectPlan must reject the removed cost role exactly like the player wire parser.");
		object clonedWire = InvokeStatic(behavior, "CloneNpcPolicyWireEffectForTarget", new[]
		{
			parsedWire, (object)"foodPerDay", "kingdom_west"
		}, 3);
		Check(string.Equals((string)Property(clonedWire.GetType(), clonedWire, "MechanismId"), "M0", StringComparison.Ordinal)
			&& string.Equals(Property(clonedWire.GetType(), clonedWire, "MechanismKind").ToString(), "Independent", StringComparison.Ordinal)
			&& string.Equals(Property(clonedWire.GetType(), clonedWire, "MechanismRole").ToString(), "Subject", StringComparison.Ordinal)
			&& !(bool)Property(clonedWire.GetType(), clonedWire, "DestinationOmitted")
			&& ReadStringPropertyValues(clonedWire, "TargetHandles").SequenceEqual(new[] { "kingdom_west" }, StringComparer.Ordinal),
			"NPC target canonicalization must preserve mechanism identity, kind, role, and omission flags.");
		JObject planWithIdentityRewrite = JObject.Parse(directEffectPlanJson);
		planWithIdentityRewrite["policyName"] = "rewritten";
		object[] stripIdentityMetadata = { planWithIdentityRewrite.ToString(Formatting.None), 30, null, null };
		Check((bool)InvokeStatic(behavior, "TryParseNpcPolicyEffectPlanResponse", stripIdentityMetadata, 4)
			&& Items(Property(stripIdentityMetadata[2].GetType(), stripIdentityMetadata[2], "Effects")).Count() == 1,
			"NPC stage two must share the player parser's harmless root-metadata stripping; the frozen draft remains authoritative outside the EffectPlan.");
		JObject planWithMultipleTargets = JObject.Parse(directEffectPlanJson);
		planWithMultipleTargets["effects"][0]["targetHandles"] = new JArray("kingdom_west", "P0");
		object[] acceptMultipleTargets = { planWithMultipleTargets.ToString(Formatting.None), 30, null, null };
		Check((bool)InvokeStatic(behavior, "TryParseNpcPolicyEffectPlanResponse", acceptMultipleTargets, 4)
			&& ReadStringPropertyValues(
				Items(Property(acceptMultipleTargets[2].GetType(), acceptMultipleTargets[2], "Effects")).Single(),
				"TargetHandles").SequenceEqual(new[] { "P0", "kingdom_west" }, StringComparer.Ordinal),
			"NPC direct EffectPlan must retain player-compatible multi-handle effects for later shell splitting.");
		JObject narrativeOnlyPlan = JObject.Parse(directEffectPlanJson);
		narrativeOnlyPlan["disposition"] = "narrativeOnly";
		narrativeOnlyPlan["effects"] = new JArray();
		object[] rejectNarrativeOnly = { narrativeOnlyPlan.ToString(Formatting.None), 30, null, null };
		Check(!(bool)InvokeStatic(behavior, "TryParseNpcPolicyEffectPlanResponse", rejectNarrativeOnly, 4),
			"NPC publication must require at least one executable direct effect.");

		string firstInstanceId = (string)InvokeStatic(behavior, "BuildNpcPolicyEffectInstanceId", new object[] { "policy-alpha", 0 }, 2);
		string secondInstanceId = (string)InvokeStatic(behavior, "BuildNpcPolicyEffectInstanceId", new object[] { "policy-alpha", 1 }, 2);
		Check(string.Equals(firstInstanceId, "policy-alpha:effect:0", StringComparison.Ordinal)
			&& string.Equals(secondInstanceId, "policy-alpha:effect:1", StringComparison.Ordinal)
			&& !string.Equals(firstInstanceId, secondInstanceId, StringComparison.Ordinal),
			"New NPC policy instances must use player-parity ordinal IDs so multiple mechanisms cannot collide.");

		TestNpcPolicyHistoryGlobalAccessContracts(behavior);
		TestUnifiedPolicyHistoryContracts();
		TestDialoguePolicyHistoryContracts();
		TestNpcPolicyHistoryBaselineContracts(behavior);
		TestNpcTwoStageApiCallOverrideContract(behavior, contextType, context);
	}

	private static void TestNpcPolicyHistoryGlobalAccessContracts(Type behavior)
	{
		Type serviceType = SutType("AnimusForge.PolicyHistoryRetrievalService");
		Type entryType = SutType("AnimusForge.NpcPolicyHistoryEntry");
		Type filterType = SutType("AnimusForge.NpcPolicyHistorySelectionFilter");
		IList entries = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(entryType));
		entries.Add(BuildNpcPolicyHistoryEntry(entryType, "own-active-expired", "kingdom_west", "active", "expired", 0.80f, 10));
		entries.Add(BuildNpcPolicyHistoryEntry(entryType, "own-abolished", "kingdom_west", "abolished", "ended_by_abolition", 0.90f, 9));
		entries.Add(BuildNpcPolicyHistoryEntry(entryType, "foreign-published", "kingdom_east", "active", "active", 0.95f, 11));
		object foreignLocal = BuildNpcPolicyHistoryEntry(entryType, "foreign-local", "kingdom_east", "active", "active", 0.99f, 12);
		SetProperty(entryType, foreignLocal, "SourceKind", "player_local");
		((IList<string>)Property(entryType, foreignLocal, "TargetKingdomIds")).Add("kingdom_west");
		entries.Add(foreignLocal);
		entries.Add(BuildNpcPolicyHistoryEntry(entryType, "foreign-legacy", "kingdom_east", "active", "active", 1.00f, 13));
		object activeFilter = Activator.CreateInstance(filterType, nonPublic: true);
		SetProperty(filterType, activeFilter, "RequiredStatus", "active");
		SetProperty(filterType, activeFilter, "MaxCount", 4);
		SetProperty(filterType, activeFilter, "MinimumScore", 0.45f);
		object selectedActive = InvokeStatic(serviceType, "SelectEntries", new[] { entries, activeFilter }, 2);
		string[] activeIds = Items(selectedActive).Select(item => (string)Property(entryType, item, "EntryId")).ToArray();
		Check(activeIds.SequenceEqual(new[] { "foreign-legacy", "foreign-local", "foreign-published", "own-active-expired" }, StringComparer.Ordinal),
			"Policy history retrieval must rank every successful policy globally without requester visibility gates.");
		object abolishedFilter = Activator.CreateInstance(filterType, nonPublic: true);
		SetProperty(filterType, abolishedFilter, "RequiredStatus", "abolished");
		SetProperty(filterType, abolishedFilter, "MaxCount", 1);
		SetProperty(filterType, abolishedFilter, "MinimumScore", 0.45f);
		object selectedAbolished = InvokeStatic(serviceType, "SelectEntries", new[] { entries, abolishedFilter }, 2);
		Check(Items(selectedAbolished).Select(item => (string)Property(entryType, item, "EntryId"))
			.SequenceEqual(new[] { "own-abolished" }, StringComparer.Ordinal),
			"NPC history retrieval must keep a separate abolished-policy quota.");
		object eastFilter = Activator.CreateInstance(filterType, nonPublic: true);
		SetProperty(filterType, eastFilter, "AllowedOwnerKingdomIds", new List<string> { "kingdom_east" });
		SetProperty(filterType, eastFilter, "RequiredStatus", "active");
		SetProperty(filterType, eastFilter, "MaxCount", 3);
		SetProperty(filterType, eastFilter, "MinimumScore", 0.45f);
		object selectedEast = InvokeStatic(serviceType, "SelectEntries", new[] { entries, eastFilter }, 2);
		Check(Items(selectedEast).Select(item => (string)Property(entryType, item, "EntryId"))
			.SequenceEqual(new[] { "foreign-legacy", "foreign-local", "foreign-published" }, StringComparer.Ordinal),
			"Owner filters may narrow an explicit query but must not act as requester access control.");
	}

	private static object BuildNpcPolicyHistoryEntry(
		Type entryType,
		string entryId,
		string ownerKingdomId,
		string status,
		string effectStatus,
		float score,
		int day)
	{
		object entry = Activator.CreateInstance(entryType, nonPublic: true);
		SetProperty(entryType, entry, "EntryId", entryId);
		SetProperty(entryType, entry, "SourceKind", "npc");
		SetProperty(entryType, entry, "OwnerKingdomId", ownerKingdomId);
		SetProperty(entryType, entry, "IssuerKingdomId", ownerKingdomId);
		SetProperty(entryType, entry, "PolicyName", entryId);
		SetProperty(entryType, entry, "PolicyContent", entryId + " policy content");
		SetProperty(entryType, entry, "PolicyStatus", status);
		SetProperty(entryType, entry, "EffectStatus", effectStatus);
		SetProperty(entryType, entry, "RecallScore", score);
		SetProperty(entryType, entry, "PublishedDay", day);
		return entry;
	}

	private static void TestUnifiedPolicyHistoryContracts()
	{
		Type serviceType = SutType("AnimusForge.PolicyHistoryRetrievalService");
		Type entryType = SutType("AnimusForge.NpcPolicyHistoryEntry");
		Type filterType = SutType("AnimusForge.NpcPolicyHistorySelectionFilter");
		Type enemyType = SutType("AnimusForge.PolicyEnemyKingdomSnapshot");
		foreach ((string Status, string Bucket) expected in new[]
		{
			("active", "current"),
			("expiry_vote_pending", "current"),
			("abolished", "historical"),
			("expired", "historical"),
			("targets_lost", "historical"),
			("relationship_ended", "historical"),
			("pending", string.Empty),
			("approved_pending_commit", string.Empty),
			("approved_renewal_pending_commit", string.Empty),
			("commit_suspended", string.Empty),
			("rejected", string.Empty)
		})
		{
			string actual = (string)InvokeStatic(serviceType, "ResolveHistoryBucketFromStatus", new object[] { expected.Status }, 1);
			Check(string.Equals(actual, expected.Bucket, StringComparison.Ordinal),
				"Unified policy history status mapping mismatch for " + expected.Status + ".");
		}

		int neutralEmbeddingCalls = 0;
		float[] NeutralEmbedding(string text)
		{
			neutralEmbeddingCalls++;
			return (text ?? string.Empty).IndexOf("补贴", StringComparison.Ordinal) >= 0
				? new[] { 1f, 0f }
				: new[] { 0.9f, 0.1f };
		}
		NpcPolicyHistoryEntry cachedHistory = new NpcPolicyHistoryEntry
		{
			EntryId = "neutral-embedding-history",
			SourceKind = "player_kingdom",
			ScopeKind = "kingdom",
			OwnerKingdomId = "kingdom_west",
			IssuerKingdomId = "kingdom_west",
			PolicyName = "旧补贴政策",
			PolicyContent = "曾向领主发放补贴。",
			PolicyStatus = "active",
			RawPolicyStatus = "active",
			HistoryBucket = "current",
			EffectStatus = "active",
			PublishedDay = 5
		};
		PolicyTextEmbeddingSession neutralSession = new PolicyTextEmbeddingSession(NeutralEmbedding, "contract-model-v1");
		PolicyHistoryRetrievalResult firstNeutral = PolicyHistoryRetrievalService.Retrieve(
			neutralSession, "领主补贴", new[] { cachedHistory }, Array.Empty<PolicyEnemyKingdomSnapshot>(),
			"kingdom_west", 987654321L);
		PolicyHistoryRetrievalResult secondNeutral = PolicyHistoryRetrievalService.Retrieve(
			neutralSession, "领主补贴", new[] { cachedHistory }, Array.Empty<PolicyEnemyKingdomSnapshot>(),
			"kingdom_west", 987654321L);
		Check(firstNeutral.DocumentVectorCacheMisses == 1
			&& secondNeutral.DocumentVectorCacheHits == 1
			&& neutralEmbeddingCalls == 2
			&& neutralSession.Dimension == 2
			&& neutralSession.EmbeddingFingerprint.IndexOf("contract-model-v1", StringComparison.Ordinal) >= 0,
			"Neutral history embedding must reuse the request query vector and the 512-entry document cache by fingerprint/text hash.");
		PolicyTextEmbeddingSession changedFingerprintSession = new PolicyTextEmbeddingSession(NeutralEmbedding, "contract-model-v2");
		PolicyHistoryRetrievalResult changedFingerprint = PolicyHistoryRetrievalService.Retrieve(
			changedFingerprintSession, "领主补贴", new[] { cachedHistory }, Array.Empty<PolicyEnemyKingdomSnapshot>(),
			"kingdom_west", 987654321L);
		Check(changedFingerprint.DocumentVectorCacheMisses == 1,
			"A changed embedding fingerprint must invalidate history document vectors without widening recall authority.");

		IList independentEntries = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(entryType));
		object independentEnded = BuildNpcPolicyHistoryEntry(
			entryType, "independent-ended", string.Empty, "abolished", "expired", 0.90f, 8);
		SetProperty(entryType, independentEnded, "SourceKind", "player_local");
		SetProperty(entryType, independentEnded, "OwnerClanId", "player_clan");
		SetProperty(entryType, independentEnded, "RawPolicyStatus", "targets_lost");
		SetProperty(entryType, independentEnded, "HistoryBucket", "historical");
		independentEntries.Add(independentEnded);
		object historicalFilter = Activator.CreateInstance(filterType, nonPublic: true);
		SetProperty(filterType, historicalFilter, "RequiredBucket", "historical");
		SetProperty(filterType, historicalFilter, "MaxCount", 1);
		object independentSelected = InvokeStatic(serviceType, "SelectEntries", new[] { independentEntries, historicalFilter }, 2);
		Check(Items(independentSelected).Select(item => (string)Property(entryType, item, "EntryId"))
			.SequenceEqual(new[] { "independent-ended" }, StringComparer.Ordinal),
			"Independent-clan local history must remain globally usable without a kingdom owner ID.");

		IList enemyEntries = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(entryType));
		object eastOlder = BuildNpcPolicyHistoryEntry(entryType, "east-active", "kingdom_east", "active", "active", 0f, 10);
		SetProperty(entryType, eastOlder, "HistoryBucket", "current");
		enemyEntries.Add(eastOlder);
		object eastLatest = BuildNpcPolicyHistoryEntry(entryType, "east-ended", "kingdom_east", "abolished", "ended_by_abolition", 0f, 12);
		SetProperty(entryType, eastLatest, "RawPolicyStatus", "abolished");
		SetProperty(entryType, eastLatest, "HistoryBucket", "historical");
		SetProperty(entryType, eastLatest, "PolicyName", new string('E', 60));
		SetProperty(entryType, eastLatest, "PolicyContent", "第一句完整政策摘要。第二句用于验证敌国摘要预算不会删除敌国行。");
		enemyEntries.Add(eastLatest);
		object targetOnly = BuildNpcPolicyHistoryEntry(entryType, "target-only", "kingdom_west", "active", "active", 0f, 99);
		SetProperty(entryType, targetOnly, "HistoryBucket", "current");
		((IList<string>)Property(entryType, targetOnly, "TargetKingdomIds")).Add("kingdom_north");
		enemyEntries.Add(targetOnly);
		IList enemies = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(enemyType));
		foreach ((string Id, string Name) enemy in new[]
		{
			("kingdom_east", new string('东', 40)),
			("kingdom_north", "北境王国")
		})
		{
			object snapshot = Activator.CreateInstance(enemyType, nonPublic: true);
			SetProperty(enemyType, snapshot, "KingdomId", enemy.Id);
			SetProperty(enemyType, snapshot, "KingdomName", enemy.Name);
			enemies.Add(snapshot);
		}
		object enemyResult = InvokeStatic(serviceType, "BuildEnemyHistory", new object[]
		{
			enemyEntries, enemies, "kingdom_west"
		}, 3);
		Check((int)Property(enemyResult.GetType(), enemyResult, "EnemyCount") == 2
			&& (int)Property(enemyResult.GetType(), enemyResult, "EnemyWithPolicyCount") == 1,
			"Enemy policy history must keep every enemy row and count only enemies with owner-matched policies.");
		string enemyPrompt = (string)Property(enemyResult.GetType(), enemyResult, "EnemyPrompt");
		object repeatedEnemyResult = InvokeStatic(serviceType, "BuildEnemyHistory", new object[]
		{
			enemyEntries, enemies, "kingdom_west"
		}, 3);
		Check(string.Equals(enemyPrompt, (string)Property(repeatedEnemyResult.GetType(), repeatedEnemyResult, "EnemyPrompt"), StringComparison.Ordinal),
			"Player and NPC callers must receive the same deterministic enemy-history prompt for the same snapshot.");
		Check(enemyPrompt.Contains("enemyCount=2")
			&& enemyPrompt.Contains("withPolicyCount=1")
			&& enemyPrompt.Contains("status=abolished")
			&& enemyPrompt.Contains("kingdomId=kingdom_north,name=北境王国,latest=none")
			&& !enemyPrompt.Contains("target-only"),
			"Enemy prompt must choose the newest strict owner record across current/historical states and emit latest=none.");
		string eastName = enemyPrompt.Split('\n').First(line => line.Contains("kingdomId=kingdom_east"));
		Check(!eastName.Contains(new string('东', 31)) && !eastName.Contains(new string('E', 41)),
			"Enemy and policy names must be compressed to the fixed 30/40 character budgets.");

		Type behaviorType = SutType("AnimusForge.NpcRulerPolicyBehavior");
		Type recordType = SutType("AnimusForge.NpcRulerPolicyRecord");
		IList records = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(recordType));
		for (int day = 2; day <= 181; day++)
		{
			object record = Activator.CreateInstance(recordType);
			SetProperty(recordType, record, "PolicyId", "east-" + day.ToString(CultureInfo.InvariantCulture));
			SetProperty(recordType, record, "KingdomId", "kingdom_east");
			SetProperty(recordType, record, "AgendaStatus", "active");
			SetProperty(recordType, record, "Day", day);
			records.Add(record);
		}
		object onlyNorth = Activator.CreateInstance(recordType);
		SetProperty(recordType, onlyNorth, "PolicyId", "north-only");
		SetProperty(recordType, onlyNorth, "KingdomId", "kingdom_north");
		SetProperty(recordType, onlyNorth, "AgendaStatus", "abolished");
		SetProperty(recordType, onlyNorth, "Day", 1);
		records.Add(onlyNorth);
		object retained = InvokeStatic(behaviorType, "SelectNpcPolicyRecordIdsForRetention", new object[]
		{
			records, new[] { "kingdom_east", "kingdom_north" }, 180
		}, 3);
		string[] retainedIds = Items(retained).Cast<string>().ToArray();
		Check(retainedIds.Length == 181 && retainedIds.Contains("north-only", StringComparer.Ordinal),
			"NPC policy trimming must retain every active policy plus the newest valid history for each live kingdom beyond the global limit.");

		Type playerBehaviorType = SutType("AnimusForge.CustomPolicyBehavior");
		Type requestType = playerBehaviorType.GetNestedType("PolicyDraftRequest", BindingFlags.NonPublic);
		Type promptContextType = playerBehaviorType.GetNestedType("PolicyPromptContextBundle", BindingFlags.NonPublic);
		Type assessmentType = playerBehaviorType.GetNestedType("PolicyMainAssessmentResult", BindingFlags.NonPublic);
		Type retrievalType = SutType("AnimusForge.PolicyHistoryRetrievalResult");
		object request = Activator.CreateInstance(requestType, nonPublic: true);
		SetField(requestType, request, "RequestId", "history-prompt-contract");
		SetField(requestType, request, "ScopeKind", "kingdom");
		SetField(requestType, request, "PolicyName", "统一历史提示词合同");
		SetField(requestType, request, "PolicyContent", "验证玩家主评议与效果后处理共享同一历史段。");
		SetField(requestType, request, "DateText", "day 42");
		SetField(requestType, request, "PlayerKingdomId", "kingdom_west");
		SetField(requestType, request, "ManualDurationDays", 30);
		SetField(requestType, request, "PublicFeedbackTargetChars", 240);
		object promptContext = Activator.CreateInstance(promptContextType, nonPublic: true);
		SetField(promptContextType, promptContext, "PolicyRuleContext", "contract rules");
		SetField(promptContextType, promptContext, "WorldContextFull", "contract world");
		SetField(promptContextType, promptContext, "ExtensionContext", "contract extension");
		SetField(requestType, request, "PromptContext", promptContext);
		object retrieval = Activator.CreateInstance(retrievalType, nonPublic: true);
		SetProperty(retrievalType, retrieval, "CombinedPrompt", "HISTORY_PROMPT_CONTRACT_MARKER");
		SetField(requestType, request, "PolicyHistoryRetrieval", retrieval);
		object assessment = Activator.CreateInstance(assessmentType, nonPublic: true);
		SetProperty(assessmentType, assessment, "ImpactSummary", "contract impact");
		SetProperty(assessmentType, assessment, "NumericIntent", "contract numeric intent");
		SetProperty(assessmentType, assessment, "PolicyContentDigest", "contract digest");
		SetProperty(assessmentType, assessment, "DurationDays", 30);
		string mainPromptJson = JsonConvert.SerializeObject(
			((IEnumerable)InvokeStatic(playerBehaviorType, "BuildMainMessages", new object[] { request, string.Empty }, 2)).Cast<object>());
		string effectPromptJson = JsonConvert.SerializeObject(
			((IEnumerable)InvokeStatic(playerBehaviorType, "BuildEffectPostprocessMessages", new[] { request, assessment }, 2)).Cast<object>());
		Check(mainPromptJson.Contains("HISTORY_PROMPT_CONTRACT_MARKER")
			&& !effectPromptJson.Contains("HISTORY_PROMPT_CONTRACT_MARKER"),
			"Player history belongs to the semantic main assessment and must not be reintroduced into restricted mapping.");
	}

	private static void TestNpcPolicyHistoryBaselineContracts(Type behavior)
	{
		if (string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(OnnxRuntimeDirectoryEnvironmentVariable)))
		{
			return;
		}
		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string baselinePath = Path.Combine(repositoryRoot ?? string.Empty,
			"Phase0_Local_Archive", "baseline", "cases", "policy_history_retrieval.jsonl");
		Check(File.Exists(baselinePath), "NPC policy history baseline is missing: " + baselinePath);
		Type serviceType = SutType("AnimusForge.PolicyHistoryRetrievalService");
		Type entryType = SutType("AnimusForge.NpcPolicyHistoryEntry");
		Type filterType = SutType("AnimusForge.NpcPolicyHistorySelectionFilter");
		Type routerType = SutType("AnimusForge.PolicyEffects.PolicyEffectModuleRouter");
		Dictionary<string, string[]> stabilityResults = new Dictionary<string, string[]>(StringComparer.Ordinal);
		foreach (string line in File.ReadLines(baselinePath, Encoding.UTF8).Where(value => !string.IsNullOrWhiteSpace(value)))
		{
			JObject testCase = JObject.Parse(line);
			string caseId = testCase.Value<string>("case_id") ?? string.Empty;
			string query = testCase.Value<string>("query") ?? string.Empty;
			JObject scope = (JObject)testCase["scope"];
			float[] queryVector = (float[])InvokeStatic(routerType, "GetQueryEmbedding", new object[] { query }, 1);
			Check(queryVector != null && queryVector.Length == 512,
				"Existing policy-history ONNX query embedding must remain 512-dimensional for " + caseId + ".");
			IList entries = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(entryType));
			Dictionary<string, float> scoreById = new Dictionary<string, float>(StringComparer.Ordinal);
			int candidateOrdinal = 0;
			foreach (JObject candidate in (JArray)testCase["candidates"])
			{
				object entry = Activator.CreateInstance(entryType, nonPublic: true);
				string source = candidate.Value<string>("source") ?? string.Empty;
				SetProperty(entryType, entry, "EntryId", candidate.Value<string>("id") ?? string.Empty);
				SetProperty(entryType, entry, "SourceKind", source);
				if (source.StartsWith("player_", StringComparison.Ordinal))
				{
					SetProperty(entryType, entry, "OwnerClanId", "player_clan");
				}
				SetProperty(entryType, entry, "OwnerKingdomId", candidate.Value<string>("owner_kingdom_id") ?? string.Empty);
				SetProperty(entryType, entry, "IssuerKingdomId", candidate.Value<string>("owner_kingdom_id") ?? string.Empty);
				SetProperty(entryType, entry, "PolicyName", string.Empty);
				SetProperty(entryType, entry, "PolicyContent", candidate.Value<string>("text") ?? string.Empty);
				SetProperty(entryType, entry, "PolicyStatus", candidate.Value<string>("status") ?? string.Empty);
				SetProperty(entryType, entry, "EffectStatus", candidate.Value<string>("effect_status") ?? string.Empty);
				SetProperty(entryType, entry, "PublishedDay", 100 - candidateOrdinal++);
				SetProperty(entryType, entry, "TargetKingdomIds", ReadJsonStringList(candidate["target_kingdom_ids"]));
				SetProperty(entryType, entry, "TargetClanIds", ReadJsonStringList(candidate["target_clan_ids"]));
				SetProperty(entryType, entry, "TargetSettlementIds", ReadJsonStringList(candidate["target_settlement_ids"]));
				float[] documentVector = (float[])InvokeStatic(routerType, "GetQueryEmbedding",
					new object[] { (string)Property(entryType, entry, "RetrievalText") }, 1);
				Check(documentVector != null && documentVector.Length == 512,
					"Existing policy-history ONNX document embedding must remain 512-dimensional for " + caseId + ".");
				float score = Convert.ToSingle(InvokeStatic(behavior, "CosineNpcPolicyHistoryVectors",
					new object[] { queryVector, documentVector }, 2), CultureInfo.InvariantCulture);
				scoreById[candidate.Value<string>("id") ?? string.Empty] = score;
				SetProperty(entryType, entry, "RecallScore", score);
				entries.Add(entry);
			}

			string ownerKingdomId = scope?.Value<string>("owner_kingdom_id") ?? string.Empty;
			List<string> selectedIds = new List<string>();
			int abolishedQuota = Math.Max(0, testCase.Value<int?>("abolished_quota") ?? 0);
			foreach ((string Status, int Limit) quota in new[]
			{
				("active", Math.Max(0, testCase.Value<int?>("top_k") ?? 0)),
				("abolished", abolishedQuota)
			})
			{
				object filter = Activator.CreateInstance(filterType, nonPublic: true);
				SetProperty(filterType, filter, "QueryText", query);
				SetProperty(filterType, filter, "AllowedOwnerKingdomIds", new List<string> { ownerKingdomId });
				SetProperty(filterType, filter, "AllowedSources", ReadJsonStringList(scope?["allowed_sources"]));
				SetProperty(filterType, filter, "AllowedTargetKingdomIds", ReadJsonStringList(scope?["target_kingdom_ids"]));
				SetProperty(filterType, filter, "AllowedTargetClanIds", ReadJsonStringList(scope?["target_clan_ids"]));
				SetProperty(filterType, filter, "AllowedTargetSettlementIds", ReadJsonStringList(scope?["target_settlement_ids"]));
				SetProperty(filterType, filter, "RequiredStatus", quota.Status);
				SetProperty(filterType, filter, "RequireOwnerMatch", true);
				SetProperty(filterType, filter, "MaxCount", quota.Limit);
				SetProperty(filterType, filter, "MinimumScore", 0.52f);
				object selected = InvokeStatic(serviceType, "SelectEntries",
					new[] { entries, filter }, 2);
				selectedIds.AddRange(Items(selected).Select(item => (string)Property(entryType, item, "EntryId")));
			}

			string[] expected = ReadJsonStringList(testCase["expected_relevant_ids"]).ToArray();
			string[] forbidden = ReadJsonStringList(testCase["forbidden_ids"])
				.Concat(ReadJsonStringList(testCase["hard_negative_ids"]))
				.Distinct(StringComparer.Ordinal)
				.ToArray();
			string scoreSummary = string.Join(",", scoreById.OrderByDescending(pair => pair.Value)
				.Select(pair => pair.Key + "=" + pair.Value.ToString("0.000", CultureInfo.InvariantCulture)));
			Check(expected.All(id => selectedIds.Contains(id, StringComparer.Ordinal)),
				"NPC policy history baseline missed expected records for " + caseId + ": " + string.Join(",", selectedIds)
				+ " scores=" + scoreSummary);
			Check(!forbidden.Any(id => selectedIds.Contains(id, StringComparer.Ordinal)),
				"NPC policy history baseline admitted a hard negative for " + caseId + ": " + string.Join(",", selectedIds)
				+ " scores=" + scoreSummary);
			if (string.Equals(testCase.Value<string>("expected_outcome"), "no_match", StringComparison.Ordinal))
			{
				Check(selectedIds.Count == 0,
					"NPC policy history baseline must fail closed for " + caseId + ": " + string.Join(",", selectedIds));
			}
			if (testCase["expected_abolished_max"] != null)
			{
				HashSet<string> abolishedIds = new HashSet<string>(((JArray)testCase["candidates"])
					.OfType<JObject>()
					.Where(candidate => string.Equals(candidate.Value<string>("status"), "abolished", StringComparison.Ordinal))
					.Select(candidate => candidate.Value<string>("id") ?? string.Empty), StringComparer.Ordinal);
				Check(selectedIds.Count(abolishedIds.Contains) <= testCase.Value<int>("expected_abolished_max"),
					"NPC policy history baseline exceeded the abolished quota for " + caseId + ".");
			}
			string expectedFirst = testCase.Value<string>("expected_first_id");
			if (!string.IsNullOrWhiteSpace(expectedFirst))
			{
				Check(selectedIds.Count > 0 && string.Equals(selectedIds[0], expectedFirst, StringComparison.Ordinal),
					"NPC policy history baseline returned an unstable first result for " + caseId + ": " + string.Join(",", selectedIds));
			}
			string stabilityGroup = testCase.Value<string>("stability_group");
			if (!string.IsNullOrWhiteSpace(stabilityGroup))
			{
				if (stabilityResults.TryGetValue(stabilityGroup, out string[] previous))
				{
					Check(previous.SequenceEqual(selectedIds, StringComparer.Ordinal),
						"NPC policy history baseline ordering is unstable for group " + stabilityGroup + ".");
				}
				else
				{
					stabilityResults[stabilityGroup] = selectedIds.ToArray();
				}
			}
			Console.WriteLine("NPC_POLICY_HISTORY_BASELINE case=" + caseId + " selected=" + string.Join(",", selectedIds)
				+ " scores=" + scoreSummary);
		}

		Type mentionsType = SutType("AnimusForge.MentionedWorldEntities");
		Type resultType = SutType("AnimusForge.PolicyHistoryRetrievalResult");
		Type guardType = SutType("AnimusForge.SaveRuntimeGuard");
		IList dialogueEntries = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(entryType));
		object eastGrain = BuildNpcPolicyHistoryEntry(entryType, "onnx-dialogue-east-grain", "kingdom_east", "active", "active", 0f, 30);
		SetProperty(entryType, eastGrain, "OwnerKingdomName", "东方王国");
		SetProperty(entryType, eastGrain, "PolicyName", "东方粮仓保障令");
		SetProperty(entryType, eastGrain, "PolicyContent", "保障粮食储备，稳定粮价并降低驻军粮食消耗。");
		dialogueEntries.Add(eastGrain);
		object eastGarrison = BuildNpcPolicyHistoryEntry(entryType, "onnx-dialogue-east-garrison", "kingdom_east", "active", "active", 0f, 31);
		SetProperty(entryType, eastGarrison, "OwnerKingdomName", "东方王国");
		SetProperty(entryType, eastGarrison, "PolicyName", "边境驻军训练章程");
		SetProperty(entryType, eastGarrison, "PolicyContent", "提高城堡驻军训练速度并规定军费上限。");
		dialogueEntries.Add(eastGarrison);
		object westGrain = BuildNpcPolicyHistoryEntry(entryType, "onnx-dialogue-west-grain", "kingdom_west", "active", "active", 0f, 32);
		SetProperty(entryType, westGrain, "OwnerKingdomName", "瓦兰迪亚");
		SetProperty(entryType, westGrain, "PolicyName", "西境粮仓保障令");
		SetProperty(entryType, westGrain, "PolicyContent", "保障粮食储备并稳定粮价。");
		dialogueEntries.Add(westGrain);
		object dialogueMentions = Activator.CreateInstance(mentionsType);
		SetField(mentionsType, dialogueMentions, "Entities", new List<string> { "粮食政策", "最近" });
		long runtimeGeneration = Convert.ToInt64(Property(guardType, null, "CurrentGeneration"), CultureInfo.InvariantCulture);
		object[] dialogueArgs =
		{
			"你们最近实行的粮食政策是什么？",
			dialogueMentions,
			new List<string> { "kingdom_east" },
			dialogueEntries,
			runtimeGeneration,
			null
		};
		bool dialogueRetrieved = (bool)InvokeStatic(serviceType, "TryRetrieveDialogueByMentions", dialogueArgs, 6);
		string[] dialogueSelected = Items(Property(resultType, dialogueArgs[5], "RelatedCurrentPolicies"))
			.Select(item => (string)Property(entryType, item, "EntryId"))
			.ToArray();
		float eastGrainScore = Convert.ToSingle(Property(entryType, eastGrain, "RecallScore"), CultureInfo.InvariantCulture);
		float eastGarrisonScore = Convert.ToSingle(Property(entryType, eastGarrison, "RecallScore"), CultureInfo.InvariantCulture);
		Check(dialogueRetrieved
			&& dialogueSelected.Length > 0
			&& string.Equals(dialogueSelected[0], "onnx-dialogue-east-grain", StringComparison.Ordinal)
			&& !dialogueSelected.Contains("onnx-dialogue-west-grain", StringComparer.Ordinal)
			&& eastGrainScore >= 0.52f
			&& eastGrainScore > eastGarrisonScore,
			"Existing ONNX dialogue retrieval must rank the scoped grain policy above a newer same-owner garrison policy and exclude foreign owners. selected="
			+ string.Join(",", dialogueSelected)
			+ " grain=" + eastGrainScore.ToString("0.000", CultureInfo.InvariantCulture)
			+ " garrison=" + eastGarrisonScore.ToString("0.000", CultureInfo.InvariantCulture));
	}

	private static void TestDialoguePolicyHistoryContracts()
	{
		Type serviceType = SutType("AnimusForge.PolicyHistoryRetrievalService");
		Type entryType = SutType("AnimusForge.NpcPolicyHistoryEntry");
		Type resultType = SutType("AnimusForge.PolicyHistoryRetrievalResult");
		Type mentionsType = SutType("AnimusForge.MentionedWorldEntities");
		Type guardType = SutType("AnimusForge.SaveRuntimeGuard");
		Type worldContextType = SutType("AnimusForge.WorldEntityPromptContext");
		Type shoutContextType = SutType("AnimusForge.MyBehavior+ShoutPromptContext");
		FieldInfo embeddingOverride = serviceType.GetField("DialogueEmbeddingOverrideForTests", All);
		Check(embeddingOverride != null,
			"Dialogue policy retrieval must expose one internal embedding seam for deterministic failure-isolation contracts.");
		Check(worldContextType.GetField("ExplicitMentionedKingdomIds", All) != null
			&& shoutContextType.GetField("ExplicitMentionedKingdomIds", All) != null,
			"World-entity preprocessing must carry explicit kingdom ids into the shared shout prompt context.");
		List<string> embeddingInputs = new List<string>();
		Func<string, float[]> embedding = text =>
		{
			string value = text ?? string.Empty;
			embeddingInputs.Add(value);
			if (value.IndexOf("玩家问题：", StringComparison.Ordinal) >= 0) return new[] { 1f, 0f };
			if (value.IndexOf("semantic-high", StringComparison.Ordinal) >= 0) return new[] { 1f, 0f };
			if (value.IndexOf("semantic-mid", StringComparison.Ordinal) >= 0) return new[] { 0.8f, 0.6f };
			if (value.IndexOf("semantic-low", StringComparison.Ordinal) >= 0) return new[] { 0.6f, 0.8f };
			return new[] { -1f, 0f };
		};
		embeddingOverride.SetValue(null, embedding);
		try
		{
			InvokeStatic(serviceType, "ClearTransientCache", Array.Empty<object>(), 0);
			IList entries = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(entryType));
			object semanticHigh = BuildNpcPolicyHistoryEntry(entryType, "east-semantic-high", "kingdom_east", "active", "active", 0f, 10);
			SetProperty(entryType, semanticHigh, "SourceKind", "player_local");
			SetProperty(entryType, semanticHigh, "OwnerKingdomName", "东方王国");
			SetProperty(entryType, semanticHigh, "PolicyName", "东方粮仓令");
			SetProperty(entryType, semanticHigh, "PolicyContent", "semantic-high。" + new string('粮', 400));
			SetProperty(entryType, semanticHigh, "EffectSummaries", new List<string>
			{
				"粮食储备每日增加",
				"市场粮价波动降低",
				"村庄炉火数每日恢复",
				"商队粮食采购成本降低",
				"驻军粮食消耗比例降低"
			});
			entries.Add(semanticHigh);
			object semanticMid = BuildNpcPolicyHistoryEntry(entryType, "east-semantic-mid-newer", "kingdom_east", "active", "active", 0f, 30);
			SetProperty(entryType, semanticMid, "OwnerKingdomName", "东方王国");
			SetProperty(entryType, semanticMid, "PolicyContent", "semantic-mid");
			entries.Add(semanticMid);
			object semanticLow = BuildNpcPolicyHistoryEntry(entryType, "east-semantic-low-newest", "kingdom_east", "active", "active", 0f, 40);
			SetProperty(entryType, semanticLow, "OwnerKingdomName", "东方王国");
			SetProperty(entryType, semanticLow, "PolicyContent", "semantic-low");
			entries.Add(semanticLow);
			object historicalGrain = BuildNpcPolicyHistoryEntry(entryType, "east-historical", "kingdom_east", "abolished", "ended_by_abolition", 0f, 17);
			SetProperty(entryType, historicalGrain, "OwnerKingdomName", "东方王国");
			SetProperty(entryType, historicalGrain, "RawPolicyStatus", "abolished");
			SetProperty(entryType, historicalGrain, "HistoryBucket", "historical");
			SetProperty(entryType, historicalGrain, "PolicyContent", "semantic-high historical policy");
			entries.Add(historicalGrain);
			object westPolicy = BuildNpcPolicyHistoryEntry(entryType, "west-policy", "kingdom_west", "active", "active", 0f, 25);
			SetProperty(entryType, westPolicy, "OwnerKingdomName", "瓦兰迪亚");
			SetProperty(entryType, westPolicy, "PolicyName", "西境粮仓章程");
			SetProperty(entryType, westPolicy, "PolicyContent", "semantic-high west policy");
			entries.Add(westPolicy);
			object westTargetOnly = BuildNpcPolicyHistoryEntry(entryType, "north-targets-west", "kingdom_north", "active", "active", 0f, 50);
			SetProperty(entryType, westTargetOnly, "OwnerKingdomName", "北方王国");
			SetProperty(entryType, westTargetOnly, "PolicyContent", "semantic-high north policy");
			SetProperty(entryType, westTargetOnly, "TargetKingdomIds", new List<string> { "kingdom_west" });
			entries.Add(westTargetOnly);

			object mentions = Activator.CreateInstance(mentionsType);
			string longMention = new string('长', 100);
			SetField(mentionsType, mentions, "Entities", new List<string>
			{
				"政策", "粮食", "最近", longMention, "第五个词"
			});
			long runtimeGeneration = Convert.ToInt64(Property(guardType, null, "CurrentGeneration"), CultureInfo.InvariantCulture);
			object[] retrieveArgs =
			{
				"你们最近实行的粮食政策是什么？",
				mentions,
				new List<string> { "kingdom_east" },
				entries,
				runtimeGeneration,
				null
			};
			bool retrieved = (bool)InvokeStatic(serviceType, "TryRetrieveDialogueByMentions", retrieveArgs, 6);
			object result = retrieveArgs[5];
			Check(retrieved && result != null,
				"Dialogue policy retrieval must succeed when the unified semantic query matches an owner-scoped policy.");
			Check((int)Property(resultType, result, "DialogueMentionTermCount") == 5
				&& (int)Property(resultType, result, "DialogueAttemptedQueryCount") == 1
				&& (int)Property(resultType, result, "DialogueSuccessfulQueryCount") == 1,
				"Dialogue policy retrieval must generate exactly one ONNX query from the full utterance and ordered mentions.");
			string semanticQuery = embeddingInputs.Single(value => value.IndexOf("玩家问题：", StringComparison.Ordinal) >= 0);
			Check(semanticQuery.Length <= 480
				&& semanticQuery.IndexOf("东方王国", StringComparison.Ordinal) >= 0
				&& semanticQuery.IndexOf("kingdom_east", StringComparison.Ordinal) >= 0
				&& semanticQuery.IndexOf("你们最近实行的粮食政策是什么", StringComparison.Ordinal) >= 0
				&& semanticQuery.IndexOf("政策", StringComparison.Ordinal) >= 0
				&& semanticQuery.IndexOf("粮食", StringComparison.Ordinal) >= 0
				&& semanticQuery.IndexOf("第五个词", StringComparison.Ordinal) < 0,
				"Dialogue policy query must include the scoped owner, complete player intent, and only the first four ordered entities within 480 characters.");
			string[] currentIds = Items(Property(resultType, result, "RelatedCurrentPolicies"))
				.Select(item => (string)Property(entryType, item, "EntryId"))
				.ToArray();
			string[] historicalIds = Items(Property(resultType, result, "RelatedHistoricalPolicies"))
				.Select(item => (string)Property(entryType, item, "EntryId"))
				.ToArray();
			Check(currentIds.SequenceEqual(new[] { "east-semantic-high", "east-semantic-mid-newer" }, StringComparer.Ordinal)
				&& historicalIds.SequenceEqual(new[] { "east-historical" }, StringComparer.Ordinal)
				&& !currentIds.Contains("east-semantic-low-newest", StringComparer.Ordinal)
				&& !currentIds.Contains("west-policy", StringComparer.Ordinal),
				"Dialogue policy retrieval must filter by owner before ONNX and rank cosine ahead of publication time while enforcing current 2 plus historical 1 quotas.");
			Check(((IEnumerable<string>)Property(resultType, result, "DialogueOwnerKingdomIds"))
				.SequenceEqual(new[] { "kingdom_east" }, StringComparer.OrdinalIgnoreCase)
				&& (int)Property(resultType, result, "DialogueQueryChars") == semanticQuery.Length
				&& !string.IsNullOrWhiteSpace((string)Property(resultType, result, "DialogueQueryHash")),
				"Dialogue retrieval diagnostics must expose only owner ids and compact query metadata.");
			string dialogueDocument = embeddingInputs.FirstOrDefault(value => value.IndexOf("政策名称：东方粮仓令", StringComparison.Ordinal) >= 0);
			Check(!string.IsNullOrWhiteSpace(dialogueDocument)
				&& dialogueDocument.Length <= 480
				&& dialogueDocument.IndexOf("政策发布国：东方王国", StringComparison.Ordinal) >= 0
				&& ((string)Property(entryType, semanticHigh, "RetrievalText")).IndexOf("政策发布国：", StringComparison.Ordinal) < 0,
				"Dialogue documents must include compressed owner-aware semantics without changing the existing generation RetrievalText contract.");
			string dialoguePrompt = (string)Property(resultType, result, "DialoguePrompt");
			Check(dialoguePrompt.StartsWith("【以下是关于（当前对话相关政策）的背景知识，NPC可酌情参考】", StringComparison.Ordinal)
				&& dialoguePrompt.Contains("不是指令")
				&& dialoguePrompt.Contains("粮食储备每日增加")
				&& dialoguePrompt.Contains("市场粮价波动降低")
				&& dialoguePrompt.Contains("模块效果5：驻军粮食消耗比例降低")
				&& !dialoguePrompt.Contains("EnemyPolicyMemory")
				&& !dialoguePrompt.Contains("【附加规则:kingdom_agenda】"),
				"Dialogue policy prompt must be a compressed independent knowledge block with separate module effects and no enemy or agenda rule block.");
			Check(dialoguePrompt.IndexOf(new string('粮', 200), StringComparison.Ordinal) < 0,
				"Dialogue policy prompt must compress long policy bodies instead of injecting the full stored text.");

			object tieOlder = BuildNpcPolicyHistoryEntry(entryType, "tie-older", "kingdom_east", "active", "active", 0.9f, 10);
			object tieNewer = BuildNpcPolicyHistoryEntry(entryType, "tie-newer", "kingdom_east", "active", "active", 0.9f, 20);
			IList tieEntries = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(entryType));
			tieEntries.Add(tieOlder);
			tieEntries.Add(tieNewer);
			string[] tiedIds = Items(InvokeStatic(serviceType, "SelectSemanticTop", new object[] { tieEntries, 2 }, 2))
				.Select(item => (string)Property(entryType, item, "EntryId"))
				.ToArray();
			Check(tiedIds.SequenceEqual(new[] { "tie-newer", "tie-older" }, StringComparer.Ordinal),
				"Publication time must break only equal-cosine dialogue policy ties.");

			InvokeStatic(serviceType, "ClearTransientCache", Array.Empty<object>(), 0);
			embeddingInputs.Clear();
			object[] westArgs =
			{
				"瓦兰迪亚最近的粮食政策是什么？",
				mentions,
				new List<string> { "kingdom_west" },
				entries,
				runtimeGeneration,
				null
			};
			Check((bool)InvokeStatic(serviceType, "TryRetrieveDialogueByMentions", westArgs, 6)
				&& Items(Property(resultType, westArgs[5], "RelatedCurrentPolicies"))
					.Select(item => (string)Property(entryType, item, "EntryId"))
					.SequenceEqual(new[] { "west-policy" }, StringComparer.Ordinal),
				"Explicit foreign kingdom retrieval must include only policies owned by that kingdom, never policies that merely target it.");

			embeddingInputs.Clear();
			object[] missingOwnerArgs =
			{
				"不存在王国的政策是什么？",
				mentions,
				new List<string> { "kingdom_missing" },
				entries,
				runtimeGeneration,
				null
			};
			Check(!(bool)InvokeStatic(serviceType, "TryRetrieveDialogueByMentions", missingOwnerArgs, 6)
				&& string.Equals((string)Property(resultType, missingOwnerArgs[5], "DialogueFailureCode"), "no_candidates", StringComparison.Ordinal)
				&& embeddingInputs.Count == 0,
				"An explicit kingdom without successful policies must fail closed before ONNX and must not fall back to another owner.");

			object countryOnlyMentions = Activator.CreateInstance(mentionsType);
			SetField(mentionsType, countryOnlyMentions, "Entities", new List<string> { "瓦兰迪亚" });
			embeddingInputs.Clear();
			object[] countryOnlyArgs =
			{
				"瓦兰迪亚现在怎么样？",
				countryOnlyMentions,
				new List<string> { "kingdom_west" },
				entries,
				runtimeGeneration,
				null
			};
			Check(!(bool)InvokeStatic(serviceType, "TryRetrieveDialogueByMentions", countryOnlyArgs, 6)
				&& string.Equals((string)Property(resultType, countryOnlyArgs[5], "DialogueFailureCode"), "no_policy_mention", StringComparison.Ordinal)
				&& embeddingInputs.Count == 0,
				"A country mention without a policy/law phrase or stored policy name must not trigger policy ONNX retrieval.");

			object namedPolicyMentions = Activator.CreateInstance(mentionsType);
			SetField(mentionsType, namedPolicyMentions, "Entities", new List<string> { "西境粮仓章程" });
			embeddingInputs.Clear();
			object[] namedPolicyArgs =
			{
				"西境粮仓章程现在执行得怎么样？",
				namedPolicyMentions,
				new List<string> { "kingdom_west" },
				entries,
				runtimeGeneration,
				null
			};
			Check((bool)InvokeStatic(serviceType, "TryRetrieveDialogueByMentions", namedPolicyArgs, 6)
				&& Items(Property(resultType, namedPolicyArgs[5], "RelatedCurrentPolicies"))
					.Select(item => (string)Property(entryType, item, "EntryId"))
					.SequenceEqual(new[] { "west-policy" }, StringComparer.Ordinal),
				"An exact stored policy-name mention must trigger the same owner-scoped semantic pipeline without requiring generic policy keywords.");

			object emptyMentions = Activator.CreateInstance(mentionsType);
			embeddingInputs.Clear();
			object[] emptyArgs = { "政策", emptyMentions, new List<string> { "kingdom_east" }, entries, runtimeGeneration, null };
			Check(!(bool)InvokeStatic(serviceType, "TryRetrieveDialogueByMentions", emptyArgs, 6)
				&& embeddingInputs.Count == 0,
				"Dialogue policy retrieval must not scan or call ONNX when preprocessing produced no entities.");

			embeddingOverride.SetValue(null, new Func<string, float[]>(text => null));
			object[] unavailableArgs = { "你们的政策", mentions, new List<string> { "kingdom_east" }, entries, runtimeGeneration, null };
			Check(!(bool)InvokeStatic(serviceType, "TryRetrieveDialogueByMentions", unavailableArgs, 6)
				&& string.Equals((string)Property(resultType, unavailableArgs[5], "DialogueFailureCode"), "query_embedding_unavailable", StringComparison.Ordinal),
				"Dialogue policy retrieval must fail closed without throwing when its single query embedding is unavailable.");

			object[] staleArgs = { "你们的政策", mentions, new List<string> { "kingdom_east" }, entries, runtimeGeneration + 1L, null };
			Check(!(bool)InvokeStatic(serviceType, "TryRetrieveDialogueByMentions", staleArgs, 6)
				&& string.Equals((string)Property(resultType, staleArgs[5], "DialogueFailureCode"), "stale_runtime_generation", StringComparison.Ordinal),
				"Dialogue policy retrieval must discard a stale save generation without affecting the caller.");

			Type behaviorType = SutType("AnimusForge.NpcRulerPolicyBehavior");
			object[] snapshotFailureArgs =
			{
				"你们的政策",
				mentions,
				new List<string>(),
				null,
				null,
				"kingdom_east",
				runtimeGeneration,
				null
			};
			Check(!(bool)InvokeStatic(behaviorType, "TryBuildPolicyDialogueContextForExternal", snapshotFailureArgs, 8),
				"Dialogue policy snapshot failure outside a campaign must return an empty optional context instead of throwing.");
			Check(((IEnumerable<string>)Property(resultType, snapshotFailureArgs[7], "DialogueOwnerKingdomIds"))
				.SequenceEqual(new[] { "kingdom_east" }, StringComparer.OrdinalIgnoreCase),
				"Dialogue policy retrieval must use the target NPC kingdom override when preprocessing names no kingdom.");
			object[] explicitOwnerArgs =
			{
				"瓦兰迪亚的政策",
				mentions,
				new List<string> { "kingdom_west" },
				null,
				null,
				"kingdom_east",
				runtimeGeneration,
				null
			};
			Check(!(bool)InvokeStatic(behaviorType, "TryBuildPolicyDialogueContextForExternal", explicitOwnerArgs, 8)
				&& ((IEnumerable<string>)Property(resultType, explicitOwnerArgs[7], "DialogueOwnerKingdomIds"))
					.SequenceEqual(new[] { "kingdom_west" }, StringComparer.OrdinalIgnoreCase),
				"Explicitly mentioned kingdoms must override the target NPC kingdom without falling back after snapshot failure.");

			Type playerBehaviorType = SutType("AnimusForge.CustomPolicyBehavior");
			string existingExtras = "普通上下文\n【附加规则:kingdom_agenda】\n议程动作规则";
			string appended = (string)InvokeStatic(playerBehaviorType, "AppendPolicyDialogueKnowledgeBlock", new object[] { existingExtras, dialoguePrompt }, 2);
			Check(appended.StartsWith(existingExtras, StringComparison.Ordinal)
				&& appended.EndsWith(dialoguePrompt, StringComparison.Ordinal)
				&& appended.IndexOf("【议程相关政策与事件】", StringComparison.Ordinal) < 0,
				"Policy dialogue knowledge must append after action rules and must not revive the old agenda-gated policy block.");
		}
		finally
		{
			embeddingOverride.SetValue(null, null);
			InvokeStatic(serviceType, "ClearTransientCache", Array.Empty<object>(), 0);
		}
	}

	private static List<string> ReadJsonStringList(JToken token)
	{
		return (token as JArray)?.Values<string>()
			.Where(value => !string.IsNullOrWhiteSpace(value))
			.ToList() ?? new List<string>();
	}

	private static void TestNpcDraftSemanticRepairOrchestrationContract(
		Type behavior,
		Type contextType,
		object context,
		object target,
		object draftPrompt,
		string validDraft,
		string wrongIdentityDraft)
	{
		FieldInfo overrideField = behavior.GetField("NpcPolicyApiTextOverrideForTests", All);
		FieldInfo embeddingOverrideField = behavior.GetField("NpcPolicyQueryEmbeddingOverrideForTests", All);
		Type jobType = behavior.GetNestedType("NpcPolicyGenerationJob", All);
		Type resultType = behavior.GetNestedType("NpcPolicyGenerationResult", All);
		Check(overrideField != null && embeddingOverrideField != null && jobType != null && resultType != null,
			"NPC draft repair orchestration requires the production API/embedding hooks and job/result contracts.");
		long runtimeGeneration = Convert.ToInt64(Property(
			SutType("AnimusForge.SaveRuntimeGuard"), null, "CurrentGeneration"), CultureInfo.InvariantCulture);
		object behaviorInstance = Activator.CreateInstance(behavior);
		Func<object> buildJob = () =>
		{
			object job = Activator.CreateInstance(jobType, nonPublic: true);
			SetField(jobType, job, "JobId", "npc-draft-repair-contract");
			SetField(jobType, job, "BatchId", "npc-draft-repair-contract");
			SetField(jobType, job, "Context", context);
			SetField(jobType, job, "RuntimeGeneration", runtimeGeneration);
			SetField(jobType, job, "HardTimeoutMilliseconds", 1000);
			return job;
		};
		embeddingOverrideField.SetValue(null, new Func<string, float[]>(query => new[] { 1f }));
		try
		{
			List<string> sources = new List<string>();
			overrideField.SetValue(null, new Func<string, string, long, Task<string>>((prompt, source, generation) =>
			{
				sources.Add(source ?? string.Empty);
				return Task.FromResult(sources.Count == 1 ? wrongIdentityDraft : validDraft);
			}));
			object repairedJob = buildJob();
			object repairedResult = Activator.CreateInstance(resultType, nonPublic: true);
			Task repairedTask = (Task)InvokeInstance(
				behavior,
				behaviorInstance,
				"GenerateNpcPolicyDraftWithSemanticRepairAsync",
				new[] { repairedJob, repairedResult, target, draftPrompt },
				4);
			repairedTask.GetAwaiter().GetResult();
			object repairedDraft = repairedTask.GetType().GetProperty("Result", All)?.GetValue(repairedTask, null);
			Check(repairedDraft != null
				&& sources.SequenceEqual(new[] { "NpcRulerPolicyDraft", "NpcRulerPolicyDraftRepair" }, StringComparer.Ordinal),
				"A wrong NPC kingdom/ruler must receive exactly one constrained draft repair and accept the corrected frozen identity.");

			sources.Clear();
			overrideField.SetValue(null, new Func<string, string, long, Task<string>>((prompt, source, generation) =>
			{
				sources.Add(source ?? string.Empty);
				return Task.FromResult(wrongIdentityDraft);
			}));
			object rejectedJob = buildJob();
			object rejectedResult = Activator.CreateInstance(resultType, nonPublic: true);
			Task rejectedTask = (Task)InvokeInstance(
				behavior,
				behaviorInstance,
				"GenerateNpcPolicyDraftWithSemanticRepairAsync",
				new[] { rejectedJob, rejectedResult, target, draftPrompt },
				4);
			rejectedTask.GetAwaiter().GetResult();
			object rejectedDraft = rejectedTask.GetType().GetProperty("Result", All)?.GetValue(rejectedTask, null);
			Check(rejectedDraft == null
				&& sources.SequenceEqual(new[] { "NpcRulerPolicyDraft", "NpcRulerPolicyDraftRepair" }, StringComparer.Ordinal),
				"A second wrong NPC identity must fail closed after one repair and must not proceed to the effect stage.");

			sources.Clear();
			object staleJob = buildJob();
			overrideField.SetValue(null, new Func<string, string, long, Task<string>>((prompt, source, generation) =>
			{
				sources.Add(source ?? string.Empty);
				SetField(jobType, staleJob, "Version", 1);
				return Task.FromResult(validDraft);
			}));
			Task staleTask = (Task)InvokeInstance(
				behavior,
				behaviorInstance,
				"ProcessPolicyGenerationJobAsync",
				new[] { staleJob },
				1);
			staleTask.GetAwaiter().GetResult();
			Check(sources.SequenceEqual(new[] { "NpcRulerPolicyDraft" }, StringComparer.Ordinal),
				"A generation that becomes stale after the accepted NPC draft must not send an EffectPlan request.");
		}
		finally
		{
			overrideField.SetValue(null, null);
			embeddingOverrideField.SetValue(null, null);
		}
	}

	private static void TestNpcEffectSemanticRepairOrchestrationContract(
		Type behavior,
		object context,
		object target,
		object draft,
		object effectPrompt,
		string validEffectPlan)
	{
		FieldInfo overrideField = behavior.GetField("NpcPolicyApiTextOverrideForTests", All);
		FieldInfo embeddingOverrideField = behavior.GetField("NpcPolicyQueryEmbeddingOverrideForTests", All);
		Type jobType = behavior.GetNestedType("NpcPolicyGenerationJob", All);
		Type resultType = behavior.GetNestedType("NpcPolicyGenerationResult", All);
		Check(overrideField != null && embeddingOverrideField != null && jobType != null && resultType != null,
			"NPC effect repair orchestration requires the production API/embedding hooks and job/result contracts.");
		List<string> sources = new List<string>();
		overrideField.SetValue(null, new Func<string, string, long, Task<string>>((prompt, source, generation) =>
		{
			sources.Add(source ?? string.Empty);
			return Task.FromResult(sources.Count == 1 ? "{" : validEffectPlan);
		}));
		embeddingOverrideField.SetValue(null, new Func<string, float[]>(query => new[] { 1f }));
		try
		{
			object job = Activator.CreateInstance(jobType, nonPublic: true);
			SetField(jobType, job, "JobId", "npc-effect-repair-contract");
			SetField(jobType, job, "BatchId", "npc-effect-repair-contract");
			SetField(jobType, job, "Context", context);
			SetField(jobType, job, "RuntimeGeneration", Convert.ToInt64(Property(
				SutType("AnimusForge.SaveRuntimeGuard"), null, "CurrentGeneration"), CultureInfo.InvariantCulture));
			SetField(jobType, job, "HardTimeoutMilliseconds", 1000);
			object result = Activator.CreateInstance(resultType, nonPublic: true);
			object behaviorInstance = Activator.CreateInstance(behavior);
			Task effectTask = (Task)InvokeInstance(
				behavior,
				behaviorInstance,
				"GenerateNpcPolicyEffectsWithSemanticRepairAsync",
				new[] { job, result, target, draft, effectPrompt },
				5);
			effectTask.GetAwaiter().GetResult();
			Check(sources.SequenceEqual(new[]
			{
				"NpcRulerPolicyEffectPostprocess",
				"NpcRulerPolicyEffectPostprocessRepair"
			}, StringComparer.Ordinal),
				"A malformed NPC EffectPlan must receive exactly one effect-only repair and never a third semantic attempt.");
			string finalError = resultType.GetField("Error", All).GetValue(result)?.ToString() ?? string.Empty;
			Check(finalError.IndexOf("target-kingdom-unavailable", StringComparison.OrdinalIgnoreCase) >= 0
				|| finalError.IndexOf("repair rejected", StringComparison.OrdinalIgnoreCase) >= 0,
				"The corrected NPC EffectPlan must pass strict JSON parsing and reach the expected no-Campaign target boundary: "
				+ finalError);
		}
		finally
		{
			overrideField.SetValue(null, null);
			embeddingOverrideField.SetValue(null, null);
		}
	}

	private static void TestNpcTwoStageApiCallOverrideContract(Type behavior, Type contextType, object context)
	{
		if (string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(OnnxRuntimeDirectoryEnvironmentVariable)))
		{
			return;
		}
		FieldInfo overrideField = behavior.GetField("NpcPolicyApiTextOverrideForTests", All);
		FieldInfo embeddingOverrideField = behavior.GetField("NpcPolicyQueryEmbeddingOverrideForTests", All);
		Check(overrideField != null,
			"NPC two-stage orchestration must expose an internal text-only API override for contract tests.");
		Check(embeddingOverrideField != null,
			"NPC two-stage orchestration must expose an internal query-embedding counter hook for contract tests.");
		object orchestrationTarget = Items(contextType.GetField("Kingdoms", All).GetValue(context)).Single();
		FieldInfo allowedTargetsField = orchestrationTarget.GetType().GetField("AllowedEffectTargets", All);
		IList orchestrationAllowedTargets = (IList)allowedTargetsField.GetValue(orchestrationTarget);
		for (int targetIndex = orchestrationAllowedTargets.Count - 1; targetIndex >= 0; targetIndex--)
		{
			object allowedTarget = orchestrationAllowedTargets[targetIndex];
			string planHandle = allowedTarget?.GetType().GetField("PlanHandle", All)?.GetValue(allowedTarget)?.ToString() ?? string.Empty;
			if (!string.IsNullOrWhiteSpace(planHandle))
			{
				orchestrationAllowedTargets.RemoveAt(targetIndex);
			}
		}
		List<string> sources = new List<string>();
		List<string> prompts = new List<string>();
		string generationError = string.Empty;
		int queryEmbeddingCount = 0;
		string routingQuery = "Granary Reform\nKingdom West funds granaries.";
		int expectedQueryEmbeddingCount = PolicyEffectModuleRouter.BuildQueryIntents(
			routingQuery,
			PolicyEffectScopes.Kingdom).Count;
		string draftResponse = new JObject
		{
			["policy"] = new JObject
			{
				["kingdomId"] = "kingdom_west", ["kingdomName"] = "Kingdom West",
				["rulerHeroId"] = "hero_west", ["rulerName"] = "Ruler West",
				["creativePremise"] = "focused", ["policyName"] = "Granary Reform",
				["policyContent"] = "Kingdom West funds granaries.", ["policyDigest"] = "fund granaries",
				["eventPremise"] = "deliveries change", ["feedbackTitle"] = "debate",
				["publicFeedback"] = "support", ["feedbackDigest"] = "support grows",
				["impactSummary"] = "food improves", ["numericIntent"] = "raise food reserves",
				["authoritarianWeight"] = 0.2, ["oligarchicWeight"] = 0.1, ["egalitarianWeight"] = 0.4,
				["durationDays"] = 30
			}
		}.ToString(Formatting.None);
		JObject wrongDraft = JObject.Parse(draftResponse);
		wrongDraft["policy"]["kingdomId"] = "kingdom_east";
		wrongDraft["policy"]["kingdomName"] = "Kingdom East";
		wrongDraft["policy"]["rulerHeroId"] = "hero_east";
		wrongDraft["policy"]["rulerName"] = "Ruler East";
		string wrongDraftResponse = wrongDraft.ToString(Formatting.None);
		string effectResponse = "{\"effectPlanVersion\":1,\"disposition\":\"unsupported\",\"reason\":\"fixture rejection\",\"effects\":[]}";
		Func<string, string, long, Task<string>> fake = (prompt, source, generation) =>
		{
			prompts.Add(prompt ?? string.Empty);
			sources.Add(source ?? string.Empty);
			return Task.FromResult(string.Equals(source, "NpcRulerPolicyDraft", StringComparison.Ordinal)
				? wrongDraftResponse
				: string.Equals(source, "NpcRulerPolicyDraftRepair", StringComparison.Ordinal)
					? draftResponse
					: effectResponse);
		};
		overrideField.SetValue(null, fake);
		Func<string, float[]> queryEmbedding = query =>
		{
			queryEmbeddingCount++;
			return (float[])InvokeStatic(
				SutType("AnimusForge.PolicyEffects.PolicyEffectModuleRouter"),
				"GetQueryEmbedding",
				new object[] { query },
				1);
		};
		embeddingOverrideField.SetValue(null, queryEmbedding);
		try
		{
			Type jobType = behavior.GetNestedType("NpcPolicyGenerationJob", BindingFlags.NonPublic);
			object job = Activator.CreateInstance(jobType, nonPublic: true);
			SetField(jobType, job, "JobId", "two-stage-contract-job");
			SetField(jobType, job, "BatchId", "npc-two-stage-contract");
			SetField(jobType, job, "Context", context);
			SetField(jobType, job, "RuntimeGeneration", Convert.ToInt64(Property(
				SutType("AnimusForge.SaveRuntimeGuard"), null, "CurrentGeneration"), CultureInfo.InvariantCulture));
			SetField(jobType, job, "HardTimeoutMilliseconds", 1000);
			object behaviorInstance = Activator.CreateInstance(behavior);
			Task task = (Task)InvokeInstance(behavior, behaviorInstance, "ProcessPolicyGenerationJobAsync", new[] { job }, 1);
			task.GetAwaiter().GetResult();
			object pendingCommit = Items(behavior.GetField("_pendingPolicyCommits", All).GetValue(behaviorInstance)).LastOrDefault();
			object generationResult = pendingCommit?.GetType().GetField("GenerationResult", All)?.GetValue(pendingCommit);
			generationError = generationResult?.GetType().GetField("Error", All)?.GetValue(generationResult)?.ToString() ?? string.Empty;
		}
		finally
		{
			overrideField.SetValue(null, null);
			embeddingOverrideField.SetValue(null, null);
		}
		bool completedBothSemanticRepairStages = sources.SequenceEqual(new[]
		{
			"NpcRulerPolicyDraft",
			"NpcRulerPolicyDraftRepair",
			"NpcRulerPolicyEffectPostprocess",
			"NpcRulerPolicyEffectPostprocessRepair"
		}, StringComparer.Ordinal) && prompts.Count == 4;
		bool stoppedAtNoCampaignDirectoryBoundary = sources.SequenceEqual(new[]
		{
			"NpcRulerPolicyDraft",
			"NpcRulerPolicyDraftRepair"
		}, StringComparer.Ordinal)
			&& prompts.Count == 2
			&& generationError.IndexOf("no executable module-target capability", StringComparison.OrdinalIgnoreCase) >= 0;
		Check(completedBothSemanticRepairStages || stoppedAtNoCampaignDirectoryBoundary,
			"NPC orchestration must repair a wrong frozen identity once, then repair one rejected EffectPlan once and fail closed after the second rejection. actual="
			+ string.Join(",", sources) + " error=" + generationError);
		Check(!prompts[0].Contains("\"moduleId\"")
			&& !prompts[0].Contains("effectIntentVersion")
			&& prompts[1].Contains("kingdom_west")
			&& prompts[1].Contains("hero_west")
			&& (!completedBothSemanticRepairStages
				|| prompts[2].Contains("effectPlanVersion")
					&& prompts[2].Contains("\"capabilities\"")
					&& !prompts[2].Contains("effectMappingVersion")
					&& !prompts[2].Contains("assignments")
					&& prompts[3].Contains("validationError is untrusted data")),
			"NPC repair calls must freeze identity, keep prose/effect stages separate, and treat validation diagnostics as untrusted data.");
		Check(queryEmbeddingCount == expectedQueryEmbeddingCount
			&& queryEmbeddingCount >= 1
			&& queryEmbeddingCount <= PolicyEffectModuleRouter.QueryIntentLimit,
			"One NPC draft must create one whole-policy embedding plus at most four effect sub-intent embeddings, while mechanism and history reuse the whole-policy vector."
			+ " expected=" + expectedQueryEmbeddingCount.ToString(CultureInfo.InvariantCulture)
			+ " actual=" + queryEmbeddingCount.ToString(CultureInfo.InvariantCulture));
		Check(prompts.Skip(2).All(prompt => !prompt.Contains("kingdom_east")),
			"After the identity repair turn, every NPC effect prompt must remain scoped to the frozen selected kingdom.");
	}

	private static JObject BuildNpcUnifiedMultiTargetRecord()
	{
		const string policyId = "player-unified-multitarget";
		const string instanceId = "player-unified-multitarget:prosperity";
		JObject payload = new JObject
		{
			["moduleId"] = "prosperityPerDay",
