			["value"] = 2.5
		};
		JArray effects = new JArray();
		foreach (string kingdomId in new[] { "k1", "k2" })
		{
			JObject targetSet = new JObject
			{
				["structureVersion"] = 1,
				["selectorHandles"] = new JArray("K:" + kingdomId),
				["kingdomIds"] = new JArray(kingdomId)
			};
			JObject receipt = new JObject
			{
				["receiptId"] = "receipt:" + instanceId,
				["instanceId"] = instanceId,
				["policyId"] = policyId,
				["moduleId"] = "prosperityPerDay",
				["targetSet"] = targetSet.DeepClone(),
				["status"] = 0,
				["requestedValue"] = 2.5,
				["appliedValue"] = 2.5,
				["requestedPayload"] = payload.DeepClone(),
				["appliedPayload"] = payload.DeepClone(),
				["campaignDay"] = 10,
				["message"] = "applied"
			};
			JObject instance = new JObject
			{
				["instanceId"] = instanceId,
				["policyId"] = policyId,
				["moduleId"] = "prosperityPerDay",
				["payloadSchemaVersion"] = 1,
				["payload"] = payload.DeepClone(),
				["targetSet"] = targetSet,
				["lifecycleState"] = 1,
				["stateSchemaVersion"] = 1,
				["executionReceipt"] = receipt,
				["startDay"] = 10,
				["endDay"] = 18,
				["sourceScope"] = "kingdom",
				["reason"] = "multi-target contract"
			};
			effects.Add(new JObject
			{
				["effectId"] = "player-effect",
