				["durationDays"] = 8,
				["remainingDays"] = 8,
				["isEnded"] = false,
				["reason"] = "multi-target contract",
				["moduleEffects"] = new JArray(instance)
			});
		}
		return new JObject
		{
			["Version"] = 5,
			["policyId"] = policyId,
			["kingdomId"] = "k1",
			["kingdomName"] = "Issuer",
			["isPlayerPolicy"] = true,
			["Day"] = 10,
			["durationDays"] = 8,
			["effects"] = effects,
			["executionReceipts"] = new JArray()
		};
	}

