	private static void TestStructuredUnknownModuleRoundTripIsInert()
	{
		const string structuredPayload = "{\"mode\":\"weighted\",\"enabled\":true,"
			+ "\"bands\":[{\"name\":\"low\",\"weight\":0.25},{\"name\":\"high\",\"weight\":0.75}]}";
		string envelopeJson = "{\"schemaVersion\":1,\"instances\":[{\"instanceId\":\"dummy-structured-1\","
			+ "\"policyId\":\"p-1\",\"moduleId\":\"contractDummy.structured\",\"payloadSchemaVersion\":3,"
			+ "\"payload\":" + structuredPayload + ",\"targetSet\":{\"structureVersion\":1,"
			+ "\"selectorHandles\":[\"K:k1\"],\"selectorIds\":[\"selector.a\"],"
			+ "\"targetPlans\":[{\"planVersion\":2,\"resolverVersion\":1,\"branches\":[{"
			+ "\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"Town\","
			+ "\"relation\":\"Domestic\",\"cardinality\":\"All\"}]}],\"kingdomIds\":[\"k1\"]},\"lifecycleState\":1,"
			+ "\"stateSchemaVersion\":4,\"runtimeState\":{\"opaque\":[1,2,3]},\"startDay\":10,"
			+ "\"endDay\":20,\"sourceScope\":\"kingdom\",\"reason\":\"structured contract dummy\"}],\"receipts\":[]}";
		Type codec = SutType("AnimusForge.PolicyEffects.PolicyEffectSaveCodec");
		object[] decode = { envelopeJson, null, null };
		Check((bool)InvokeStatic(codec, "TryDeserialize", decode, 3),
			"Structured unknown module envelope must decode: " + decode[2]);
		object decodeResult = decode[1];
		object normalized = Items(Property(decodeResult.GetType(), decodeResult, "Instances")).Single();
		Check((bool)Property(normalized.GetType(), normalized, "IsInert"),
			"Unknown structured module must remain inert.");
		Check(string.Equals((string)Property(normalized.GetType(), normalized, "InertReason"), "unknownModule", StringComparison.Ordinal),
			"Unknown structured module must report unknownModule.");
		object envelope = Property(decodeResult.GetType(), decodeResult, "Envelope");
		object[] encode = { envelope, null, null };
		Check((bool)InvokeStatic(codec, "TrySerialize", encode, 3),
			"Structured unknown module envelope must serialize: " + encode[2]);
		string roundTripJson = (string)encode[1];
		Check(roundTripJson.Contains("weighted") && roundTripJson.Contains("bands") && roundTripJson.Contains("enabled")
			&& roundTripJson.Contains("selector.a"),
			"Structured non-numeric payload members must survive codec round-trip.");
		object[] decodeAgain = { roundTripJson, null, null };
		Check((bool)InvokeStatic(codec, "TryDeserialize", decodeAgain, 3),
			"Structured unknown module must decode after round-trip: " + decodeAgain[2]);
		object normalizedAgain = Items(Property(decodeAgain[1].GetType(), decodeAgain[1], "Instances")).Single();
		Check((bool)Property(normalizedAgain.GetType(), normalizedAgain, "IsInert"),
			"Round-tripped structured unknown module must still be inert.");
		object roundTripSaveData = Property(normalizedAgain.GetType(), normalizedAgain, "SaveData");
		object roundTripTargetSet = Property(roundTripSaveData.GetType(), roundTripSaveData, "TargetSet");
		Check(ReadStringPropertyValues(roundTripTargetSet, "SelectorIds").SequenceEqual(new[] { "selector.a" }, StringComparer.Ordinal),
			"selectorIds must survive save-codec round-trip.");
		Check(Items(Property(roundTripTargetSet.GetType(), roundTripTargetSet, "TargetPlans")).Count() == 1,
			"A valid TargetPlan must survive save-codec round-trip.");

		JObject v3ThresholdEnvelope = JObject.Parse(envelopeJson);
		v3ThresholdEnvelope["instances"][0]["targetSet"]["targetPlans"] = new JArray(JObject.Parse(
			"{\"planVersion\":3,\"resolverVersion\":2,\"branches\":[{"
			+ "\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\","
			+ "\"entityType\":\"Town\",\"relation\":\"Domestic\","
			+ "\"metric\":\"Militia\",\"sortDirection\":\"Descending\","
			+ "\"metricComparison\":\"GreaterThanOrEqual\",\"metricThreshold\":250,"
			+ "\"cardinality\":\"TopN\",\"limit\":2}]}"));
		object[] v3Decode = { v3ThresholdEnvelope.ToString(Formatting.None), null, null };
		Check((bool)InvokeStatic(codec, "TryDeserialize", v3Decode, 3),
			"A v3 threshold TargetPlan must decode through the existing save codec: " + v3Decode[2]);
		object v3DecodedInstance = Items(Property(v3Decode[1].GetType(), v3Decode[1], "Instances")).Single();
		object v3DecodedTargetSet = Property(Property(v3DecodedInstance.GetType(), v3DecodedInstance, "SaveData").GetType(),
			Property(v3DecodedInstance.GetType(), v3DecodedInstance, "SaveData"), "TargetSet");
		object v3DecodedPlan = Items(Property(v3DecodedTargetSet.GetType(), v3DecodedTargetSet, "TargetPlans")).Single();
		object v3DecodedBranch = Items(Property(v3DecodedPlan.GetType(), v3DecodedPlan, "Branches")).Single();
		Check(Convert.ToInt32(Property(v3DecodedPlan.GetType(), v3DecodedPlan, "PlanVersion"), CultureInfo.InvariantCulture) == 3
			&& string.Equals(Property(v3DecodedBranch.GetType(), v3DecodedBranch, "Metric").ToString(), "Militia", StringComparison.Ordinal)
			&& string.Equals(Property(v3DecodedBranch.GetType(), v3DecodedBranch, "MetricComparison").ToString(), "GreaterThanOrEqual", StringComparison.Ordinal)
			&& Math.Abs(Convert.ToSingle(Property(v3DecodedBranch.GetType(), v3DecodedBranch, "MetricThreshold"), CultureInfo.InvariantCulture) - 250f) < 0.0001f,
			"The save codec must retain the v3 metric threshold without widening its target set.");
		object[] v3Encode = { Property(v3Decode[1].GetType(), v3Decode[1], "Envelope"), null, null };
		Check((bool)InvokeStatic(codec, "TrySerialize", v3Encode, 3)
			&& ((string)v3Encode[1]).Contains("\"metricComparison\":\"GreaterThanOrEqual\"")
			&& ((string)v3Encode[1]).Contains("\"metricThreshold\":250"),
			"A v3 threshold TargetPlan must survive save-codec serialization with its predicate intact.");

		string invalidPlanEnvelope = "{\"schemaVersion\":1,\"instances\":[{\"instanceId\":\"invalid-plan-1\","
			+ "\"policyId\":\"p-invalid\",\"moduleId\":\"prosperityPerDay\",\"payloadSchemaVersion\":1,"
			+ "\"payload\":{\"value\":1},\"targetSet\":{\"structureVersion\":1,\"selectorHandles\":[\"P0\"],"
			+ "\"targetPlans\":[{\"planVersion\":2,\"resolverVersion\":1,\"branches\":[{"
			+ "\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\",\"entityType\":\"Town\","
			+ "\"relation\":\"FutureRelation\",\"cardinality\":\"All\"}]}]},\"lifecycleState\":1,"
			+ "\"stateSchemaVersion\":1,\"startDay\":10,\"endDay\":20,\"sourceScope\":\"local\",\"reason\":\"invalid plan\"}],\"receipts\":[]}";
		object[] invalidPlanDecode = { invalidPlanEnvelope, null, null };
		Check((bool)InvokeStatic(codec, "TryDeserialize", invalidPlanDecode, 3),
			"A known module with an unknown future TargetPlan operator must remain deserializable: " + invalidPlanDecode[2]);
		object invalidPlanNormalized = Items(Property(invalidPlanDecode[1].GetType(), invalidPlanDecode[1], "Instances")).Single();
		Check((bool)Property(invalidPlanNormalized.GetType(), invalidPlanNormalized, "IsInert")
			&& ((string)Property(invalidPlanNormalized.GetType(), invalidPlanNormalized, "InertReason"))
				.StartsWith("invalidTargetPlan:", StringComparison.Ordinal),
			"Unknown TargetPlan operators on known modules must be preserved inert and never executed.");
		Type targetSetType = SutType("AnimusForge.PolicyEffects.PolicyEffectCanonicalTargetSet");
		object legacyTargetSet = TokenToObject(JObject.Parse("{\"structureVersion\":1,\"settlementIds\":[\"s1\"]}"), targetSetType);
		Check(!ReadStringPropertyValues(legacyTargetSet, "SelectorIds").Any(),
			"Legacy target sets without selectorIds must deserialize as an empty list.");

		Type catalog = SutType("AnimusForge.PolicyEffects.PolicyEffectModuleCatalog");
		object[] resolve = { "contractDummy.structured", null };
		Check(!(bool)InvokeStatic(catalog, "TryResolveCanonicalId", resolve, 2), "Unknown module must not become executable.");
		object saveData = Items(Property(envelope.GetType(), envelope, "Instances")).Single();
		object[] deserialize = { "contractDummy.structured", Property(saveData.GetType(), saveData, "Payload"), 3, null, null };
		Check(!(bool)InvokeStatic(catalog, "TryDeserializePayload", deserialize, 5), "Unknown module payload must remain inert.");
		Check(deserialize[3] == null, "Unknown module must not produce an executable typed payload.");
	}

	private static void TestPolicyEffectPlanSaveAndLifecycleContracts()
	{
		Check(PolicyEffectDataVersions.SaveSchemaVersion == 2,
			"EffectPlan persistence must upgrade the policy effect save envelope to v2.");
		Type codec = SutType("AnimusForge.PolicyEffects.PolicyEffectSaveCodec");
		const string payload = "{\"moduleId\":\"prosperityPerDay\",\"schemaVersion\":1,\"value\":2}";
		const string target = "{\"structureVersion\":1,\"selectorHandles\":[\"S:s1\"],\"townIds\":[\"s1\"]}";
		string legacyJson = "{\"schemaVersion\":1,\"instances\":[{\"instanceId\":\"legacy-independent\","
			+ "\"policyId\":\"p-legacy\",\"moduleId\":\"prosperityPerDay\",\"payloadSchemaVersion\":1,"
			+ "\"payload\":" + payload + ",\"targetSet\":" + target + ",\"lifecycleState\":1,"
			+ "\"stateSchemaVersion\":1,\"startDay\":10,\"endDay\":20,\"sourceScope\":\"local\"}],\"receipts\":[]}";
		object[] legacyDecode = { legacyJson, null, null };
		Check((bool)InvokeStatic(codec, "TryDeserialize", legacyDecode, 3),
			"A v1 save must migrate without semantic expansion: " + legacyDecode[2]);
		object legacyNormalized = Items(Property(legacyDecode[1].GetType(), legacyDecode[1], "Instances")).Single();
		object legacySave = Property(legacyNormalized.GetType(), legacyNormalized, "SaveData");
		Check(Convert.ToInt32(Property(legacySave.GetType(), legacySave, "EffectPlanVersion"), CultureInfo.InvariantCulture)
				== PolicyEffectPlanVersions.CurrentVersion
			&& string.Equals(Property(legacySave.GetType(), legacySave, "MechanismKind").ToString(), "Independent", StringComparison.Ordinal)
			&& string.Equals(Property(legacySave.GetType(), legacySave, "MechanismRole").ToString(), "Subject", StringComparison.Ordinal),
			"A v1 save must become one independent subject mechanism.");

		string linkedJson = "{\"schemaVersion\":2,\"instances\":["
			+ BuildEffectPlanSaveInstanceJson("linked-source", "M0", "source", false, false, "s1", payload)
			+ "," + BuildEffectPlanSaveInstanceJson("linked-beneficiary", "M0", "beneficiary", false, false, "s2", payload)
			+ "],\"receipts\":[]}";
		object[] linkedDecode = { linkedJson, null, null };
		Check((bool)InvokeStatic(codec, "TryDeserialize", linkedDecode, 3),
			"A valid linked v2 save must decode: " + linkedDecode[2]);
		object linkedEnvelope = Property(linkedDecode[1].GetType(), linkedDecode[1], "Envelope");
		object[] linkedEncode = { linkedEnvelope, null, null };
		Check((bool)InvokeStatic(codec, "TrySerialize", linkedEncode, 3)
			&& ((string)linkedEncode[1]).Contains("\"mechanismId\":\"M0\"")
			&& ((string)linkedEncode[1]).Contains("\"mechanismRole\":\"beneficiary\""),
			"Linked mechanism metadata must survive save round-trip: " + linkedEncode[2]);

		JObject overlappingSource = JObject.Parse(BuildEffectPlanSaveInstanceJson(
			"overlap-source", "M-overlap", "source", false, false, "s1", payload));
		JObject overlappingBeneficiary = JObject.Parse(BuildEffectPlanSaveInstanceJson(
			"overlap-beneficiary", "M-overlap", "beneficiary", false, false, "s1", payload));
		string activeOverlapJson = new JObject
		{
			["schemaVersion"] = 2,
			["instances"] = new JArray(overlappingSource.DeepClone(), overlappingBeneficiary.DeepClone()),
			["receipts"] = new JArray()
		}.ToString(Formatting.None);
		object[] activeOverlapDecode = { activeOverlapJson, null, null };
		Check(!(bool)InvokeStatic(codec, "TryDeserialize", activeOverlapDecode, 3),
			"An active same-module linked mechanism must still reject overlapping sides.");
		overlappingSource["lifecycleState"] = 2;
		overlappingBeneficiary["lifecycleState"] = 2;
		string suspendedOverlapJson = new JObject
		{
			["schemaVersion"] = 2,
			["instances"] = new JArray(overlappingSource, overlappingBeneficiary),
			["receipts"] = new JArray()
		}.ToString(Formatting.None);
		object[] suspendedOverlapDecode = { suspendedOverlapJson, null, null };
		Check((bool)InvokeStatic(codec, "TryDeserialize", suspendedOverlapDecode, 3),
			"A runtime-suspended linked overlap must remain persistable for later recovery: " + suspendedOverlapDecode[2]);
		object suspendedOverlapEnvelope = Property(suspendedOverlapDecode[1].GetType(), suspendedOverlapDecode[1], "Envelope");
		object[] suspendedOverlapEncode = { suspendedOverlapEnvelope, null, null };
		Check((bool)InvokeStatic(codec, "TrySerialize", suspendedOverlapEncode, 3),
			"A runtime-suspended linked overlap must survive save round-trip: " + suspendedOverlapEncode[2]);

		string futureJson = "{\"schemaVersion\":2,\"instances\":[{\"instanceId\":\"future-plan\","
			+ "\"policyId\":\"p-future\",\"moduleId\":\"prosperityPerDay\",\"effectPlanVersion\":99,"
			+ "\"mechanismId\":\"M0\",\"mechanismKind\":\"independent\",\"mechanismRole\":\"subject\","
			+ "\"payloadSchemaVersion\":1,\"payload\":" + payload + ",\"targetSet\":" + target + ","
			+ "\"lifecycleState\":1,\"stateSchemaVersion\":1,\"sourceScope\":\"local\"}],\"receipts\":[]}";
		object[] futureDecode = { futureJson, null, null };
		Check((bool)InvokeStatic(codec, "TryDeserialize", futureDecode, 3),
			"An unknown EffectPlan version must remain readable: " + futureDecode[2]);
		object futureNormalized = Items(Property(futureDecode[1].GetType(), futureDecode[1], "Instances")).Single();
		Check((bool)Property(futureNormalized.GetType(), futureNormalized, "IsInert")
			&& ((string)Property(futureNormalized.GetType(), futureNormalized, "InertReason"))
				.StartsWith("invalidEffectPlan:", StringComparison.Ordinal),
			"An unknown EffectPlan version must remain inert.");
		Type behaviorType = SutType("AnimusForge.CustomPolicyBehavior");
		Type activeEffectType = behaviorType.GetNestedType("ActivePolicyEffectSaveData", All);
		object activeEffect = Activator.CreateInstance(activeEffectType, nonPublic: true);
		SetProperty(activeEffectType, activeEffect, "EffectId", "future-plan-active");
		((IList)Property(activeEffectType, activeEffect, "ModuleEffects")).Add(
			Property(futureNormalized.GetType(), futureNormalized, "SaveData"));
		object futureContributions = InvokeStatic(
			behaviorType,
			"BuildModulePolicyEffectRuntimeContributions",
			new[] { activeEffect },
			1);
		Check(!Items(futureContributions).Any(),
			"An unknown EffectPlan version must never enter the model-modifier runtime index.");

		Type saveDataType = SutType("AnimusForge.PolicyEffects.PolicyEffectInstanceSaveData");
		object source = TokenToObject(JObject.Parse(BuildEffectPlanSaveInstanceJson(
			"runtime-source", "M1", "source", false, false, string.Empty, payload)), saveDataType);
		object beneficiary = TokenToObject(JObject.Parse(BuildEffectPlanSaveInstanceJson(
			"runtime-beneficiary", "M1", "beneficiary", false, false, "s2", payload)), saveDataType);
		Array linkedInstances = Array.CreateInstance(saveDataType, 2);
		linkedInstances.SetValue(source, 0);
		linkedInstances.SetValue(beneficiary, 1);
		FreezeLinkedMechanismContract(linkedInstances);
		Type coordinator = SutType("AnimusForge.PolicyEffectActivationCoordinator");
		object[] suspend = { linkedInstances, null, null };
		Check((bool)InvokeStatic(coordinator, "ReconcileMechanismLifecycleStates", suspend, 3)
			&& (bool)suspend[1]
			&& string.Equals(Property(saveDataType, source, "LifecycleState").ToString(), "Suspended", StringComparison.Ordinal)
			&& string.Equals(Property(saveDataType, beneficiary, "LifecycleState").ToString(), "Suspended", StringComparison.Ordinal),
			"A linked mechanism must suspend every known leg when one required leg is empty: " + suspend[2]);
		object sourceTargetSet = Property(saveDataType, source, "TargetSet");
		((IList<string>)Property(sourceTargetSet.GetType(), sourceTargetSet, "TownIds")).Add("s1");
		object[] resume = { linkedInstances, null, null };
		Check((bool)InvokeStatic(coordinator, "ReconcileMechanismLifecycleStates", resume, 3)
			&& (bool)resume[1]
			&& Items(linkedInstances).All(instance =>
				string.Equals(Property(saveDataType, instance, "LifecycleState").ToString(), "Active", StringComparison.Ordinal)),
			"A linked mechanism must resume as a group after all required legs recover: " + resume[2]);
		object beneficiaryTargetSet = Property(saveDataType, beneficiary, "TargetSet");
		IList<string> beneficiaryTownIds = (IList<string>)Property(beneficiaryTargetSet.GetType(), beneficiaryTargetSet, "TownIds");
		beneficiaryTownIds.Add("s1");
		object[] overlapSuspend = { linkedInstances, null, null };
		Check((bool)InvokeStatic(coordinator, "ReconcileMechanismLifecycleStates", overlapSuspend, 3)
			&& (bool)overlapSuspend[1]
			&& Items(linkedInstances).All(instance =>
				string.Equals(Property(saveDataType, instance, "LifecycleState").ToString(), "Suspended", StringComparison.Ordinal)),
			"A same-module linked mechanism must suspend as a group when its materialized sides overlap: " + overlapSuspend[2]);
		beneficiaryTownIds.Remove("s1");
		object[] overlapResume = { linkedInstances, null, null };
		Check((bool)InvokeStatic(coordinator, "ReconcileMechanismLifecycleStates", overlapResume, 3)
			&& (bool)overlapResume[1]
			&& Items(linkedInstances).All(instance =>
				string.Equals(Property(saveDataType, instance, "LifecycleState").ToString(), "Active", StringComparison.Ordinal)),
			"A linked mechanism suspended by overlap must resume when its sides separate: " + overlapResume[2]);
		SetProperty(saveDataType, source, "LifecycleState", EnumValue(
			SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState"), "Completed"));
		object[] crossCadenceReconcile = { linkedInstances, null, null };
		Check((bool)InvokeStatic(coordinator, "ReconcileMechanismLifecycleStates", crossCadenceReconcile, 3)
			&& !(bool)crossCadenceReconcile[1]
			&& string.Equals(Property(saveDataType, source, "LifecycleState").ToString(), "Completed", StringComparison.Ordinal)
			&& string.Equals(Property(saveDataType, beneficiary, "LifecycleState").ToString(), "Active", StringComparison.Ordinal),
			"A completed ScheduledOnce leg must remain part of contract validation without making a live Daily leg look missing.");
		SetProperty(saveDataType, source, "LifecycleState", EnumValue(
			SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState"), "Failed"));
		object[] failedLegReconcile = { linkedInstances, null, null };
		Check((bool)InvokeStatic(coordinator, "ReconcileMechanismLifecycleStates", failedLegReconcile, 3)
			&& Items(linkedInstances).All(instance =>
				string.Equals(Property(saveDataType, instance, "LifecycleState").ToString(), "Failed", StringComparison.Ordinal)),
			"A persisted Failed required leg must fail the complete linked mechanism instead of disappearing before grouping.");

		SetProperty(saveDataType, beneficiary, "LifecycleState", EnumValue(
			SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState"), "Active"));
		Array missingLegInstances = Array.CreateInstance(saveDataType, 1);
		missingLegInstances.SetValue(beneficiary, 0);
		object[] missingLegReconcile = { missingLegInstances, null, null };
		Check((bool)InvokeStatic(coordinator, "ReconcileMechanismLifecycleStates", missingLegReconcile, 3)
			&& string.Equals(Property(saveDataType, beneficiary, "LifecycleState").ToString(), "Failed", StringComparison.Ordinal),
			"A linked mechanism with a missing persisted leg must fail closed.");

		SetProperty(saveDataType, source, "LifecycleState", EnumValue(
			SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState"), "Active"));
		SetProperty(saveDataType, beneficiary, "LifecycleState", EnumValue(
			SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState"), "Active"));
		SetProperty(saveDataType, source, "ModuleId", "heroGoldPerDay");
		SetProperty(saveDataType, beneficiary, "ModuleId", "heroGoldPerDay");
		FreezeLinkedMechanismContract(linkedInstances);
		SetProperty(saveDataType, beneficiary, "MechanismContractHash", "tampered");
		object[] tamperedContractReconcile = { linkedInstances, null, null };
		Check((bool)InvokeStatic(coordinator, "ReconcileMechanismLifecycleStates", tamperedContractReconcile, 3)
			&& Items(linkedInstances).All(instance =>
				string.Equals(Property(saveDataType, instance, "LifecycleState").ToString(), "Failed", StringComparison.Ordinal)),
			"A tampered linked mechanism contract must fail every leg before execution.");

		SetProperty(saveDataType, source, "LifecycleState", EnumValue(
			SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState"), "Active"));
		SetProperty(saveDataType, beneficiary, "LifecycleState", EnumValue(
			SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState"), "Active"));
		FreezeLinkedMechanismContract(linkedInstances);
		foreach (object instance in Items(linkedInstances))
		{
			IList expectedIds = (IList)Property(saveDataType, instance, "ExpectedMechanismLegIds");
			expectedIds.Clear();
			expectedIds.Add("source");
			expectedIds.Add("source");
		}
		object[] duplicatedContractReconcile = { linkedInstances, null, null };
		Check((bool)InvokeStatic(coordinator, "ReconcileMechanismLifecycleStates", duplicatedContractReconcile, 3)
			&& Items(linkedInstances).All(instance =>
				string.Equals(Property(saveDataType, instance, "LifecycleState").ToString(), "Failed", StringComparison.Ordinal)),
			"A linked mechanism contract with duplicated expected leg IDs must fail every leg.");

		SetProperty(saveDataType, source, "LifecycleState", EnumValue(
			SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState"), "Active"));
		SetProperty(saveDataType, beneficiary, "LifecycleState", EnumValue(
			SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState"), "Active"));
		FreezeLinkedMechanismContract(linkedInstances);
		string sourceDailyKey = "runtime-source\u001f1\u001fs1";
		string beneficiaryDailyKey = "runtime-beneficiary\u001f1\u001fs2";
		object[] staleFrozenDaily =
		{
			linkedInstances,
			new List<string> { sourceDailyKey, beneficiaryDailyKey },
			new HashSet<string>(new[] { sourceDailyKey }, StringComparer.OrdinalIgnoreCase),
			null
		};
		Check(!(bool)InvokeStatic(behaviorType, "TryPreflightFrozenLinkedDailyEntries", staleFrozenDaily, 4)
			&& Items(linkedInstances).All(instance =>
				string.Equals(Property(saveDataType, instance, "LifecycleState").ToString(), "Suspended", StringComparison.Ordinal)),
			"A frozen daily Linked bundle must suspend every leg when one target entry disappears after refresh.");

		SetProperty(saveDataType, source, "LifecycleState", EnumValue(
			SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState"), "Active"));
		SetProperty(saveDataType, beneficiary, "LifecycleState", EnumValue(
			SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState"), "Active"));
		object[] incompleteFrozenDaily =
		{
			linkedInstances,
			new List<string> { sourceDailyKey },
			new HashSet<string>(new[] { sourceDailyKey }, StringComparer.OrdinalIgnoreCase),
			null
		};
		Check(!(bool)InvokeStatic(behaviorType, "TryPreflightFrozenLinkedDailyEntries", incompleteFrozenDaily, 4)
			&& Items(linkedInstances).All(instance =>
				string.Equals(Property(saveDataType, instance, "LifecycleState").ToString(), "Suspended", StringComparison.Ordinal)),
			"A daily Linked bundle frozen without every contracted leg must fail closed before any leg executes.");

		JObject renewedInstanceToken = JObject.Parse(BuildEffectPlanSaveInstanceJson(
			"renewed-dynamic", "renewed_dynamic", "source", false, false, string.Empty, payload));
		renewedInstanceToken["policyId"] = "renew-record";
		renewedInstanceToken["mechanismKind"] = "independent";
		renewedInstanceToken["mechanismRole"] = "subject";
		renewedInstanceToken["lifecycleState"] = 2;
		JObject renewedTargetSet = (JObject)renewedInstanceToken["targetSet"];
		renewedTargetSet["selectorHandles"] = new JArray("P0");
		renewedTargetSet["targetPlans"] = new JArray(JObject.Parse(
			"{\"planVersion\":2,\"resolverVersion\":1,\"branches\":[{"
			+ "\"universe\":\"PrimaryFiefs\",\"scopeAnchor\":\"TargetKingdom\","
			+ "\"entityType\":\"Town\",\"relation\":\"Domestic\",\"cardinality\":\"All\"}]}"));
		object renewedInstance = TokenToObject(renewedInstanceToken, saveDataType);
		object renewedActive = Activator.CreateInstance(activeEffectType, nonPublic: true);
		SetProperty(activeEffectType, renewedActive, "Version", 8);
		SetProperty(activeEffectType, renewedActive, "EffectId", "renewed-active");
		SetProperty(activeEffectType, renewedActive, "RecordId", "renew-record");
		SetProperty(activeEffectType, renewedActive, "ScopeKind", "local");
		SetProperty(activeEffectType, renewedActive, "TotalDurationDays", 20);
		SetProperty(activeEffectType, renewedActive, "RemainingDays", 10);
		((IList)Property(activeEffectType, renewedActive, "ModuleEffects")).Add(renewedInstance);
		Array renewedActives = Array.CreateInstance(activeEffectType, 1);
		renewedActives.SetValue(renewedActive, 0);
		object behavior = Activator.CreateInstance(behaviorType);
		object[] prepareRenewal = { renewedActives, null };
		Check((bool)InvokeInstance(behaviorType, behavior, "TryPrepareRenewedPolicyEffectsForCommit", prepareRenewal, 2)
			&& string.Equals(Property(saveDataType, renewedInstance, "LifecycleState").ToString(), "Suspended", StringComparison.Ordinal),
			"A v8 renewal with a temporarily empty dynamic TargetPlan must remain suspended and commit-ready: " + prepareRenewal[1]);
		SetProperty(activeEffectType, renewedActive, "Version", 7);
		object[] rejectLegacyRenewalShell = { renewedActives, null };
		Check(!(bool)InvokeInstance(behaviorType, behavior, "TryPrepareRenewedPolicyEffectsForCommit", rejectLegacyRenewalShell, 2),
			"Renewal commit validation must use the current v8 active-effect schema.");

		SetProperty(activeEffectType, renewedActive, "Version", 8);
		object selectorOnlyTargetSet = Property(saveDataType, renewedInstance, "TargetSet");
		((IList)Property(selectorOnlyTargetSet.GetType(), selectorOnlyTargetSet, "TargetPlans")).Clear();
		IList<string> selectorOnlyHandles = (IList<string>)Property(selectorOnlyTargetSet.GetType(), selectorOnlyTargetSet, "SelectorHandles");
		selectorOnlyHandles.Clear();
		selectorOnlyHandles.Add("L0:legacy-target");
		SetProperty(saveDataType, renewedInstance, "LifecycleState", EnumValue(
			SutType("AnimusForge.PolicyEffects.PolicyEffectLifecycleState"), "Active"));
		object[] prepareSelectorOnlyRenewal = { renewedActives, null };
		Check((bool)InvokeInstance(behaviorType, behavior, "TryPrepareRenewedPolicyEffectsForCommit", prepareSelectorOnlyRenewal, 2)
			&& string.Equals(Property(saveDataType, renewedInstance, "LifecycleState").ToString(), "Suspended", StringComparison.Ordinal),
			"A selector-only legacy renewal with no current materialized target must remain persistable and suspended: "
			+ prepareSelectorOnlyRenewal[1]);
	}

	private static void FreezeLinkedMechanismContract(Array instances)
	{
		Type contractType = SutType("AnimusForge.PolicyEffects.PolicyEffectMechanismContract");
		object[] arguments = { instances, null };
		Check((bool)InvokeStatic(contractType, "TryFreeze", arguments, 2),
			"Linked mechanism contract test fixture must freeze successfully: " + arguments[1]);
	}

	private static string BuildEffectPlanSaveInstanceJson(
		string instanceId,
		string mechanismId,
		string role,
		bool sourceOmitted,
		bool destinationOmitted,
		string townId,
		string payload)
	{
		JObject targetSet = new JObject
		{
			["structureVersion"] = 1,
			["selectorHandles"] = new JArray("S:" + (townId.Length == 0 ? "dynamic" : townId)),
			["townIds"] = townId.Length == 0 ? new JArray() : new JArray(townId)
		};
		return new JObject
		{
			["instanceId"] = instanceId,
			["policyId"] = "p-linked",
			["moduleId"] = "prosperityPerDay",
			["effectPlanVersion"] = 1,
			["mechanismId"] = mechanismId,
			["mechanismKind"] = "linked",
			["mechanismRole"] = role,
			["sourceOmitted"] = sourceOmitted,
			["destinationOmitted"] = destinationOmitted,
			["payloadSchemaVersion"] = 1,
			["payload"] = JObject.Parse(payload),
			["targetSet"] = targetSet,
			["lifecycleState"] = 1,
			["stateSchemaVersion"] = 1,
			["startDay"] = 10,
			["endDay"] = 20,
			["sourceScope"] = "local"
		}.ToString(Formatting.None);
	}

	private static void TestOneShotIdempotencyAndRollback()
	{
		Type saveDataType = SutType("AnimusForge.PolicyEffects.PolicyEffectInstanceSaveData");
		string json = "{\"instanceId\":\"stability-once-1\",\"policyId\":\"p1\",\"moduleId\":\"kingdomStabilityOnce\","
			+ "\"payloadSchemaVersion\":1,\"payload\":{\"moduleId\":\"kingdomStabilityOnce\",\"schemaVersion\":1,\"value\":3},"
			+ "\"targetSet\":{\"structureVersion\":1,\"selectorHandles\":[\"K:k1\",\"K:k2\"],"
			+ "\"kingdomIds\":[\"k1\",\"k2\"]},\"lifecycleState\":0,\"stateSchemaVersion\":1,"
			+ "\"startDay\":10,\"endDay\":20,\"sourceScope\":\"kingdom\",\"reason\":\"contract\"}";
		object saveData = TokenToObject(ParseToken(json), saveDataType);
		Array sourceInstances = Array.CreateInstance(saveDataType, 1);
		sourceInstances.SetValue(saveData, 0);
		Type bridgeType = SutType("AnimusForge.PolicyEffects.IPolicyEffectGameBridge");
		Type coordinator = SutType("AnimusForge.PolicyEffectActivationCoordinator");
		GameBridgeProxy failingBridgeProxy = new GameBridgeProxy(bridgeType) { FailKingdomIdOnce = "k2" };
		object[] failedActivation = { sourceInstances, null, failingBridgeProxy.GetTransparentProxy(), 41f, null, null };
		Check(!(bool)InvokeStatic(coordinator, "TryActivate", failedActivation, 6),
			"A mid-OneShot target failure must reject the whole activation.");
		Check(failedActivation[4] == null, "Failed OneShot activation must not expose a committable transaction.");
		Check(failingBridgeProxy.CallCount == 3 && failingBridgeProxy.TotalDelta == 0,
			"A mid-OneShot target failure must roll back the already-applied target completely.");

		GameBridgeProxy bridgeProxy = new GameBridgeProxy(bridgeType);
		object bridge = bridgeProxy.GetTransparentProxy();

		object[] firstActivation = { sourceInstances, null, bridge, 42f, null, null };
		Check((bool)InvokeStatic(coordinator, "TryActivate", firstActivation, 6),
			"OneShot activation must succeed: " + firstActivation[5]);
		object firstTransaction = firstActivation[4];
		Check(firstTransaction != null, "OneShot activation must return a transaction.");
		Check(bridgeProxy.CallCount == 2 && bridgeProxy.TotalDelta == 6,
			"OneShot activation must apply each canonical target exactly once.");
		object receipts = Property(firstTransaction.GetType(), firstTransaction, "Receipts");
		Check(Items(receipts).Count() == 1, "OneShot activation must persist one aggregate receipt.");

		object[] retryActivation = { sourceInstances, receipts, bridge, 42f, null, null };
		Check((bool)InvokeStatic(coordinator, "TryActivate", retryActivation, 6),
			"Idempotent OneShot retry must succeed: " + retryActivation[5]);
		Check(bridgeProxy.CallCount == 2 && bridgeProxy.TotalDelta == 6,
			"Idempotent OneShot retry must not invoke the game bridge again.");
		Check(Items(Property(retryActivation[4].GetType(), retryActivation[4], "AppliedOneShots")).Count() == 0,
			"Idempotent retry must not register a newly applied OneShot.");

		object prepared = Items(Property(firstTransaction.GetType(), firstTransaction, "AppliedOneShots")).Single();
		object appliedReceipt = Items(receipts).Single();
		Type executionContextType = SutType("AnimusForge.PolicyEffects.PolicyEffectExecutionContext");
		object executionContext = Activator.CreateInstance(executionContextType, nonPublic: true);
		SetProperty(executionContextType, executionContext, "PreparedInstance", prepared);
		SetProperty(executionContextType, executionContext, "CampaignDay", 43f);
		SetProperty(executionContextType, executionContext, "GameBridge", bridge);
		SetProperty(executionContextType, executionContext, "ExistingReceipt", appliedReceipt);
		SetProperty(executionContextType, executionContext, "IdempotencyKey", (string)Property(prepared.GetType(), prepared, "IdempotencyKey"));
		Check(PolicyEffectModuleCatalog.TryGet("kingdomStabilityOnce", out IPolicyEffectModule module),
			"Hidden legacy kingdomStabilityOnce must remain available to rollback old saves.");
		object rollbackResult = InvokeInstance(module.GetType(), module, "RollbackOnce", new[] { executionContext }, 1);
		Check((bool)Property(rollbackResult.GetType(), rollbackResult, "Success"), "OneShot rollback must succeed.");
		Check(string.Equals(Property(rollbackResult.GetType(), rollbackResult, "Status").ToString(), "RolledBack", StringComparison.Ordinal),
			"OneShot rollback must return RolledBack.");
		Check(bridgeProxy.CallCount == 4 && bridgeProxy.TotalDelta == 0,
			"OneShot rollback must reverse only the actual applied values.");

		object rolledBackReceipt = Property(rollbackResult.GetType(), rollbackResult, "Receipt");
		SetProperty(executionContextType, executionContext, "ExistingReceipt", rolledBackReceipt);
		object retryRollback = InvokeInstance(module.GetType(), module, "RollbackOnce", new[] { executionContext }, 1);
		Check((bool)Property(retryRollback.GetType(), retryRollback, "Success"), "Repeated rollback must be idempotent.");
		Check(string.Equals(Property(retryRollback.GetType(), retryRollback, "Status").ToString(), "AlreadyApplied", StringComparison.Ordinal),
			"Repeated rollback must report AlreadyApplied.");
		Check(bridgeProxy.CallCount == 4 && bridgeProxy.TotalDelta == 0,
			"Repeated rollback must not mutate the game again.");

		Array rollbackReceipts = Array.CreateInstance(rolledBackReceipt.GetType(), 1);
		rollbackReceipts.SetValue(rolledBackReceipt, 0);
		object[] savedRollback = { Property(firstTransaction.GetType(), firstTransaction, "Instances"), rollbackReceipts, bridge, 44f, null };
		Check((bool)InvokeStatic(coordinator, "TryRollbackSavedOneShots", savedRollback, 5),
			"Saved rolled-back receipt must be accepted: " + savedRollback[4]);
		Check(bridgeProxy.CallCount == 4 && bridgeProxy.TotalDelta == 0,
			"Saved rolled-back receipt must suppress duplicate rollback.");

		const string legacyTargetSet = "{\"structureVersion\":1,\"selectorHandles\":[\"K:k1\"],\"kingdomIds\":[\"k1\"]}";
		string legacyJson = "{\"instanceId\":\"legacy-stability-completed\",\"policyId\":\"legacy-policy\","
			+ "\"moduleId\":\"kingdomStabilityOnce\",\"payloadSchemaVersion\":1,"
			+ "\"payload\":{\"moduleId\":\"kingdomStabilityOnce\",\"schemaVersion\":1,\"value\":9},"
			+ "\"targetSet\":" + legacyTargetSet + ",\"lifecycleState\":3,\"stateSchemaVersion\":1,"
			+ "\"executionReceipt\":{\"receiptId\":\"legacyAssumedCompleted:legacy-stability-completed\","
			+ "\"instanceId\":\"legacy-stability-completed\",\"policyId\":\"legacy-policy\","
			+ "\"moduleId\":\"kingdomStabilityOnce\",\"targetSet\":" + legacyTargetSet + ","
			+ "\"status\":0,\"requestedValue\":9,\"appliedValue\":9,\"campaignDay\":1,"
			+ "\"message\":\"legacyAssumedCompleted\"},\"sourceScope\":\"kingdom\"}";
		object legacySave = TokenToObject(JObject.Parse(legacyJson), saveDataType);
		object legacyReceipt = Property(saveDataType, legacySave, "ExecutionReceipt");
		Array legacyInstances = Array.CreateInstance(saveDataType, 1);
		legacyInstances.SetValue(legacySave, 0);
		Array legacyReceipts = Array.CreateInstance(legacyReceipt.GetType(), 1);
		legacyReceipts.SetValue(legacyReceipt, 0);
		object[] legacyReload = { legacyInstances, legacyReceipts, bridge, 45f, null, null };
		Check((bool)InvokeStatic(coordinator, "TryActivate", legacyReload, 6),
			"Reloading legacy assumed-completed stability must succeed inertly: " + legacyReload[5]);
		Check(bridgeProxy.CallCount == 4 && bridgeProxy.TotalDelta == 0,
			"Reloading legacy assumed-completed stability must never replay it.");
		object[] legacyRollback = { legacyInstances, legacyReceipts, bridge, 46f, null };
		Check((bool)InvokeStatic(coordinator, "TryRollbackSavedOneShots", legacyRollback, 5),
			"Legacy assumed-completed stability must be skipped during rollback: " + legacyRollback[4]);
		Check(bridgeProxy.CallCount == 4 && bridgeProxy.TotalDelta == 0,
			"Legacy assumed-completed stability must never be rolled back against a historical save.");
	}

	private static void TestScheduledOnceNextDayAndReloadIdempotency()
	{
		PolicyEffectInstanceSaveData scheduled = new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "scheduled-stability",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "scheduled-stability-next-day",
			PolicyId = "scheduled-policy",
			ActorHeroId = "frozen-ruler",
			ModuleId = "kingdomStabilityNextDayOnce",
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = "kingdomStabilityNextDayOnce",
				["schemaVersion"] = 1,
				["value"] = 4f
			},
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "K:k1" },
				KingdomIds = new List<string> { "k1" }
			},
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			StartDay = 10f,
			EndDay = 20f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "next-day timing contract"
		};
		List<PolicyEffectExecutionReceipt> receipts = new List<PolicyEffectExecutionReceipt>();
		GameBridgeProxy bridgeProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge));
		IPolicyEffectGameBridge bridge = (IPolicyEffectGameBridge)bridgeProxy.GetTransparentProxy();

		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { scheduled }, receipts, bridge, 10,
			out List<string> adoptionDayCompleted, out bool adoptionDayChanged, out string adoptionDayError),
			"ScheduledOnce adoption-day scan must succeed inertly: " + adoptionDayError);
		Check(adoptionDayCompleted.Count == 0
			&& !adoptionDayChanged
			&& bridgeProxy.CallCount == 0
			&& scheduled.LifecycleState == PolicyEffectLifecycleState.Active
			&& scheduled.ExecutionReceipt == null,
			"ScheduledOnce must not execute or complete on the policy adoption day.");

		scheduled.TargetSet.KingdomIds.Clear();
		scheduled.LifecycleState = PolicyEffectLifecycleState.Suspended;
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { scheduled }, receipts, bridge, 11,
			out List<string> suspendedCompleted, out bool suspendedChanged, out string suspendedError),
			"A suspended ScheduledOnce next-day scan must succeed inertly: " + suspendedError);
		Check(suspendedCompleted.Count == 0
			&& !suspendedChanged
			&& bridgeProxy.CallCount == 0
			&& scheduled.LifecycleState == PolicyEffectLifecycleState.Suspended
			&& scheduled.ExecutionReceipt == null
			&& !AnimusForge.PolicyEffectActivationCoordinator.HasFrozenScheduledTargets(scheduled),
			"A suspended ScheduledOnce must neither execute nor freeze targets on its due day.");
		scheduled.TargetSet.KingdomIds.Add("k1");

		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { scheduled }, receipts, bridge, 11,
			out List<string> nextDayCompleted, out bool nextDayChanged, out string nextDayError),
			"ScheduledOnce must execute on the next game day: " + nextDayError);
		Check(nextDayChanged
			&& nextDayCompleted.SequenceEqual(new[] { scheduled.InstanceId }, StringComparer.Ordinal)
			&& bridgeProxy.CallCount == 1
			&& bridgeProxy.TotalDelta == 4
			&& scheduled.LifecycleState == PolicyEffectLifecycleState.Completed
			&& scheduled.ExecutionReceipt != null
			&& receipts.Count == 1
			&& AnimusForge.PolicyEffectActivationCoordinator.HasFrozenScheduledTargets(scheduled),
			"A recovered next-day target must reactivate, freeze targets, persist one receipt, and complete exactly once.");

		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { scheduled }, receipts, bridge, 11,
			out List<string> sameDayCompleted, out bool sameDayChanged, out string sameDayError),
			"A committed ScheduledOnce same-day retry must be inert: " + sameDayError);
		Check(sameDayCompleted.Count == 0 && !sameDayChanged && bridgeProxy.CallCount == 1,
			"A committed ScheduledOnce must not replay within the same day.");

		PolicyEffectSaveEnvelope envelope = new PolicyEffectSaveEnvelope
		{
			Instances = new List<PolicyEffectInstanceSaveData> { scheduled },
			Receipts = receipts.ToList()
		};
		Check(PolicyEffectSaveCodec.TrySerialize(envelope, out string json, out string encodeError),
			"Completed ScheduledOnce state must serialize: " + encodeError);
		Check(PolicyEffectSaveCodec.TryDeserialize(json, out PolicyEffectSaveDecodeResult decoded, out string decodeError),
			"Completed ScheduledOnce state must deserialize: " + decodeError);
		PolicyEffectInstanceSaveData reloaded = decoded.Envelope.Instances.Single();
		Check(string.Equals(reloaded.ActorHeroId, "frozen-ruler", StringComparison.Ordinal)
			&& reloaded.LifecycleState == PolicyEffectLifecycleState.Completed
			&& reloaded.ExecutionReceipt != null
			&& AnimusForge.PolicyEffectActivationCoordinator.HasFrozenScheduledTargets(reloaded),
			"Reload must retain frozen actor, target snapshot, receipt, and completed state.");
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { reloaded }, decoded.Envelope.Receipts, bridge, 12,
			out List<string> reloadCompleted, out bool reloadChanged, out string reloadError),
			"Reloaded completed ScheduledOnce must be accepted inertly: " + reloadError);
		Check(reloadCompleted.Count == 0 && !reloadChanged && bridgeProxy.CallCount == 1,
			"Saving and reloading must never replay a completed ScheduledOnce effect.");
	}

	private static void TestClanLeaderRelationScheduledModuleAndCasContracts()
	{
		const string actorHeroId = "relation-actor";
		const string targetHeroId = "relation-target-hero";
		PolicyEffectInstanceSaveData scheduled = BuildRelationScheduledInstance(
			"scheduled-relation-contract",
			actorHeroId,
			new[]
			{
				"relation-target-clan",
				"relation-same-actor-clan",
				"relation-self-clan",
				"relation-no-leader-clan"
			},
			"relation module contract");
		List<PolicyEffectExecutionReceipt> receipts = new List<PolicyEffectExecutionReceipt>();
		GameBridgeProxy bridgeProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge))
		{
			RelationAppliedDeltaOverride = 7
		};
		bridgeProxy.SetRelationClanLeader("relation-target-clan", targetHeroId);
		bridgeProxy.SetRelationClanLeader("relation-same-actor-clan", "relation-same-clan-leader");
		bridgeProxy.SetRelationClanLeader("relation-self-clan", actorHeroId);
		bridgeProxy.SetRelationHeroClan(actorHeroId, "relation-same-actor-clan");
		bridgeProxy.SetHeroRelation(actorHeroId, targetHeroId, 20);
		IPolicyEffectGameBridge bridge = (IPolicyEffectGameBridge)bridgeProxy.GetTransparentProxy();

		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { scheduled }, receipts, bridge, 11,
			out List<string> completed, out bool executionChanged, out string executionError),
			"clanLeaderRelationOnce must execute through the production ScheduledOnce path: " + executionError);
		PolicyEffectExecutionReceipt appliedReceipt = scheduled.ExecutionReceipt;
		JArray appliedTargets = appliedReceipt?.AppliedPayload?["targets"] as JArray;
		Check(executionChanged
			&& completed.SequenceEqual(new[] { scheduled.InstanceId }, StringComparer.Ordinal)
			&& scheduled.LifecycleState == PolicyEffectLifecycleState.Completed
			&& receipts.Count == 1
			&& appliedReceipt?.Status == PolicyEffectExecutionStatus.Applied
			&& bridgeProxy.RelationCallCount == 4
			&& bridgeProxy.ReadHeroRelation(actorHeroId, targetHeroId) == 27,
			"clanLeaderRelationOnce must apply one external leader and skip same-clan/self/no-leader targets without failing the transaction.");
		Check(appliedReceipt.RequestedValue == 5f
			&& appliedReceipt.AppliedValue == 7f
			&& string.Equals((string)appliedReceipt.RequestedPayload?["actorHeroId"], actorHeroId, StringComparison.Ordinal)
			&& (int?)appliedReceipt.AppliedPayload?["skippedTargets"] == 3
			&& appliedTargets?.Count == 1,
			"Relation receipt must retain the frozen non-leader actor, requested value, vanilla-adjusted actual value, and skipped count.");
		JObject appliedTarget = appliedTargets?[0] as JObject;
		Check(string.Equals((string)appliedTarget?["clanId"], "relation-target-clan", StringComparison.Ordinal)
			&& string.Equals((string)appliedTarget?["heroId"], targetHeroId, StringComparison.Ordinal)
			&& (int?)appliedTarget?["requestedDelta"] == 5
			&& (int?)appliedTarget?["before"] == 20
			&& (int?)appliedTarget?["after"] == 27
			&& (int?)appliedTarget?["actualDelta"] == 7
			&& string.Equals(bridgeProxy.LastChangedRelationActorHeroId, actorHeroId, StringComparison.Ordinal)
			&& string.Equals(bridgeProxy.LastChangedRelationTargetClanId, "relation-target-clan", StringComparison.Ordinal)
			&& string.Equals(bridgeProxy.LastChangedRelationTargetHeroId, targetHeroId, StringComparison.Ordinal)
			&& bridgeProxy.LastChangedRelationRequestedDelta == 5
			&& string.Equals(bridgeProxy.LastChangedRelationReason, scheduled.Reason, StringComparison.Ordinal),
			"Relation receipt and bridge call must retain actor/target/requested/before/after/actual values exactly.");

		bridgeProxy.FailHeroRelationRestoreCallsRemaining = 1;
		Check(!AnimusForge.PolicyEffectActivationCoordinator.TryCompensateScheduledOnceAfterPersistenceFailure(
			new[] { scheduled }, receipts, completed, bridge, 11,
			out bool failedCompensationChanged, out string failedCompensationError)
			&& failedCompensationChanged
			&& !string.IsNullOrWhiteSpace(failedCompensationError),
			"A relation compensation bridge failure must fail closed and surface an error.");
		Check(AnimusForge.PolicyEffectActivationCoordinator.HasPendingScheduledCompensation(new[] { scheduled })
			&& scheduled.LifecycleState == PolicyEffectLifecycleState.Completed
			&& scheduled.ExecutionReceipt?.Status == PolicyEffectExecutionStatus.Applied
			&& receipts.Count == 1
			&& bridgeProxy.RelationRestoreCallCount == 1
			&& bridgeProxy.RelationRestoreMutationCount == 0
			&& bridgeProxy.ReadHeroRelation(actorHeroId, targetHeroId) == 27,
			"Failed relation compensation must preserve the applied receipt, exact value, and durable recoverable marker.");

		bridgeProxy.SetHeroRelation(actorHeroId, targetHeroId, 31);
		Check(!AnimusForge.PolicyEffectActivationCoordinator.TryResumeScheduledCompensation(
			new[] { scheduled }, receipts, bridge, 12,
			out bool casMismatchChanged, out string casMismatchError)
			&& casMismatchChanged
			&& !string.IsNullOrWhiteSpace(casMismatchError),
			"Relation compensation must reject a third-party CAS change.");
		Check(AnimusForge.PolicyEffectActivationCoordinator.HasPendingScheduledCompensation(new[] { scheduled })
			&& bridgeProxy.RelationRestoreCallCount == 2
			&& bridgeProxy.RelationRestoreMutationCount == 0
			&& bridgeProxy.ReadHeroRelation(actorHeroId, targetHeroId) == 31,
			"A relation CAS mismatch must not overwrite the third-party value and must remain recoverable.");

		bridgeProxy.SetHeroRelation(actorHeroId, targetHeroId, 27);
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryResumeScheduledCompensation(
			new[] { scheduled }, receipts, bridge, 12,
			out bool resumedChanged, out string resumedError),
			"Pending relation compensation must resume when expectedAfter matches exactly: " + resumedError);
		Check(resumedChanged
			&& !AnimusForge.PolicyEffectActivationCoordinator.HasPendingScheduledCompensation(new[] { scheduled })
			&& scheduled.LifecycleState == PolicyEffectLifecycleState.Active
			&& scheduled.ExecutionReceipt == null
			&& receipts.Count == 0
			&& bridgeProxy.RelationRestoreCallCount == 3
			&& bridgeProxy.RelationRestoreMutationCount == 1
			&& bridgeProxy.ReadHeroRelation(actorHeroId, targetHeroId) == 20
			&& bridgeProxy.LastRelationRestoreExpectedAfter == 27
			&& bridgeProxy.LastRelationRestoreBefore == 20,
			"Exact expectedAfter compensation must restore before, clear the pending marker, and not replay the policy effect.");

		int mutationsBeforeIdempotentRestore = bridgeProxy.RelationRestoreMutationCount;
		Check(bridge.TryRestoreHeroRelation(
			actorHeroId, targetHeroId, expectedAfterValue: 27, beforeValue: 20, reason: "already restored contract",
			out int alreadyRestoredAfter, out string alreadyRestoredError)
			&& alreadyRestoredAfter == 20
			&& string.IsNullOrWhiteSpace(alreadyRestoredError)
			&& bridgeProxy.RelationRestoreMutationCount == mutationsBeforeIdempotentRestore
			&& bridgeProxy.ReadHeroRelation(actorHeroId, targetHeroId) == 20,
			"TryRestoreHeroRelation must treat current==before as an idempotent success without mutation.");

		bridgeProxy.SetHeroRelation(actorHeroId, targetHeroId, 27);
		int mutationsBeforeExactRestore = bridgeProxy.RelationRestoreMutationCount;
		Check(bridge.TryRestoreHeroRelation(
			actorHeroId, targetHeroId, expectedAfterValue: 27, beforeValue: 20, reason: "exact restore contract",
			out int exactRestoredAfter, out string exactRestoredError)
			&& exactRestoredAfter == 20
			&& string.IsNullOrWhiteSpace(exactRestoredError)
			&& bridgeProxy.RelationRestoreMutationCount == mutationsBeforeExactRestore + 1
			&& bridgeProxy.ReadHeroRelation(actorHeroId, targetHeroId) == 20,
			"TryRestoreHeroRelation must restore before only when current equals expectedAfter exactly.");

		PolicyEffectInstanceSaveData deadActorScheduled = BuildRelationScheduledInstance(
			"scheduled-relation-dead-actor",
			"dead-relation-actor",
			new[] { "relation-target-clan" },
			"dead actor skip contract");
		GameBridgeProxy deadActorProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge));
		deadActorProxy.SetRelationClanLeader("relation-target-clan", targetHeroId);
		deadActorProxy.SetHeroRelation("dead-relation-actor", targetHeroId, 44);
		deadActorProxy.SkipRelationActor("dead-relation-actor");
		IPolicyEffectGameBridge deadActorBridge = (IPolicyEffectGameBridge)deadActorProxy.GetTransparentProxy();
		List<PolicyEffectExecutionReceipt> deadActorReceipts = new List<PolicyEffectExecutionReceipt>();
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { deadActorScheduled }, deadActorReceipts, deadActorBridge, 11,
			out List<string> deadActorCompleted, out bool deadActorChanged, out string deadActorError),
			"A dead/disabled frozen actor must skip relation targets without blocking linked execution: " + deadActorError);
		Check(deadActorChanged
			&& deadActorCompleted.SequenceEqual(new[] { deadActorScheduled.InstanceId }, StringComparer.Ordinal)
			&& deadActorScheduled.LifecycleState == PolicyEffectLifecycleState.Completed
			&& deadActorProxy.RelationCallCount == 1
			&& deadActorProxy.ReadHeroRelation("dead-relation-actor", targetHeroId) == 44
			&& (deadActorScheduled.ExecutionReceipt?.AppliedPayload?["targets"] as JArray)?.Count == 0
			&& (int?)deadActorScheduled.ExecutionReceipt?.AppliedPayload?["skippedTargets"] == 1,
			"Dead/disabled actor skip must produce a committed zero-target receipt without changing relation.");
	}

	private static PolicyEffectInstanceSaveData BuildRelationScheduledInstance(
		string instanceId,
		string actorHeroId,
		IEnumerable<string> clanIds,
		string reason)
	{
		List<string> targets = (clanIds ?? Array.Empty<string>())
			.Where(clanId => !string.IsNullOrWhiteSpace(clanId))
			.Select(clanId => clanId.Trim())
			.Distinct(StringComparer.OrdinalIgnoreCase)
			.ToList();
		return new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "relation-contract",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = instanceId,
			PolicyId = "relation-contract-policy",
			ActorHeroId = actorHeroId,
			ModuleId = "clanLeaderRelationOnce",
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = "clanLeaderRelationOnce",
				["schemaVersion"] = 1,
				["value"] = 5f
			},
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = targets.Select(clanId => "C:" + clanId).ToList(),
				ClanIds = targets
			},
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			StartDay = 10f,
			EndDay = 20f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = reason
		};
	}

	private static void TestMalformedScheduledCompensationReceiptsFailClosed()
	{
		PolicyEffectInstanceSaveData influence = new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "malformed-influence",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "malformed-influence-receipt-instance",
			PolicyId = "malformed-receipt-policy",
			ActorHeroId = "frozen-ruler",
			ModuleId = "clanInfluenceNextDayOnce",
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = "clanInfluenceNextDayOnce",
				["schemaVersion"] = 1,
				["value"] = 5f
			},
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "C:malformed-influence-clan" },
				ClanIds = new List<string> { "malformed-influence-clan" }
			},
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			StartDay = 10f,
			EndDay = 20f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "malformed influence receipt contract"
		};
		GameBridgeProxy influenceProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge))
		{
			ClanInfluenceValue = 20f
		};
		IPolicyEffectGameBridge influenceBridge =
			(IPolicyEffectGameBridge)influenceProxy.GetTransparentProxy();
		List<PolicyEffectExecutionReceipt> influenceReceipts = new List<PolicyEffectExecutionReceipt>();
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { influence }, influenceReceipts, influenceBridge, 11,
			out List<string> influenceCompleted, out bool influenceChanged, out string influenceError)
			&& influenceChanged
			&& influenceCompleted.SequenceEqual(new[] { influence.InstanceId }, StringComparer.Ordinal)
			&& Math.Abs(influenceProxy.ClanInfluenceValue - 25f) < 0.0001f,
			"Malformed influence receipt fixture must first apply through the production ScheduledOnce path: " + influenceError);
		influence.ExecutionReceipt.AppliedPayload = new JObject { ["receiptCorrupted"] = true };
		bool influenceFailedClosed = !AnimusForge.PolicyEffectActivationCoordinator.TryCompensateScheduledOnceAfterPersistenceFailure(
			new[] { influence }, influenceReceipts, influenceCompleted, influenceBridge, 11,
			out bool influenceCompensationChanged, out string influenceCompensationError)
			&& influenceCompensationChanged
			&& !string.IsNullOrWhiteSpace(influenceCompensationError)
			&& AnimusForge.PolicyEffectActivationCoordinator.HasPendingScheduledCompensation(new[] { influence })
			&& influence.LifecycleState == PolicyEffectLifecycleState.Completed
			&& influence.ExecutionReceipt?.Status == PolicyEffectExecutionStatus.Applied
			&& influenceReceipts.Count == 1
			&& influenceProxy.InfluenceRestoreCallCount == 0
			&& Math.Abs(influenceProxy.ClanInfluenceValue - 25f) < 0.0001f;

		const string actorHeroId = "malformed-relation-actor";
		const string targetHeroId = "malformed-relation-target";
		PolicyEffectInstanceSaveData relation = BuildRelationScheduledInstance(
			"malformed-relation-receipt-instance",
			actorHeroId,
			new[] { "malformed-relation-clan" },
			"malformed relation receipt contract");
		GameBridgeProxy relationProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge));
		relationProxy.SetRelationClanLeader("malformed-relation-clan", targetHeroId);
		relationProxy.SetHeroRelation(actorHeroId, targetHeroId, 10);
		IPolicyEffectGameBridge relationBridge =
			(IPolicyEffectGameBridge)relationProxy.GetTransparentProxy();
		List<PolicyEffectExecutionReceipt> relationReceipts = new List<PolicyEffectExecutionReceipt>();
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { relation }, relationReceipts, relationBridge, 11,
			out List<string> relationCompleted, out bool relationChanged, out string relationError)
			&& relationChanged
			&& relationCompleted.SequenceEqual(new[] { relation.InstanceId }, StringComparer.Ordinal)
			&& relationProxy.ReadHeroRelation(actorHeroId, targetHeroId) == 15,
			"Malformed relation receipt fixture must first apply through the production ScheduledOnce path: " + relationError);
		relation.ExecutionReceipt.AppliedPayload = new JObject { ["receiptCorrupted"] = true };
		bool relationFailedClosed = !AnimusForge.PolicyEffectActivationCoordinator.TryCompensateScheduledOnceAfterPersistenceFailure(
			new[] { relation }, relationReceipts, relationCompleted, relationBridge, 11,
			out bool relationCompensationChanged, out string relationCompensationError)
			&& relationCompensationChanged
			&& !string.IsNullOrWhiteSpace(relationCompensationError)
			&& AnimusForge.PolicyEffectActivationCoordinator.HasPendingScheduledCompensation(new[] { relation })
			&& relation.LifecycleState == PolicyEffectLifecycleState.Completed
			&& relation.ExecutionReceipt?.Status == PolicyEffectExecutionStatus.Applied
			&& relationReceipts.Count == 1
			&& relationProxy.RelationRestoreCallCount == 0
			&& relationProxy.ReadHeroRelation(actorHeroId, targetHeroId) == 15;
		Check(relationFailedClosed,
			"A missing relation targets array must fail closed instead of reporting a zero-target rollback: "
				+ relationCompensationError);
		Check(influenceFailedClosed,
			"A missing influence targets array must fail closed instead of reporting a zero-target rollback: "
				+ influenceCompensationError);
	}

	private static void TestDailyRetryWindowPreservesActiveInstance()
	{
		PolicyEffectInstanceSaveData daily = new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "daily-influence",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "daily-influence-retry-window",
			PolicyId = "daily-retry-policy",
			ActorHeroId = "frozen-ruler",
			ModuleId = "clanInfluencePerDay",
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = "clanInfluencePerDay",
				["schemaVersion"] = 1,
				["value"] = -1.5f
			},
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "C:c1" },
				ClanIds = new List<string> { "c1" }
			},
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			StartDay = 10f,
			EndDay = 20f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "daily retry window contract"
		};
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryPrepareSavedInstance(
			daily,
			out IPolicyEffectModule module,
			out PolicyEffectPreparedInstance prepared,
			out string prepareError),
			"Daily retry fixture must prepare through the production save path: " + prepareError);
		GameBridgeProxy bridgeProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge))
		{
			FailClanInfluenceCallsRemaining = 3,
			ClanInfluenceValue = 20f
		};
		IPolicyEffectGameBridge bridge = (IPolicyEffectGameBridge)bridgeProxy.GetTransparentProxy();

		AnimusForge.PolicyEffectDailyExecutionOutcome exhausted = AnimusForge.PolicyEffectActivationCoordinator.ExecuteDailyTarget(
			daily,
			module,
			prepared,
			PolicyEffectTargetKind.Clan,
			"c1",
			bridge,
			campaignDay: 11,
			attemptWindowDay: 11);
		Check(exhausted.Failed
			&& exhausted.Retryable
			&& exhausted.Attempts == 3
			&& exhausted.AttemptWindowDay == 11
			&& daily.LifecycleState == PolicyEffectLifecycleState.Active
			&& bridgeProxy.InfluenceCallCount == 3
			&& Math.Abs(bridgeProxy.ClanInfluenceValue - 20f) < 0.0001f,
			"Exhausting a retryable daily window must not permanently fail the active instance.");

		AnimusForge.PolicyEffectDailyExecutionOutcome sameWindow = AnimusForge.PolicyEffectActivationCoordinator.ExecuteDailyTarget(
			daily,
			module,
			prepared,
			PolicyEffectTargetKind.Clan,
			"c1",
			bridge,
			campaignDay: 11,
			attemptWindowDay: 11);
		Check(sameWindow.Failed
			&& sameWindow.Retryable
			&& sameWindow.Attempts == 3
			&& daily.LifecycleState == PolicyEffectLifecycleState.Active
			&& bridgeProxy.InfluenceCallCount == 3,
			"The same retry window must not exceed its three-attempt budget.");

		AnimusForge.PolicyEffectDailyExecutionOutcome nextWindow = AnimusForge.PolicyEffectActivationCoordinator.ExecuteDailyTarget(
			daily,
			module,
			prepared,
			PolicyEffectTargetKind.Clan,
			"c1",
			bridge,
			campaignDay: 11,
			attemptWindowDay: 12);
		Check(nextWindow.Succeeded
			&& !nextWindow.Failed
			&& nextWindow.Attempts == 1
			&& nextWindow.AttemptWindowDay == 12
			&& daily.LifecycleState == PolicyEffectLifecycleState.Active
			&& bridgeProxy.InfluenceCallCount == 4
			&& Math.Abs(bridgeProxy.ClanInfluenceValue - 18.5f) < 0.0001f
			&& nextWindow.AppliedReceipt != null
			&& nextWindow.AppliedReceipt.CampaignDay == 11f,
			"A later attempt window must retry the same logical campaign day and complete idempotently.");
	}

	private static void TestScheduledCompensationPendingResume()
	{
		PolicyEffectInstanceSaveData scheduled = new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "scheduled-comp",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "scheduled-persistence-compensation",
			PolicyId = "scheduled-persistence-policy",
			ActorHeroId = "frozen-ruler",
			ModuleId = "kingdomStabilityNextDayOnce",
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = "kingdomStabilityNextDayOnce",
				["schemaVersion"] = 1,
				["value"] = 4f
			},
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "K:k1" },
				KingdomIds = new List<string> { "k1" }
			},
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			StartDay = 10f,
			EndDay = 20f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "persistence compensation marker contract"
		};
		List<PolicyEffectExecutionReceipt> receipts = new List<PolicyEffectExecutionReceipt>();
		GameBridgeProxy appliedBridgeProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge));
		IPolicyEffectGameBridge appliedBridge = (IPolicyEffectGameBridge)appliedBridgeProxy.GetTransparentProxy();
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { scheduled }, receipts, appliedBridge, 11,
			out List<string> completed, out bool executionChanged, out string executionError),
			"Scheduled persistence-compensation fixture must first apply: " + executionError);
		Check(executionChanged
			&& completed.SequenceEqual(new[] { scheduled.InstanceId }, StringComparer.Ordinal)
			&& scheduled.LifecycleState == PolicyEffectLifecycleState.Completed
			&& scheduled.ExecutionReceipt?.Status == PolicyEffectExecutionStatus.Applied
			&& receipts.Count == 1
			&& appliedBridgeProxy.CallCount == 1
			&& appliedBridgeProxy.TotalDelta == 4
			&& appliedBridgeProxy.StabilityValue == 4
			&& (int?)scheduled.ExecutionReceipt?.AppliedPayload?["targets"]?[0]?["before"] == 0
			&& (int?)scheduled.ExecutionReceipt?.AppliedPayload?["targets"]?[0]?["after"] == 4,
			"Scheduled persistence-compensation fixture must record one committed applied leg.");

		GameBridgeProxy failingCompensationProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge))
		{
			FailKingdomIdOnce = "k1"
		};
		IPolicyEffectGameBridge failingCompensation =
			(IPolicyEffectGameBridge)failingCompensationProxy.GetTransparentProxy();
		Check(!AnimusForge.PolicyEffectActivationCoordinator.TryCompensateScheduledOnceAfterPersistenceFailure(
			new[] { scheduled }, receipts, completed, failingCompensation, 11,
			out bool compensationChanged, out string compensationError)
			&& compensationChanged
			&& !string.IsNullOrWhiteSpace(compensationError),
			"A failed persistence compensation must fail closed and report its error.");
		Check(AnimusForge.PolicyEffectActivationCoordinator.HasPendingScheduledCompensation(new[] { scheduled })
			&& scheduled.LifecycleState == PolicyEffectLifecycleState.Completed
			&& scheduled.ExecutionReceipt?.Status == PolicyEffectExecutionStatus.Applied
			&& receipts.Count == 1
			&& failingCompensationProxy.CallCount == 1,
			"Failed compensation must preserve the applied receipt and write a durable pending marker.");

		PolicyEffectSaveEnvelope pendingEnvelope = new PolicyEffectSaveEnvelope
		{
			Instances = new List<PolicyEffectInstanceSaveData> { scheduled },
			Receipts = receipts.ToList()
		};
		Check(PolicyEffectSaveCodec.TrySerialize(pendingEnvelope, out string pendingJson, out string encodeError),
			"A pending scheduled compensation marker must remain persistable: " + encodeError);
		Check(PolicyEffectSaveCodec.TryDeserialize(pendingJson, out PolicyEffectSaveDecodeResult decoded, out string decodeError),
			"A pending scheduled compensation marker must survive reload: " + decodeError);
		PolicyEffectInstanceSaveData reloaded = decoded.Envelope.Instances.Single();
		Check(AnimusForge.PolicyEffectActivationCoordinator.HasPendingScheduledCompensation(new[] { reloaded })
			&& reloaded.LifecycleState == PolicyEffectLifecycleState.Completed
			&& reloaded.ExecutionReceipt?.Status == PolicyEffectExecutionStatus.Applied,
			"Reload must preserve pending compensation authority and its applied receipt.");

		int callsBeforeBlockedExecution = appliedBridgeProxy.CallCount;
		Check(!AnimusForge.PolicyEffectActivationCoordinator.TryExecuteScheduledOnce(
			new[] { reloaded }, decoded.Envelope.Receipts, appliedBridge, 12,
			out List<string> blockedCompleted, out bool blockedChanged, out string blockedError)
			&& blockedCompleted.Count == 0
			&& !blockedChanged
			&& blockedError.IndexOf("compensation", StringComparison.OrdinalIgnoreCase) >= 0
			&& appliedBridgeProxy.CallCount == callsBeforeBlockedExecution,
			"A pending compensation marker must block ScheduledOnce replay until compensation resumes.");

		appliedBridgeProxy.StabilityValue = 2;
		int callsBeforeCasMismatch = appliedBridgeProxy.CallCount;
		Check(!AnimusForge.PolicyEffectActivationCoordinator.TryResumeScheduledCompensation(
			new[] { reloaded }, decoded.Envelope.Receipts, appliedBridge, 12,
			out bool mismatchChanged, out string mismatchError)
			&& mismatchChanged
			&& !string.IsNullOrWhiteSpace(mismatchError),
			"Scheduled compensation must reject a CAS mismatch instead of overwriting a third-party stability change.");
		Check(AnimusForge.PolicyEffectActivationCoordinator.HasPendingScheduledCompensation(new[] { reloaded })
			&& reloaded.LifecycleState == PolicyEffectLifecycleState.Completed
			&& reloaded.ExecutionReceipt?.Status == PolicyEffectExecutionStatus.Applied
			&& decoded.Envelope.Receipts.Count == 1
			&& appliedBridgeProxy.CallCount == callsBeforeCasMismatch + 1
			&& appliedBridgeProxy.StabilityRestoreCallCount == 1
			&& appliedBridgeProxy.StabilityValue == 2
			&& appliedBridgeProxy.TotalDelta == 4,
			"CAS mismatch must preserve the pending marker, applied receipt, and current stability exactly.");

		appliedBridgeProxy.StabilityValue = 4;
		int callsBeforeSuccessfulResume = appliedBridgeProxy.CallCount;
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryResumeScheduledCompensation(
			new[] { reloaded }, decoded.Envelope.Receipts, appliedBridge, 12,
			out bool resumeChanged, out string resumeError),
			"Reloaded pending compensation must resume successfully: " + resumeError);
		Check(resumeChanged
			&& !AnimusForge.PolicyEffectActivationCoordinator.HasPendingScheduledCompensation(new[] { reloaded })
			&& reloaded.LifecycleState == PolicyEffectLifecycleState.Active
			&& reloaded.ExecutionReceipt == null
			&& decoded.Envelope.Receipts.Count == 0
			&& appliedBridgeProxy.CallCount == callsBeforeSuccessfulResume + 1
			&& appliedBridgeProxy.StabilityRestoreCallCount == 2
			&& appliedBridgeProxy.TotalDelta == 0
			&& appliedBridgeProxy.StabilityValue == 0,
			"Successful resume must compensate exactly once, restore pre-execution state, and clear marker/receipt.");

		int restoreCallsBeforeAlreadyRestoredCas = appliedBridgeProxy.StabilityRestoreCallCount;
		Check(appliedBridge.TryRestoreKingdomStability(
			"k1", expectedAfterValue: 4, beforeValue: 0, reason: "idempotent CAS contract",
			out int alreadyRestoredValue, out string alreadyRestoredError)
			&& alreadyRestoredValue == 0
			&& string.IsNullOrWhiteSpace(alreadyRestoredError)
			&& appliedBridgeProxy.StabilityRestoreCallCount == restoreCallsBeforeAlreadyRestoredCas + 1
			&& appliedBridgeProxy.StabilityValue == 0
			&& appliedBridgeProxy.TotalDelta == 0,
			"Stability CAS restore must treat current==before as an idempotent success without modifying the value.");

		int callsBeforeIdempotentResume = appliedBridgeProxy.CallCount;
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryResumeScheduledCompensation(
			new[] { reloaded }, decoded.Envelope.Receipts, appliedBridge, 12,
			out bool repeatedChanged, out string repeatedError),
			"Repeated scheduled-compensation resume must succeed inertly: " + repeatedError);
		Check(!repeatedChanged
			&& !AnimusForge.PolicyEffectActivationCoordinator.HasPendingScheduledCompensation(new[] { reloaded })
			&& reloaded.LifecycleState == PolicyEffectLifecycleState.Active
			&& reloaded.ExecutionReceipt == null
			&& decoded.Envelope.Receipts.Count == 0
			&& appliedBridgeProxy.CallCount == callsBeforeIdempotentResume,
			"Repeated resume must be idempotent and must not replay either effect or compensation.");
	}

	private static void TestDailyCompensationPendingResume()
	{
		PolicyEffectCanonicalTargetSet targetSet = new PolicyEffectCanonicalTargetSet
		{
			SelectorHandles = new List<string> { "C:c1" },
			ClanIds = new List<string> { "c1" }
		};
		PolicyEffectExecutionReceipt previousReceipt = new PolicyEffectExecutionReceipt
		{
			ReceiptId = "daily-compensation-previous-receipt",
			InstanceId = "daily-compensation-pending",
			PolicyId = "daily-compensation-policy",
			ModuleId = "clanInfluencePerDay",
			TargetSet = targetSet,
			Status = PolicyEffectExecutionStatus.Applied,
			RequestedValue = -0.25f,
			AppliedValue = -0.25f,
			RequestedPayload = new JObject { ["value"] = -0.25f },
			AppliedPayload = new JObject { ["historical"] = true },
			CampaignDay = 10f,
			Message = "previous daily receipt"
		};
		PolicyEffectInstanceSaveData daily = new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "daily-comp",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = previousReceipt.InstanceId,
			PolicyId = previousReceipt.PolicyId,
			ActorHeroId = "frozen-ruler",
			ModuleId = previousReceipt.ModuleId,
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = "clanInfluencePerDay",
				["schemaVersion"] = 1,
				["value"] = -1.5f
			},
			TargetSet = targetSet,
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			ExecutionReceipt = previousReceipt,
			StartDay = 10f,
			EndDay = 20f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "durable daily compensation marker contract"
		};
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryPrepareSavedInstance(
			daily,
			out IPolicyEffectModule module,
			out PolicyEffectPreparedInstance prepared,
			out string prepareError),
			"Daily durable-compensation fixture must prepare: " + prepareError);
		GameBridgeProxy appliedProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge))
		{
			ClanInfluenceValue = 20f
		};
		IPolicyEffectGameBridge appliedBridge = (IPolicyEffectGameBridge)appliedProxy.GetTransparentProxy();
		AnimusForge.PolicyEffectDailyExecutionOutcome applied = AnimusForge.PolicyEffectActivationCoordinator.ExecuteDailyTarget(
			daily,
			module,
			prepared,
			PolicyEffectTargetKind.Clan,
			"c1",
			appliedBridge,
			campaignDay: 11,
			attemptWindowDay: 11);
		Check(applied.Succeeded
			&& applied.AppliedReceipt != null
			&& ReferenceEquals(applied.PreviousReceipt, previousReceipt)
			&& string.Equals(daily.ExecutionReceipt?.ReceiptId, applied.AppliedReceipt.ReceiptId, StringComparison.Ordinal)
			&& appliedProxy.InfluenceCallCount == 1
			&& Math.Abs(appliedProxy.ClanInfluenceValue - 18.5f) < 0.0001f,
			"Daily durable-compensation fixture must apply once while retaining the transaction's previous receipt.");

		GameBridgeProxy failingProxy = new GameBridgeProxy(typeof(IPolicyEffectGameBridge))
		{
			ClanInfluenceValue = 18.5f,
			FailClanInfluenceRestoreCallsRemaining = 1
		};
		IPolicyEffectGameBridge failingBridge = (IPolicyEffectGameBridge)failingProxy.GetTransparentProxy();
		Check(!AnimusForge.PolicyEffectActivationCoordinator.TryCompensateDailyTargetAfterPersistenceFailure(
			applied, failingBridge, out string compensationError)
			&& !string.IsNullOrWhiteSpace(compensationError)
			&& failingProxy.InfluenceRestoreCallCount == 1
			&& Math.Abs(failingProxy.ClanInfluenceValue - 18.5f) < 0.0001f,
			"A failed daily persistence compensation must report failure without losing its applied value.");
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryMarkDailyCompensationPending(
			applied,
			previousReceipt,
			order: 0,
			compensationError,
			out string markerError),
			"Failed daily compensation must create a durable marker: " + markerError);
		Check(AnimusForge.PolicyEffectActivationCoordinator.HasPendingDailyCompensation(new[] { daily })
			&& string.Equals(daily.ExecutionReceipt?.ReceiptId, applied.AppliedReceipt.ReceiptId, StringComparison.Ordinal),
			"Daily compensation marker must remain authoritative over the currently applied receipt.");

		List<PolicyEffectExecutionReceipt> receipts = new List<PolicyEffectExecutionReceipt>
		{
			daily.ExecutionReceipt
		};
		PolicyEffectSaveEnvelope envelope = new PolicyEffectSaveEnvelope
		{
			Instances = new List<PolicyEffectInstanceSaveData> { daily },
			Receipts = receipts
		};
		Check(PolicyEffectSaveCodec.TrySerialize(envelope, out string pendingJson, out string encodeError),
			"A pending daily compensation marker must remain persistable: " + encodeError);
		Check(PolicyEffectSaveCodec.TryDeserialize(pendingJson, out PolicyEffectSaveDecodeResult decoded, out string decodeError),
			"A pending daily compensation marker must survive reload: " + decodeError);
		PolicyEffectInstanceSaveData reloaded = decoded.Envelope.Instances.Single();
		Check(AnimusForge.PolicyEffectActivationCoordinator.HasPendingDailyCompensation(new[] { reloaded })
			&& string.Equals(reloaded.ExecutionReceipt?.ReceiptId, applied.AppliedReceipt.ReceiptId, StringComparison.Ordinal),
			"Reload must preserve daily pending authority and the applied transaction receipt.");

		Check(AnimusForge.PolicyEffectActivationCoordinator.TryPrepareSavedInstance(
			reloaded, out IPolicyEffectModule reloadedModule, out PolicyEffectPreparedInstance reloadedPrepared, out string reloadPrepareError),
			"Reloaded daily compensation instance must prepare: " + reloadPrepareError);
		int callsBeforePendingReplayCheck = appliedProxy.InfluenceCallCount;
		AnimusForge.PolicyEffectDailyExecutionOutcome blockedReplay = AnimusForge.PolicyEffectActivationCoordinator.ExecuteDailyTarget(
			reloaded,
			reloadedModule,
			reloadedPrepared,
			PolicyEffectTargetKind.Clan,
			"c1",
			appliedBridge,
			campaignDay: 11,
			attemptWindowDay: 12);
		Check(blockedReplay.Status == PolicyEffectExecutionStatus.AlreadyApplied
			&& blockedReplay.Succeeded
			&& appliedProxy.InfluenceCallCount == callsBeforePendingReplayCheck
			&& AnimusForge.PolicyEffectActivationCoordinator.HasPendingDailyCompensation(new[] { reloaded }),
			"Pending daily compensation must prevent same-logical-day replay and remain prioritized for recovery.");

		int restoresBeforeResume = appliedProxy.InfluenceRestoreCallCount;
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryResumeDailyCompensation(
			new[] { reloaded }, decoded.Envelope.Receipts, appliedBridge, 12,
			out bool resumeChanged, out string resumeError),
			"Reloaded daily compensation marker must resume: " + resumeError);
		Check(resumeChanged
			&& !AnimusForge.PolicyEffectActivationCoordinator.HasPendingDailyCompensation(new[] { reloaded })
			&& appliedProxy.InfluenceRestoreCallCount == restoresBeforeResume + 1
			&& Math.Abs(appliedProxy.ClanInfluenceValue - 20f) < 0.0001f
			&& string.Equals(reloaded.ExecutionReceipt?.ReceiptId, previousReceipt.ReceiptId, StringComparison.Ordinal)
			&& decoded.Envelope.Receipts.Count == 1
			&& string.Equals(decoded.Envelope.Receipts[0].ReceiptId, previousReceipt.ReceiptId, StringComparison.Ordinal),
			"Daily resume must compensate exactly once, clear marker, and restore the transaction's old receipt.");

		int restoresBeforeRepeatedResume = appliedProxy.InfluenceRestoreCallCount;
		Check(AnimusForge.PolicyEffectActivationCoordinator.TryResumeDailyCompensation(
			new[] { reloaded }, decoded.Envelope.Receipts, appliedBridge, 12,
			out bool repeatedChanged, out string repeatedError),
			"Repeated daily compensation resume must succeed inertly: " + repeatedError);
		Check(!repeatedChanged
			&& !AnimusForge.PolicyEffectActivationCoordinator.HasPendingDailyCompensation(new[] { reloaded })
			&& appliedProxy.InfluenceRestoreCallCount == restoresBeforeRepeatedResume
			&& Math.Abs(appliedProxy.ClanInfluenceValue - 20f) < 0.0001f
			&& string.Equals(reloaded.ExecutionReceipt?.ReceiptId, previousReceipt.ReceiptId, StringComparison.Ordinal),
			"Repeated daily resume must not compensate twice or disturb the restored receipt.");
	}

	private static void TestPendingCompensationSurvivesTrimAndScheduler()
	{
		Type behaviorType = SutType("AnimusForge.CustomPolicyBehavior");
		Type activeEffectType = behaviorType.GetNestedType("ActivePolicyEffectSaveData", All);
		Check(activeEffectType != null, "CustomPolicyBehavior.ActivePolicyEffectSaveData contract type is missing.");
		object behavior = Activator.CreateInstance(behaviorType);
		object activeEffect = Activator.CreateInstance(activeEffectType, nonPublic: true);
		SetProperty(activeEffectType, activeEffect, "EffectId", "pending-scheduled-effect");
		SetProperty(activeEffectType, activeEffect, "SubmittedDay", 10);
		SetProperty(activeEffectType, activeEffect, "LastEffectProcessedDay", 11);
		SetProperty(activeEffectType, activeEffect, "RemainingDays", 0);
		SetProperty(activeEffectType, activeEffect, "Ended", true);
		SetProperty(activeEffectType, activeEffect, "ScopeKind", PolicyEffectScopes.Kingdom);

		PolicyEffectInstanceSaveData scheduled = new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "trim-pending-scheduled",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "trim-pending-scheduled-instance",
			PolicyId = "trim-pending-policy",
			ActorHeroId = "frozen-ruler",
			ModuleId = "kingdomStabilityNextDayOnce",
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = "kingdomStabilityNextDayOnce",
				["schemaVersion"] = 1,
				["value"] = 2f
			},
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "K:k1" },
				KingdomIds = new List<string> { "k1" }
			},
			LifecycleState = PolicyEffectLifecycleState.Completed,
			StateSchemaVersion = 1,
			StartDay = 10f,
			EndDay = 11f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "pending compensation trim contract",
			RuntimeState = new JObject
			{
				[PolicyEffectRuntimeStateEnvelope.FrameworkProperty] = new JObject
				{
					["scheduledOnce"] = new JObject
					{
						["compensationPending"] = true
					}
				}
			}
		};
		((IList)Property(activeEffectType, activeEffect, "ModuleEffects")).Add(scheduled);

		Dictionary<string, string> activeEffects
			= (Dictionary<string, string>)behaviorType.GetField("_activePolicyEffects", All).GetValue(behavior);
		activeEffects["pending-scheduled-effect"] = JsonConvert.SerializeObject(activeEffect);

		InvokeInstance(behaviorType, behavior, "TrimActivePolicyEffects", Array.Empty<object>(), 0);
		Check(activeEffects.ContainsKey("pending-scheduled-effect"),
			"TrimActivePolicyEffects must preserve an ended effect while scheduled compensation is still pending.");

		InvokeInstance(behaviorType, behavior, "EnsureActivePolicyEffectWorkScheduled", new object[] { 12 }, 1);
		HashSet<string> queuedIds
			= (HashSet<string>)behaviorType.GetField("_queuedActivePolicyEffectIds", All).GetValue(behavior);
		Check(queuedIds.Contains("pending-scheduled-effect"),
			"EnsureActivePolicyEffectWorkScheduled must enqueue a persisted scheduled-compensation marker even after natural expiry.");
	}

	private static void TestActivePolicyEffectRecoverySyncDataContracts()
	{
		Type behaviorType = SutType("AnimusForge.CustomPolicyBehavior");
		Type activeEffectType = behaviorType.GetNestedType("ActivePolicyEffectSaveData", All);
		Check(activeEffectType != null, "CustomPolicyBehavior.ActivePolicyEffectSaveData contract type is missing.");

		object rollback = CreateExceptionalActiveEffect(activeEffectType, "rollback-recovery", "rollbackPending:contract", null);
		object daily = CreateExceptionalActiveEffect(activeEffectType, "daily-recovery", "daily compensation", "daily");
		object scheduled = CreateExceptionalActiveEffect(activeEffectType, "scheduled-recovery", "scheduled compensation", "scheduledOnce");
		object mismatchedKey = CreateExceptionalActiveEffect(activeEffectType, "key-mismatch-effect", "daily compensation", "daily");
		foreach (object effect in new[] { rollback, daily, scheduled })
		{
			Check((bool)InvokeStatic(behaviorType, "ShouldRetainActivePolicyEffect", new[] { effect }, 1),
				"Every exceptional active-effect recovery state must use the shared retention predicate.");
		}

		object source = Activator.CreateInstance(behaviorType);
		Dictionary<string, string> sourceEffects
			= (Dictionary<string, string>)behaviorType.GetField("_activePolicyEffects", All).GetValue(source);
		object boundEffect = Activator.CreateInstance(activeEffectType, nonPublic: true);
		SetProperty(activeEffectType, boundEffect, "Version", 8);
		SetProperty(activeEffectType, boundEffect, "EffectId", "binding-effect");
		SetProperty(activeEffectType, boundEffect, "RecordId", "binding-record");
		SetProperty(activeEffectType, boundEffect, "ScopeKind", PolicyEffectScopes.Kingdom);
		SetProperty(activeEffectType, boundEffect, "SubmittedDay", 10);
		SetProperty(activeEffectType, boundEffect, "RemainingDays", 5);
		((IList)Property(activeEffectType, boundEffect, "ModuleEffects")).Add(new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "binding-mechanism",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "binding-instance",
			PolicyId = "binding-record",
			ModuleId = "prosperityPerDay",
			SourceModuleId = "prosperityPerDay",
			PayloadSchemaVersion = 1,
			Payload = new JObject { ["moduleId"] = "prosperityPerDay", ["schemaVersion"] = 1, ["value"] = 1f },
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "K:k1" },
				KingdomIds = new List<string> { "k1" },
				TownIds = new List<string> { "town-1" }
			},
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			StartDay = 10,
			EndDay = 20,
			SourceScope = PolicyEffectScopes.Kingdom
		});
		sourceEffects["binding-effect"] = JsonConvert.SerializeObject(boundEffect);
		sourceEffects["rollback-recovery"] = JsonConvert.SerializeObject(rollback);
		sourceEffects["daily-recovery"] = JsonConvert.SerializeObject(daily);
		sourceEffects["scheduled-recovery"] = JsonConvert.SerializeObject(scheduled);
		sourceEffects["wrong-storage-key"] = JsonConvert.SerializeObject(mismatchedKey);
		sourceEffects["corrupt-recovery"] = "{not-valid-json";
		Dictionary<string, string> sourceDynamicPolicies
			= (Dictionary<string, string>)behaviorType.GetField("_dynamicPolicyRegistry", All).GetValue(source);
		sourceDynamicPolicies["af_policy:binding-valid"] = new JObject
		{
			["Version"] = 4,
			["PolicyObjectId"] = "af_policy:binding-valid",
			["RecordId"] = "binding-record",
			["ActiveEffectId"] = "binding-effect",
			["RequiresEffectBundle"] = true,
			["CommitState"] = "active",
			["Source"] = "player",
			["Status"] = "active"
		}.ToString(Formatting.None);
		sourceDynamicPolicies["af_policy:binding-missing"] = new JObject
		{
			["Version"] = 4,
			["PolicyObjectId"] = "af_policy:binding-missing",
			["RecordId"] = "missing-record",
			["ActiveEffectId"] = "missing-effect",
			["RequiresEffectBundle"] = true,
			["CommitState"] = "active",
			["Source"] = "player",
			["Status"] = "active"
		}.ToString(Formatting.None);
		sourceDynamicPolicies["af_policy:binding-wrong-record"] = new JObject
		{
			["Version"] = 4,
			["PolicyObjectId"] = "af_policy:binding-wrong-record",
			["RecordId"] = "other-record",
			["ActiveEffectId"] = "binding-effect",
			["RequiresEffectBundle"] = true,
			["CommitState"] = "active",
			["Source"] = "player",
			["Status"] = "active"
		}.ToString(Formatting.None);
		sourceDynamicPolicies["af_policy:no-bundle"] = new JObject
		{
			["Version"] = 4,
			["PolicyObjectId"] = "af_policy:no-bundle",
			["RecordId"] = "no-bundle-record",
			["RequiresEffectBundle"] = false,
			["CommitState"] = "active",
			["Source"] = "player",
			["Status"] = "active"
		}.ToString(Formatting.None);
		sourceDynamicPolicies["af_policy:legacy-ambiguous"] = new JObject
		{
			["Version"] = 3,
			["PolicyObjectId"] = "af_policy:legacy-ambiguous",
			["RecordId"] = "binding-record",
			["Source"] = "player",
			["Status"] = "active"
		}.ToString(Formatting.None);
		string futureDynamicRaw = new JObject
		{
			["Version"] = 99,
			["PolicyObjectId"] = "af_policy:future-schema",
			["OwnerKingdomId"] = "future-owner",
			["RecordId"] = "future-record",
			["Source"] = "player",
			["Status"] = "active"
		}.ToString(Formatting.None);
		sourceDynamicPolicies["af_policy:future-schema"] = futureDynamicRaw;
		sourceDynamicPolicies["af_policy:corrupt-dynamic"] = "{not-valid-dynamic-json";

		Dictionary<string, string> persisted = new Dictionary<string, string>(StringComparer.Ordinal);
		Type dataStoreType = RequireType("TaleWorlds.CampaignSystem.IDataStore, TaleWorlds.CampaignSystem");
		object savingStore = new ContractDataStoreProxy(dataStoreType, persisted, isSaving: true).GetTransparentProxy();
		InvokeInstance(behaviorType, source, "SyncData", new[] { savingStore }, 1);
		object reloaded = Activator.CreateInstance(behaviorType);
		object loadingStore = new ContractDataStoreProxy(dataStoreType, persisted, isSaving: false).GetTransparentProxy();
		InvokeInstance(behaviorType, reloaded, "SyncData", new[] { loadingStore }, 1);
		Dictionary<string, string> reloadedEffects
			= (Dictionary<string, string>)behaviorType.GetField("_activePolicyEffects", All).GetValue(reloaded);
		Check(new[] { "binding-effect", "rollback-recovery", "daily-recovery", "scheduled-recovery", "wrong-storage-key", "corrupt-recovery" }
			.All(reloadedEffects.ContainsKey),
			"SyncData must retain rollback, daily compensation, scheduled compensation, key-drift, and corrupt raw state.");
		HashSet<string> quarantined
			= (HashSet<string>)behaviorType.GetField("_quarantinedActivePolicyEffectIds", All).GetValue(reloaded);
		Check(quarantined.SetEquals(new[] { "rollback-recovery", "wrong-storage-key", "corrupt-recovery" }),
			"Corrupt raw state, key-drift, and rollbackPending state without an executable bundle must be quarantined after load.");
		Dictionary<string, string> reloadedDynamicPolicies
			= (Dictionary<string, string>)behaviorType.GetField("_dynamicPolicyRegistry", All).GetValue(reloaded);
		HashSet<string> quarantinedDynamicPolicies
			= (HashSet<string>)behaviorType.GetField("_quarantinedDynamicPolicyIds", All).GetValue(reloaded);
		Check(reloadedDynamicPolicies.TryGetValue("af_policy:future-schema", out string retainedFutureDynamic)
			&& string.Equals(retainedFutureDynamic, futureDynamicRaw, StringComparison.Ordinal)
			&& reloadedDynamicPolicies.TryGetValue("af_policy:corrupt-dynamic", out string retainedCorruptDynamic)
			&& string.Equals(retainedCorruptDynamic, "{not-valid-dynamic-json", StringComparison.Ordinal)
			&& quarantinedDynamicPolicies.SetEquals(new[] { "af_policy:future-schema", "af_policy:corrupt-dynamic" }),
			"Future-schema and corrupt dynamic-policy rows must remain byte-for-byte recoverable while quarantined from runtime membership.");
		string ReadCommitState(string policyObjectId)
			=> JObject.Parse(reloadedDynamicPolicies[policyObjectId]).Value<string>("CommitState") ?? string.Empty;
		Check(string.Equals(ReadCommitState("af_policy:binding-valid"), "active", StringComparison.Ordinal)
			&& string.Equals(ReadCommitState("af_policy:no-bundle"), "active", StringComparison.Ordinal),
			"An exact valid bundle and an explicit no-bundle policy must remain executable after cross-store reconciliation.");
		Check(string.Equals(ReadCommitState("af_policy:binding-missing"), "quarantinedBlocked", StringComparison.Ordinal)
			&& string.Equals(ReadCommitState("af_policy:binding-wrong-record"), "quarantinedBlocked", StringComparison.Ordinal)
			&& string.Equals(ReadCommitState("af_policy:legacy-ambiguous"), "quarantinedBlocked", StringComparison.Ordinal),
			"Missing, wrong-record, and ambiguous legacy bundle bindings must be blocked without widening or restoring membership.");

		Dictionary<string, string> resaved = new Dictionary<string, string>(StringComparer.Ordinal);
		object resavingStore = new ContractDataStoreProxy(dataStoreType, resaved, isSaving: true).GetTransparentProxy();
		InvokeInstance(behaviorType, reloaded, "SyncData", new[] { resavingStore }, 1);
		object reloadedAgain = Activator.CreateInstance(behaviorType);
		object reloadingStore = new ContractDataStoreProxy(dataStoreType, resaved, isSaving: false).GetTransparentProxy();
		InvokeInstance(behaviorType, reloadedAgain, "SyncData", new[] { reloadingStore }, 1);
		Dictionary<string, string> reloadedAgainEffects
			= (Dictionary<string, string>)behaviorType.GetField("_activePolicyEffects", All).GetValue(reloadedAgain);
		Check(reloadedAgainEffects.TryGetValue("corrupt-recovery", out string corruptRaw)
			&& string.Equals(corruptRaw, "{not-valid-json", StringComparison.Ordinal),
			"A quarantined corrupt active-effect row must survive another save/load cycle byte-for-byte.");
		Dictionary<string, string> reloadedAgainDynamicPolicies
			= (Dictionary<string, string>)behaviorType.GetField("_dynamicPolicyRegistry", All).GetValue(reloadedAgain);
		Check(string.Equals(reloadedAgainDynamicPolicies["af_policy:future-schema"], futureDynamicRaw, StringComparison.Ordinal)
			&& string.Equals(reloadedAgainDynamicPolicies["af_policy:corrupt-dynamic"], "{not-valid-dynamic-json", StringComparison.Ordinal),
			"Quarantined dynamic-policy raw rows must survive another save/load cycle byte-for-byte.");

		InvokeInstance(behaviorType, reloaded, "EnsureActivePolicyEffectWorkScheduled", new object[] { 12 }, 1);
		HashSet<string> queuedIds
			= (HashSet<string>)behaviorType.GetField("_queuedActivePolicyEffectIds", All).GetValue(reloaded);
		Check(!queuedIds.Contains("rollback-recovery")
			&& queuedIds.Contains("daily-recovery")
			&& queuedIds.Contains("scheduled-recovery")
			&& !queuedIds.Contains("corrupt-recovery"),
			"The daily scheduler must enqueue only recovery states with executable bundles and never execute quarantined raw data.");

		object successfulRetryBehavior = Activator.CreateInstance(behaviorType);
		object successfulRetry = CreateExceptionalActiveEffect(
			activeEffectType,
			"rollback-success",
			"rollbackPending:contract",
			null);
		Dictionary<string, string> successfulRetryEffects
			= (Dictionary<string, string>)behaviorType.GetField("_activePolicyEffects", All).GetValue(successfulRetryBehavior);
		successfulRetryEffects["rollback-success"] = JsonConvert.SerializeObject(successfulRetry);
		InvokeInstance(behaviorType, successfulRetryBehavior, "ProcessPendingPolicyEffectRollback",
			new object[] { "rollback-success", successfulRetry, 11 }, 3);
		Check(successfulRetryEffects.ContainsKey("rollback-success"),
			"A rollback-pending effect must not retry again on LastAppliedDay.");
		InvokeInstance(behaviorType, successfulRetryBehavior, "ProcessPendingPolicyEffectRollback",
			new object[] { "rollback-success", successfulRetry, 12 }, 3);
		Check(!successfulRetryEffects.ContainsKey("rollback-success"),
			"A rollback-pending effect must be removed only after the real rollback path reports success.");

		object failedRetryBehavior = Activator.CreateInstance(behaviorType);
		object failedRetry = CreateExceptionalActiveEffect(
			activeEffectType,
			"rollback-failure",
			"rollbackPending:contract",
			null);
		PolicyEffectInstanceSaveData invalidOneShot = new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "rollback-failure-mechanism",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "rollback-failure-instance",
			PolicyId = "record-rollback-failure",
			ModuleId = "kingdomStabilityOnce",
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = "kingdomStabilityOnce",
				["schemaVersion"] = 1,
				["value"] = 1f
			},
			TargetSet = new PolicyEffectCanonicalTargetSet(),
			LifecycleState = PolicyEffectLifecycleState.Completed,
			StateSchemaVersion = 1,
			ExecutionReceipt = new PolicyEffectExecutionReceipt
			{
				ReceiptId = "rollback-failure-receipt",
				InstanceId = "rollback-failure-instance",
				PolicyId = "record-rollback-failure",
				ModuleId = "kingdomStabilityOnce",
				TargetSet = new PolicyEffectCanonicalTargetSet(),
				Status = PolicyEffectExecutionStatus.Applied,
				AppliedValue = 1f,
				CampaignDay = 10f
			}
		};
		((IList)Property(activeEffectType, failedRetry, "ModuleEffects")).Add(invalidOneShot);
		((IList)Property(activeEffectType, failedRetry, "ExecutionReceipts")).Add(invalidOneShot.ExecutionReceipt);
		Dictionary<string, string> failedRetryEffects
			= (Dictionary<string, string>)behaviorType.GetField("_activePolicyEffects", All).GetValue(failedRetryBehavior);
		failedRetryEffects["rollback-failure"] = JsonConvert.SerializeObject(failedRetry);
		InvokeInstance(behaviorType, failedRetryBehavior, "ProcessPendingPolicyEffectRollback",
			new object[] { "rollback-failure", failedRetry, 12 }, 3);
		Check(failedRetryEffects.TryGetValue("rollback-failure", out string failedRetryRaw)
			&& JObject.Parse(failedRetryRaw).Value<int>("LastAppliedDay") == 12,
			"A failed rollback must persist its pending row and advance LastAppliedDay to enforce once-per-day retry.");
		InvokeInstance(behaviorType, failedRetryBehavior, "EnsureActivePolicyEffectWorkScheduled", new object[] { 12 }, 1);
		HashSet<string> failedRetryQueuedIds
			= (HashSet<string>)behaviorType.GetField("_queuedActivePolicyEffectIds", All).GetValue(failedRetryBehavior);
		Check(!failedRetryQueuedIds.Contains("rollback-failure"),
			"A failed rollback must not be requeued again on the same campaign day.");
		InvokeInstance(behaviorType, failedRetryBehavior, "EnsureActivePolicyEffectWorkScheduled", new object[] { 13 }, 1);
		Check(failedRetryQueuedIds.Contains("rollback-failure"),
			"A persisted rollback failure must re-enter the work queue on the next campaign day.");

		Type dynamicPolicyType = behaviorType.GetNestedType("DynamicPolicySaveData", All);
		object playerActivePolicy = Activator.CreateInstance(dynamicPolicyType, nonPublic: true);
		SetProperty(dynamicPolicyType, playerActivePolicy, "Source", "player");
		SetProperty(dynamicPolicyType, playerActivePolicy, "Status", "active");
		Check((bool)InvokeStatic(behaviorType, "ShouldAutoTerminatePlayerPolicyAtNaturalExpiry",
			new[] { playerActivePolicy }, 1),
			"An active player national policy must take the direct natural-expiry termination path.");
		SetProperty(dynamicPolicyType, playerActivePolicy, "Source", "npc");
		Check(!(bool)InvokeStatic(behaviorType, "ShouldAutoTerminatePlayerPolicyAtNaturalExpiry",
			new[] { playerActivePolicy }, 1),
			"NPC policies must remain on their existing expiry-agenda path.");
	}

	private static object CreateExceptionalActiveEffect(
		Type activeEffectType,
		string effectId,
		string endReason,
		string compensationKind)
	{
		object effect = Activator.CreateInstance(activeEffectType, nonPublic: true);
		SetProperty(activeEffectType, effect, "Version", 7);
		SetProperty(activeEffectType, effect, "EffectId", effectId);
		SetProperty(activeEffectType, effect, "RecordId", "record-" + effectId);
		SetProperty(activeEffectType, effect, "ScopeKind", PolicyEffectScopes.Kingdom);
		SetProperty(activeEffectType, effect, "SubmittedDay", 10);
		SetProperty(activeEffectType, effect, "LastAppliedDay", 11);
		SetProperty(activeEffectType, effect, "LastEffectProcessedDay", 11);
		SetProperty(activeEffectType, effect, "RemainingDays", 0);
		SetProperty(activeEffectType, effect, "Ended", true);
		SetProperty(activeEffectType, effect, "EndReason", endReason);
		if (string.IsNullOrWhiteSpace(compensationKind))
		{
			return effect;
		}

		bool scheduled = string.Equals(compensationKind, "scheduledOnce", StringComparison.Ordinal);
		PolicyEffectInstanceSaveData instance = new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "recovery-" + effectId,
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "instance-" + effectId,
			PolicyId = "record-" + effectId,
			ActorHeroId = "contract-ruler",
			ModuleId = scheduled ? "kingdomStabilityNextDayOnce" : "prosperityPerDay",
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = scheduled ? "kingdomStabilityNextDayOnce" : "prosperityPerDay",
				["schemaVersion"] = 1,
				["value"] = 1f
			},
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "K:k1" },
				KingdomIds = new List<string> { "k1" },
				TownIds = scheduled ? new List<string>() : new List<string> { "town-1" }
			},
			LifecycleState = PolicyEffectLifecycleState.Completed,
			StateSchemaVersion = 1,
			StartDay = 10f,
			EndDay = 11f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "contract recovery",
			RuntimeState = new JObject
			{
				[PolicyEffectRuntimeStateEnvelope.FrameworkProperty] = new JObject
				{
					[compensationKind] = new JObject { ["compensationPending"] = true }
				}
			}
		};
		((IList)Property(activeEffectType, effect, "ModuleEffects")).Add(instance);
		return effect;
	}

	private static void TestPolicyApprovalResultSequenceContracts()
	{
		Type behaviorType = SutType("AnimusForge.CustomPolicyBehavior");
		ConcurrentQueue<Action> actions
			= (ConcurrentQueue<Action>)behaviorType.GetField("MainThreadActions", All).GetValue(null);
		while (actions.TryDequeue(out _))
		{
		}
		int cleanupCount = 0;
		InvokeStatic(behaviorType, "BeginPolicyApprovalResultSequence", new object[] { "af_policy:contract" }, 1);
		Check((bool)InvokeStatic(behaviorType, "TryDeferOriginalPolicyResult", new object[]
		{
			"af_policy:contract", new Action(() => cleanupCount++)
		}, 2), "A dynamic policy result must be intercepted before its post-vote atomic commit begins.");
		InvokeStatic(behaviorType, "CompletePolicySuccessResultSequence", new object[] { "af_policy:contract", true }, 2);
		Check(actions.TryDequeue(out Action cleanup) && cleanup != null && actions.IsEmpty,
			"Completing either approval result path must release exactly one original decision cleanup callback.");
		cleanup();
		Check(cleanupCount == 1
			&& !(bool)InvokeStatic(behaviorType, "TryDeferOriginalPolicyResult", new object[]
			{
				"af_policy:contract", new Action(() => cleanupCount++)
			}, 2),
			"The deferred cleanup must run once and the result interception state must close afterwards.");
	}

	private static void TestNpcPolicyPresentationOutboxContracts()
	{
		Type behaviorType = SutType("AnimusForge.NpcRulerPolicyBehavior");
		Type recordType = SutType("AnimusForge.NpcRulerPolicyRecord");

		object legacyPlayer = Activator.CreateInstance(recordType);
		SetProperty(recordType, legacyPlayer, "Version", 5);
		SetProperty(recordType, legacyPlayer, "PolicyId", "legacy-player-active");
		SetProperty(recordType, legacyPlayer, "KingdomId", "k1");
		SetProperty(recordType, legacyPlayer, "AgendaStatus", "active");
		SetProperty(recordType, legacyPlayer, "IsPlayerPolicy", true);
		object migratedLegacyPlayer = InvokeStatic(
			behaviorType,
			"NormalizePersistedNpcPolicyRecord",
			new[] { legacyPlayer },
			1);
		Check((int)Property(recordType, migratedLegacyPlayer, "Version") == 6
			&& (bool)Property(recordType, migratedLegacyPlayer, "ApprovalAnnouncementPublished")
			&& (bool)Property(recordType, migratedLegacyPlayer, "ApprovalPolicyEventPublished")
			&& (bool)Property(recordType, migratedLegacyPlayer, "ApprovalPublicFeedbackPublished")
			&& (bool)Property(recordType, migratedLegacyPlayer, "ApprovalWeeklyMaterialRecorded"),
			"A legacy v5 active player record must migrate as already presented to prevent duplicate load announcements.");

		object currentPlayer = Activator.CreateInstance(recordType);
		SetProperty(recordType, currentPlayer, "Version", 6);
		SetProperty(recordType, currentPlayer, "PolicyId", "v6-player-active");
		SetProperty(recordType, currentPlayer, "KingdomId", "k1");
		SetProperty(recordType, currentPlayer, "AgendaStatus", "active");
		SetProperty(recordType, currentPlayer, "IsPlayerPolicy", true);
		object normalizedCurrentPlayer = InvokeStatic(
			behaviorType,
			"NormalizePersistedNpcPolicyRecord",
			new[] { currentPlayer },
			1);
		Check((int)Property(recordType, normalizedCurrentPlayer, "Version") == 6
			&& (bool)InvokeStatic(behaviorType, "HasIncompletePolicyPresentation", new[] { normalizedCurrentPlayer }, 1),
			"A new v6 player record must preserve its incomplete durable presentation outbox.");

		object behavior = Activator.CreateInstance(behaviorType);
		Check((bool)InvokeInstance(behaviorType, behavior, "RegisterPlayerPolicyInternal", new[] { currentPlayer }, 1),
			"A v6 player policy must be accepted by the authoritative unified ledger.");
		IDictionary attemptDays = (IDictionary)behaviorType.GetField("_policyPresentationLastAttemptDayById", All).GetValue(behavior);
		Check(attemptDays.Count == 0,
			"Authoritative player ledger registration must not execute or schedule presentation side effects before the caller commits.");
		bool firstPresentationAttempt = (bool)InvokeInstance(
			behaviorType,
			behavior,
			"TryPublishPolicyPresentationInternal",
			new object[] { "v6-player-active", "player", false },
			3);
		Check(!firstPresentationAttempt && attemptDays.Count == 1,
			"An incomplete presentation must remain durable and record exactly one low-frequency attempt.");
		object attemptedDay = attemptDays["v6-player-active"];
		bool repeatedPresentationAttempt = (bool)InvokeInstance(
			behaviorType,
			behavior,
			"TryPublishPolicyPresentationInternal",
			new object[] { "v6-player-active", "player", false },
			3);
		Check(!repeatedPresentationAttempt
			&& attemptDays.Count == 1
			&& Equals(attemptedDay, attemptDays["v6-player-active"]),
			"An incomplete presentation outbox row must not retry more than once on the same campaign day.");

		IList protectedRecords = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(recordType));
		for (int index = 0; index < 181; index++)
		{
			object active = Activator.CreateInstance(recordType);
			SetProperty(recordType, active, "Version", 6);
			SetProperty(recordType, active, "PolicyId", "protected-active-" + index.ToString(CultureInfo.InvariantCulture));
			SetProperty(recordType, active, "KingdomId", "k1");
			SetProperty(recordType, active, "AgendaStatus", "active");
			SetProperty(recordType, active, "Day", index);
			SetProperty(recordType, active, "ApprovalAnnouncementPublished", true);
			SetProperty(recordType, active, "ApprovalPolicyEventPublished", true);
			SetProperty(recordType, active, "ApprovalPublicFeedbackPublished", true);
			SetProperty(recordType, active, "ApprovalWeeklyMaterialRecorded", true);
			protectedRecords.Add(active);
		}
		object historical = Activator.CreateInstance(recordType);
		SetProperty(recordType, historical, "Version", 6);
		SetProperty(recordType, historical, "PolicyId", "ordinary-history");
		SetProperty(recordType, historical, "KingdomId", "eliminated-kingdom");
		SetProperty(recordType, historical, "AgendaStatus", "abolished");
		SetProperty(recordType, historical, "Day", 999);
		protectedRecords.Add(historical);
		string[] retained = Items(InvokeStatic(behaviorType, "SelectNpcPolicyRecordIdsForRetention", new object[]
		{
			protectedRecords, new[] { "k1" }, 180
		}, 3)).Cast<string>().ToArray();
		Check(retained.Length == 181
			&& Enumerable.Range(0, 181).All(index => retained.Contains(
				"protected-active-" + index.ToString(CultureInfo.InvariantCulture), StringComparer.Ordinal)),
			"The 180-record history cap must never evict active records and may be exceeded by protected lifecycle state.");
	}

	private static void TestPlayerPolicyAgendaAutoSubmissionContract()
	{
		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string source = File.ReadAllText(
			Path.Combine(repositoryRoot, "PolicySystem", "Core", "CustomPolicyBehavior.Generation.cs"),
			Encoding.UTF8);
		int start = source.IndexOf(
			"private void CompletePolicyGeneration(PolicyDraftRequest request, PolicyGenerationResult result)",
			StringComparison.Ordinal);
		int end = source.IndexOf("private void SubmitPlayerPolicyAgenda(", start, StringComparison.Ordinal);
		Check(start >= 0 && end > start, "Player policy generation/submission call-site boundaries are missing.");
		string completionCallSite = source.Substring(start, end - start);
		Check(completionCallSite.IndexOf("SubmitPlayerPolicyAgenda(request, result, application, dynamicPolicy);", StringComparison.Ordinal) >= 0,
			"A successfully evaluated player policy must submit its AF kingdom agenda directly.");
		Check(completionCallSite.IndexOf("确认提交政策议程", StringComparison.Ordinal) < 0
			&& completionCallSite.IndexOf("CancelPlayerPolicyAgendaSubmission", StringComparison.Ordinal) < 0,
			"Player policy agenda submission must not show a second player confirmation/cancel inquiry.");
	}

	private static void TestPlayerPolicyCompletionIsolationContracts()
	{
		Type behaviorType = SutType("AnimusForge.CustomPolicyBehavior");
		Type requestType = behaviorType.GetNestedType("PolicyDraftRequest", All);
		Type settingsType = behaviorType.GetNestedType("PolicyGenerationSettingsSnapshot", All);
		Check(requestType != null && settingsType != null,
			"Player policy completion isolation requires the frozen request/settings contracts.");
		object request = Activator.CreateInstance(requestType, nonPublic: true);
		object settings = Activator.CreateInstance(settingsType, nonPublic: true);
		long currentGeneration = Convert.ToInt64(Property(
			SutType("AnimusForge.SaveRuntimeGuard"), null, "CurrentGeneration"), CultureInfo.InvariantCulture);
		SetField(settingsType, settings, "RuntimeGeneration", currentGeneration);
		SetField(requestType, request, "GenerationSettings", settings);
		SetField(requestType, request, "RequestId", "player-completion-isolation-contract");
		Check((bool)InvokeStatic(
			behaviorType,
			"IsCurrentPlayerPolicyGenerationCompletion",
			new[] { request },
			1),
			"A completion carrying the current frozen runtime generation must remain eligible for the existing completion path.");

		long staleGeneration = currentGeneration == long.MaxValue ? currentGeneration - 1L : currentGeneration + 1L;
		SetField(settingsType, settings, "RuntimeGeneration", staleGeneration);
		Check(!(bool)InvokeStatic(
			behaviorType,
			"IsCurrentPlayerPolicyGenerationCompletion",
			new[] { request },
			1),
			"A completion from a different runtime generation must be rejected before touching current campaign state.");

		object behavior = Activator.CreateInstance(behaviorType);
		SetField(behaviorType, behavior, "_generationInProgress", true);
		SetField(behaviorType, behavior, "_policyWaitPopupShown", true);
		SetField(behaviorType, behavior, "_waitTimeLocked", true);
		IDictionary dynamicPolicies = (IDictionary)behaviorType.GetField("_dynamicPolicyRegistry", All).GetValue(behavior);
		IDictionary activeEffects = (IDictionary)behaviorType.GetField("_activePolicyEffects", All).GetValue(behavior);
		IDictionary localRecords = (IDictionary)behaviorType.GetField("_localPolicyRecords", All).GetValue(behavior);
		int dynamicCount = dynamicPolicies.Count;
		int activeCount = activeEffects.Count;
		int localCount = localRecords.Count;
		InvokeInstance(
			behaviorType,
			behavior,
			"CompletePolicyGeneration",
			new object[] { request, null },
			2);
		Check((bool)behaviorType.GetField("_generationInProgress", All).GetValue(behavior)
			&& (bool)behaviorType.GetField("_policyWaitPopupShown", All).GetValue(behavior)
			&& (bool)behaviorType.GetField("_waitTimeLocked", All).GetValue(behavior)
			&& dynamicPolicies.Count == dynamicCount
			&& activeEffects.Count == activeCount
			&& localRecords.Count == localCount,
			"A stale completion must not close a newer wait state or mutate policy/effect/record stores.");

		int attemptedSteps = 0;
		InvokeStatic(
			behaviorType,
			"RunPolicyPostCommitStep",
			new object[]
			{
				"Contract",
				"post-commit-failed",
				"post-commit-contract",
				"throwing-step",
				new Action(() =>
				{
					attemptedSteps++;
					throw new InvalidOperationException("contract post-commit failure");
				})
			},
			5);
		InvokeStatic(
			behaviorType,
			"RunPolicyPostCommitStep",
			new object[]
			{
				"Contract",
				"post-commit-failed",
				"post-commit-contract",
				"following-step",
				new Action(() => attemptedSteps++)
			},
			5);
		Check(attemptedSteps == 2,
			"A failed post-commit action must be isolated so the next independent post-commit action can still run.");

		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string generationSource = File.ReadAllText(
			Path.Combine(repositoryRoot, "PolicySystem", "Core", "CustomPolicyBehavior.Generation.cs"),
			Encoding.UTF8);
		int completionStart = generationSource.IndexOf(
			"private void CompletePolicyGeneration(PolicyDraftRequest request, PolicyGenerationResult result)",
			StringComparison.Ordinal);
		int completionEnd = generationSource.IndexOf("private void SubmitPlayerPolicyAgenda(", completionStart, StringComparison.Ordinal);
		Check(completionStart >= 0 && completionEnd > completionStart,
			"Player policy completion source boundaries are missing.");
		string completionSource = generationSource.Substring(completionStart, completionEnd - completionStart);
		int generationGuardIndex = completionSource.IndexOf("if (!IsCurrentPlayerPolicyGenerationCompletion(request))", StringComparison.Ordinal);
		int waitMutationIndex = completionSource.IndexOf("EndPolicyWaitPause(\"completed\", request);", StringComparison.Ordinal);
		int progressMutationIndex = completionSource.IndexOf("_generationInProgress = false;", StringComparison.Ordinal);
		Check(generationGuardIndex >= 0
			&& waitMutationIndex > generationGuardIndex
			&& progressMutationIndex > generationGuardIndex,
			"The stale-generation guard must run before wait-state or generation-state mutation.");

		int localStart = generationSource.IndexOf(
			"private void CompleteLocalPolicyGeneration(PolicyDraftRequest request, PolicyGenerationResult result)",
			StringComparison.Ordinal);
		int localEnd = generationSource.IndexOf("private void CompleteVassalPolicyGeneration(", localStart, StringComparison.Ordinal);
		Check(localStart >= 0 && localEnd > localStart,
			"Local policy completion source boundaries are missing.");
		string localSource = generationSource.Substring(localStart, localEnd - localStart);
		int paymentIndex = localSource.IndexOf("DeductPublishCost(request, costReceipt);", StringComparison.Ordinal);
		string localPostCommitSource = paymentIndex < 0 ? string.Empty : localSource.Substring(paymentIndex);
		foreach (string stage in new[] { "replacement", "lifecycle-memory", "trim-records", "success-popup", "published-log" })
		{
			Check(localPostCommitSource.IndexOf(
				"RunLocalPolicyPostCommitStep(recordId, \"" + stage + "\"",
				StringComparison.Ordinal) >= 0,
				"Local policy post-commit stage must be isolated after payment: " + stage);
		}
	}

	private static void TestClanInfluenceVanillaDisplayBridgeContract()
	{
		Type behaviorType = SutType("AnimusForge.CustomPolicyBehavior");
		Type activeEffectType = behaviorType.GetNestedType("ActivePolicyEffectSaveData", All);
		object activeEffect = Activator.CreateInstance(activeEffectType, nonPublic: true);
		SetProperty(activeEffectType, activeEffect, "EffectId", "influence-display-effect");
		SetProperty(activeEffectType, activeEffect, "RecordId", "influence-display-policy");
		SetProperty(activeEffectType, activeEffect, "PolicyName", "影响力显示合同政策");
		SetProperty(activeEffectType, activeEffect, "ScopeKind", PolicyEffectScopes.Kingdom);
		SetProperty(activeEffectType, activeEffect, "RemainingDays", 60);
		SetProperty(activeEffectType, activeEffect, "MaintenanceFunded", true);
		PolicyEffectInstanceSaveData influence = new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "M0",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "influence-display-instance",
			PolicyId = "influence-display-policy",
			ActorHeroId = "contract-ruler",
			ModuleId = "clanInfluencePerDay",
			SourceModuleId = "clanInfluence",
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = "clanInfluencePerDay",
				["schemaVersion"] = 1,
				["value"] = 0.5f
			},
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "C:clan-contract" },
				ClanIds = new List<string> { "clan-contract" }
			},
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			StartDay = 10f,
			EndDay = 70f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "contract influence display"
		};
		((IList)Property(activeEffectType, activeEffect, "ModuleEffects")).Add(influence);
		Check(PolicyEffectSaveCodec.TryNormalizeInstance(
			influence,
			out PolicyEffectNormalizedInstance normalizedInfluence,
			out string influenceNormalizationError)
			&& normalizedInfluence?.IsInert == false,
			"The active clan influence display fixture must normalize through the production save codec: "
			+ influenceNormalizationError + " inert=" + (normalizedInfluence?.InertReason ?? string.Empty));

		object runtimeContributions = InvokeStatic(
			behaviorType,
			"BuildActivePolicyEffectRuntimeContributions",
			new[] { activeEffect },
			1);
		object[] contributions = Items(runtimeContributions).ToArray();
		Check(contributions.Length == 1,
			"An active clanInfluencePerDay instance must publish one immutable vanilla-display contribution for its clan target; actual="
			+ contributions.Length.ToString(CultureInfo.InvariantCulture));
		Type contributionType = SutType("AnimusForge.PolicyEffectRuntimeContribution");
		Check(string.Equals((string)Property(contributionType, contributions[0], "ModuleId"), "clanInfluencePerDay", StringComparison.Ordinal)
			&& string.Equals(Property(contributionType, contributions[0], "Hook").ToString(), "DailyScheduler", StringComparison.Ordinal)
			&& string.Equals(Property(contributionType, contributions[0], "TargetKind").ToString(), "Clan", StringComparison.Ordinal)
			&& string.Equals((string)Property(contributionType, contributions[0], "TargetId"), "clan-contract", StringComparison.Ordinal)
			&& Math.Abs(Convert.ToSingle(Property(contributionType, contributions[0], "Value"), CultureInfo.InvariantCulture) - 0.5f) < 0.0001f,
			"The influence display contribution must preserve the module, DailyScheduler hook, clan identity, and daily delta.");

		Type indexType = SutType("AnimusForge.PolicyEffectRuntimeIndex");
		object index = Activator.CreateInstance(indexType, nonPublic: true);
		InvokeInstance(indexType, index, "Rebuild", new[] { runtimeContributions }, 1);
		Type explainedNumberType = RequireType("TaleWorlds.CampaignSystem.ExplainedNumber, TaleWorlds.CampaignSystem");
		object[] bridgeArguments =
		{
			index,
			EnumValue(Property(contributionType, contributions[0], "Hook").GetType(), "DailyScheduler"),
			EnumValue(Property(contributionType, contributions[0], "TargetKind").GetType(), "Clan"),
			"clan-contract",
			false,
			Activator.CreateInstance(explainedNumberType)
		};
		InvokeStatic(behaviorType, "AddIndexedAdditiveContributions", bridgeArguments, 6);
		Check(Math.Abs(Convert.ToSingle(Property(explainedNumberType, bridgeArguments[5], "ResultNumber"), CultureInfo.InvariantCulture) - 0.5f) < 0.0001f,
			"The original ExplainedNumber bridge must add the indexed AF daily influence delta.");

		Assembly campaignAssembly = AppDomain.CurrentDomain.GetAssemblies().FirstOrDefault(assembly =>
			string.Equals(assembly.GetName().Name, "TaleWorlds.CampaignSystem", StringComparison.Ordinal));
		Type[] campaignTypes;
		try
		{
			campaignTypes = campaignAssembly?.GetTypes() ?? Array.Empty<Type>();
		}
		catch (ReflectionTypeLoadException ex)
		{
			campaignTypes = ex.Types.Where(type => type != null).ToArray();
		}
		Type clanPoliticsModelType = campaignTypes.FirstOrDefault(type =>
			string.Equals(type.Name, "ClanPoliticsModel", StringComparison.Ordinal));
		Type clanType = RequireType("TaleWorlds.CampaignSystem.Clan, TaleWorlds.CampaignSystem");
		Check(clanPoliticsModelType != null
			&& clanPoliticsModelType.GetMethods(All).Any(method =>
				string.Equals(method.Name, "CalculateInfluenceChange", StringComparison.Ordinal)
				&& method.ReturnType == explainedNumberType
				&& method.GetParameters().Select(parameter => parameter.ParameterType)
					.SequenceEqual(new[] { clanType, typeof(bool) })),
			"The loaded Bannerlord API must expose ClanPoliticsModel.CalculateInfluenceChange(Clan, bool) -> ExplainedNumber.");

		string repositoryRoot = FindRepositoryRoot(AppDomain.CurrentDomain.BaseDirectory);
		string source = File.ReadAllText(
			Path.Combine(repositoryRoot, "PolicySystem", "Core", "CustomPolicyBehavior.Effects.cs"),
			Encoding.UTF8);
		int postfixStart = source.IndexOf("private static void Patch_PolicyClanInfluenceChange_Postfix(", StringComparison.Ordinal);
		int postfixEnd = source.IndexOf("private static void", postfixStart + 1, StringComparison.Ordinal);
		Check(postfixStart >= 0 && postfixEnd > postfixStart, "Clan influence vanilla display postfix is missing.");
		string postfix = source.Substring(postfixStart, postfixEnd - postfixStart);
		Check(postfix.IndexOf("if (!includeDescriptions)", StringComparison.Ordinal) >= 0,
			"The clan influence bridge must be display-only so vanilla daily settlement cannot apply the AF delta a second time.");
	}

	private static void TestSaveCodecLimitsAndTypeSafety()
	{
		Type codec = SutType("AnimusForge.PolicyEffects.PolicyEffectSaveCodec");
		Check(PolicyEffectSaveCodec.MaxWireEffectsPerPolicy == 12
			&& PolicyEffectSaveCodec.MaxInstancesPerPolicy == 24
			&& PolicyEffectSaveCodec.MaxPayloadBytes == 4 * 1024
			&& PolicyEffectSaveCodec.MaxTotalPayloadBytes == 32 * 1024
			&& PolicyEffectSaveCodec.MaxRuntimeStateBytes == 512 * 1024
			&& PolicyEffectSaveCodec.MaxReceiptPayloadBytes == 256 * 1024
			&& PolicyEffectSaveCodec.MaxSerializedEnvelopeBytes == 2 * 1024 * 1024,
			"Wire/instance and normal LLM payload caps must remain unchanged while rollback state, receipt and envelope use dedicated limits.");
		JArray twentyFour = new JArray(Enumerable.Range(0, 24).Select(index =>
			BuildUnknownSaveInstance(index, new JObject { ["mode"] = "small" })));
		JObject validEnvelope = new JObject
		{
			["schemaVersion"] = 1,
			["instances"] = twentyFour,
			["receipts"] = new JArray()
		};
		object[] valid = { validEnvelope.ToString(Formatting.None), null, null };
		Check((bool)InvokeStatic(codec, "TryDeserialize", valid, 3),
			"Exactly 24 small runtime module instances must be accepted: " + valid[2]);

		JObject RuntimeStateOfSize(int bytes)
		{
			const int objectOverhead = 8; // {"d":""}
			JObject value = new JObject { ["d"] = new string('x', Math.Max(0, bytes - objectOverhead)) };
			Check(Encoding.UTF8.GetByteCount(value.ToString(Formatting.None)) == bytes,
				"Runtime/receipt boundary fixture must have the requested UTF-8 size.");
			return value;
		}
		PolicyEffectInstanceSaveData runtimeBoundary = new PolicyEffectInstanceSaveData
		{
			InstanceId = "runtime-boundary",
			ModuleId = "contractDummy.unknown",
			PayloadSchemaVersion = 1,
			Payload = new JObject { ["mode"] = "small" },
			TargetSet = new PolicyEffectCanonicalTargetSet { KingdomIds = new List<string> { "k1" } },
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			RuntimeState = RuntimeStateOfSize(PolicyEffectSaveCodec.MaxRuntimeStateBytes),
			SourceScope = PolicyEffectScopes.Kingdom
		};
		object[] runtimeAtLimit = { runtimeBoundary, null };
		Check((bool)InvokeStatic(codec, "TryValidateInstanceShape", runtimeAtLimit, 2),
			"RuntimeState exactly at 512KiB must be accepted: " + runtimeAtLimit[1]);
		runtimeBoundary.RuntimeState = RuntimeStateOfSize(PolicyEffectSaveCodec.MaxRuntimeStateBytes + 1);
		object[] runtimeOverLimit = { runtimeBoundary, null };
		Check(!(bool)InvokeStatic(codec, "TryValidateInstanceShape", runtimeOverLimit, 2),
			"RuntimeState at 512KiB plus one byte must fail closed.");

		object[] receiptAtLimit =
		{
			RuntimeStateOfSize(PolicyEffectSaveCodec.MaxReceiptPayloadBytes),
			"receipt-boundary",
			null
		};
		Check((bool)InvokeStatic(codec, "TryValidateReceiptPayload", receiptAtLimit, 3),
			"Receipt payload exactly at 256KiB must be accepted: " + receiptAtLimit[2]);
		object[] receiptOverLimit =
		{
			RuntimeStateOfSize(PolicyEffectSaveCodec.MaxReceiptPayloadBytes + 1),
			"receipt-boundary",
			null
		};
		Check(!(bool)InvokeStatic(codec, "TryValidateReceiptPayload", receiptOverLimit, 3),
			"Receipt payload at 256KiB plus one byte must fail closed.");

		JObject envelopeBoundary = (JObject)validEnvelope.DeepClone();
		envelopeBoundary["padding"] = string.Empty;
		string emptyPaddingEnvelope = envelopeBoundary.ToString(Formatting.None);
		int paddingBytes = PolicyEffectSaveCodec.MaxSerializedEnvelopeBytes
			- Encoding.UTF8.GetByteCount(emptyPaddingEnvelope);
		Check(paddingBytes >= 0, "Envelope boundary fixture base must fit below 2MiB.");
		envelopeBoundary["padding"] = new string('x', paddingBytes);
		string envelopeAtLimitJson = envelopeBoundary.ToString(Formatting.None);
		Check(Encoding.UTF8.GetByteCount(envelopeAtLimitJson) == PolicyEffectSaveCodec.MaxSerializedEnvelopeBytes,
			"Envelope boundary fixture must be exactly 2MiB.");
		object[] envelopeAtLimit = { envelopeAtLimitJson, null, null };
		Check((bool)InvokeStatic(codec, "TryDeserialize", envelopeAtLimit, 3),
			"Serialized envelope exactly at 2MiB must be accepted: " + envelopeAtLimit[2]);
		object[] envelopeOverLimit = { envelopeAtLimitJson + " ", null, null };
		Check(!(bool)InvokeStatic(codec, "TryDeserialize", envelopeOverLimit, 3),
			"Serialized envelope at 2MiB plus one byte must fail before parsing.");

		JArray twentyFive = new JArray(Enumerable.Range(0, 25).Select(index =>
			BuildUnknownSaveInstance(index, new JObject { ["mode"] = "small" })));
		object[] tooMany = { new JObject
		{
			["schemaVersion"] = 1,
			["instances"] = twentyFive,
			["receipts"] = new JArray()
		}.ToString(Formatting.None), null, null };
		Check(!(bool)InvokeStatic(codec, "TryDeserialize", tooMany, 3),
			"A 25th runtime module instance must fail closed.");

		object[] oversized = { new JObject
		{
			["schemaVersion"] = 1,
			["instances"] = new JArray(BuildUnknownSaveInstance(1,
				new JObject { ["data"] = new string('x', 5 * 1024) })),
			["receipts"] = new JArray()
		}.ToString(Formatting.None), null, null };
		Check(!(bool)InvokeStatic(codec, "TryDeserialize", oversized, 3),
			"A payload over 4KiB must fail closed.");

		JArray totalOversizedInstances = new JArray(Enumerable.Range(0, 12).Select(index =>
			BuildUnknownSaveInstance(index, new JObject { ["data"] = new string('x', 2800) })));
		object[] totalOversized = { new JObject
		{
			["schemaVersion"] = 1,
			["instances"] = totalOversizedInstances,
			["receipts"] = new JArray()
		}.ToString(Formatting.None), null, null };
		Check(!(bool)InvokeStatic(codec, "TryDeserialize", totalOversized, 3),
			"Aggregate payloads over 32KiB must fail closed.");

		object[] typeMetadata = { new JObject
		{
			["schemaVersion"] = 1,
			["instances"] = new JArray(BuildUnknownSaveInstance(1,
				new JObject { ["nested"] = new JObject { ["$type"] = "System.IO.FileInfo" } })),
			["receipts"] = new JArray()
		}.ToString(Formatting.None), null, null };
		Check(!(bool)InvokeStatic(codec, "TryDeserialize", typeMetadata, 3),
			"Recursive $type metadata must be rejected.");

		TestActiveV4PendingMirrorNotDoubleCounted(codec);
		TestDirectEffectShellLogicalInstanceValidation(codec);
		TestCompositePersistenceRejection(codec);
	}

	private static void TestCompositePersistenceRejection(Type codec)
	{
		PolicyEffectInstanceSaveData influenceComposite = new PolicyEffectInstanceSaveData
		{
			EffectPlanVersion = PolicyEffectPlanVersions.CurrentVersion,
			MechanismId = "persisted-composite",
			MechanismKind = PolicyEffectMechanismKind.Independent,
			MechanismRole = PolicyEffectMechanismRole.Subject,
			InstanceId = "persisted-clan-influence-composite",
			PolicyId = "persisted-composite-policy",
			ActorHeroId = "frozen-ruler",
			ModuleId = "clanInfluence",
			PayloadSchemaVersion = 1,
			Payload = new JObject
			{
				["moduleId"] = "clanInfluence",
				["schemaVersion"] = 1,
				["onceDelta"] = 2f,
				["dailyDelta"] = -0.5f
			},
			TargetSet = new PolicyEffectCanonicalTargetSet
			{
				SelectorHandles = new List<string> { "C:c1" },
				ClanIds = new List<string> { "c1" }
			},
			LifecycleState = PolicyEffectLifecycleState.Active,
			StateSchemaVersion = 1,
			StartDay = 10f,
			EndDay = 20f,
			SourceScope = PolicyEffectScopes.Kingdom,
			Reason = "compile-time shell must not persist"
		};
		PolicyEffectSaveEnvelope envelope = new PolicyEffectSaveEnvelope
		{
			Instances = new List<PolicyEffectInstanceSaveData> { influenceComposite }
		};
		Check(!PolicyEffectSaveCodec.TrySerialize(envelope, out _, out string serializeError)
			&& serializeError.IndexOf("Composite", StringComparison.OrdinalIgnoreCase) >= 0,
			"SaveCodec serialization must explicitly reject a persisted visible clanInfluence Composite shell: " + serializeError);
		string rawEnvelope = new JObject
		{
			["schemaVersion"] = PolicyEffectDataVersions.SaveSchemaVersion,
			["instances"] = new JArray(JObject.FromObject(influenceComposite)),
			["receipts"] = new JArray()
		}.ToString(Formatting.None);
		object[] deserialize = { rawEnvelope, null, null };
		Check(!(bool)InvokeStatic(codec, "TryDeserialize", deserialize, 3)
			&& (deserialize[2] as string)?.IndexOf("Composite", StringComparison.OrdinalIgnoreCase) >= 0,
			"SaveCodec deserialization must explicitly reject a persisted visible clanInfluence Composite shell.");

		JObject embeddedRecord = BuildPolicyRecordV2DirectShells();
		JObject stabilityComposite = new JObject
		{
			["effectPlanVersion"] = PolicyEffectPlanVersions.CurrentVersion,
			["mechanismId"] = "persisted-stability-composite",
			["mechanismKind"] = "independent",
			["mechanismRole"] = "subject",
			["instanceId"] = "persisted-kingdom-stability-composite",
			["policyId"] = "policy-v2-direct-shells",
			["actorHeroId"] = "frozen-ruler",
			["moduleId"] = "kingdomStability",
			["payloadSchemaVersion"] = 1,
			["payload"] = new JObject
			{
				["moduleId"] = "kingdomStability",
				["schemaVersion"] = 1,
				["value"] = 3f
			},
			["targetSet"] = new JObject
			{
				["structureVersion"] = 1,
				["selectorHandles"] = new JArray("K:k1"),
				["kingdomIds"] = new JArray("k1")
			},
			["lifecycleState"] = 1,
			["stateSchemaVersion"] = 1,
			["startDay"] = 10f,
			["endDay"] = 20f,
			["sourceScope"] = "kingdom",
			["reason"] = "embedded compile-time shell must not persist"
		};
		((JArray)embeddedRecord["Effects"]).Add(new JObject
		{
			["EffectId"] = "embedded-composite-shell",
			["ModuleEffects"] = new JArray(stabilityComposite),
			["ExecutionReceipts"] = new JArray()
		});
		MethodInfo normalizer = codec.GetMethods(All).Single(method =>
			method.Name == "TryNormalizePolicyRecordV1ToV2"
			&& method.IsStatic
			&& method.GetParameters().Length == 4
			&& method.GetParameters()[0].ParameterType == typeof(JObject));
		object[] normalizeArguments = { embeddedRecord, null, null, null };
		Check(!(bool)normalizer.Invoke(null, normalizeArguments)
			&& (normalizeArguments[3] as string)?.IndexOf("Composite", StringComparison.OrdinalIgnoreCase) >= 0,
			"Embedded logical-collection validation must explicitly reject a persisted visible kingdomStability Composite shell.");
	}

	private static void TestActiveV4PendingMirrorNotDoubleCounted(Type codec)
	{
		JArray authoritativeTwentyFour = new JArray(Enumerable.Range(0, 24).Select(index =>
			BuildUnknownSaveInstance(index, new JObject
			{
				["mode"] = "preserve",
				["ordinal"] = index
			})));
		JToken expectedUnknownPayload = authoritativeTwentyFour[0]["payload"].DeepClone();
		JObject mirroredActive = BuildActiveV4ForLimits(authoritativeTwentyFour,
			(JArray)authoritativeTwentyFour.DeepClone());
		object normalizedMirroredActive = NormalizeJObject(codec, "TryNormalizeActiveV4ToV5",
			mirroredActive.ToString(Formatting.None), out object mirroredSummary);
		object[] normalizedAuthoritative = TokenArray(normalizedMirroredActive, "ModuleEffects");
		Check(normalizedAuthoritative.Length == 24,
			"Active v4 must apply the 24-runtime-instance limit to authoritative top-level ModuleEffects only.");
		Check(JToken.DeepEquals((JToken)GetToken(normalizedAuthoritative[0], "Payload"), expectedUnknownPayload),
			"Active v4 migration must preserve an unknown top-level module payload exactly.");
		Check(Convert.ToInt32(Property(mirroredSummary.GetType(), mirroredSummary, "InertInstances"),
			CultureInfo.InvariantCulture) == 24,
			"pendingApplication.appliedEffect.ModuleEffects must not be counted as a second authoritative set.");

		JArray authoritativeLargeButValid = new JArray(Enumerable.Range(0, 6).Select(index =>
			BuildUnknownSaveInstance(index, new JObject { ["data"] = new string('m', 3000) })));
		object normalizedLargeButValid = NormalizeJObject(codec, "TryNormalizeActiveV4ToV5",
			BuildActiveV4ForLimits(authoritativeLargeButValid,
				(JArray)authoritativeLargeButValid.DeepClone()).ToString(Formatting.None), out object largeButValidSummary);
		Check(TokenArray(normalizedLargeButValid, "ModuleEffects").Length == 6,
			"A valid top-level payload total must not fail because the pending mirror duplicates its bytes.");
		Check(Convert.ToInt32(Property(largeButValidSummary.GetType(), largeButValidSummary, "InertInstances"),
			CultureInfo.InvariantCulture) == 6,
			"The pending mirror must not duplicate total-payload accounting or inert-module reporting.");
	}

	private static void TestDirectEffectShellLogicalInstanceValidation(Type codec)
	{
		JObject policyRecord = BuildPolicyRecordV2DirectShells();
		object normalized = NormalizeJObject(codec, "TryNormalizePolicyRecordV1ToV2",
			policyRecord.ToString(Formatting.None), out object summary);
		Check(TokenArray(normalized, "Effects").Length == 14,
			"PolicyRecord v2 normalization must preserve all direct target shells.");
		Check(Convert.ToInt32(Property(summary.GetType(), summary, "InertInstances"),
			CultureInfo.InvariantCulture) == 2,
			"Fourteen direct target shells must be validated as two logical InstanceIds.");

		JObject conflicting = (JObject)policyRecord.DeepClone();
		JArray effects = (JArray)conflicting["Effects"];
		JObject conflictingInstance = (JObject)((JArray)((JObject)effects[1])["ModuleEffects"])[0];
		((JObject)conflictingInstance["payload"])["logical"] = "conflict";
		MethodInfo normalizer = codec.GetMethods(All).Single(method =>
			method.Name == "TryNormalizePolicyRecordV1ToV2"
			&& method.IsStatic
			&& method.GetParameters().Length == 4
			&& method.GetParameters()[0].ParameterType == typeof(JObject));
		object[] arguments = { conflicting, null, null, null };
		Check(!(bool)normalizer.Invoke(null, arguments),
			"Direct target shells sharing an InstanceId must reject conflicting payloads.");
		Check(!string.IsNullOrWhiteSpace(arguments[3] as string),
			"Conflicting direct target shell payloads must return a validation error.");

		JObject actorConflict = (JObject)policyRecord.DeepClone();
		JArray actorEffects = (JArray)actorConflict["Effects"];
		((JObject)((JArray)((JObject)actorEffects[0])["ModuleEffects"])[0])["actorHeroId"] = "actor-alpha";
		((JObject)((JArray)((JObject)actorEffects[1])["ModuleEffects"])[0])["actorHeroId"] = "actor-beta";
		object[] actorArguments = { actorConflict, null, null, null };
		Check(!(bool)normalizer.Invoke(null, actorArguments),
			"Save normalization must reject direct shells sharing an InstanceId with conflicting ActorHeroId values.");
		Check(!string.IsNullOrWhiteSpace(actorArguments[3] as string),
			"Conflicting direct target shell actors must return a validation error.");
	}

	private static JObject BuildPolicyRecordV2DirectShells()
	{
		JArray effects = new JArray();
		for (int logicalIndex = 0; logicalIndex < 2; logicalIndex++)
		{
			JObject payload = new JObject
			{
				["logical"] = "logical-" + logicalIndex.ToString(CultureInfo.InvariantCulture),
				["data"] = new string((char)('a' + logicalIndex), 3000)
			};
			for (int targetIndex = 0; targetIndex < 7; targetIndex++)
			{
				JObject instance = BuildUnknownSaveInstance(logicalIndex, (JObject)payload.DeepClone());
				instance["instanceId"] = "direct-logical-" + logicalIndex.ToString(CultureInfo.InvariantCulture);
				instance["policyId"] = "policy-v2-direct-shells";
				instance["targetSet"] = new JObject
				{
					["structureVersion"] = 1,
					["kingdomIds"] = new JArray("k-" + logicalIndex.ToString(CultureInfo.InvariantCulture)
						+ "-" + targetIndex.ToString(CultureInfo.InvariantCulture))
				};
				effects.Add(new JObject
				{
					["EffectId"] = "direct-shell-" + logicalIndex.ToString(CultureInfo.InvariantCulture)
						+ "-" + targetIndex.ToString(CultureInfo.InvariantCulture),
					["ModuleEffects"] = new JArray(instance),
					["ExecutionReceipts"] = new JArray()
				});
			}
		}
		return new JObject
		{
			["Version"] = 2,
			["RecordId"] = "policy-v2-direct-shells",
			["ScopeKind"] = "kingdom",
			["Effects"] = effects
		};
	}

	private static JObject BuildActiveV4ForLimits(JArray moduleEffects, JArray pendingMirror = null)
	{
		JObject active = new JObject
		{
			["Version"] = 4,
			["EffectId"] = "active-v4-limits",
			["RecordId"] = "record-v4-limits",
			["ScopeKind"] = "kingdom",
			["TargetKingdomId"] = "k1",
			["ModuleEffects"] = moduleEffects,
			["ExecutionReceipts"] = new JArray()
		};
		if (pendingMirror != null)
		{
			active["pendingApplication"] = new JObject
			{
				["appliedEffect"] = new JObject
				{
					["ModuleEffects"] = pendingMirror
				}
			};
		}
		return active;
	}

	private static JObject BuildUnknownSaveInstance(int index, JObject payload)
	{
		return new JObject
		{
			["instanceId"] = "limit-" + index.ToString(CultureInfo.InvariantCulture),
			["policyId"] = "limit-policy",
			["moduleId"] = "contractDummy.unknown",
			["payloadSchemaVersion"] = 1,
			["payload"] = payload,
			["targetSet"] = new JObject
			{
				["structureVersion"] = 1,
				["kingdomIds"] = new JArray("k1")
			},
			["lifecycleState"] = 1,
			["stateSchemaVersion"] = 1,
			["sourceScope"] = "kingdom"
		};
	}

	private static void TestSyntheticDescriptorsAndRuntimeIndex()
	{
		Type descriptorType = SutType("AnimusForge.PolicyEffects.PolicyEffectModuleDescriptor");
		ConstructorInfo descriptorConstructor = descriptorType.GetConstructors(All)
			.Where(constructor => constructor.GetParameters().Any(parameter =>
				string.Equals(parameter.Name, "fundingStrategy", StringComparison.Ordinal)))
			.OrderByDescending(constructor => constructor.GetParameters().Length)
			.First();
		object schema = InvokeStatic(SutType("AnimusForge.PolicyEffects.PolicyEffectPayloadSchemas"), "CreateNumericValueSchema", Array.Empty<object>(), 0);
		List<object> descriptors = new List<object>(64);
		for (int i = 0; i < 64; i++)
		{
			object[] arguments = BuildSyntheticDescriptorArguments(descriptorConstructor, schema, i);
			descriptors.Add(descriptorConstructor.Invoke(arguments));
		}
		Check(descriptors.Select(item => (string)Property(descriptorType, item, "Id")).Distinct(StringComparer.Ordinal).Count() == 64,
			"64 synthetic descriptor IDs must remain unique.");
		Check(descriptors.Select(item => Convert.ToInt32(Property(descriptorType, item, "Order"), CultureInfo.InvariantCulture)).Distinct().Count() == 64,
			"64 synthetic descriptor orders must remain unique.");
		Check(descriptors.GroupBy(item => Property(descriptorType, item, "Hook")).Sum(group => group.Count()) == 64,
			"64 synthetic descriptors must be indexable by hook without loss.");

		Type contributionType = SutType("AnimusForge.PolicyEffectRuntimeContribution");
		Type indexType = SutType("AnimusForge.PolicyEffectRuntimeIndex");
		ConstructorInfo contributionConstructor = contributionType.GetConstructors(All).Single();
		Type[] contributionParameters = contributionConstructor.GetParameters().Select(parameter => parameter.ParameterType).ToArray();
		Array contributions = Array.CreateInstance(contributionType, 100);
		object[] hooks = Enum.GetValues(contributionParameters[4]).Cast<object>().ToArray();
		object[] runtimeTargetKinds = Enum.GetValues(contributionParameters[5]).Cast<object>().ToArray();
		for (int i = 0; i < 100; i++)
		{
			object contribution = contributionConstructor.Invoke(new object[]
			{
				"instance-" + i.ToString("D2", CultureInfo.InvariantCulture), "policy-" + (i % 4),
				"synthetic." + i.ToString("D2", CultureInfo.InvariantCulture), "Synthetic " + i,
				hooks[i % hooks.Length], runtimeTargetKinds[i % runtimeTargetKinds.Length],
				"target-" + i.ToString("D2", CultureInfo.InvariantCulture),
				EnumValue(contributionParameters[7], "Additive"), i + 0.5f
			});
			contributions.SetValue(contribution, i);
		}

		object index = Activator.CreateInstance(indexType, nonPublic: true);
		InvokeInstance(indexType, index, "Rebuild", new object[] { contributions }, 1);
		Check(Convert.ToInt32(Property(indexType, index, "ContributionCount"), CultureInfo.InvariantCulture) == 100,
			"Runtime index must retain all 100 active synthetic contributions.");
		Check(Convert.ToInt64(Property(indexType, index, "StructureVersion"), CultureInfo.InvariantCulture) == 1L,
			"Initial runtime index rebuild must publish one structure version.");
		for (int i = 0; i < 100; i++)
		{
			object contribution = contributions.GetValue(i);
			object result = InvokeInstance(indexType, index, "GetContributions", new[]
			{
				Property(contributionType, contribution, "Hook"), Property(contributionType, contribution, "TargetKind"),
				Property(contributionType, contribution, "TargetId")
			}, 3);
			Check(Items(result).Count() == 1, "Runtime index lookup lost synthetic contribution " + i);
		}
		Check(Convert.ToInt64(Property(indexType, index, "StructureVersion"), CultureInfo.InvariantCulture) == 1L,
			"100 hot-path lookups must not rebuild the structural index.");

		Array replacement = Array.CreateInstance(contributionType, 1);
		replacement.SetValue(contributions.GetValue(0), 0);
		InvokeInstance(indexType, index, "ReplaceInstance", new object[] { "instance-00", replacement }, 2);
		Check(Convert.ToInt64(Property(indexType, index, "StructureVersion"), CultureInfo.InvariantCulture) == 2L,
			"One structural replacement must publish exactly one new snapshot.");
		Check(Convert.ToInt32(Property(indexType, index, "ContributionCount"), CultureInfo.InvariantCulture) == 100,
			"Replacing an active instance must not duplicate its contribution.");
		Check((bool)InvokeInstance(indexType, index, "RemoveInstance", new object[] { "instance-00" }, 1),
			"Removing an active instance must report a structural change.");
		Check(Convert.ToInt64(Property(indexType, index, "StructureVersion"), CultureInfo.InvariantCulture) == 3L,
			"One structural removal must publish exactly one new snapshot.");
		Check(Convert.ToInt32(Property(indexType, index, "ContributionCount"), CultureInfo.InvariantCulture) == 99,
			"Removing one active instance must remove only its own contribution.");

		bool rejectedNaN = false;
		try
		{
			contributionConstructor.Invoke(new object[]
			{
				"nan-instance", "p", "synthetic.nan", "NaN", hooks[0], runtimeTargetKinds[0], "target-nan",
				EnumValue(contributionParameters[7], "Additive"), float.NaN
			});
		}
		catch (TargetInvocationException ex) when (ex.InnerException is ArgumentOutOfRangeException)
		{
			rejectedNaN = true;
		}
		Check(rejectedNaN, "Runtime contribution must reject NaN.");

		object duplicateIndex = Activator.CreateInstance(indexType, nonPublic: true);
		Array duplicateContributions = Array.CreateInstance(contributionType, 4);
		duplicateContributions.SetValue(contributionConstructor.Invoke(new object[]
		{
			"instance-z", "same-policy", "same-module", "Duplicate Z", hooks[0], runtimeTargetKinds[0],
			"same-target", EnumValue(contributionParameters[7], "Additive"), 2f
		}), 0);
		duplicateContributions.SetValue(contributionConstructor.Invoke(new object[]
		{
			"instance-a", "same-policy", "same-module", "Duplicate A", hooks[0], runtimeTargetKinds[0],
			"same-target", EnumValue(contributionParameters[7], "Additive"), 2f
		}), 1);
		duplicateContributions.SetValue(contributionConstructor.Invoke(new object[]
		{
			"instance-other-policy", "other-policy", "same-module", "Other policy", hooks[0], runtimeTargetKinds[0],
			"same-target", EnumValue(contributionParameters[7], "Additive"), 3f
		}), 2);
		duplicateContributions.SetValue(contributionConstructor.Invoke(new object[]
		{
			"instance-m", "same-policy", "same-module", "Conflicting duplicate", hooks[0], runtimeTargetKinds[0],
			"same-target", EnumValue(contributionParameters[7], "Additive"), 9f
		}), 3);
		InvokeInstance(indexType, duplicateIndex, "Rebuild", new object[] { duplicateContributions }, 1);
		Check(Convert.ToInt32(Property(indexType, duplicateIndex, "ContributionCount"), CultureInfo.InvariantCulture) == 2,
			"Runtime index must keep one contribution per policy/module/target while allowing another policy to stack.");
		object duplicateLookup = InvokeInstance(indexType, duplicateIndex, "GetContributions", new[]
		{
			hooks[0], runtimeTargetKinds[0], "same-target"
		}, 3);
		object[] retainedDuplicates = Items(duplicateLookup).ToArray();
		Check(retainedDuplicates.Length == 2
			&& retainedDuplicates.Count(item => string.Equals((string)Property(contributionType, item, "PolicyId"), "same-policy", StringComparison.Ordinal)) == 1
			&& retainedDuplicates.Any(item => string.Equals((string)Property(contributionType, item, "InstanceId"), "instance-a", StringComparison.Ordinal)
				&& Math.Abs(Convert.ToSingle(Property(contributionType, item, "Value"), CultureInfo.InvariantCulture) - 2f) < 0.0001f),
			"Runtime duplicate protection must deterministically keep the lowest instance ID for one policy without suppressing other policies.");
	}

	private static object[] BuildSyntheticDescriptorArguments(
		ConstructorInfo descriptorConstructor,
		object schema,
		int index)
	{
		ParameterInfo[] parameters = descriptorConstructor.GetParameters();
		object[] arguments = new object[parameters.Length];
		for (int parameterIndex = 0; parameterIndex < parameters.Length; parameterIndex++)
		{
			ParameterInfo parameter = parameters[parameterIndex];
			switch (parameter.Name)
			{
				case "id":
					arguments[parameterIndex] = "synthetic." + index.ToString("D2", CultureInfo.InvariantCulture);
					break;
				case "order":
					arguments[parameterIndex] = index;
					break;
				case "legacyIds":
					arguments[parameterIndex] = Array.Empty<string>();
					break;
				case "allowedScopes":
					arguments[parameterIndex] = new[] { "local" };
					break;
				case "allowedSelectorKinds":
				case "targetKinds":
					arguments[parameterIndex] = SingleElementArray(
						parameter.ParameterType.GetGenericArguments()[0], "Settlement");
					break;
				case "cueTerms":
					arguments[parameterIndex] = new[] { "synthetic" };
					break;
				case "retrievalText":
					arguments[parameterIndex] = "synthetic retrieval";
					break;
				case "catalogSummary":
					arguments[parameterIndex] = "synthetic catalog";
					break;
				case "mainInstruction":
					arguments[parameterIndex] = "synthetic main";
					break;
				case "postprocessRule":
					arguments[parameterIndex] = "synthetic postprocess";
					break;
				case "payloadPromptSchema":
					arguments[parameterIndex] = schema;
					break;
				case "family":
					arguments[parameterIndex] = EnumValue(parameter.ParameterType, 0);
					break;
				case "executionKind":
					arguments[parameterIndex] = EnumValue(parameter.ParameterType, "ModelModifier");
					break;
				case "hook":
					arguments[parameterIndex] = EnumValue(
						parameter.ParameterType,
						index % Enum.GetValues(parameter.ParameterType).Length);
					break;
				case "aggregation":
					arguments[parameterIndex] = EnumValue(parameter.ParameterType, "Additive");
					break;
				case "valueUnit":
					arguments[parameterIndex] = EnumValue(parameter.ParameterType, "PointsPerDay");
					break;
				case "fundingMode":
					arguments[parameterIndex] = EnumValue(parameter.ParameterType, "Unscaled");
					break;
				case "fundingStrategy":
					arguments[parameterIndex] = EnumValue(parameter.ParameterType, "Linear");
					break;
				case "payloadSchemaVersion":
					arguments[parameterIndex] = 1;
					break;
				case "supportsRollback":
				case "supportsIdempotency":
					arguments[parameterIndex] = false;
					break;
				default:
					if (!parameter.HasDefaultValue)
					{
						throw new InvalidOperationException(
							"Synthetic descriptor fixture has no value for required parameter: " + parameter.Name);
					}
					arguments[parameterIndex] = parameter.DefaultValue;
					break;
			}
		}
		return arguments;
	}

	private static string[] ScopeIds(Type catalog, string scope)
	{
		return Items(InvokeStatic(catalog, "GetModulesForScope", new object[] { scope }, 1))
			.Select(module => (string)Property(module.GetType(), module, "Id"))
			.ToArray();
	}

	private static object NormalizeJObject(Type codec, string methodName, string json, out object summary)
	{
		JObject source = JObject.Parse(json);
		MethodInfo normalizer = codec.GetMethods(All).Single(method =>
			method.Name == methodName
			&& method.IsStatic
			&& method.GetParameters().Length == 4
			&& method.GetParameters()[0].ParameterType == typeof(JObject));
		object[] arguments = { source, null, null, null };
		Check((bool)normalizer.Invoke(null, arguments), methodName + " rejected fixture: " + arguments[3]);
		Check(arguments[1] is JObject, methodName + " must return a JObject.");
		Check(arguments[2] != null, methodName + " must return a migration summary.");
		summary = arguments[2];
		return arguments[1];
	}

	private static object GetToken(object value, string name)
	{
		Check(value is JObject, "Expected JObject while reading " + name + ", actual=" + (value?.GetType().FullName ?? "(null)"));
		return ((JObject)value).GetValue(name, StringComparison.OrdinalIgnoreCase);
	}

	private static object[] TokenArray(object value, string name)
	{
		object token = GetToken(value, name);
		Check(token is JArray, "Expected JArray " + name + ".");
		return ((JArray)token).Cast<object>().ToArray();
	}

	private static int TokenInt(object value, string name)
	{
		object token = GetToken(value, name);
		Check(token != null, "Missing integer token " + name + ".");
		return ((JToken)token).Value<int>();
	}

	private static bool TokenBool(object value, string name)
	{
		object token = GetToken(value, name);
		Check(token != null, "Missing boolean token " + name + ".");
		return ((JToken)token).Value<bool>();
	}

	private static string TokenString(object value, string name)
	{
		object token = GetToken(value, name);
		return token == null ? string.Empty : ((JToken)token).Value<string>() ?? string.Empty;
	}

	private static bool HasModule(IEnumerable<object> instances, string moduleId)
	{
		return (instances ?? Enumerable.Empty<object>()).Any(instance =>
			string.Equals(TokenString(instance, "ModuleId"), moduleId, StringComparison.Ordinal));
	}

	private static bool HasTypedModule(IEnumerable<object> instances, string moduleId)
	{
		return (instances ?? Enumerable.Empty<object>()).Any(instance => instance != null
			&& string.Equals((string)Property(instance.GetType(), instance, "ModuleId"), moduleId, StringComparison.Ordinal));
	}

	private static void SetProperty(Type type, object instance, string name, object value)
	{
		PropertyInfo property = type.GetProperty(name, All);
		Check(property != null && property.CanWrite, "Required writable property missing: " + type.FullName + "." + name);
		property.SetValue(instance, value, null);
	}

	private static void SetField(Type type, object instance, string name, object value)
	{
		FieldInfo field = type.GetField(name, All);
		Check(field != null, "Required field missing: " + type.FullName + "." + name);
		field.SetValue(instance, value);
	}

	private static object SingleElementArray(Type elementType, string enumName)
	{
		Array array = Array.CreateInstance(elementType, 1);
		array.SetValue(EnumValue(elementType, enumName), 0);
		return array;
	}

	private static object EnumValue(Type enumType, string name)
	{
		return Enum.Parse(enumType, name, ignoreCase: false);
	}

	private static object EnumValue(Type enumType, int index)
	{
		return Enum.GetValues(enumType).GetValue(index);
	}

	private static object ParseToken(string json)
	{
		MethodInfo method = _jTokenType.GetMethod("Parse", All, null, new[] { typeof(string) }, null);
		Check(method != null, "JToken.Parse(string) missing.");
		return method.Invoke(null, new object[] { json });
	}

	private static object TokenFromObject(object value)
	{
		MethodInfo method = _jTokenType.GetMethods(All)
			.Single(candidate => candidate.Name == "FromObject" && candidate.IsStatic && candidate.GetParameters().Length == 1);
		return method.Invoke(null, new[] { value });
	}

	private static object TokenToObject(object token, Type targetType)
	{
		MethodInfo method = _jTokenType.GetMethod("ToObject", All, null, new[] { typeof(Type) }, null);
		Check(method != null, "JToken.ToObject(Type) missing.");
		return method.Invoke(token, new object[] { targetType });
	}

	private static string TokenText(object token)
	{
		return token?.ToString() ?? string.Empty;
	}

	private static Dictionary<string, float> ReadStringFloatDictionary(object dictionary)
	{
		Dictionary<string, float> result = new Dictionary<string, float>(StringComparer.Ordinal);
		foreach (object pair in Items(dictionary))
		{
			Type pairType = pair.GetType();
			result.Add(
				(string)Property(pairType, pair, "Key"),
				Convert.ToSingle(Property(pairType, pair, "Value"), CultureInfo.InvariantCulture));
		}
		return result;
	}

	private static Type SutType(string fullName)
	{
		Type type = _sut.GetType(fullName, throwOnError: false, ignoreCase: false);
		Check(type != null, "Required production contract type missing: " + fullName);
		return type;
	}

	private static Type RequireType(string assemblyQualifiedName)
	{
		Type type = Type.GetType(assemblyQualifiedName, throwOnError: false);
		if (type == null)
		{
			string fullTypeName = assemblyQualifiedName.Split(',')[0].Trim();
			foreach (Assembly assembly in AppDomain.CurrentDomain.GetAssemblies())
			{
				type = assembly.GetType(fullTypeName, throwOnError: false, ignoreCase: false);
				if (type != null)
				{
					break;
				}
			}
		}
		Check(type != null, "Required runtime type missing: " + assemblyQualifiedName);
		return type;
	}

	private static object Property(Type type, object instance, string name)
	{
		PropertyInfo property = type.GetProperty(name, All);
		Check(property != null, "Required property missing: " + type.FullName + "." + name);
		return property.GetValue(instance, null);
	}

	private static object InvokeStatic(Type type, string name, object[] arguments, int parameterCount)
	{
		return Method(type, name, parameterCount, isStatic: true).Invoke(null, arguments);
	}

	private static object InvokeInstance(Type type, object instance, string name, object[] arguments, int parameterCount)
	{
		return Method(type, name, parameterCount, isStatic: false).Invoke(instance, arguments);
	}

	private static MethodInfo Method(Type type, string name, int parameterCount, bool isStatic)
	{
		MethodInfo[] matches = type.GetMethods(All)
			.Where(method => method.Name == name && method.IsStatic == isStatic && method.GetParameters().Length == parameterCount)
			.ToArray();
		Check(matches.Length == 1, "Expected one method " + type.FullName + "." + name + "/" + parameterCount + ", actual=" + matches.Length);
		return matches[0];
	}

	private static IEnumerable<object> Items(object value)
	{
		Check(value is IEnumerable, "Value is not enumerable: " + (value?.GetType().FullName ?? "(null)"));
		foreach (object item in (IEnumerable)value)
		{
			yield return item;
		}
	}

	private static void Check(bool condition, string message)
	{
		_assertionCount++;
		if (!condition)
		{
			throw new InvalidOperationException(message);
		}
	}

	private static Exception Unwrap(Exception exception)
	{
		while (exception is TargetInvocationException invocation && invocation.InnerException != null)
		{
			exception = invocation.InnerException;
		}
		return exception;
	}

	private sealed class GameBridgeProxy : RealProxy
	{
		internal GameBridgeProxy(Type interfaceType)
			: base(interfaceType)
		{
		}

		internal int CallCount { get; private set; }

		internal int TotalDelta { get; private set; }

		internal int InfluenceCallCount { get; private set; }

		internal int InfluenceRestoreCallCount { get; private set; }

		internal int FailClanInfluenceCallsRemaining { get; set; }

		internal int FailClanInfluenceRestoreCallsRemaining { get; set; }

		internal float ClanInfluenceValue { get; set; }

		internal int RelationCallCount { get; private set; }

		internal int RelationRestoreCallCount { get; private set; }

		internal int RelationRestoreMutationCount { get; private set; }

		internal int HeroGoldReadCallCount { get; private set; }

		internal int HeroGoldChangeCallCount { get; private set; }

		internal int HeroGoldRestoreCallCount { get; private set; }

		internal int TroopXpPrepareCallCount { get; private set; }

		internal int TroopXpApplyCallCount { get; private set; }

		internal int TroopXpRestoreCallCount { get; private set; }

		internal int FailTroopXpApplyAfterStacks { get; set; }

		internal IReadOnlyList<string> LastTroopXpClanIds { get; private set; } = Array.Empty<string>();

		internal string FailHeroGoldChangeIdOnce { get; set; } = string.Empty;

		internal int FailHeroGoldChangeCallsRemaining { get; set; }

		internal int FailHeroGoldRestoreCallsRemaining { get; set; }

		internal int FailHeroRelationRestoreCallsRemaining { get; set; }

		internal int? RelationAppliedDeltaOverride { get; set; }

		internal string LastChangedRelationActorHeroId { get; private set; } = string.Empty;

		internal string LastChangedRelationTargetClanId { get; private set; } = string.Empty;

		internal string LastChangedRelationTargetHeroId { get; private set; } = string.Empty;

		internal int LastChangedRelationRequestedDelta { get; private set; }

		internal string LastChangedRelationReason { get; private set; } = string.Empty;

		internal int LastRelationRestoreExpectedAfter { get; private set; }

		internal int LastRelationRestoreBefore { get; private set; }

		internal int StabilityRestoreCallCount { get; private set; }

		internal int StabilityValue
		{
			get => ReadStability("k1");
			set => _stabilityByKingdom["k1"] = value;
		}

		internal string FailKingdomIdOnce { get; set; } = string.Empty;

		private bool _failureInjected;
		private readonly Dictionary<string, int> _stabilityByKingdom = new Dictionary<string, int>(StringComparer.Ordinal);
		private readonly Dictionary<string, string> _relationLeaderByClan =
			new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
		private readonly Dictionary<string, string> _relationClanByHero =
			new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
		private readonly Dictionary<string, int> _relationByHeroPair =
			new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
		private readonly HashSet<string> _skippedRelationActors =
			new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		private readonly Dictionary<string, int> _heroGoldById =
			new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
		private readonly HashSet<string> _unavailableHeroGoldIds =
			new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		private bool _heroGoldChangeFailureInjected;
		private readonly Dictionary<string, int> _troopXpByKey =
			new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
		private JToken _clanTroopXpPlan;
		private bool _troopXpApplyFailureInjected;

		internal void SetHeroGold(string heroId, int value)
		{
			_heroGoldById[(heroId ?? string.Empty).Trim()] = value;
		}

		internal void SetClanTroopXpPlan(JToken plan)
		{
			_clanTroopXpPlan = plan?.DeepClone();
			_troopXpByKey.Clear();
			foreach (JObject stack in ReadTroopXpStacks(_clanTroopXpPlan))
			{
				string partyId = (string)stack["partyId"] ?? string.Empty;
				string troopId = (string)stack["i"] ?? string.Empty;
				_troopXpByKey[TroopXpKey(partyId, troopId)] = stack.Value<int>("b");
			}
		}

		internal int ReadTroopXp(string partyId, string troopId)
		{
			return _troopXpByKey.TryGetValue(TroopXpKey(partyId, troopId), out int value) ? value : 0;
		}

		internal int ReadHeroGold(string heroId)
		{
			return _heroGoldById.TryGetValue((heroId ?? string.Empty).Trim(), out int value) ? value : 0;
		}

		internal void SetHeroGoldAvailable(string heroId, bool available)
		{
			string normalized = (heroId ?? string.Empty).Trim();
			if (available) _unavailableHeroGoldIds.Remove(normalized);
			else _unavailableHeroGoldIds.Add(normalized);
		}

		internal void SetRelationClanLeader(string clanId, string heroId)
		{
			string normalizedClanId = (clanId ?? string.Empty).Trim();
			string normalizedHeroId = (heroId ?? string.Empty).Trim();
			if (normalizedClanId.Length <= 0)
			{
				return;
			}
			if (normalizedHeroId.Length <= 0)
			{
				_relationLeaderByClan.Remove(normalizedClanId);
				return;
			}
			_relationLeaderByClan[normalizedClanId] = normalizedHeroId;
		}

		internal void SetHeroRelation(string actorHeroId, string targetHeroId, int value)
		{
			_relationByHeroPair[RelationKey(actorHeroId, targetHeroId)] = value;
		}

		internal void SetRelationHeroClan(string heroId, string clanId)
		{
			string normalizedHeroId = (heroId ?? string.Empty).Trim();
			string normalizedClanId = (clanId ?? string.Empty).Trim();
			if (normalizedHeroId.Length <= 0)
			{
				return;
			}
			if (normalizedClanId.Length <= 0)
			{
				_relationClanByHero.Remove(normalizedHeroId);
				return;
			}
			_relationClanByHero[normalizedHeroId] = normalizedClanId;
		}

		internal int ReadHeroRelation(string actorHeroId, string targetHeroId)
		{
			return _relationByHeroPair.TryGetValue(RelationKey(actorHeroId, targetHeroId), out int value)
				? value
				: 0;
		}

		internal void SkipRelationActor(string actorHeroId)
		{
			string normalized = (actorHeroId ?? string.Empty).Trim();
			if (normalized.Length > 0)
			{
				_skippedRelationActors.Add(normalized);
			}
		}

		public override IMessage Invoke(IMessage message)
		{
			IMethodCallMessage call = message as IMethodCallMessage;
			if (call == null)
			{
				return new ReturnMessage(new MissingMethodException("unknown"), call);
			}
			if (string.Equals(call.MethodName, "TryChangeClanLeaderRelation", StringComparison.Ordinal))
			{
				string actorHeroId = Convert.ToString(call.Args[0], CultureInfo.InvariantCulture) ?? string.Empty;
				string targetClanId = Convert.ToString(call.Args[1], CultureInfo.InvariantCulture) ?? string.Empty;
				int requestedDelta = Convert.ToInt32(call.Args[2], CultureInfo.InvariantCulture);
				string reason = Convert.ToString(call.Args[3], CultureInfo.InvariantCulture) ?? string.Empty;
				RelationCallCount++;
				if (_skippedRelationActors.Contains(actorHeroId)
					|| (_relationClanByHero.TryGetValue(actorHeroId, out string actorClanId)
						&& string.Equals(actorClanId, targetClanId, StringComparison.OrdinalIgnoreCase))
					|| !_relationLeaderByClan.TryGetValue(targetClanId, out string targetHeroId)
					|| string.IsNullOrWhiteSpace(targetHeroId)
					|| string.Equals(actorHeroId, targetHeroId, StringComparison.OrdinalIgnoreCase))
				{
					return BuildRelationChangeReturnMessage(call, true, string.Empty, 0, 0, string.Empty);
				}

				int relationBefore = ReadHeroRelation(actorHeroId, targetHeroId);
				int actualDelta = RelationAppliedDeltaOverride ?? requestedDelta;
				int relationAfter = Math.Max(-100, Math.Min(100, relationBefore + actualDelta));
				SetHeroRelation(actorHeroId, targetHeroId, relationAfter);
				LastChangedRelationActorHeroId = actorHeroId;
				LastChangedRelationTargetClanId = targetClanId;
				LastChangedRelationTargetHeroId = targetHeroId;
				LastChangedRelationRequestedDelta = requestedDelta;
				LastChangedRelationReason = reason;
				return BuildRelationChangeReturnMessage(
					call, true, targetHeroId, relationBefore, relationAfter, string.Empty);
			}
			if (string.Equals(call.MethodName, "TryPrepareClanTroopXp", StringComparison.Ordinal))
			{
				LastTroopXpClanIds = (call.Args[0] as IEnumerable ?? Array.Empty<string>())
					.Cast<object>()
					.Select(value => Convert.ToString(value, CultureInfo.InvariantCulture) ?? string.Empty)
					.ToArray();
				TroopXpPrepareCallCount++;
				JToken plan = _clanTroopXpPlan?.DeepClone()
					?? new JObject { ["v"] = 1, ["x"] = 0, ["p"] = new JArray() };
				return BuildTroopXpPrepareReturnMessage(call, true, plan, string.Empty);
			}
			if (string.Equals(call.MethodName, "TryApplyClanTroopXp", StringComparison.Ordinal))
			{
				JToken plan = call.Args[0] as JToken;
				TroopXpApplyCallCount++;
				int parties = (plan?["p"] as JArray)?.Count ?? 0;
				int stacks = 0;
				long totalXp = 0;
				foreach (JObject stack in ReadTroopXpStacks(plan))
				{
					string partyId = (string)stack["partyId"] ?? string.Empty;
					string troopId = (string)stack["i"] ?? string.Empty;
					int before = stack.Value<int>("b");
					int after = stack.Value<int>("a");
					string key = TroopXpKey(partyId, troopId);
					if (!_troopXpByKey.TryGetValue(key, out int current) || current != before)
					{
						return BuildTroopXpApplyReturnMessage(
							call, false, new JObject { ["v"] = 1, ["x"] = plan?["x"], ["p"] = new JArray() },
							0, 0, 0L, "troop XP preflight CAS mismatch");
					}
					_troopXpByKey[key] = after;
					stacks++;
					totalXp += (long)after - before;
					if (!_troopXpApplyFailureInjected
						&& FailTroopXpApplyAfterStacks > 0
						&& stacks >= FailTroopXpApplyAfterStacks)
					{
						_troopXpApplyFailureInjected = true;
						JToken partialJournal = BuildTroopXpPrefixJournal(plan, stacks);
						int partialParties = (partialJournal?["p"] as JArray)?.Count ?? 0;
						return BuildTroopXpApplyReturnMessage(
							call, false, partialJournal, partialParties, stacks, totalXp,
							"injected troop XP partial failure");
					}
				}
				return BuildTroopXpApplyReturnMessage(
					call, true, plan?.DeepClone(), parties, stacks, totalXp, string.Empty);
			}
			if (string.Equals(call.MethodName, "TryRestoreClanTroopXp", StringComparison.Ordinal))
			{
				JToken journal = call.Args[0] as JToken;
				TroopXpRestoreCallCount++;
				List<JObject> stacks = ReadTroopXpStacks(journal).ToList();
				int restored = 0;
				for (int index = stacks.Count - 1; index >= 0; index--)
				{
					JObject stack = stacks[index];
					string partyId = (string)stack["partyId"] ?? string.Empty;
					string troopId = (string)stack["i"] ?? string.Empty;
					int before = stack.Value<int>("b");
					int after = stack.Value<int>("a");
					string key = TroopXpKey(partyId, troopId);
					if (!_troopXpByKey.TryGetValue(key, out int current)
						|| (current != before && current != after))
					{
						return BuildTroopXpRestoreReturnMessage(call, false, restored, "troop XP restore CAS mismatch");
					}
					if (current == after)
					{
						_troopXpByKey[key] = before;
						restored++;
					}
				}
				return BuildTroopXpRestoreReturnMessage(call, true, restored, string.Empty);
			}
			if (string.Equals(call.MethodName, "TryReadHeroGold", StringComparison.Ordinal))
			{
				string heroId = Convert.ToString(call.Args[0], CultureInfo.InvariantCulture) ?? string.Empty;
				bool available = !_unavailableHeroGoldIds.Contains(heroId) && _heroGoldById.ContainsKey(heroId);
				HeroGoldReadCallCount++;
				return BuildHeroGoldReadReturnMessage(call, true, available, available ? ReadHeroGold(heroId) : 0, string.Empty);
			}
			if (string.Equals(call.MethodName, "TryChangeHeroGoldExact", StringComparison.Ordinal))
			{
				string heroId = Convert.ToString(call.Args[0], CultureInfo.InvariantCulture) ?? string.Empty;
				int goldDelta = Convert.ToInt32(call.Args[1], CultureInfo.InvariantCulture);
				bool available = !_unavailableHeroGoldIds.Contains(heroId) && _heroGoldById.ContainsKey(heroId);
				int before = available ? ReadHeroGold(heroId) : 0;
				HeroGoldChangeCallCount++;
				bool failOnce = !_heroGoldChangeFailureInjected
					&& string.Equals(heroId, FailHeroGoldChangeIdOnce, StringComparison.OrdinalIgnoreCase);
				bool failRemaining = FailHeroGoldChangeCallsRemaining > 0
					&& string.Equals(heroId, FailHeroGoldChangeIdOnce, StringComparison.OrdinalIgnoreCase);
				if (failOnce || failRemaining)
				{
					_heroGoldChangeFailureInjected = true;
					if (failRemaining) FailHeroGoldChangeCallsRemaining--;
					return BuildHeroGoldChangeReturnMessage(call, false, available, before, before, "forced hero gold change failure");
				}
				long expected = (long)before + goldDelta;
				if (!available || expected < 0 || expected > int.MaxValue)
				{
					return BuildHeroGoldChangeReturnMessage(call, false, available, before, before, "hero gold range failure");
				}
				_heroGoldById[heroId] = (int)expected;
				return BuildHeroGoldChangeReturnMessage(call, true, true, before, (int)expected, string.Empty);
			}
			if (string.Equals(call.MethodName, "TryRestoreHeroGold", StringComparison.Ordinal))
			{
				string heroId = Convert.ToString(call.Args[0], CultureInfo.InvariantCulture) ?? string.Empty;
				int expectedAfter = Convert.ToInt32(call.Args[1], CultureInfo.InvariantCulture);
				int before = Convert.ToInt32(call.Args[2], CultureInfo.InvariantCulture);
				int current = ReadHeroGold(heroId);
				HeroGoldRestoreCallCount++;
				if (FailHeroGoldRestoreCallsRemaining > 0)
				{
					FailHeroGoldRestoreCallsRemaining--;
					return BuildHeroGoldRestoreReturnMessage(call, false, current, "forced hero gold restore failure");
				}
				if (!_heroGoldById.ContainsKey(heroId) || (current != before && current != expectedAfter))
				{
					return BuildHeroGoldRestoreReturnMessage(call, false, current, "hero gold CAS mismatch");
				}
				_heroGoldById[heroId] = before;
				return BuildHeroGoldRestoreReturnMessage(call, true, before, string.Empty);
			}
			if (string.Equals(call.MethodName, "TryRestoreHeroRelation", StringComparison.Ordinal))
			{
				string actorHeroId = Convert.ToString(call.Args[0], CultureInfo.InvariantCulture) ?? string.Empty;
				string targetHeroId = Convert.ToString(call.Args[1], CultureInfo.InvariantCulture) ?? string.Empty;
				int expectedAfter = Convert.ToInt32(call.Args[2], CultureInfo.InvariantCulture);
				int before = Convert.ToInt32(call.Args[3], CultureInfo.InvariantCulture);
				int current = ReadHeroRelation(actorHeroId, targetHeroId);
				RelationRestoreCallCount++;
				LastRelationRestoreExpectedAfter = expectedAfter;
				LastRelationRestoreBefore = before;
				if (FailHeroRelationRestoreCallsRemaining > 0)
				{
					FailHeroRelationRestoreCallsRemaining--;
					return BuildRelationRestoreReturnMessage(
						call, false, current, "forced hero relation restore failure");
				}
				if (current == before)
				{
					return BuildRelationRestoreReturnMessage(call, true, current, string.Empty);
				}
				if (current != expectedAfter)
				{
					return BuildRelationRestoreReturnMessage(call, false, current, "hero relation CAS mismatch");
				}
				SetHeroRelation(actorHeroId, targetHeroId, before);
				RelationRestoreMutationCount++;
				return BuildRelationRestoreReturnMessage(call, true, before, string.Empty);
			}
			if (string.Equals(call.MethodName, "TryChangeClanInfluence", StringComparison.Ordinal))
			{
				float before = ClanInfluenceValue;
				float influenceDelta = Convert.ToSingle(call.Args[1], CultureInfo.InvariantCulture);
				InfluenceCallCount++;
				if (FailClanInfluenceCallsRemaining > 0)
				{
					FailClanInfluenceCallsRemaining--;
					return BuildClanInfluenceReturnMessage(call, false, before, before, "forced retryable influence failure");
				}
				ClanInfluenceValue += influenceDelta;
				return BuildClanInfluenceReturnMessage(call, true, before, ClanInfluenceValue, string.Empty);
			}
			if (string.Equals(call.MethodName, "TryRestoreClanInfluence", StringComparison.Ordinal))
			{
				float expectedAfter = Convert.ToSingle(call.Args[1], CultureInfo.InvariantCulture);
				float before = Convert.ToSingle(call.Args[2], CultureInfo.InvariantCulture);
				InfluenceRestoreCallCount++;
				if (FailClanInfluenceRestoreCallsRemaining > 0)
				{
					FailClanInfluenceRestoreCallsRemaining--;
					return BuildRestoreValueReturnMessage(
						call, false, ClanInfluenceValue, "forced clan influence restore failure");
				}
				if (Math.Abs(ClanInfluenceValue - before) < 0.0001f)
				{
					return BuildRestoreValueReturnMessage(call, true, ClanInfluenceValue, string.Empty);
				}
				if (Math.Abs(ClanInfluenceValue - expectedAfter) >= 0.0001f)
				{
					return BuildRestoreValueReturnMessage(
						call, false, ClanInfluenceValue, "clan influence CAS mismatch");
				}
				ClanInfluenceValue = before;
				return BuildRestoreValueReturnMessage(call, true, ClanInfluenceValue, string.Empty);
			}
			if (string.Equals(call.MethodName, "TryRestoreKingdomStability", StringComparison.Ordinal))
			{
				string restoreKingdomId = Convert.ToString(call.Args[0], CultureInfo.InvariantCulture) ?? string.Empty;
				int expectedAfter = Convert.ToInt32(call.Args[1], CultureInfo.InvariantCulture);
				int before = Convert.ToInt32(call.Args[2], CultureInfo.InvariantCulture);
				int current = ReadStability(restoreKingdomId);
				CallCount++;
				StabilityRestoreCallCount++;
				if (ShouldFailKingdomCall(restoreKingdomId))
				{
					return BuildRestoreValueReturnMessage(call, false, current, "forced contract failure");
				}
				if (current == before)
				{
					return BuildRestoreValueReturnMessage(call, true, current, string.Empty);
				}
				if (current != expectedAfter)
				{
					return BuildRestoreValueReturnMessage(call, false, current, "kingdom stability CAS mismatch");
				}
				_stabilityByKingdom[restoreKingdomId] = before;
				TotalDelta += before - current;
				return BuildRestoreValueReturnMessage(call, true, before, string.Empty);
			}
			if (!string.Equals(call.MethodName, "TryAdjustKingdomStability", StringComparison.Ordinal))
			{
				return new ReturnMessage(new MissingMethodException(call.MethodName), call);
			}
			string kingdomId = Convert.ToString(call.Args[0], CultureInfo.InvariantCulture) ?? string.Empty;
			int delta = Convert.ToInt32(call.Args[1], CultureInfo.InvariantCulture);
			int stabilityBefore = ReadStability(kingdomId);
			CallCount++;
			if (ShouldFailKingdomCall(kingdomId))
			{
				return call.Args.Length == 6
					? BuildStabilitySnapshotReturnMessage(
						call, false, stabilityBefore, stabilityBefore, "forced contract failure")
					: BuildBridgeReturnMessage(call, false, 0, "forced contract failure");
			}
			int stabilityAfter = stabilityBefore + delta;
			_stabilityByKingdom[kingdomId] = stabilityAfter;
			TotalDelta += delta;
			return call.Args.Length == 6
				? BuildStabilitySnapshotReturnMessage(call, true, stabilityBefore, stabilityAfter, string.Empty)
				: BuildBridgeReturnMessage(call, true, delta, string.Empty);
		}

		private int ReadStability(string kingdomId)
		{
			return _stabilityByKingdom.TryGetValue(kingdomId ?? string.Empty, out int value) ? value : 0;
		}

		private bool ShouldFailKingdomCall(string kingdomId)
		{
			if (_failureInjected
				|| string.IsNullOrWhiteSpace(FailKingdomIdOnce)
				|| !string.Equals(kingdomId, FailKingdomIdOnce, StringComparison.Ordinal))
			{
				return false;
			}
			_failureInjected = true;
			return true;
		}

		private static string RelationKey(string actorHeroId, string targetHeroId)
		{
			return (actorHeroId ?? string.Empty).Trim() + "\0" + (targetHeroId ?? string.Empty).Trim();
		}

		private static string TroopXpKey(string partyId, string troopId)
		{
			return (partyId ?? string.Empty).Trim() + "\0" + (troopId ?? string.Empty).Trim();
		}

		private static IEnumerable<JObject> ReadTroopXpStacks(JToken plan)
		{
			if (plan?["p"] is not JArray parties)
			{
				yield break;
			}
			foreach (JObject party in parties.OfType<JObject>())
			{
				string partyId = ((string)party["i"] ?? string.Empty).Trim();
				if (party["s"] is not JArray stacks)
				{
					continue;
				}
				foreach (JObject source in stacks.OfType<JObject>())
				{
					JObject stack = (JObject)source.DeepClone();
					stack["partyId"] = partyId;
					yield return stack;
				}
			}
		}

		private static JToken BuildTroopXpPrefixJournal(JToken plan, int stackCount)
		{
			JObject result = new JObject
			{
				["v"] = plan?["v"]?.DeepClone(),
				["x"] = plan?["x"]?.DeepClone(),
				["p"] = new JArray()
			};
			int remaining = Math.Max(0, stackCount);
			if (plan?["p"] is not JArray parties || remaining == 0)
			{
				return result;
			}
			foreach (JObject sourceParty in parties.OfType<JObject>())
			{
				if (remaining == 0)
				{
					break;
				}
				JArray selectedStacks = new JArray();
				foreach (JObject sourceStack in (sourceParty["s"] as JArray)?.OfType<JObject>() ?? Enumerable.Empty<JObject>())
				{
					if (remaining-- == 0)
					{
						break;
					}
					selectedStacks.Add(sourceStack.DeepClone());
				}
				if (selectedStacks.Count > 0)
				{
					JObject party = (JObject)sourceParty.DeepClone();
					party["s"] = selectedStacks;
					((JArray)result["p"]).Add(party);
				}
			}
			return result;
		}

		private static ReturnMessage BuildRelationChangeReturnMessage(
			IMethodCallMessage call,
			bool returnValue,
			string targetHeroId,
			int before,
			int after,
			string error)
		{
			object[] returnedArguments = (object[])call.Args.Clone();
			returnedArguments[4] = targetHeroId;
			returnedArguments[5] = before;
			returnedArguments[6] = after;
			returnedArguments[7] = error;
			return new ReturnMessage(
				returnValue,
				returnedArguments,
				returnedArguments.Length,
				call.LogicalCallContext,
				call);
		}

		private static ReturnMessage BuildHeroGoldReadReturnMessage(
			IMethodCallMessage call,
			bool returnValue,
			bool available,
			int gold,
			string error)
		{
			object[] returnedArguments = (object[])call.Args.Clone();
			returnedArguments[1] = available;
			returnedArguments[2] = gold;
			returnedArguments[3] = error;
			return new ReturnMessage(returnValue, returnedArguments, returnedArguments.Length, call.LogicalCallContext, call);
		}

		private static ReturnMessage BuildTroopXpPrepareReturnMessage(
			IMethodCallMessage call,
			bool returnValue,
			JToken plan,
			string error)
		{
			object[] returnedArguments = (object[])call.Args.Clone();
			returnedArguments[2] = plan;
			returnedArguments[3] = error;
			return new ReturnMessage(returnValue, returnedArguments, returnedArguments.Length, call.LogicalCallContext, call);
		}

		private static ReturnMessage BuildTroopXpApplyReturnMessage(
			IMethodCallMessage call,
			bool returnValue,
			JToken journal,
			int parties,
			int stacks,
			long totalXp,
			string error)
		{
			object[] returnedArguments = (object[])call.Args.Clone();
			returnedArguments[2] = journal;
			returnedArguments[3] = parties;
			returnedArguments[4] = stacks;
			returnedArguments[5] = totalXp;
			returnedArguments[6] = error;
			return new ReturnMessage(returnValue, returnedArguments, returnedArguments.Length, call.LogicalCallContext, call);
		}

		private static ReturnMessage BuildTroopXpRestoreReturnMessage(
			IMethodCallMessage call,
			bool returnValue,
			int restoredStacks,
			string error)
		{
			object[] returnedArguments = (object[])call.Args.Clone();
			returnedArguments[2] = restoredStacks;
			returnedArguments[3] = error;
			return new ReturnMessage(returnValue, returnedArguments, returnedArguments.Length, call.LogicalCallContext, call);
		}

		private static ReturnMessage BuildHeroGoldChangeReturnMessage(
			IMethodCallMessage call,
			bool returnValue,
			bool available,
			int before,
			int after,
			string error)
		{
			object[] returnedArguments = (object[])call.Args.Clone();
			returnedArguments[3] = available;
			returnedArguments[4] = before;
			returnedArguments[5] = after;
			returnedArguments[6] = error;
			return new ReturnMessage(returnValue, returnedArguments, returnedArguments.Length, call.LogicalCallContext, call);
		}

		private static ReturnMessage BuildHeroGoldRestoreReturnMessage(
			IMethodCallMessage call,
			bool returnValue,
			int after,
			string error)
		{
