internal sealed class ContractDataStoreProxy : RealProxy
{
	private readonly Dictionary<string, string> _values;
	private readonly bool _isSaving;

	internal ContractDataStoreProxy(Type interfaceType, Dictionary<string, string> values, bool isSaving)
		: base(interfaceType)
	{
		_values = values ?? throw new ArgumentNullException(nameof(values));
		_isSaving = isSaving;
	}

	public override IMessage Invoke(IMessage message)
	{
		IMethodCallMessage call = (IMethodCallMessage)message;
		if (string.Equals(call.MethodName, "get_IsSaving", StringComparison.Ordinal))
		{
			return new ReturnMessage(_isSaving, null, 0, call.LogicalCallContext, call);
		}
		if (string.Equals(call.MethodName, "get_IsLoading", StringComparison.Ordinal))
		{
			return new ReturnMessage(!_isSaving, null, 0, call.LogicalCallContext, call);
		}
		if (!string.Equals(call.MethodName, "SyncData", StringComparison.Ordinal) || call.ArgCount != 2)
		{
			return new ReturnMessage(new NotSupportedException("Unsupported IDataStore member: " + call.MethodName), call);
		}
		string key = call.Args[0] as string ?? string.Empty;
		object value = call.Args[1];
		if (_isSaving)
		{
			_values[key] = JsonConvert.SerializeObject(value);
		}
		else if (_values.TryGetValue(key, out string raw))
		{
			Type valueType = ((MethodInfo)call.MethodBase).GetGenericArguments()[0];
			value = JsonConvert.DeserializeObject(raw, valueType);
		}
		object[] returnedArguments = (object[])call.Args.Clone();
		returnedArguments[1] = value;
		return new ReturnMessage(true, returnedArguments, returnedArguments.Length, call.LogicalCallContext, call);
	}
}

