internal class StructuredDummyEffectModule : PolicyEffectModuleBase<StructuredDummyPayload>, IModelModifierPolicyEffectModule, IPolicyEffectLifecycleModule
{
	internal const string ModuleId = "contractDummy.structured";

	private static readonly PolicyEffectModuleDescriptor ModuleDescriptor = new PolicyEffectModuleDescriptor(
		id: ModuleId,
		order: 10000,
		legacyIds: Array.Empty<string>(),
		allowedScopes: new[] { PolicyEffectScopes.Local, PolicyEffectScopes.Kingdom },
		allowedSelectorKinds: new[] { PolicyEffectTargetKind.Settlement },
		targetKinds: new[] { PolicyEffectTargetKind.Settlement },
		cueTerms: new[] { "contract structured dummy", "nested payload" },
		retrievalText: "Contract-only structured non-numeric payload module.",
		catalogSummary: "Contract-only structured payload",
		mainInstruction: "Emit a structured mode, enabled flag, and weighted bands.",
		postprocessRule: "The payload must match the declared structured schema exactly.",
		payloadPromptSchema: new JObject
		{
			["type"] = "object",
			["properties"] = new JObject
			{
				["mode"] = new JObject { ["type"] = "string" },
				["enabled"] = new JObject { ["type"] = "boolean" },
				["bands"] = new JObject
				{
					["type"] = "array",
					["items"] = new JObject
					{
						["type"] = "object",
						["properties"] = new JObject
						{
							["name"] = new JObject { ["type"] = "string" },
							["weight"] = new JObject { ["type"] = "number" }
						},
						["required"] = new JArray("name", "weight"),
						["additionalProperties"] = false
					}
				}
			},
			["required"] = new JArray("mode", "enabled", "bands"),
			["additionalProperties"] = false
		},
		family: PolicyEffectFamily.Governance,
		executionKind: PolicyEffectExecutionKind.ModelModifier,
		hook: PolicyEffectHook.SettlementConstructionDaily,
		aggregation: PolicyEffectAggregationKind.Additive,
		valueUnit: PolicyEffectValueUnit.PointsPerDay,
		fundingMode: PolicyEffectFundingMode.Gold,
		fundingStrategy: PolicyEffectFundingStrategy.Custom,
		payloadSchemaVersion: 1);

	public override PolicyEffectModuleDescriptor Descriptor => ModuleDescriptor;

	internal static PolicyEffectModuleDescriptor DescriptorForContractTests => ModuleDescriptor;

	internal static PolicyEffectModuleDescriptor CreateDescriptor(string id, int order, IReadOnlyCollection<string> legacyIds)
	{
		PolicyEffectModuleDescriptor source = ModuleDescriptor;
		return new PolicyEffectModuleDescriptor(
			id,
			order,
			legacyIds,
			source.AllowedScopes,
			source.AllowedSelectorKinds,
			source.TargetKinds,
			source.CueTerms,
			source.RetrievalText,
			source.CatalogSummary,
			source.MainInstruction,
			source.PostprocessRule,
			(JObject)source.PayloadPromptSchema.DeepClone(),
			source.Family,
			source.ExecutionKind,
			source.Hook,
			source.Aggregation,
			source.ValueUnit,
			source.FundingMode,
			source.FundingStrategy,
			source.PayloadSchemaVersion,
			source.SupportsRollback,
			source.SupportsIdempotency);
	}

	public override bool TryNormalizeTypedPayload(
		StructuredDummyPayload payload,
		string scope,
		out StructuredDummyPayload normalizedPayload,
		out string error)
	{
		normalizedPayload = null;
		if (!base.TryNormalizeTypedPayload(payload, scope, out StructuredDummyPayload envelope, out error))
		{
			return false;
		}
		if (string.IsNullOrWhiteSpace(envelope.Mode) || envelope.Bands == null || envelope.Bands.Count == 0)
		{
			error = "mode and at least one band are required";
			return false;
		}
		if (envelope.Bands.Any(band => band == null || string.IsNullOrWhiteSpace(band.Name)
			|| float.IsNaN(band.Weight) || float.IsInfinity(band.Weight)))
		{
			error = "every band requires a name and finite weight";
			return false;
		}
		normalizedPayload = Clone(envelope, 1f);
		error = string.Empty;
		return true;
	}

	public override bool TryApplyTypedFunding(
		StructuredDummyPayload payload,
		PolicyEffectFundingContext funding,
		out StructuredDummyPayload fundedPayload,
		out string error)
	{
		fundedPayload = null;
		if (!TryNormalizeTypedPayload(payload, string.Empty, out StructuredDummyPayload normalized, out error))
		{
			return false;
		}
		float scale = funding?.ResolveScale(Descriptor.FundingMode) ?? 1f;
		return TryNormalizeTypedPayload(Clone(normalized, scale), string.Empty, out fundedPayload, out error);
	}

	public override string DescribeTypedPayload(StructuredDummyPayload payload)
	{
		return payload == null
			? string.Empty
			: payload.Mode + ":" + string.Join(",", payload.Bands.Select(band =>
				band.Name + "=" + band.Weight.ToString("0.###", CultureInfo.InvariantCulture)));
	}

	public IReadOnlyList<PolicyEffectModelContribution> BuildModelContributions(PolicyEffectPreparedInstance preparedInstance)
	{
		return Array.Empty<PolicyEffectModelContribution>();
	}

	public PolicyEffectExecutionResult OnActivated(PolicyEffectExecutionContext context)
	{
		return LifecycleResult(context, "activated");
	}

	public PolicyEffectExecutionResult OnRenewed(PolicyEffectExecutionContext context)
	{
		return LifecycleResult(context, "renewed");
	}

	public PolicyEffectExecutionResult OnExpired(PolicyEffectExecutionContext context)
	{
		return LifecycleResult(context, "expired");
	}

	public PolicyEffectExecutionResult OnAbolished(PolicyEffectExecutionContext context)
	{
		return LifecycleResult(context, "abolished");
	}

	private static PolicyEffectExecutionResult LifecycleResult(PolicyEffectExecutionContext context, string phase)
	{
		PolicyEffectInstance instance = context?.PreparedInstance?.Instance;
		if (instance == null)
		{
			return new PolicyEffectExecutionResult
			{
				Status = PolicyEffectExecutionStatus.Failed,
				Error = "missing prepared instance"
			};
		}
		return new PolicyEffectExecutionResult
		{
			Status = PolicyEffectExecutionStatus.Applied,
			Receipt = new PolicyEffectExecutionReceipt
			{
				ReceiptId = (context.IdempotencyKey ?? instance.InstanceId) + ":" + phase,
				InstanceId = instance.InstanceId,
				PolicyId = instance.PolicyId,
				ModuleId = instance.ModuleId,
				TargetSet = instance.TargetSet,
				Status = PolicyEffectExecutionStatus.Applied,
				RequestedPayload = JToken.FromObject(instance.Payload),
				AppliedPayload = JToken.FromObject(instance.Payload),
				CampaignDay = context.CampaignDay,
				Message = phase
			}
		};
	}

	private static StructuredDummyPayload Clone(StructuredDummyPayload source, float scale)
	{
		return new StructuredDummyPayload
		{
			ModuleId = ModuleId,
			SchemaVersion = 1,
			Mode = source.Mode.Trim(),
			Enabled = source.Enabled,
			Bands = source.Bands.Select(band => new StructuredDummyBand
			{
				Name = band.Name.Trim(),
				Weight = band.Weight * scale
			}).ToList()
		};
	}
}

