internal class VersionedContractDummyModule : PolicyEffectModuleBase<VersionedContractPayload>, IDailyPolicyEffectModule
{
	private readonly PolicyEffectModuleDescriptor _descriptor;

	internal VersionedContractDummyModule()
		: this(CreateDescriptor("contractDummy.versioned", new[] { 1, 2 }, new[] { 1, 2 }))
	{
	}

	protected VersionedContractDummyModule(PolicyEffectModuleDescriptor descriptor)
	{
		_descriptor = descriptor;
	}

	public override PolicyEffectModuleDescriptor Descriptor => _descriptor;

	internal static PolicyEffectModuleDescriptor CreateDescriptor(
		string id,
		IReadOnlyCollection<int> payloadMigrationSources,
		IReadOnlyCollection<int> runtimeStateMigrationSources)
	{
		return new PolicyEffectModuleDescriptor(
			id: id,
			order: 12000,
			legacyIds: Array.Empty<string>(),
			allowedScopes: new[] { PolicyEffectScopes.Kingdom },
			allowedSelectorKinds: new[]
			{
				PolicyEffectTargetKind.Settlement,
				PolicyEffectTargetKind.Clan,
				PolicyEffectTargetKind.Kingdom
			},
			targetKinds: Enum.GetValues(typeof(PolicyEffectTargetKind)).Cast<PolicyEffectTargetKind>().ToArray(),
			cueTerms: new[] { "contract version migration" },
			retrievalText: "Contract-only versioned payload and runtime state.",
			catalogSummary: "Contract-only versioned state",
			mainInstruction: "Emit a versioned contract payload.",
			postprocessRule: "The payload must contain name.",
			payloadPromptSchema: new JObject
			{
				["type"] = "object",
				["properties"] = new JObject { ["name"] = new JObject { ["type"] = "string" } },
				["required"] = new JArray("name"),
				["additionalProperties"] = false
			},
			family: PolicyEffectFamily.Governance,
			executionKind: PolicyEffectExecutionKind.DailyMutation,
			hook: PolicyEffectHook.DailyScheduler,
			aggregation: PolicyEffectAggregationKind.Additive,
			valueUnit: PolicyEffectValueUnit.PointsPerDay,
			fundingMode: PolicyEffectFundingMode.Unscaled,
			fundingStrategy: PolicyEffectFundingStrategy.None,
			payloadSchemaVersion: 3,
			supportsRollback: false,
			supportsIdempotency: true,
			minimumReadablePayloadSchemaVersion: 1,
			payloadMigrationSourceVersions: payloadMigrationSources,
			runtimeStateSchemaVersion: 3,
			minimumReadableRuntimeStateSchemaVersion: 1,
			runtimeStateMigrationSourceVersions: runtimeStateMigrationSources);
	}

	public override bool TryMigrateTypedPayload(
		JToken persistedPayload,
		int sourceVersion,
		out VersionedContractPayload migratedPayload,
		out string error)
	{
		migratedPayload = null;
		string name = (string)persistedPayload?["name"] ?? (string)persistedPayload?["legacyName"] ?? string.Empty;
		if (sourceVersion < 1 || sourceVersion > Descriptor.PayloadSchemaVersion || string.IsNullOrWhiteSpace(name))
		{
			error = "unsupported contract payload migration";
			return false;
		}
		migratedPayload = new VersionedContractPayload
		{
			ModuleId = Id,
			SchemaVersion = Descriptor.PayloadSchemaVersion,
			Name = name
		};
		error = string.Empty;
		return true;
	}

	public override bool TryMigrateRuntimeState(
		JToken persistedState,
		int sourceVersion,
		out JToken migratedState,
		out string error)
	{
		migratedState = null;
		if (sourceVersion < 1 || sourceVersion > Descriptor.RuntimeStateSchemaVersion)
		{
			error = "unsupported contract runtime state migration";
			return false;
		}
		JObject state = persistedState as JObject == null
			? new JObject()
			: (JObject)persistedState.DeepClone();
		state["migratedTo"] = Descriptor.RuntimeStateSchemaVersion;
		migratedState = state;
		error = string.Empty;
		return true;
	}

	public PolicyEffectExecutionResult ExecuteDaily(PolicyEffectExecutionContext context)
	{
		return new PolicyEffectExecutionResult { Status = PolicyEffectExecutionStatus.Skipped };
	}
}

