		StructuredDummyPayload payload,
		string scope,
		out StructuredDummyPayload normalizedPayload,
		out string error)
	{
		if (payload != null)
		{
			payload.ModuleId = Id;
		}
		if (!base.TryNormalizeTypedPayload(payload, scope, out normalizedPayload, out error))
		{
			return false;
		}
		normalizedPayload.ModuleId = Id;
		return true;
	}
}
